async function formatterConfigSignature(cwd: string): Promise<string> {
	const paths = await findUp(FORMATTER_CONFIG_FILES, cwd);
	const parts = await Promise.all(
		paths.sort(compareOrdinal).map(async (filePath) => {
			try {
				const stat = await fs.stat(filePath);
				return `${filePath}:${stat.mtimeMs}:${stat.size}`;
			} catch {
				return `${filePath}:missing`;
			}
		}),
	);
	return parts.join("|");
}

async function getFormatterConfigSignature(
	cwd: string,
	normalizedCwd: string,
): Promise<string> {
	const existing = formatterSignatureFlights.get(normalizedCwd);
	if (existing) return existing.promise;
	const promise = formatterConfigSignature(cwd).finally(() => {
		const current = formatterSignatureFlights.get(normalizedCwd);
		if (current?.promise === promise)
			formatterSignatureFlights.delete(normalizedCwd);
	});
	formatterSignatureFlights.set(normalizedCwd, { promise });
	return promise;
}

// --- Public API ---

export async function getFormattersForFile(
	filePath: string,
	cwd: string,
): Promise<FormatterInfo[]> {
	const ext = path.extname(filePath).toLowerCase();
	const base = path.basename(filePath).toLowerCase();
	// Filename-keyed formatters (e.g. terragrunt.hcl) can share an extension
	// with unrelated files in the same dir (.terraform.lock.hcl next to
	// terragrunt.hcl). Fold the basename into the cache key only when a
	// filename-based formatter actually applies, so a plain .hcl file cached
	// first doesn't poison the cache for terragrunt.hcl/root.hcl, or vice versa.
	const normalizedCwd = normalizeMapKey(cwd);
	const cacheKey = FILENAME_FORMATTER_BASENAMES.has(base)
		? `${normalizedCwd}:${ext}:${base}`
		: `${normalizedCwd}:${ext}`;

	// A warm entry is authoritative until the write-result seam invalidates its
	// config path. This is the only way to make the warm path free of config
	// polling while still reacting immediately to pi-authored create/remove/
	// change events. External editor changes remain a documented session-boundary
	// limitation, like other write-result-owned freshness seams.
	let cached = detectionCache.get(normalizedCwd);
	if (cached?.entries.has(cacheKey)) {
		const enabledNames = cached.entries.get(cacheKey);
		const selectedFormatterName =
			enabledNames && enabledNames.length > 0 ? enabledNames[0] : null;
		logLatency({
			type: "phase",
			phase: "formatter_selected",
			filePath,
			durationMs: 0,
			metadata: {
				formatter: selectedFormatterName,
				reason: "cache",
				cached: true,
				outcome: "hit" satisfies FormatterSelectionOutcome,
				cwd,
			},
		});
		if (!enabledNames || enabledNames.length === 0) return [];
		return ALL_FORMATTERS.filter((f) => enabledNames.includes(f.name));
	}
	if (!cached) {
		const generation = formatterCacheGeneration.capture();
		const configSignature = await getFormatterConfigSignature(
			cwd,
			normalizedCwd,
		);
		// An invalidation can happen while the first signature walk is in flight.
		// Do not publish a pre-invalidation signature into the new generation.
		if (!generation.isCurrent()) {
			return getFormattersForFile(filePath, cwd);
		}
		// Another cold caller for this cwd can finish the shared signature flight
		// first. Re-read the LRU before installing an object so the later caller
		// merges its extension entry into the existing object instead of replacing
		// the earlier entry.
		cached = detectionCache.get(normalizedCwd);
		if (!cached) {
			cached = { signature: configSignature, entries: new Map() };
			detectionCache.set(normalizedCwd, cached);
		}
	}

	// Detect formatters for this extension (or exact filename, e.g. terragrunt.hcl)
	const matching = ALL_FORMATTERS.filter(
		(f) => f.extensions.includes(ext) || f.filenames?.includes(base),
	);
	const formatterPolicy = getFormatterPolicyForFile(filePath);
	const smartDefaultFormatterName = getSmartDefaultFormatterName(filePath);

	const candidateFormatters = formatterPolicy?.formatterNames?.length
		? matching.filter((f) => formatterPolicy.formatterNames.includes(f.name))
		: matching;

	let selected: FormatterInfo | undefined;
	/**
	 * One entry per candidate this pass actually ASKED, in the order it asked
	 * them (#1539). Candidates eliminated without a probe — an explicit-config
	 * decision is pure filesystem — contribute nothing, which is the point: a
	 * decision that never probed cannot have been degraded by a probe.
	 */
	const candidateOutcomes: CandidateOutcome[] = [];
	if (formatterPolicy) {
		const explicitlyConfigured = candidateFormatters.filter((formatter) =>
			hasExplicitFormatterConfig(formatter.name, cwd, ext),
		);
		if (explicitlyConfigured.length > 0) {
			// A formatter with explicit project config was found — use it.
			// Prefer the policy's defaultFormatter only if it has explicit config,
			// otherwise pick the first explicitly-configured formatter.
			selected = formatterPolicy.defaultFormatter
				? (explicitlyConfigured.find(
						(f) => f.name === formatterPolicy.defaultFormatter,
					) ?? explicitlyConfigured[0])
				: explicitlyConfigured[0];
		} else if (smartDefaultFormatterName) {
			// Reached only when explicitlyConfigured is empty, so no candidate
			// has explicit config. Safe to activate the smart-default.
			const smartDefaultFormatter = candidateFormatters.find(
				(f) => f.name === smartDefaultFormatterName,
			);
			if (smartDefaultFormatter) {
				const autoInstallToolId = getAutoInstallToolIdForFormatter(
					smartDefaultFormatter.name,
				);
				if (autoInstallToolId) {
					selected = smartDefaultFormatter;
				} else {
					const { detected, error, outcome } = await detectCandidate(
						smartDefaultFormatter,
						cwd,
					);
					candidateOutcomes.push(outcome);
					// This branch never caught a throwing detection, and still
					// does not: `detectCandidate` catches only so the probes survive.
					if (error !== undefined) throw error;
					if (detected) selected = smartDefaultFormatter;
				}
			}
		}
	} else {
		for (const formatter of candidateFormatters) {
			const { detected, error, outcome } = await detectCandidate(
				formatter,
				cwd,
			);
			candidateOutcomes.push(outcome);
			if (error !== undefined) {
				// pi-lens-ignore: missing-error-propagation — optional formatter detection, skip on failure
				logExtension({
					subsystem: "format",
					message: `Detection failed for ${formatter.name}: ${
						error instanceof Error ? error.message : String(error)
					}`,
					metadata: { formatter: formatter.name, cwd },
				});
				continue;
			}
			if (detected) {
				selected = formatter;
				break;
			}
		}
	}

	const enabled = selected ? [selected] : [];
	// The #925/#1467 `wouldPoisonCache` shape: an empty result produced while a
	// PATH probe was timing out is not a finding about this project. Caching it
	// would survive until a config file's mtime or size changed, so leave the
	// cache untouched and let the next turn re-detect.
	// Which of THIS file's candidates are currently un-answered? Read off the
	// binaries the candidates' own `detect()`s actually probed (#1539), so a
	// stalled `which rustfmt` cannot stop a shell or Python detection from
	// caching (#1495 review) AND a leftover transient verdict for a binary this
	// pass never consulted cannot be blamed on this decision.
	//
	// This replaces the `command[0]` approximation, which missed both shapes of
	// extra probe: a co-equal ALTERNATIVE (`pwsh` ?? `powershell`) and — the
	// case the old comment wrongly called harmless — an install FALLBACK reached
	// after the primary answered a GENUINE absence. `rustfmt` missing plus a
	// stalled `which rustup` skips the lazy install, and nothing named `rustfmt`
	// is transient, so the empty result used to cache for the session.
	//
	// Residual: the record covers this module's own `which()` only. A detection
	// that reaches PATH some other way is invisible to it — ktlint's `detect()`
	// falls back to the installer's `getToolPath("ktlint")`, which has its own
	// probe and its own 24-hour cache. Widening the record to those is deferred to
	// the installer-side follow-up rather than bolted on here.
	const stalledCandidateCommands = [
		...new Set(candidateOutcomes.flatMap((outcome) => outcome.stalledCommands)),
	];
	const poisonedByTransientProbe =
		enabled.length === 0 && stalledCandidateCommands.length > 0;

	// A NON-empty result the poison guard cannot see (#1539): the winner won only
	// because a candidate ahead of it was never asked. `candidateOutcomes` is in
	// ask order and the loop stops at the winner, so every entry before the
	// winner's is a candidate that lost — and an `unreachable` one did not lose
	// on the merits. Caching this would hand the session to the runner-up until
	// a config file's mtime or size changed.
	const winnerIndex = selected
		? candidateOutcomes.findIndex((outcome) => outcome.name === selected.name)
		: -1;
	const unreachablePreferred = candidateOutcomes
		.slice(0, winnerIndex === -1 ? 0 : winnerIndex)
		.filter((outcome) => outcome.verdict === "unreachable")
		.map((outcome) => outcome.name);
	const degradedSelection = unreachablePreferred.length > 0;

	let selectionReason: string;
	if (poisonedByTransientProbe) {
		selectionReason = "probe-timeout";
	} else if (degradedSelection) {
		// The reason now describes how the winner WON, not just what the config
		// looks like. "explicit-config" on a selection whose preferred candidate
		// was never reachable was the most misleading record in this seam.
		selectionReason = "preferred-unreachable";
	} else if (!selected) {
		selectionReason = "none";
	} else if (!formatterPolicy) {
		selectionReason = "detect";
	} else {
		selectionReason = candidateFormatters.some((f) =>
			hasExplicitFormatterConfig(f.name, cwd, ext),
		)
			? "explicit-config"
			: "smart-default";
	}
	const provisional = poisonedByTransientProbe || degradedSelection;
	logLatency({
		type: "phase",
		phase: "formatter_selected",
		filePath: filePath,
		durationMs: 0,
		metadata: {
			formatter: selected?.name ?? null,
			reason: selectionReason,
			outcome: "miss" satisfies FormatterSelectionOutcome,
			cwd,
			...(provisional && {
				cached: false,
				stalledProbes: stalledCandidateCommands,
			}),
			...(degradedSelection && { unreachablePreferred }),
		},
	});

	// Provisional either way: not cached, so the next pass re-detects once the
	// cooldown expires and the preferred formatter's recovery takes effect
	// without waiting on a config-file edit.
	if (provisional) return enabled;

	// Store the list of enabled formatter names in cache
	const enabledNames = enabled.map((f) => f.name);
	// An invalidation may have removed or replaced this object while detection
	// awaited a tool probe. Never repopulate the old generation.
	if (detectionCache.get(normalizedCwd) === cached) {
		cached.entries.set(cacheKey, enabledNames);
	}
	return enabled;
}

/**
 * Re-arm formatter availability: drop both the per-cwd selection cache and the
 * PATH latches.
 *
 * #1895: this is the session-boundary reset. Both halves are required. The
 * latches decide whether `which` runs at all, but `detectionCache` short-
 * circuits ahead of them — a same-cwd lookup returns the previous verdict's
 * formatter names without reaching a probe. Clearing only the latches
 * therefore re-arms every directory EXCEPT the one the user is working in.
 */
export function clearFormatterCache(): void {
	formatterCacheGeneration.bump();
	formatterSignatureFlights.clear();
	detectionCache.clear();
	resetWhichLatches();
}

const formatterConfigBasenames = new Set(
	FORMATTER_CONFIG_FILES.map((fileName) => fileName.toLowerCase()),
);

/** Invalidate selection when the write-result seam reports a config path. */
export function invalidateFormatterCacheForPath(filePath: string): void {
	const basename = filePath.includes("\\")
		? path.win32.basename(filePath)
		: path.basename(filePath);
	if (!formatterConfigBasenames.has(basename.toLowerCase())) return;
	clearFormatterCache();
}

/**
 * Test-only internals access for the session-state registry probe (#1895):
 * the conformance suite must arm all four pieces of state this reset claims
 * to cover and prove none survives.
 */
export function _getFormatterResetStateForTests(): {
	whichLatchByCommand: Map<
		string,
		{ latch: AvailabilityLatch; resolved: string | null }
	>;
	whichTransientCommands: Set<string>;
	cooldownRecordedForRetryAtMs: Map<string, number>;
	detectionCache: BoundedLruCache<
		string,
		{ signature: string; entries: Map<string, string[]> }
	>;
	formatterSignatureFlights: BoundedLruCache<
		string,
		{ promise: Promise<string> }
	>;
} {
	return {
		whichLatchByCommand,
		whichTransientCommands,
		cooldownRecordedForRetryAtMs,
		detectionCache,
		formatterSignatureFlights,
	};
}

export function clearFormatterRuntimeState(): void {
	clearFormatterCache();
	// NO `resetLazyInstallAttempts()` here (#1537 review F1). This function runs
	// from `resetFormatService()`, which `handleTurnEnd` calls every turn — so
	// clearing the lazy-install hold here made "held for the session" mean "held
	// for a turn", and a failing install re-ran every turn. The hold's only reset
	// is `session_start`'s block in runtime-session.ts.
}

const BOX_DRAWING_GLOBAL = /[\u2500-\u257F]/g;
/** Blank, or a rule made of box-drawing characters and spacing alone. */
const DECORATION_RULE = /^[\u2500-\u257F\s]*$/;
/** The renderer's section heading: one word, then box-drawing to end of line. */
const DECORATION_HEADING = /^\S+[ \t]+[\u2500-\u257F][\u2500-\u257F\s]*$/;

/**
 * First line of `text` that actually carries a diagnostic.
 *
 * #1337 made nonzero exits user-visible, which put whatever this returns in
 * front of the agent (`clients/pipeline.ts`) and in the end-of-turn summary
 * (`clients/runtime-agent-end.ts`) — so "first line of stderr" is no longer
 * good enough. Biome opens stderr with a decorated section rule
 * (`format ━━━━━━━━━━━`), which as an error message is pure noise.
 *
 * Skips blank lines, pure box-drawing rules, and short banner headings; strips
 * ANSI colour so the message stays readable in a plain-text surface.
 */
export function firstDiagnosticLine(
	text: string | undefined,
): string | undefined {
	for (const raw of (text ?? "").split("\n")) {
		const line = stripAnsi(raw).trimEnd();
		if (isDecorativeLine(line)) continue;
		return line.replace(BOX_DRAWING_GLOBAL, "").trim().slice(0, 300);
	}
	return undefined;
}

/**
 * The two decoration SHAPES a renderer emits, and nothing else: a rule made of
 * box-drawing characters alone (blank lines included), and a `<word> ━━━━`
 * section heading whose remainder after the word is box-drawing only.
 *
 * The single normalization both readers above and below share, so the bounded
 * tail cannot surface what the first-line reader already rejects (#3312 review
 * R3-4: the tail put biome's `format ━━━━` banner back in front of the strict
 * #1337 seam). Matching SHAPES rather than "contains a box character and is
 * short" is #3312 review R4-1: the length heuristic deleted
 * `━ traceback source excerpt`, a diagnostic whose own text opens with a box
 * character. A line carrying any non-decorative text is never decoration.
 */
function isDecorativeLine(line: string): boolean {
	return DECORATION_RULE.test(line) || DECORATION_HEADING.test(line);
}

const FORMATTER_ERROR_TAIL_LINES = 20;

/**
 * Preserve a bounded tail of a formatter's diagnostic output.
 *
 * A traceback's first line is not actionable on its own (#3312). Keep the
 * final lines, which include the exception and its message, while bounding
 * the model-facing error when a formatter emits an unexpectedly large log.
 *
 * Decorative lines are dropped FIRST, by the same predicate `firstDiagnosticLine`
 * uses: a tail that kept them would hand the strict #1337 seam the banner this
 * module already decided is not a diagnostic, and every banner line it kept
 * would evict a real traceback line from the bound.
 */
export function diagnosticTail(
	text: string | undefined,
	maxLines = FORMATTER_ERROR_TAIL_LINES,
): string | undefined {
	const lines: string[] = [];
	for (const raw of (text ?? "").split("\n")) {
		const line = stripAnsi(raw).trimEnd();
		if (isDecorativeLine(line)) continue;
		lines.push(line.slice(0, 300));
	}
	if (lines.length === 0) return undefined;
	return lines.slice(-maxLines).join("\n");
}

/**
 * Resolve a static npx fallback to a pi-lens-managed binary so the tool runs
 * with the PROJECT cwd and still honours cwd-relative config/ignore files
 * (#4268 HIGH-2). The managed install itself runs from the pi-lens-owned env
 * (see `getIsolatedNpxSpawnOptions`), so the project's `.npmrc` is never read.
 * Returns the fallback unchanged when no managed tool id exists or the install
 * fails; `formatFile` then runs npx from the neutral pi-lens-owned cwd.
 */
async function resolveNpxFallback(
	formatterName: string,
	fallback: string[],
): Promise<string[]> {
	const toolId = getAutoInstallToolIdForFormatter(formatterName);
	if (!toolId) return fallback;
	const { ensureTool } = await import("./installer/index.js");
	const installed = await ensureTool(toolId);
	if (!installed) return fallback;
	// Drop the leading `npx <package>` pair; keep the tool's own argv.
	return [installed, ...fallback.slice(2)];
}

/**
 * Resolve a formatter command without allowing the static command fallback to
 * bypass a resolver's style-preservation refusal (#1345). `null` means the
 * primary command is unavailable; the explicit sentinel means formatting is
 * forbidden for this file and must be returned before the static command is
 * materialized.
 */
async function resolveFormatterCommand(
	formatter: FormatterInfo,
	absolutePath: string,
	cwd: string,
): Promise<
	| string[]
	| typeof SKIP_FORMATTING
	| typeof FORMATTER_UNAVAILABLE
	| typeof FORMATTER_AGREEMENT_UNAVAILABLE
> {
	const agreement = establishToolAgreement(formatter.name, cwd);
	if (agreement.decision === "decline") {
		recordDegradationOnce({
			kind: "formatter-agreement-unavailable",
			subject: agreement.subject,
			reason: agreement.reason,
		});
		return FORMATTER_AGREEMENT_UNAVAILABLE;
	}
	const resolved = formatter.resolveCommand
		? await formatter.resolveCommand(absolutePath, cwd)
		: null;
	if (resolved === SKIP_FORMATTING) return SKIP_FORMATTING;
	// The resolver proved the executable absent — DO NOT fall through to the
	// static bare command, which is the same binary it just probed and missing
	// (#2413). The caller turns this into a typed `unavailable` outcome, never a
	// spawn and never a failure.
	if (resolved === FORMATTER_UNAVAILABLE) return FORMATTER_UNAVAILABLE;
	if (resolved !== null) return resolved;
	const fallback = formatter.command.map((c) =>
		c.replace("$FILE", absolutePath),
	);
	// Trust gate on the install-capable static fallback (#1334 S5): npx can
	// DOWNLOAD packages, so an untrusted project treats the fallback as
	// unavailable -- a skip, not a formatter failure; may converge next turn.
	if (fallback[0] === "npx") {
		if (!assertInstallAllowed(`formatter npx fallback: ${formatter.name}`)) {
			// No second ledger entry here (#1366 review): assertInstallAllowed just
			// recorded the trust-refusal with this formatter's context — recording
			// formatter-skip too would count one user-visible degradation twice.
			return SKIP_FORMATTING;
		}
		// Install/resolve from the pi-lens-owned env, then run the resolved
		// binary with the project cwd so `.prettierignore`/`biome.json` still win
		// (#4268 HIGH-2).
		return resolveNpxFallback(formatter.name, fallback);
	}
	return fallback;
}

export async function formatFile(
	filePath: string,
	formatter: FormatterInfo,
	/**
	 * #3558: enters pi's mutation queue for the file. Called once the command
	 * is resolved (an install can take minutes) and before the before-read.
	 */
	enter?: () => Promise<void>,
): Promise<FormatterResult> {
	try {
		const absolutePath = path.resolve(filePath);
		const cwd = path.dirname(absolutePath);
		const formatterCwd = resolveToolCwd(
			"formatter",
			formatter.name,
			absolutePath,
			{ cwd: path.parse(absolutePath).root },
		).cwd;

		// Resolve command: prefer local (venv/vendor/node_modules) over global.
		// The shared seam must honor SKIP_FORMATTING before selecting the static
		// command, including its npx fallback (#1345).
		const cmd = await resolveFormatterCommand(formatter, absolutePath, cwd);
		if (cmd === SKIP_FORMATTING) {
			// Style-preserving refusal (#1144): no repo config and no detectable
			// indentation to pin — formatting would impose the tool's stock style.
			return { success: true, changed: false, outcome: "skipped" };
		}
		if (cmd === FORMATTER_UNAVAILABLE) {
			// The resolver proved the executable absent (#2413): the oxfmt ENOENT
			// trap and its siblings. This is unavailable infrastructure, not a code
			// failure — success stays true so it is never counted as a failed file
			// or requeued, and the typed outcome keeps it out of the failure bucket.
			return {
				success: true,
				changed: false,
				outcome: "unavailable",
				error: `${formatter.name}: formatter executable not found`,
			};
		}
		if (cmd === FORMATTER_AGREEMENT_UNAVAILABLE) {
			return {
				success: true,
				changed: false,
				outcome: "unavailable",
				error: `${formatter.name}: project tool agreement could not be established`,
			};
		}
		await enter?.();
		const contentBefore = await fs.readFile(absolutePath, "utf-8");
		// Run formatter without blocking the event loop. An unresolved npx/bunx
		// fallback is the ONLY case that gets the neutral pi-lens-owned cwd
		// (#4268 acceptance 3); a resolved binary keeps the project cwd.
		const result = await safeSpawnAsync(cmd[0], cmd.slice(1), {
			timeout: 15000,
			cwd: formatterCwd,
			...(cmd[0] === "npx" || cmd[0] === "bunx"
				? getIsolatedNpxSpawnOptions()
				: {}),
		});

		// A resolver that could NOT prove absence (it never probed PATH — e.g.
		// black/sqlfluff, which only look in a venv) legitimately falls back to the
		// bare static command. When that bare command is missing, the spawn boundary
		// reports a typed `tool-not-found` failure — never a nonzero exit. Treat it
		// as unavailable, not a formatting failure, closing the same #2413 class for
		// the formatters whose `null` correctly means "static untried" (no
		// oxfmt-specific string matching — this reads the typed spawn-failure kind).
		if (result.spawnFailure?.kind === "tool-not-found") {
			return {
				success: true,
				changed: false,
				outcome: "unavailable",
				error: result.spawnFailure.message,
			};
		}

		// Strict by default (#1337): only a formatter with a documented
		// benign-nonzero mode (`lenientExitCode`) may exit nonzero and still be
		// read as a successful run. Everything else that exits nonzero never
		// rewrote the file, and reporting {success: true, changed: false} there is
		// indistinguishable from "already formatted" — the #1336 silent no-op.
		const lenientOk =
			formatter.lenientExitCode !== undefined &&
			result.status !== null &&
			(formatter.lenientStatuses ?? []).includes(result.status);
		if (result.error || (result.status !== 0 && !lenientOk)) {
			return {
				success: false,
				changed: false,
				outcome: "failed",
				error:
					result.error?.message ||
					diagnosticTail(result.stderr) ||
					// biome, ktlint and `mix format` report on STDOUT; without this
					// their diagnostic is discarded and the user is told only that
					// the tool "exited with status 1".
					diagnosticTail(result.stdout) ||
					`${formatter.name} exited with status ${result.status}`,
			};
		}

		// Check if content changed
		const contentAfter = await fs.readFile(absolutePath, "utf-8");
		const changed = contentBefore !== contentAfter;

		return {
			success: true,
			changed,
			outcome: changed ? "formatted" : "unchanged",
		};
	} catch (err) {
		return {
			success: false,
			changed: false,
			outcome: "failed",
			error: err instanceof Error ? err.message : String(err),
		};
	}
}

export function listAllFormatters(): string[] {
	return ALL_FORMATTERS.map((f) => f.name);
}

clients/govulncheck-client.ts:
/**
 * govulncheck client for pi-lens
 *
 * Surfaces Go module CVEs that are actually reachable from the build graph.
 * Complements trivy-style \"all CVEs in any dep\" scanning by filtering to
 * vulnerabilities whose vulnerable function is called from the analyzed code.
 *
 * Lifecycle:
 *   - session_start scan + cache (keyed by go.sum mtime via cacheManager)
 *   - turn_end delta vs cached findings (mirrors KnipClient)
 *   - skipped silently if `govulncheck` is not on PATH (no auto-install in this
 *     slice — see issue #132 for the deferred `go-install` installer strategy)
 *
 * Invocation: `govulncheck -mode=source -format=json ./...` from the module root.
 *
 * Docs: https://pkg.go.dev/golang.org/x/vuln/cmd/govulncheck
 * Refs: #132
 */

import type { AnalysedRootSignal } from "./analysed-root.js";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { safeSpawnAsync, isAcceptedCommandFile } from "./safe-spawn.js";
import { probeToolAsync } from "./tool-probe.js";
import {
	firstOutputLine,
	spawnFailedWithNoOutput,
} from "./dispatch/runners/utils/spawn-outcome.js";
import { assertInstallAllowed } from "./project-trust.js";
import { SecurityScanClient } from "./security-scan-client.js";
import {
	classifyProbeFailure,
	describeProbeEvidence,
	INSTALL_TRANSIENT_MAX_ATTEMPTS,
	logAvailabilityDecision,
	startHostStallSampler,
} from "./dispatch/runners/utils/availability-policy.js";
import { recordDegradationOnce } from "./degradation-ledger.js";

// --- Types ---

export interface GovulncheckTraceFrame {
	module?: string;
	packageName?: string;
	functionName?: string;
	filename?: string;
	line?: number;
}

export interface GovulncheckFinding {
	osv: string;
	module?: string;
	packageName?: string;
	fixedVersion?: string;
	severity?: string;
	summary?: string;
	url?: string;
	trace: GovulncheckTraceFrame[];
}

export interface GovulncheckResult extends AnalysedRootSignal {
	success: boolean;
	findings: GovulncheckFinding[];
	scannedAt: string;
	summary?: string;
}

const EMPTY_RESULT: Omit<GovulncheckResult, "scannedAt"> = {
	success: false,
	findings: [],
};

const SCAN_TIMEOUT_MS = 120_000;
/** Budget for the `go install` auto-install, ms. */
const INSTALL_TIMEOUT_MS = 60_000;

// --- Internal: raw record shapes from govulncheck's JSON stream ---

interface RawTraceEntry {
	module?: string;
	package?: string;
	function?: string;
	position?: { filename?: string; line?: number };
}

interface RawFindingRecord {
	finding?: {
		osv?: string;
		fixed_version?: string;
		trace?: RawTraceEntry[];
	};
}

interface RawOsvRecord {
	osv?: {
		id?: string;
		summary?: string;
		details?: string;
		database_specific?: { url?: string };
		affected?: Array<{
			package?: { name?: string };
			database_specific?: { url?: string };
			ranges?: Array<{
				events?: Array<{ fixed?: string }>;
			}>;
		}>;
	};
}

// --- Client ---

export class GovulncheckClient extends SecurityScanClient<GovulncheckResult> {
	constructor(verbose = false) {
		super("govulncheck", verbose);
	}

	/**
	 * Detect whether the project root is a Go module. Cheap filesystem check.
	 */
	static hasGoModule(cwd: string): boolean {
		try {
			return fs.existsSync(path.join(cwd, "go.mod"));
		} catch {
			return false;
		}
	}

	/**
	 * Resolve `govulncheck`: PATH probe, then auto-install via `go install`
	 * (not the GitHub-release installer the other security clients use — the
	 * toolchain is present by definition when there's a go.mod).
	 */
	protected async doEnsureAvailable(): Promise<boolean> {
		// PATH probe first.
		if (await this.probeVersion(["-version"])) {
			this.available = true;
			return true;
		}
		if (this.probeWasTransient()) {
			// #1467: a timed-out/killed probe says nothing about whether
			// govulncheck is on PATH. Latching `false` here disabled it for the
			// life of the process; a `go install` here would be a heavyweight
			// reaction to a host hiccup. probeVersion has already recorded the
			// expiring verdict and its retry schedule (#1501) — re-marking it
			// here would double-escalate the cooldown. Retry later.
			this.log("govulncheck probe timed out; retrying later (not installing)");
			return false;
		}
		if (!assertInstallAllowed("govulncheck go install")) {
			// Deliberately NOT latching `available = false` (#1350 delta review):
			// trust denial is policy, not tool absence -- a later trust grant
			// (re-adopted at turn_start) must be able to retry the install, and
			// the cached false in ensureAvailable() would make denial permanent.
			return false;
		}

		// Not on PATH — auto-install via `go install`. This is safe to assume
		// here because the only path reaching `ensureAvailable()` is the
		// session_start task gated on `hasGoModule(analysisRoot)`; if the
		// project has a go.mod the user has the Go toolchain by definition.
		// Same shape as rust-clippy / cargo: lean on the language's own
		// install mechanism rather than adding a new installer strategy.
		const goProbeStartedAt = Date.now();
		const goSampler = startHostStallSampler();
		let goOnPath: Awaited<ReturnType<typeof safeSpawnAsync>>;
		let goHostStallMs: number;
		try {
			goOnPath = await probeToolAsync("go", ["version"], {
				timeout: 5000,
			});
		} finally {
			goHostStallMs = goSampler.stop();
		}
		if (goOnPath.error || goOnPath.status !== 0) {
			const { outcome, cause } = classifyProbeFailure(goOnPath, {
				hostStallMs: goHostStallMs,
			});
			if (outcome === "transient") {
				this.log("`go version` probe timed out; retrying govulncheck later");
				const retryAfterMs = this.markTransientlyUnavailable(cause);
				logAvailabilityDecision({
					tool: "govulncheck",
					verdict: "unavailable",
					outcome,
					cause,
					elapsedMs: Date.now() - goProbeStartedAt,
					latched: false,
					hostStallMs: goHostStallMs,
					...(retryAfterMs > 0 && { retryAfterMs }),
					budgetMs: 5000,
					classifiedBy: "probe",
				});
				return false;
			}
			this.log("go binary not on PATH — cannot auto-install govulncheck");
			// Derived from the `go version` probe above, and recorded with it: a
			// reader can see WHY govulncheck went quiet without re-running it (#1500).
			// The evidence names `go`, because that is what was spawned — a row that
			// carried go's errno unlabelled under `tool: "govulncheck"` invited the
			// exact misreading the field exists to prevent.
			this.noteDurableAbsence({
				...describeProbeEvidence(goOnPath, "go"),
				install: "not-attempted",
			});
			return false;
		}

		this.log("govulncheck not found, attempting auto-install via go install");
		const installStartedAt = Date.now();
		const installSampler = startHostStallSampler();
		let install: Awaited<ReturnType<typeof safeSpawnAsync>>;
		let installHostStallMs: number;
		try {
			install = await safeSpawnAsync(
				"go",
				["install", "golang.org/x/vuln/cmd/govulncheck@latest"],
				{ timeout: INSTALL_TIMEOUT_MS },
			);
		} finally {
			installHostStallMs = installSampler.stop();
		}
		if (install.error || install.status !== 0) {
			this.log(
				`govulncheck auto-install failed: ${(install.stderr ?? "").slice(0, 200)}`,
			);
			// #1476: `go install` runs against a 60 s budget over the network. A
			// timed-out or killed install says nothing about whether govulncheck
			// can ever be installed here, so it must not latch the durable
			// "tool is not installed" verdict the way a real install refusal does.
			// A non-zero exit (module not found, compile error) still latches:
			// that IS evidence about this machine, and retrying it every turn
			// would be a `go install` storm.
			const { outcome, cause } = classifyProbeFailure(install, {
				hostStallMs: installHostStallMs,
			});
			if (outcome === "transient") {
				// #1497: the retried operation here is a ≤60s network compile,
				// not a cheap probe, so it escalates on the install-class
				// schedule and latches at the attempt ceiling instead of
				// re-compiling every few minutes forever.
				const retryAfterMs = this.markTransientlyUnavailable(cause, {
					operationClass: "install",
				});
				const exhausted = retryAfterMs === 0;
				const ceilingReason = `go install timed out ${INSTALL_TRANSIENT_MAX_ATTEMPTS} times; install retries disabled until the next session`;
				if (exhausted) {
					// The symptom a user notices is an unexplained busy core, not a
					// missing tool — so the terminal verdict gets the louder record.
					// Once per session, matching the latch's own lifetime: both re-arm
					// at `session_start` (review F3).
					recordDegradationOnce({
						kind: "install-retry-exhausted",
						subject: "govulncheck",
						reason: ceilingReason,
					});
				}
				// One record per decision, so an install that keeps timing out is
				// readable in latency.log the same day (#1467's forensic trail).
				logAvailabilityDecision({
					tool: "govulncheck",
					verdict: "unavailable",
					outcome,
					// At the ceiling the latch rewrote the cause; a row still saying
					// `probe-timeout` would read as "cooling down" (#1497 review F5).
					cause: exhausted ? (this.latchedCause() ?? cause) : cause,
					elapsedMs: Date.now() - installStartedAt,
					latched: exhausted,
					hostStallMs: installHostStallMs,
					...(retryAfterMs > 0 && { retryAfterMs }),
					budgetMs: INSTALL_TIMEOUT_MS,
					// The ceiling verdict is an ASSERTION by this call site, not a
					// classification of one spawn, and #1534's convention is that such a
					// row says so and carries the install facts behind it. Every retry
					// DID run a `go install` that failed, so `install: "failed"` is
					// earned, and the reason names the ceiling rather than the spawn.
					// Below the ceiling, outcome/cause are fresh off `classifyProbeFailure`
					// above, so that row is still `"probe"` (#2209).
					classifiedBy: exhausted ? "caller" : "probe",
					...(exhausted && {
						evidence: {
							...describeProbeEvidence(install, "go install"),
							install: "failed" as const,
							installReason: ceilingReason,
						},
					}),
				});
				return false;
			}
			// A non-transient install failure (module not found, compile error) IS
			// evidence about this machine, so it latches — but the row says the
			// install was tried and failed, which a plain absence never does (#1500).
			this.noteDurableAbsence(
				{
					...describeProbeEvidence(install, "go install"),
					install: "failed",
				},
				{ elapsedMs: Date.now() - installStartedAt },
			);
			return false;
		}

		// `go install` writes to `$GOBIN` or `$GOPATH/bin`. The user may not
		// have that on `$PATH`. Re-probe by name (works when it is on PATH)
		// then fall back to the canonical bin dirs.
		const reprobeStartedAt = Date.now();
		const reprobeSampler = startHostStallSampler();
		let reprobe: Awaited<ReturnType<typeof safeSpawnAsync>>;
		let reprobeHostStallMs: number;
		try {
			reprobe = await probeToolAsync("govulncheck", ["-version"], {
				timeout: 5000,
			});
		} finally {
			reprobeHostStallMs = reprobeSampler.stop();
		}
		if (!reprobe.error && reprobe.status === 0) {
			this.log("govulncheck auto-installed and found on PATH");
			this.available = true;
			// The initial PATH probe already wrote a latched `unavailable` row
			// (#1500's own assertion doesn't fire here — the reprobe SUCCEEDED —
			// but that first probe's verdict still logged, before `go install`
			// ever ran). Without a compensating row here, the durable record says
			// govulncheck is off when `go install` just put it on PATH (#1606).
			logAvailabilityDecision({
				tool: "govulncheck",
				verdict: "available",
				outcome: "success",
				cause: "ok",
				elapsedMs: Date.now() - reprobeStartedAt,
				latched: true,
				hostStallMs: reprobeHostStallMs,
				budgetMs: 5000,
				classifiedBy: "caller",
				evidence: {
					install: "succeeded",
					binary: "govulncheck",
					source: "go-install",
				},
			});
			return true;
		}

		// Look in the canonical install locations and remember the absolute
		// path so subsequent invocations spawn against it directly.
		const homeDir = os.homedir();
		const isWin = process.platform === "win32";
		const ext = isWin ? ".exe" : "";
		const candidates = [
			process.env.GOBIN,
			process.env.GOPATH ? path.join(process.env.GOPATH, "bin") : undefined,
			path.join(homeDir, "go", "bin"),
		]
			.filter((d): d is string => Boolean(d))
			.map((d) => path.join(d, `govulncheck${ext}`));
		for (const candidate of candidates) {
			try {
				if (isAcceptedCommandFile(candidate)) {
					this.binaryPath = candidate;
					this.available = true;
					this.log(`govulncheck auto-installed at ${candidate}`);
					// Same compensating row as the on-PATH reprobe arm above (#1606):
					// the initial probe already latched `unavailable`, and this arm
					// is the OTHER way to recover — the canonical $GOBIN/$GOPATH walk
					// found it after the on-PATH reprobe missed.
					logAvailabilityDecision({
						tool: "govulncheck",
						verdict: "available",
						outcome: "success",
						cause: "ok",
						elapsedMs: Date.now() - installStartedAt,
						latched: true,
						classifiedBy: "caller",
						evidence: {
							install: "succeeded",
							binary: path.basename(candidate),
							source: "go-install",
						},
					});
					return true;
				}
			} catch {
				// fall through to next candidate
			}
		}

		// The install SUCCEEDED, so the tool is on this machine somewhere. If the
		// re-probe merely timed out, latching "not installed" would be the #1467
		// mistake one step later in the same function (#1476).
		const { outcome, cause } = classifyProbeFailure(reprobe, {
			hostStallMs: reprobeHostStallMs,
		});
		if (outcome === "transient") {
			this.log(
				"govulncheck installed but the re-probe timed out; retrying later",
			);
			const retryAfterMs = this.markTransientlyUnavailable(cause);
			logAvailabilityDecision({
				tool: "govulncheck",
				verdict: "unavailable",
				outcome,
				cause,
				// The re-probe's own wall time. A hard-coded 0 here was the #1474
				// defect verbatim: a duration field that measures nothing.
				elapsedMs: Date.now() - reprobeStartedAt,
				latched: false,
				hostStallMs: reprobeHostStallMs,
				...(retryAfterMs > 0 && { retryAfterMs }),
				budgetMs: 5000,
				classifiedBy: "probe",
			});
			return false;
		}
		// The third silent arm (#1500 review): the install SUCCEEDED and the binary
		// is nowhere the re-probe or the canonical bin dirs could find it. That is a
		// durable, actionable fact — and until now it latched with no record at all,
		// so a $GOBIN misconfiguration was indistinguishable from govulncheck simply
		// not being installed. `install: "succeeded"` also appears on the two success
		// arms above (#1606's compensating `available` rows) — this is the durable
		// FAILURE counterpart, an install that worked but left nothing locatable.
		this.log(
			"govulncheck auto-install succeeded but binary not locatable — check $GOBIN / $GOPATH",
		);
		this.noteDurableAbsence(
			{
				...describeProbeEvidence(reprobe, "govulncheck"),
				install: "succeeded",
				installReason:
					"installed binary not found on PATH, $GOBIN or $GOPATH/bin",
			},
			{ elapsedMs: Date.now() - reprobeStartedAt },
		);
		return false;
	}

	/**
	 * Scan a Go module for reachable CVEs.
	 *
	 * Re-entrancy safe: concurrent calls against the same root share a single
	 * govulncheck process. Mirrors the in-flight dedupe pattern used by
	 * KnipClient / JscpdClient.
	 */
	async analyze(cwd: string): Promise<GovulncheckResult> {
		const targetDir = path.resolve(cwd);

		if (!GovulncheckClient.hasGoModule(targetDir)) {
			return {
				...EMPTY_RESULT,
				success: true,
				scannedAt: new Date().toISOString(),
				summary: "No go.mod found at analysis root; govulncheck skipped",
			};
		}

		if (!(await this.ensureAvailable())) {
			return {
				...EMPTY_RESULT,
				scannedAt: new Date().toISOString(),
				summary: "govulncheck not installed",
			};
		}

		return this.dedupeScan(targetDir, () => this.runScan(targetDir));
	}

	private async runScan(cwd: string): Promise<GovulncheckResult> {
		const scannedAt = new Date().toISOString();
		const bin = this.binaryPath ?? "govulncheck";
		try {
			const result = await safeSpawnAsync(
				bin,
				["-mode=source", "-format=json", "./..."],
				{ cwd, timeout: SCAN_TIMEOUT_MS },
			);

			// #2154 v4 F1: this was the one runner client with no `result.error`
			// check before its parse site. `safeSpawnAsync` reports a timeout or
			// an ambient abort as `{status: null, error, stdout: <partial>}`, and
			// the old guard (`!stdout.trim() && status !== 0 && status !== 3`)
			// let that partial stream through as an authoritative scan. Same
			// order as the seven sibling clients: the process first, its output
			// second.
			if (result.error) {
				this.log(`Scan error: ${result.error.message}`);
				return {
					...EMPTY_RESULT,
					scannedAt,
					summary: result.error.message.slice(0, 200),
				};
			}

			// govulncheck exits non-zero (status 3) when vulnerabilities are
			// found — that's success from our perspective. Any other exit code
			// means the scan was not analysed, even if its config preamble or
			// partial stream reached stdout before the failure.
			const rawStdout = result.stdout ?? "";
			if (result.status !== 0 && result.status !== 3) {
				return {
					...EMPTY_RESULT,
					scannedAt,
					summary: firstOutputLine(result.stderr) || "scan failed",
				};
			}
			if (!rawStdout.trim()) {
				// Nothing to parse. `govulncheck -format=json` always writes a
				// stream (a `config` record at minimum), so an empty one is never
				// evidence of "no vulnerabilities" — it must not retire a retained
				// CVE finding, whatever the exit code. `spawnFailedWithNoOutput`
				// is the same shared discriminator knip and dead-code use, in
				// place of this file's hand-rolled status test.
				if (spawnFailedWithNoOutput(result, rawStdout)) {
					this.log(`Scan failed: ${(result.stderr ?? "").slice(0, 200)}`);
					return {
						...EMPTY_RESULT,
						scannedAt,
						summary: firstOutputLine(result.stderr) || "scan failed",
					};
				}
				return {
					...EMPTY_RESULT,
					success: true,
					scannedAt,
					summary: "govulncheck produced no output; nothing parsed",
				};
			}

			const findings = parseGovulncheckJson(rawStdout);
			// #2154: the one govulncheck site that parsed a scan of this root.
			return {
				success: true,
				analyzed: true,
				findings,
				scannedAt,
			};
		} catch (err) {
			this.log(`Scan error: ${err instanceof Error ? err.message : err}`);
			return {
				...EMPTY_RESULT,
				scannedAt,
				summary: err instanceof Error ? err.message.slice(0, 200) : String(err),
			};
		}
	}
}

// --- Parser ---

/**
 * Parse govulncheck's `-format=json` stream into a clean finding list.
 *
 * The stream is a series of newline-or-brace-separated JSON objects of
 * mixed type:
 *   - `{"config": {...}}`     — DB / Go version
 *   - `{"progress": {...}}`   — scan progress
 *   - `{"osv": {...}}`        — vulnerability metadata (we extract module +
 *                                fixed version + summary + URL here)
 *   - `{"finding": {...}}`    — actual reachable finding (we extract the
 *                                osv id + trace)
 *
 * We extract OSV metadata first and then enrich each Finding with the
 * matching osv's `summary` / `fixed_version` / `url`. A single Finding
 * record from govulncheck has only the OSV id + trace, so this two-pass
 * approach is required to produce the structured shape the runner / UI
 * consumes.
 *
 * Exported for unit tests.
 */
export function parseGovulncheckJson(stream: string): GovulncheckFinding[] {
	if (!stream.trim()) return [];

	const records = splitJsonStream(stream);
	const osvMeta = new Map<
		string,
		{
			module?: string;
			fixedVersion?: string;
			summary?: string;
			url?: string;
		}
	>();
	const findings: GovulncheckFinding[] = [];

	for (const record of records) {
		const asOsv = record as RawOsvRecord;
		if (asOsv.osv && typeof asOsv.osv.id === "string") {
			const affected = asOsv.osv.affected?.[0];
			const packageName = affected?.package?.name;
			const fixedVersion = affected?.ranges
				?.flatMap((r) => r.events ?? [])
				.find((e) => typeof e.fixed === "string")?.fixed;
			osvMeta.set(asOsv.osv.id, {
				module: packageName,
				fixedVersion,
				summary: asOsv.osv.summary ?? asOsv.osv.details,
				url:
					asOsv.osv.database_specific?.url ?? affected?.database_specific?.url,
			});
		}
	}

	for (const record of records) {
		const asFinding = record as RawFindingRecord;
		const f = asFinding.finding;
		if (!f || typeof f.osv !== "string") continue;
		const trace: GovulncheckTraceFrame[] = (f.trace ?? []).map((t) => ({
			module: t.module,
			packageName: t.package,
			functionName: t.function,
			filename: t.position?.filename,
			line: t.position?.line,
		}));
		const meta = osvMeta.get(f.osv);
		findings.push({
			osv: f.osv,
			module: meta?.module,
			packageName: trace.find((t) => t.packageName)?.packageName,
			fixedVersion: f.fixed_version ?? meta?.fixedVersion,
			summary: meta?.summary,
			url: meta?.url,
			trace,
		});
	}

	// Dedupe: govulncheck may emit multiple finding records per OSV when the
	// vulnerable function is called from several call sites. Collapse to one
	// finding per OSV ID, preserving the *first* trace (deepest call-site
	// attribution is what the agent needs).
	const seen = new Set<string>();
	const deduped: GovulncheckFinding[] = [];
	for (const f of findings) {
		if (seen.has(f.osv)) continue;
		seen.add(f.osv);
		deduped.push(f);
	}
	return deduped;
}

/**
 * Parse govulncheck's JSON-stream output into structured records.
 *
 * govulncheck's `-format=json` emits one top-level JSON object per logical
 * record, but the framing is informal: most records arrive on their own
 * line, some are concatenated on one line, and corrupt / truncated lines
 * can appear when the scan is interrupted.
 *
 * Strategy:
 *  1. Try a fast line-by-line `JSON.parse` first — handles the dominant
 *     newline-delimited case and rejects malformed lines without letting
 *     them poison downstream records.
 *  2. If any line fails to parse cleanly, fall back to a brace-depth
 *     scanner over that line — handles records that have been
 *     concatenated together without newlines.
 *  3. Malformed slices are dropped rather than failing the whole scan.
 */
function splitJsonStream(stream: string): unknown[] {
	const records: unknown[] = [];
	for (const rawLine of stream.split(/\r?\n/)) {
		const line = rawLine.trim();
		if (!line) continue;
		try {
			records.push(JSON.parse(line));
			continue;
		} catch {
			// Fall through to the multi-object brace scanner.
		}
		for (const obj of extractBalancedObjects(line)) {
			records.push(obj);
		}
	}
	return records;
}

function extractBalancedObjects(input: string): unknown[] {
	const found: unknown[] = [];
	let depth = 0;
	let start = -1;
	let inString = false;
	let escape = false;

	for (let i = 0; i < input.length; i++) {
		const ch = input[i];

		if (escape) {
			escape = false;
			continue;
		}
		if (inString) {
			if (ch === "\\") escape = true;
			else if (ch === '"') inString = false;
			continue;
		}
		if (ch === '"') {
			inString = true;
			continue;
		}

		if (ch === "{") {
			if (depth === 0) start = i;
			depth++;
		} else if (ch === "}") {
			depth--;
			if (depth === 0 && start !== -1) {
				const slice = input.slice(start, i + 1);
				try {
					found.push(JSON.parse(slice));
				} catch {
					// Drop the malformed slice; keep scanning for the next
					// balanced object so a corrupt prefix doesn't poison the
					// remainder of the line.
				}
				start = -1;
			} else if (depth < 0) {
				// Stray `}` — reset and resume.
				depth = 0;
				start = -1;
			}
		}
	}

	return found;
}

