/**
 * Node.js package-manager resolution and command building.
 *
 * Single source of truth for "which package manager should we use here, and how
 * do we spell each command (run script / install / exec / global bin) for it".
 * Supports npm, pnpm, yarn and bun so pi-lens works on whatever manager the
 * machine actually ships.
 *
 * Resolution order (see `resolveNodePackageManager`):
 *   1. What the project declares — lockfile, then the corepack `packageManager`
 *      field — *if that manager is actually installed*.
 *   2. Otherwise the first installed manager in `PREFERENCE` (npm first for
 *      maximum compatibility, bun last).
 *   3. `npm` as a final fallback so callers always get a usable value.
 */

import * as fs from "node:fs";
import { BoundedFifoMap } from "./bounded-cache.js";
import * as os from "node:os";
import * as path from "node:path";
import { resolve as resolvePath } from "node:path";
import {
	type AvailabilityLatch,
	type AvailabilityOutcome,
	type AvailabilityCause,
	classifyProbeFailure,
	createAvailabilityLatch,
	isTransientDecision,
	logAvailabilityDecision,
	startHostStallSampler,
} from "./dispatch/runners/utils/availability-policy.js";
import {
	safeSpawnAsync,
	getPathExts,
	isAcceptedCommandFile,
} from "./safe-spawn.js";
import { probeToolAsync } from "./tool-probe.js";
import { createAvailabilityProbeFlight } from "./availability-probe-flight.js";
import {
	createGenerationSource,
	type GenerationHandle,
} from "./generation-guard.js";
import {
	isAtOrAboveHomeDir,
	isUnderCanonicalDir,
	isUnderDir,
	normalizeFilePath,
	pathsEqual,
	realpathOrResolve,
	walkUpDirs,
} from "./path-utils.js";
import { getProjectTrustState } from "./project-trust.js";
import {
	getDegradationLedgerGeneration,
	recordDegradationOnce,
} from "./degradation-ledger.js";
import { logExtension } from "./extension-log.js";

export type NodePackageManager = "npm" | "pnpm" | "yarn" | "bun";

/**
 * Fallback preference when nothing is declared (or the declared manager is
 * missing). npm first for maximum compatibility; bun last. A project lockfile
 * always overrides this order.
 */
const PREFERENCE: readonly NodePackageManager[] = [
	"npm",
	"pnpm",
	"yarn",
	"bun",
];

const packageManagerProbeFlights =
	createAvailabilityProbeFlight<
		Awaited<ReturnType<typeof probeAvailability>>
	>();

function onWindows(): boolean {
	return process.platform === "win32";
}

function isNodePackageManager(value: string): value is NodePackageManager {
	return (
		value === "npm" || value === "pnpm" || value === "yarn" || value === "bun"
	);
}

// ============================================================================
// DETECTION
// ============================================================================

/**
 * Detect the package manager a Node.js project declares, without checking
 * whether it is installed. Lockfiles win over the corepack `packageManager`
 * field. Returns `undefined` when the project makes no declaration.
 */
export function detectNodePackageManager(
	targetPath: string,
): NodePackageManager | undefined {
	if (
		fs.existsSync(path.join(targetPath, "bun.lockb")) ||
		fs.existsSync(path.join(targetPath, "bun.lock"))
	) {
		return "bun";
	}
	if (fs.existsSync(path.join(targetPath, "pnpm-lock.yaml"))) {
		return "pnpm";
	}
	if (fs.existsSync(path.join(targetPath, "yarn.lock"))) {
		return "yarn";
	}
	if (fs.existsSync(path.join(targetPath, "package-lock.json"))) {
		return "npm";
	}
	return readPackageManagerField(targetPath);
}

/** Read the corepack `"packageManager": "pnpm@8.15.0"` field from package.json. */
function readPackageManagerField(
	targetPath: string,
): NodePackageManager | undefined {
	try {
		const pkgPath = path.join(targetPath, "package.json");
		if (!fs.existsSync(pkgPath)) return undefined;
		const pkg = JSON.parse(fs.readFileSync(pkgPath, "utf-8")) as {
			packageManager?: unknown;
		};
		if (typeof pkg.packageManager !== "string") return undefined;
		const name = pkg.packageManager.split("@")[0].trim().toLowerCase();
		return isNodePackageManager(name) ? name : undefined;
	} catch {
		return undefined;
	}
}

// ============================================================================
// AVAILABILITY (cached per process; reset in tests)
// ============================================================================

/**
 * Budget for the `where`/`which <pm>` probe. Matches the previous
 * `isCommandAvailableAsync` default so the observable timing is unchanged.
 */
const PROBE_TIMEOUT_MS = 5_000;

/**
 * A timed-out probe used to be memoized as a permanent `false` — the process
 * would silently downgrade a declared pnpm/yarn manager to npm for its whole
 * life. The blast radius was internal: this resolver only serves installs
 * into pi-lens's own managed tools directory and `pilens_rebuild` on a
 * pi-lens source checkout, never a user project's lockfile (#1496). Each
 * manager now sits behind the shared transient-aware latch (#1467/#1476):
 * only a genuine absence (`where`/`which` exits non-zero, or ENOENT) latches;
 * a timeout, abort or host stall expires on a cooldown and is re-probed.
 */
/**
 * #4530 round 9: the availability of a package manager now depends on project
 * trust (a manager reachable only through an untrusted project's PATH is not
 * available), so the latch and the in-flight probe are keyed by the trust
 * scope as well as the manager. `turn_start` re-adopts the host's answer, and a
 * flip reads the other scope's keys — empty, so the next lookup re-probes —
 * instead of serving a verdict the other trust state produced.
 */
function trustScope(): "trusted" | "scoped" {
	return getProjectTrustState() === "trusted" ? "trusted" : "scoped";
}

function availabilityKey(pm: NodePackageManager, cwd: string): string {
	return `${trustScope()}:${normalizeFilePath(cwd)}:${pm}`;
}

const availabilityLatches = new BoundedFifoMap<string, AvailabilityLatch>(8);

function getLatch(key: string): AvailabilityLatch {
	let latch = availabilityLatches.get(key);
	if (!latch) {
		latch = createAvailabilityLatch();
		availabilityLatches.set(key, latch);
	}
	return latch;
}

/**
 * Whether `pm` can run. `key` is captured by the caller (with the manager that
 * goes with it) so a trust flip during an awaited probe cannot make a later
 * stage read a latch it did not start under (defect shapes 19 and 58).
 */
async function probeAvailability(
	pm: NodePackageManager,
	key: string,
	cwd: string,
): Promise<{
	available: boolean;
	outcome: AvailabilityOutcome;
	cause: AvailabilityCause;
}> {
	const latch = getLatch(key);
	const startedAt = Date.now();
	const finder = onWindows() ? "where" : "which";
	const sampler = startHostStallSampler();
	let result: Awaited<ReturnType<typeof safeSpawnAsync>>;
	let hostStallMs: number;
	try {
		// #4530: the lookup resolves through the trust-scoped PATH.
		const env = trustScopedSpawnEnv(cwd);
		result = await probeToolAsync(finder, [pm], {
			timeout: PROBE_TIMEOUT_MS,
			...(env && { env }),
		});
	} finally {
		hostStallMs = sampler.stop();
	}
	const elapsedMs = Date.now() - startedAt;

	if (result.status === 0 && !result.error) {
		latch.noteAvailable();
		logAvailabilityDecision({
			tool: pm,
			verdict: "available",
			outcome: "success",
			cause: "ok",
			elapsedMs,
			latched: true,
			hostStallMs,
			budgetMs: PROBE_TIMEOUT_MS,
			classifiedBy: "probe",
		});
		return { available: true, outcome: "success", cause: "ok" };
	}

	const { outcome, cause, evidence } = classifyProbeFailure(result, {
		hostStallMs,
		// Preserve pre-#1496 meaning for anything the classifier can't place: a
		// present manager that rejects its probe is durable, same as before.
		unclassifiedFailureOutcome: "missing",
	});
	const retryAfterMs = latch.noteUnavailable(outcome, cause);
	logAvailabilityDecision({
		tool: pm,
		verdict: "unavailable",
		outcome,
		cause,
		elapsedMs,
		latched: outcome !== "transient",
		hostStallMs,
		...(retryAfterMs > 0 && { retryAfterMs }),
		budgetMs: PROBE_TIMEOUT_MS,
		classifiedBy: "probe",
		evidence,
	});
	return { available: false, outcome, cause };
}

/**
 * Resolve whether `pm` is available. `onTransient`, when given, fires
 * whenever the resolved `false` came from a probe that never got a fair
 * hearing (a stall, an abort, a host-level failure classified `transient` by
 * `classifyProbeFailure`) rather than a genuine absence — including when that
 * verdict is served from the latch's own cooldown-bounded memo, not just on a
 * fresh probe (#1585).
 *
 * Before this, the return type was a bare boolean: a caller like
 * `allAvailableGlobalBinDirs` could not tell "pnpm isn't installed" from
 * "the `where pnpm` probe stalled", so a transient miss silently dropped
 * pnpm's global bin dir with no way to flag the result as provisional —
 * exactly the boolean-collapse `getToolPath`'s `onTransient` plumbing (#1569)
 * was built to avoid, one layer up.
 */
function isAvailable(
	pm: NodePackageManager,
	cwd: string,
	onTransient?: () => void,
): Promise<boolean> {
	const key = availabilityKey(pm, cwd);
	const latch = getLatch(key);

	const reportIfTransient = (result: boolean): boolean => {
		if (!result && isTransientDecision({ outcome: latch.getOutcome() })) {
			onTransient?.();
		}
		return result;
	};

	const memo = latch.read();
	if (memo !== null) return Promise.resolve(reportIfTransient(memo));

	// A verdict can now expire, so concurrent callers arriving just after a
	// cooldown must share ONE probe rather than each spawning their own.
	const shared = packageManagerProbeFlights.run(key, () =>
		probeAvailability(pm, key, cwd),
	);
	return shared.promise.then(({ available, outcome }) => {
		// #4566: a joiner's latch may have been evicted while this flight ran.
		if (isTransientDecision({ outcome })) onTransient?.();
		return available;
	});
}

/**
 * Clear the process-wide availability cache: pnpm/yarn/bun/npm each sit
 * behind their own module-local `AvailabilityLatch` in `availabilityLatches`,
 * so `resetDispatchAvailabilityState`'s generation counter (the mechanism
 * most dispatch runners inherit) never reaches them — the same shape as
 * psscriptanalyzer's (#1490) and zizmor's (#1535) module-local latches.
 * Without this wired into `session_start`, a genuine "pnpm is missing"
 * verdict from one session stayed latched into the next: install pnpm mid
 * day, start a fresh session, pi-lens still reports it missing until a
 * process restart (#1653). Called from `handleSessionStart`'s per-session
 * reset block beside `resetZizmorTokenAvailability()` /
 * `resetPsScriptAnalyzerAvailability()`; also used directly by tests. Also
 * clears `globalBinDirCache`, whose memo lifetime rides the same reset — it
 * must not outlive the availability verdicts it was derived from (#1602).
 */
export function _resetPackageManagerCache(): void {
	packageManagerCacheGeneration.bump();
	availabilityLatches.clear();
	packageManagerProbeFlights.clear();
	globalBinDirCache.clear();
	globalBinDirProbeFlights.clear();
}

// ============================================================================
// RESOLUTION
// ============================================================================

/**
 * Resolve which package manager to use for `cwd`: the project's declared manager
 * if installed, otherwise the first installed manager in `PREFERENCE`, otherwise
 * `npm`.
 */
export async function resolveNodePackageManager(
	cwd: string = process.cwd(),
): Promise<NodePackageManager> {
	const declared = detectNodePackageManager(cwd);
	if (declared && (await isAvailable(declared, cwd))) {
		return declared;
	}
	for (const pm of PREFERENCE) {
		if (await isAvailable(pm, cwd)) return pm;
	}
	return "npm";
}

// ============================================================================
// COMMAND BUILDERS
// ============================================================================

/** Platform-specific executable name (`.cmd`/`.exe` on Windows). */
export function pmBinary(pm: NodePackageManager): string {
	if (!onWindows()) return pm;
	return pm === "bun" ? "bun.exe" : `${pm}.cmd`;
}

/** Args to run a package.json script — `run <script>` works for all managers. */
export function runScriptArgs(script: string): string[] {
	return ["run", script];
}

export interface InstallOptions {
	/** Skip lifecycle scripts (`--ignore-scripts`). */
	ignoreScripts?: boolean;
	/** npm-only escape hatch for peer-dep conflicts (`--legacy-peer-deps`). */
	legacyPeerDeps?: boolean;
}

/**
 * Args to install a single package. npm uses `install`; pnpm/yarn/bun use `add`.
 * `--legacy-peer-deps` is npm-only and silently dropped for other managers.
 */
export function installArgs(
	pm: NodePackageManager,
	pkg: string,
	options: InstallOptions = {},
): string[] {
	const args = [pm === "npm" ? "install" : "add"];
	if (options.ignoreScripts) args.push("--ignore-scripts");
	if (options.legacyPeerDeps && pm === "npm") args.push("--legacy-peer-deps");
	args.push(pkg);
	return args;
}

/**
 * Args to re-resolve an already-declared dependency to the newest version its
 * recorded range still permits. npm/pnpm/bun spell this `update`; yarn classic
 * spells it `upgrade`.
 *
 * This is the command that repairs a dependency frozen by its own lockfile.
 * `installArgs` re-runs the install, and a lockfile entry that already
 * satisfies the range makes that a no-op: pi-lens's managed tools tree stayed
 * on the version written at first install for the life of the machine even
 * though the declared caret range permitted 28 newer minors (#1730).
 */
export function updateArgs(
	pm: NodePackageManager,
	pkg: string,
	options: Pick<InstallOptions, "ignoreScripts"> = {},
): string[] {
	const args = [pm === "yarn" ? "upgrade" : "update"];
	if (options.ignoreScripts) args.push("--ignore-scripts");
	args.push(pkg);
	return args;
}

// ============================================================================
// GLOBAL BIN DISCOVERY
// ============================================================================

/**
 * Per-manager global bin dir, memoized for the process (cleared alongside
 * `availabilityLatches` in `_resetPackageManagerCache`). Only a SUCCESSFUL
 * lookup is cached: a spawn failure here is evidence about this call, not
 * about the manager (the manager already passed `isAvailable`'s own probe),
 * so it must not latch an empty result the way a genuine absence would. The
 * generation guard owns post-await cache publication, so a probe crossing
 * a session reset cannot repopulate the fresh memo. Reset clears the flight
 * map separately, so later callers cannot share the pre-reset probe.
 */
// Keyed by trust scope too (#4530): a scoped query answers differently.
const globalBinDirCache = new BoundedFifoMap<string, string[]>(8);
const packageManagerCacheGeneration = createGenerationSource(
	"package-manager-global-bin",
);
const globalBinDirProbeFlights = createAvailabilityProbeFlight<string[]>();

/** Directories where a given manager installs global binaries. */
async function globalBinDirsFor(
	pm: NodePackageManager,
	cwd: string,
): Promise<string[]> {
	const key = availabilityKey(pm, cwd);
	const cached = globalBinDirCache.get(key);
	if (cached) return cached;
	const generation = packageManagerCacheGeneration.capture();

	// Concurrent callers (dispatch runs several tools per edit) must share ONE
	// probe rather than each spawning their own `npm config get prefix` (#1602).
	const shared = globalBinDirProbeFlights.run(key, () =>
		probeGlobalBinDirs(pm, key, generation, cwd),
	);
	return shared.promise;
}

async function probeGlobalBinDirs(
	pm: NodePackageManager,
	key: string,
	generation: GenerationHandle,
	cwd: string,
): Promise<string[]> {
	if (pm === "bun") {
		// bun has no per-call query cost — the global bin dir is deterministic.
		const base = process.env.BUN_INSTALL || path.join(os.homedir(), ".bun");
		const dirs = [path.join(base, "bin")];
		generation.guardedWrite(key, () => {
			globalBinDirCache.set(key, dirs);
		});
		return dirs;
	}

	const query =
		pm === "npm"
			? ["config", "get", "prefix"]
			: pm === "pnpm"
				? ["bin", "-g"]
				: ["global", "bin"]; // yarn
	// #4530: under an untrusted project the query resolves through the
	// trust-scoped PATH and runs from HOME, so project configuration cannot
	// redirect a global lookup.
	const env = trustScopedSpawnEnv(cwd);
	const res = await safeSpawnAsync(pmBinary(pm), query, {
		timeout: 5000,
		...(env && { env, cwd: os.homedir() }),
	});
	if (res.status !== 0 || res.error) return [];
	const out = res.stdout.trim();
	if (!out) return [];

	// npm reports a prefix; binaries live in `<prefix>/bin` on Unix, `<prefix>`
	// on Windows. pnpm/yarn already print the bin dir directly.
	const dirs =
		pm === "npm" ? [onWindows() ? out : path.join(out, "bin")] : [out];
	generation.guardedWrite(key, () => {
		globalBinDirCache.set(key, dirs);
	});
	return dirs;
}

/**
 * Global bin directories for every installed manager, deduped. Used to locate a
 * globally-installed tool binary when PATH is stale (e.g. right after an
 * `install -g`) or when the tool was installed via a non-npm manager.
 *
 * `onTransient`, when given, fires once per manager whose `isAvailable` probe
 * was transient (stalled/unspawnable, not a genuine absence) — the boolean
 * `allAvailableGlobalBinDirs` returns can't itself distinguish "not
 * installed" from "couldn't tell", so a caller that persists this result
 * needs the callback to know the answer may be incomplete (#1585).
 */
export async function allAvailableGlobalBinDirs(
	onTransient?: () => void,
	cwd: string = process.cwd(),
): Promise<string[]> {
	const dirs: string[] = [];
	const seen = new Set<string>();
	for (const pm of PREFERENCE) {
		if (!(await isAvailable(pm, cwd, onTransient))) continue;
		for (const dir of await globalBinDirsFor(pm, cwd)) {
			const normalized = path.resolve(dir);
			if (seen.has(normalized)) continue;
			seen.add(normalized);
			// #4530: a global bin dir that reaches an untrusted project is no
			// global one.
			if (trustScopedPath(normalized, cwd) !== normalized) continue;
			dirs.push(normalized);
		}
	}
	return dirs;
}

/**
 * Locate a globally-installed tool binary across every installed manager's
 * global bin dir (npm/pnpm/yarn/bun) by direct file lookup — no spawn, no PATH
 * reliance. Returns the full path, or `undefined` if not found.
 *
 * This is the manager-agnostic replacement for a bare `<tool> --version` PATH
 * probe: it finds tools installed via `pnpm add -g` / `bun add -g` (whose bin
 * dirs are often not on PATH) and survives the PATH-cache staleness that follows
 * an `install -g`. On Windows it checks the `.cmd` shim, then `.exe`, then the
 * remaining PATHEXT suffixes and bare name; on Unix just the bare name.
 */
export async function findGlobalBinary(
	command: string,
	windowsExt = ".cmd",
	cwd: string = process.cwd(),
): Promise<string | undefined> {
	const candidates = onWindows()
		? [...new Set([windowsExt, ".exe", ...getPathExts(process.env), ""])].map(
				(ext) => `${command}${ext}`,
			)
		: [command];
	try {
		for (const binDir of await allAvailableGlobalBinDirs(undefined, cwd)) {
			for (const name of candidates) {
				const full = path.join(binDir, name);
				if (!isAcceptedCommandFile(full)) continue;
				// #4530 round 9: the directory is outside the project, but the file
				// it holds can still be a link into it (an npm-linked language
				// server, say), and `isAcceptedCommandFile` follows that link. The
				// trust verdict therefore belongs to the target, not the directory.
				if (commandResolvesIntoProject(full, cwd)) {
					refuseGlobalCommandTarget(full);
					continue;
				}
				return full;
			}
		}
	} catch {
		// Manager probes can fail (missing binary, spawn error) — treat as "not
		// found" so callers fall through to their next resolution step.
	}
	return undefined;
}

/**
 * The three project-local bin-directory shapes in this repo, most-preferred
 * first. Exported so every caller passes the SAME constant instead of
 * re-listing the directory names next to its own copy of the walk — the venv
 * list alone had three independent spellings before #2544 review F1
 * (`formatters.ts`, `runner-helpers.ts`'s `createVenvFinder`,
 * `dead-code-client.ts`'s `venvCandidates`).
 *
 * `VENV_BIN_DIRS` lists BOTH the POSIX (`bin`) and Windows (`Scripts`) layouts
 * unconditionally rather than branching on `process.platform` at module load:
 * a module-load platform constant cannot be forced per test, so the other
 * branch is never exercised on the ubuntu lane (defect shape 30). The extra
 * two `existsSync` calls per directory are the price of a testable list, and
 * a `.venv/Scripts` on Linux (or `.venv/bin` under msys) resolves correctly
 * instead of being invisible.
 */
export const NODE_MODULES_BIN_DIRS: readonly string[] = [
	path.join("node_modules", ".bin"),
];
export const VENDOR_BIN_DIRS: readonly string[] = [path.join("vendor", "bin")];
export const VENV_BIN_DIRS: readonly string[] = [
	path.join(".venv", "bin"),
	path.join("venv", "bin"),
	path.join(".venv", "Scripts"),
	path.join("venv", "Scripts"),
];

/** Every project-local bin layout supported by the canonical resolver above. */
export const PROJECT_LOCAL_BIN_DIRS: readonly string[] = [
	...NODE_MODULES_BIN_DIRS,
	...VENDOR_BIN_DIRS,
	...VENV_BIN_DIRS,
];

/** A local candidate was present, but pi's trust policy refused its use. */
export interface LocalBinTrustRefusal {
	readonly kind: "refused-by-trust";
	readonly tool: string;
	readonly root: string;
	readonly trust: "untrusted" | "unknown";
}

export type LocalBinLookup = string | LocalBinTrustRefusal;

export function isLocalBinTrustRefusal(
	value: LocalBinLookup | undefined,
): value is LocalBinTrustRefusal {
	return (
		typeof value === "object" &&
		value !== null &&
		value.kind === "refused-by-trust"
	);
}

export function localBinPath(
	value: LocalBinLookup | undefined,
): string | undefined {
	return typeof value === "string" ? value : undefined;
}

function refuseLocalBin(tool: string, root: string): LocalBinTrustRefusal {
	const trust = getProjectTrustState() as "untrusted" | "unknown";
	const resolvedRoot = resolvePath(root);
	const subject = `project-local-binary:${resolvedRoot}:${tool}`;
	if (
		recordDegradationOnce({
			kind: "trust-refusal",
			subject,
			reason: `project-local binary refused: pi project trust is ${trust}`,
		})
	) {
		logExtension({
			subsystem: "project-trust",
			level: "warn",
			message:
				"project-local binary refused: mark the project trusted in pi or upgrade pi",
			metadata: { tool, root: resolvedRoot, trust },
		});
	}
	return { kind: "refused-by-trust", tool, root: resolvedRoot, trust };
}

/** Every project-local bin dir of `cwd` and its ancestors below HOME. */
function* projectLocalBinDirs(cwd: string): Generator<string> {
	for (const ancestor of walkUpDirs(cwd)) {
		if (isAtOrAboveHomeDir(ancestor, os.homedir())) return;
		for (const binDir of PROJECT_LOCAL_BIN_DIRS)
			yield path.join(ancestor, binDir);
	}
}

/** Keep trust classification beside the resolver's canonical directory set. */
export function isProjectLocalBinPath(
	resolvedCommand: string,
	cwd: string,
): boolean {
	for (const binDir of projectLocalBinDirs(cwd)) {
		if (isUnderDir(resolvedCommand, binDir)) return true;
	}
	return false;
}

/**
 * #4515: a test for whether one PATH entry (or a global bin dir) can resolve
 * a bare command into the project at `cwd`. It counts when it is a
 * project-local bin dir of `cwd` or an ancestor, lies at or under `cwd`, or is
 * relative: a relative entry follows each spawn's cwd, and on POSIX an empty
 * entry is the cwd. A `cwd` at or above HOME is no project, the ceiling the
 * project-local walk already stops at (#4530), so HOME's own tool dirs stay
 * usable there. Each directory is filesystem-resolved once per test, not per entry.
 */
function projectReach(cwd: string): (entry: string) => boolean {
	const posix = process.platform !== "win32";
	const dirs = [
		...(isAtOrAboveHomeDir(cwd, os.homedir()) ? [] : [cwd]),
		...projectLocalBinDirs(cwd),
	].map((dir) => normalizeFilePath(realpathOrResolve(dir)));
	return (entry) => {
		if (entry === "") return posix;
		if (!path.isAbsolute(entry)) return true;
		const canonical = normalizeFilePath(realpathOrResolve(entry));
		return dirs.some((dir) => isUnderCanonicalDir(canonical, dir));
	};
}

/** #4515: whether a bare command spawned with this process's PATH can resolve into `cwd`. */
export function commandSearchReachesProject(cwd: string): boolean {
	return (process.env.PATH ?? "").split(path.delimiter).some(projectReach(cwd));
}

/**
 * #4530 round 9: whether a RESOLVED command's real target lies in the project
 * pi has not trusted. A trust check on the directory that holds the command
 * answers a different question: a global bin dir outside the project (or an
 * outside PATH entry) can hold a link into it — an npm-linked language server
 * is the ordinary case — and the resolver follows that link when it spawns.
 * The target is what runs, so the target is what the trust gate judges
 * (#4566 round 9). Launch admission opts into trust-independent classification
 * because session trust does not grant ownership of an adopted root (#4566 r13).
 */
export function commandResolvesIntoProject(
	resolvedCommand: string,
	cwd: string = process.cwd(),
	classifyRegardlessOfTrust = false,
): boolean {
	if (!classifyRegardlessOfTrust && getProjectTrustState() === "trusted")
		return false;
	// #4566 r14: a discovered spelling can be relative (`which` echoes the PATH
	// entry it searched with), and the child resolves it against ITS cwd. Judging
	// it against `process.cwd()` measured the session's file while the spawn ran
	// the launch cwd's, so a relative project PATH entry executed unowned code
	// (R13-V1). The target that runs is the one this must judge.
	const commandPath = path.isAbsolute(resolvedCommand)
		? resolvedCommand
		: path.resolve(cwd, resolvedCommand);
	const target = normalizeFilePath(realpathOrResolve(commandPath));
	const reaches = projectReach(cwd);
	if (reaches(target)) return true;
	// #4566 F3: npm Windows shims are regular files, not symlinks. Their
	// script is the executable target; unknown script text cannot vouch for it.
	// #4566 r14: npm emits an extensionless launcher for a bin with no suffix
	// (yaml-language-server's documented wrapper), so an extensionless basename is
	// a supported target too. Every other spelling — the shim's own `node.exe`
	// copy, a `.dll`, a stray `$exe` variable — is not a target this parser can
	// vouch for, and a shim with no supported target stays refused.
	if (!/\.(?:cmd|ps1)$/i.test(commandPath)) return false;
	try {
		const content = fs.readFileSync(commandPath, "utf8");
		const scripts: string[] = [];
		for (const match of content.matchAll(
			/["'](?:%~dp0|%dp0%|\$basedir)[/\\]([^"'\r\n]+)["']/gi,
		)) {
			const spelling = match[1];
			if (typeof spelling !== "string") continue;
			const base = spelling.split(/[/\\]/).pop() ?? "";
			if (/\.(?:mjs|cjs|js)$/i.test(base) || !base.includes("."))
				scripts.push(spelling);
		}
		if (scripts.length === 0) return true;
		return scripts.some((spelling) =>
			reaches(
				normalizeFilePath(
					realpathOrResolve(
						path.resolve(
							path.dirname(commandPath),
							spelling.replace(/[/\\]/g, path.sep),
						),
					),
				),
			),
		);
	} catch {
		return true;
	}
}

/**
 * One bounded record per (target, session) for a global command that resolves
 * into the project; the link's own spelling is kept in the metadata so the
 * global directory that holds it stays identifiable.
 */
function refuseGlobalCommandTarget(resolvedCommand: string): void {
	const trust = getProjectTrustState() as "untrusted" | "unknown";
	const target = normalizeFilePath(realpathOrResolve(resolvedCommand));
	if (
		recordDegradationOnce({
			kind: "trust-refusal",
			subject: `global-command-target:${target}`,
			reason: `global command target could not be admitted outside the project: pi project trust is ${trust}`,
		})
	) {
		logExtension({
			subsystem: "project-trust",
			level: "warn",
			message:
				"global command target could not be admitted outside the project: mark the project trusted in pi or upgrade pi",
			metadata: { command: resolvedCommand, target, trust },
		});
	}
}

/**
 * #4530: the user-facing PATH-refusal notice is once per session, not once per
 * refused entry. Several entries can reach the same project (an absolute
 * `node_modules/.bin` and husky's relative one), and each warns with the same
 * sentence, so the message names no entry and repeating it adds no signal. The
 * `trust-refusal` ledger row below stays per entry, so the exact set is still
 * observable. Keyed on the degradation generation, which `session_start`
 * bumps, the same re-arm `unknownProjectLocalNoticeGeneration` uses.
 */
let trustScopedPathNoticeGeneration = -1;

/**
 * #4530: `pathValue` without the entries that reach the session project
 * (`process.cwd()`) or `cwd`, while pi has not trusted the project; a trusted
 * project gets `pathValue` back unchanged. pi-lens's own lookups, and the
 * tools they start, resolve names through this PATH, so a binary inside the
 * project never answers for a global one. Each ignored entry is recorded once
 * per session; the notice is emitted once per session. `refusedEntries`, when
 * supplied, receives those path spellings.
 */
export function trustScopedPath(
	pathValue: string,
	cwd: string = process.cwd(),
	refusedEntries?: string[],
): string {
	const trust = getProjectTrustState();
	if (trust === "trusted") return pathValue;
	const generation = getDegradationLedgerGeneration();
	const session = process.cwd();
	const reaches = [session, ...(pathsEqual(cwd, session) ? [] : [cwd])].map(
		projectReach,
	);
	const kept: string[] = [];
	for (const entry of pathValue.split(path.delimiter)) {
		if (!reaches.some((reach) => reach(entry))) {
			kept.push(entry);
			continue;
		}
		refusedEntries?.push(entry);
		recordDegradationOnce({
			kind: "trust-refusal",
			subject: `project-path-entry:${entry}`,
			reason: `lookup dir inside the project ignored: pi project trust is ${trust}`,
		});
		if (trustScopedPathNoticeGeneration !== generation) {
			trustScopedPathNoticeGeneration = generation;
			logExtension({
				subsystem: "project-trust",
				level: "warn",
				message:
					"lookup dir inside the project ignored: mark the project trusted in pi or upgrade pi",
				metadata: { entry, trust },
			});
		}
	}
	return kept.join(path.delimiter);
}

/**
 * #4530 round 9: a PATH value built from `parts`, never carrying a
 * zero-length entry. POSIX makes the kernel search the child's own working
 * directory for a zero-length PATH and for a zero-length entry between
 * separators, so a value pi-lens composes must not contain one — a trust-scoped
 * PATH that lost every entry is the case that made this visible (measured on
 * Linux: `PATH=""` ran `./pnpm-shim` from the cwd, a removed PATH did not).
 * The ONE seam every composer in the tree joins through, so the rule cannot
 * drift per call site.
 */
export function normalizeSearchPath(
	parts: readonly string[],
	separator: string = path.delimiter,
): string {
	return parts
		.flatMap((part) => part.split(separator))
		.filter((entry) => entry !== "")
		.join(separator);
}

/**
 * #4530 round 9: put `pathValue`, scoped by {@link trustScopedPath}, onto a
 * child's environment, or REMOVE the key when every entry was refused.
 *
 * A scoped result can be empty — every entry reached the project — and an empty
 * PATH is not "no directories": it hands project code back the lookup the trust
 * gate just took away (see {@link normalizeSearchPath}). A child with no PATH
 * falls back to the system default search path, which never contains the cwd.
 */
export function setTrustScopedPath(
	env: NodeJS.ProcessEnv,
	pathValue: string,
	cwd: string = process.cwd(),
): void {
	const scoped = trustScopedPath(pathValue, cwd);
	// POSIX has one lookup key. Windows spellings name the same variable.
	const spellings = new Set(
		onWindows()
			? Object.keys(env).filter((key) => key.toLowerCase() === "path")
			: ["PATH"],
	);
	if (scoped !== "") spellings.add("PATH");
	for (const key of spellings) {
		if (scoped === "") delete env[key];
		else env[key] = scoped;
	}
	if (scoped !== "" && process.platform === "win32") env.Path = scoped;
}

/**
 * #4530: the environment for a spawn pi-lens makes on its own behalf, with
 * every PATH spelling scoped by {@link trustScopedPath}, or `undefined` when
 * the project is trusted and the caller keeps its environment.
 */
export function trustScopedSpawnEnv(
	cwd: string = process.cwd(),
): NodeJS.ProcessEnv | undefined {
	if (getProjectTrustState() === "trusted") return undefined;
	const env: NodeJS.ProcessEnv = { ...process.env };
	const spelling = onWindows()
		? Object.keys(env).find((key) => key.toLowerCase() === "path")
		: env.PATH === undefined
			? undefined
			: "PATH";
	// An env without the platform PATH key inherits the system default search path.
	if (spelling !== undefined) setTrustScopedPath(env, env[spelling] ?? "", cwd);
	return env;
}

/** Tuning for {@link findLocalBinUpwards}. */
export interface LocalBinWalkOptions {
	/**
	 * Extension tried BEFORE the bare name on Windows. Default `.cmd`. An
	 * EMPTY string means the caller already spelled every name it wants (the
	 * ast-grep sweep passes `ast-grep.cmd`/`ast-grep.exe`/`ast-grep` itself, in
	 * a shell-dependent order this option cannot express) — without that case
	 * the bare name would be probed twice and reported twice.
	 */
	readonly windowsExt?: string;
	/** HOME ceiling; injectable so tests never touch the real home. */
	readonly homeDir?: string;
	/**
	 * Project-relative directories that hold the bin, most-preferred first.
	 * Default {@link NODE_MODULES_BIN_DIRS}; {@link VENDOR_BIN_DIRS} (Composer)
	 * and {@link VENV_BIN_DIRS} (Python) are the other two shapes in the repo.
	 */
	readonly binDirs?: readonly string[];
	/**
	 * Whether to expand `windowsExt` into the candidate names. Defaults to a
	 * LIVE `process.platform` read (never a module-load constant, shape 30).
	 * Injectable so the ubuntu Unit tests lane can exercise the Windows
	 * candidate ORDER — which only exists when there are two names — instead of
	 * leaving it to a dev box (#2544 review F4).
	 */
	readonly isWindows?: boolean;
	/**
	 * Whether the HOME ceiling applies to this walk. Default `true` — the
	 * ceiling is the right default for every PROJECT-tree resolution (#2514).
	 *
	 * `false` is for exactly one caller: `buildSgLocalBins`' walk from
	 * pi-lens's OWN install directory (`runner-helpers.ts`), never a project
	 * cwd. `pi install npm:pi-lens` installs into the HOME-level manifest
	 * (`~/package.json` → `~/node_modules/pi-lens`), so the bundled
	 * `@ast-grep/cli` shim can sit AT `~/node_modules/.bin/ast-grep` — a
	 * directory the ceiling exists precisely to stop at. The ceiling is a
	 * project-tree policy ("a bin found at or above HOME can never be THIS
	 * PROJECT's own dependency"); it says nothing about where pi-lens's own
	 * install tree is allowed to live, so this walk is exempt (#2544 round 4
	 * F1).
	 */
	readonly ceiling?: boolean;
}

/**
 * THE project-local tool-bin walk: yields every accepted `<binDir>/<tool>`
 * in `startDir` or one of its ancestors, nearest first, stopping at the HOME
 * ceiling (never the fs root — see below).
 *
 * A generator on purpose. {@link findLocalBinUpwards} takes the first match and
 * the walk suspends there — no ancestor above the hit is ever stat'd, which is
 * what a per-edit resolver needs — while {@link findLocalBinsUpwards} drains it
 * for the ast-grep probe sweep, the one caller that legitimately wants every
 * candidate above `startDir`. One walk body, two arities, no "collect-all"
 * flag whose disabled half nothing can observe.
 * `ceiling: false` opts a walk out of the HOME stop entirely (own-install
 * trees only, see {@link LocalBinWalkOptions.ceiling}); {@link findLocalBinsAt}
 * / {@link findLocalBinAt} below are the non-walking sibling for callers that
 * must check exactly one directory and never climb (`createVenvFinder`,
 * vulture's `venvCandidates`).
 *
 * `tools` is a LIST because the sweep callers probe several spellings of the
 * same tool and the preference order is per-directory: all of a directory's
 * candidates, in `tools` order, before the parent directory is looked at.
 *
 * `binDirs` makes this the ONLY such walker in the repo. Before #2544 there
 * were SIX copies of this loop — `formatters.ts`'s `findInNodeModules` /
 * `findInVendorBin` / `findInVenv`, `oxlint.ts`'s `resolveLocalVp`,
 * `runner-helpers.ts`'s `findNodeBinRoots` and `resolveVendorToolCommand` —
 * and they had drifted apart: only this one resolved a relative `startDir`,
 * only this one had the #2514 HOME ceiling, and `vp` was resolved with
 * OPPOSITE ceiling policies depending on whether `formatters.ts` or `oxlint.ts`
 * asked (#2544 review F1). They all delegate here now.
 *
 * Candidate order is EXT-OUTER, DIR-INNER: on Windows every `binDir` is tried
 * with `windowsExt` before any is tried with the bare name, matching what the
 * `.venv/Scripts` walker did before the fold.
 */
/**
 * Expand `tools` into the actual candidate file names for one directory,
 * EXT-OUTER: on Windows every tool's extended name is tried before any tool's
 * bare name (`windowsExt === ""` means the caller already spelled every name
 * it wants — the ast-grep sweep passes `ast-grep.cmd`/`ast-grep.exe`/`ast-grep`
 * itself in a shell-dependent order this option cannot express).
 */
function expandCandidateNames(
	tools: readonly string[],
	windowsExt: string,
	isWindows: boolean,
): string[] {
	return isWindows && windowsExt !== ""
		? tools.flatMap((tool) => [`${tool}${windowsExt}`, tool])
		: [...tools];
}

/** Every accepted `<dir>/<binDir>/<name>`, for exactly `dir` — no walk. */
function* matchesInDir(
	dir: string,
	names: readonly string[],
	binDirs: readonly string[],
): Generator<string, undefined> {
	for (const name of names) {
		for (const binDir of binDirs) {
			const full = path.join(dir, binDir, name);
			if (isAcceptedCommandFile(full)) yield full;
		}
	}
}

function* localBinMatches(
	tools: readonly string[],
	startDir: string,
	options: LocalBinWalkOptions,
): Generator<string, undefined> {
	const {
		windowsExt = ".cmd",
		homeDir = os.homedir(),
		binDirs = NODE_MODULES_BIN_DIRS,
		isWindows = onWindows(),
		ceiling = true,
	} = options;
	const names = expandCandidateNames(tools, windowsExt, isWindows);
	for (const dir of walkUpDirs(startDir)) {
		// Tool-resolution walker, not a config lookup (#2514/#2517 policy):
		// escaping the project upward past HOME means STOP, not keep reading. A
		// config-file lookup (`findLocalToolConfig`) keeps climbing past HOME
		// because the underlying tool would find a legitimate global config
		// there too; a `node_modules/.bin` match found at or above HOME can
		// never be THIS project's own installed dependency — it is some
		// unrelated home-level manifest (the pi-extensions bin shim, #2514).
		// Default-on (not opt-in like `findLocalToolConfig`'s `options.homeDir`)
		// because there is no legitimate case for this resolver to hand back a
		// bin from outside the project tree. `ceiling: false` (own-install
		// walk only, #2544 round 4 F1) skips this check entirely.
		if (ceiling && isAtOrAboveHomeDir(dir, homeDir)) return;
		yield* matchesInDir(dir, names, binDirs);
	}
}

/**
 * The nearest project-local `<binDir>/<tool>` at or above `startDir`, or
 * `undefined`. See {@link localBinMatches} for the walk itself.
 *
 * Exported so callers that must NOT pay for global-bin discovery can reuse this
 * walk instead of copying it. `findNodeToolBinary` below adds `findGlobalBinary`,
 * which spawns a probe per package manager; a caller resolving a command on
 * every run (knip, #1721) needs the filesystem half only.
 */
export function findLocalBinUpwards(
	tool: string,
	startDir: string,
	options: LocalBinWalkOptions = {},
): LocalBinLookup | undefined {
	// `.next().value`, not a `for…of` that returns on its first iteration: the
	// latter is a single-iteration loop (SonarCloud S1751, and it reads as one
	// too). The generator is simply left suspended after the first match — it
	// holds no resource that needs closing, which is exactly why the walk above
	// never stats an ancestor beyond the hit.
	const match = localBinMatches([tool], startDir, options).next().value;
	if (match === undefined || options.ceiling === false) return match;
	if (getProjectTrustState() !== "trusted")
		return refuseLocalBin(tool, startDir);
	return match;
}

/**
 * EVERY project-local match for `tools` at or above `startDir`, nearest first.
 *
 * For the ast-grep availability sweep (`runner-helpers.ts`'s `buildSgLocalBins`,
 * which spawns `--version` against each candidate until one answers, both for
 * the project walk and — with `ceiling: false` — pi-lens's own install-tree
 * walk), which previously hand-rolled its own unceilinged climb precisely
 * because the singular `findLocalBinUpwards` could not express "all of them"
 * (#2544 review F1).
 *
 * NOT for a "project's own venv/vendor-bin first" resolver: `createVenvFinder`
 * and vulture's `venvCandidates` looked like this walk's other two callers in
 * round 3, but that was an unrequested behaviour change (round 3 introduced
 * ancestor climbing where a single cwd/root lookup existed before, with no
 * #2514 defect behind it) — reverted in round 4 F2 to {@link findLocalBinsAt}.
 */
export function findLocalBinsUpwards(
	tools: readonly string[],
	startDir: string,
	options: LocalBinWalkOptions = {},
): LocalBinLookup[] {
	const matches = [...localBinMatches(tools, startDir, options)];
	if (
		matches.length === 0 ||
		options.ceiling === false ||
		getProjectTrustState() === "trusted"
	) {
		return matches;
	}
	return [refuseLocalBin(tools.join(","), startDir)];
}

/**
 * EVERY `<dir>/<binDir>/<tool>` that exists for exactly `dir` — no ancestor
 * walk, so the HOME ceiling is moot (a single directory can never climb past
 * it).
 *
 * For the "project's own venv/vendor-bin first" resolvers that must NOT climb
 * to a parent project (#2544 round 4 F2): `createVenvFinder` and vulture's
 * `venvCandidates` were fixed `cwd`/`root` lookups before #2544 review round 3
 * converted them into ancestor walks with no reported defect behind the
 * conversion (an unrelated sibling project's interpreter at `~/code/.venv`
 * could then outrank PATH for `~/code/app`, which has no venv of its own).
 * Reverted here; `binDirs`/`windowsExt` stay shared with the walking helpers
 * above so the three directory shapes have exactly one spelling.
 */
export function findLocalBinsAt(
	tools: readonly string[],
	dir: string,
	options: Pick<
		LocalBinWalkOptions,
		"windowsExt" | "binDirs" | "isWindows"
	> = {},
): LocalBinLookup[] {
	const {
		windowsExt = ".cmd",
		binDirs = NODE_MODULES_BIN_DIRS,
		isWindows = onWindows(),
	} = options;
	const names = expandCandidateNames(tools, windowsExt, isWindows);
	const matches = [...matchesInDir(path.resolve(dir), names, binDirs)];
	if (matches.length === 0 || getProjectTrustState() === "trusted")
		return matches;
	return [refuseLocalBin(tools.join(","), dir)];
}

/** The nearest — i.e. first-listed — `<dir>/<binDir>/<tool>` match, or `undefined`. */
export function findLocalBinAt(
	tool: string,
	dir: string,
	options: Pick<
		LocalBinWalkOptions,
		"windowsExt" | "binDirs" | "isWindows"
	> = {},
): LocalBinLookup | undefined {
	const match = findLocalBinsAt([tool], dir, options)[0];
	return match;
}

/**
 * Locate a Node CLI tool's binary, preferring a local `node_modules/.bin`
 * (walking up from `cwd`) then any installed package manager's global bin dir
 * (npm/pnpm/yarn/bun). Returns the absolute path, or `undefined` so the caller
 * can fall back to its own `npx` invocation.
 *
 * This is the shared "widen the global-bin lookup" step from #375: the client
 * resolvers that previously jumped straight from a local check to `npx <tool>`
 * now find tools installed via `pnpm add -g` / `bun add -g` (off PATH) too,
 * without changing their npx fallback semantics.
 */
export async function findNodeToolBinary(
	tool: string,
	cwd: string,
	windowsExt = ".cmd",
): Promise<string | undefined> {
	return (
		localBinPath(findLocalBinUpwards(tool, cwd, { windowsExt })) ??
		(await findGlobalBinary(tool, windowsExt, cwd))
	);
}

clients/path-utils.ts:
/**
 * Path utilities for pi-lens
 *
 * Handles cross-platform path normalization, particularly
 * Windows case-insensitivity issues when using paths as Map keys.
 *
 * Approach (inspired by OpenCode's Filesystem.normalizePath):
 * - On Windows: try realpathSync.native() for canonical casing
 * - Falls back to lowercase for files that don't exist yet
 * - On non-Windows: adopt the on-disk casing of an existing path (#3098 — a
 *   case-insensitive POSIX filesystem otherwise derives two Map keys for one
 *   file); a path that does not exist is returned as-is, case-preserving
 * - Always convert backslashes to forward slashes for Map key consistency
 */

import {
	type Dirent,
	existsSync,
	readFileSync,
	realpathSync,
	statSync,
} from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { win32 } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { minimatch } from "./deps/minimatch.js";

/**
 * Detect a positively Windows-shaped path, regardless of the host OS.
 *
 * A backslash anywhere in a path is not enough: it is a legal character in a
 * POSIX filename. Only a drive-letter prefix (`X:`), a UNC root (`\\`), or a
 * rooted backslash at position zero (`\`) selects Windows parsing.
 */
export function isWindowsPath(filePath: string): boolean {
	return /^[A-Za-z]:/.test(filePath) || filePath.startsWith("\\");
}

/**
 * Canonical backslash→forward-slash fold — the single sanctioned form of the
 * `p.replace(/\\/g, "/")` idiom otherwise hand-rolled across the codebase
 * (~138 sites, #1193). PURE separator normalization: it does NOT resolve,
 * canonicalize, lowercase, or collapse repeated slashes — reach for
 * `normalizeFilePath`/`normalizeMapKey`/`normalizeEphemeralMapKey` when a
 * canonical map *key* (case-fold / realpath) is what you need. Consolidating on
 * this funnels the scattered transform and makes a shape-2 lint/ast-grep rule
 * possible for the first time: today a bare inline `.replace(/\\/g, "/")` is
 * byte-identical to the sanctioned use so it can't be ruled (#1158); once
 * everything routes through `toPosix`, an *un-migrated* inline `.replace`
 * becomes detectable.
 */
export function toPosix(filePath: string): string {
	return filePath.replace(/\\/g, "/");
}

/** Return whether `filePath` is fully qualified under Windows semantics. */
export function isFullyQualifiedWin32(filePath: string): boolean {
	return win32.isAbsolute(filePath) && win32.parse(filePath).root.length > 1;
}

/** Return whether `filePath` is fully qualified under POSIX semantics. */
export function isFullyQualifiedPosix(filePath: string): boolean {
	return path.posix.isAbsolute(filePath) && !isWindowsPath(filePath);
}

/**
 * Return whether `filePath` is fully qualified under the host's semantics.
 *
 * In particular, `/foo` is rooted-relative under Win32 (ambient-drive
 * dependent) but fully qualified under POSIX.
 */
export function isFullyQualified(filePath: string): boolean {
	return process.platform === "win32"
		? isFullyQualifiedWin32(filePath)
		: isFullyQualifiedPosix(filePath);
}

/**
 * Shape-based absolute check (mirrors `toProjectRelativePath`'s idiom): a
 * Windows-shaped path (drive-letter/UNC) is parsed with `win32.isAbsolute`
 * regardless of host OS, since the host-default `path.isAbsolute` returns
 * FALSE for a Windows-shaped path on POSIX (#1150 class) and would let a
 * cross-platform-persisted relative path slip past this guard on Linux CI.
 * MUST run on the RAW `filePath`, before `normalizeMapKey`: on Windows,
 * `normalizeMapKey`'s nonexistent-path fallback (`resolveNonExisting`) calls
 * `win32.resolve`, which silently makes any relative path absolute against
 * `process.cwd()` — checking the normalized value would defeat this guard
 * entirely on Windows.
 *
 * Promoted from a private copy in `clients/review-graph/service.ts` (#2477)
 * so `clients/dispatch/dispatcher.ts`'s baseline-key guard (#2489) can share
 * the same sanctioned check instead of hand-rolling a second one.
 */
export function isAbsoluteFilePath(filePath: string): boolean {
	const p = isWindowsPath(filePath) ? win32 : path;
	return p.isAbsolute(filePath);
}

/**
 * Split a path into its non-empty segments on EITHER separator (`\` or `/`),
 * regardless of the running OS — the shape-safe form of `p.split(path.sep)` /
 * an inline `p.split(/[\\/]+/)`, which #1161/#1163 showed must not assume the
 * host separator for a possibly-cross-shaped path. Drops empty segments
 * (leading slash, drive-root, doubled separators).
 */
export function splitPathSegments(filePath: string): string[] {
	return filePath.split(/[\\/]+/).filter(Boolean);
}

/**
 * Adopt `canonical`'s CASING for the trailing segments of `held`, stopping at
 * the first segment that differs by more than case.
 *
 * `realpathSync.native` answers a different question than the one the POSIX
 * arm of `normalizeFilePath` asks: it resolves symlinks AND reports on-disk
 * casing, and we want only the second half. Walking from the tail and halting
 * at the first structural divergence separates them with no extra syscall:
 *
 *   held      /var/folders/T/x/SUB/a.ts   (macOS tmpdir, mis-cased segment)
 *   canonical /private/var/folders/T/x/sub/a.ts
 *   result    /var/folders/T/x/sub/a.ts   (case fixed, symlink prefix kept)
 *
 * The symlink prefix matters: macOS's `os.tmpdir()` is `/var/folders/...`,
 * a symlink into `/private/var`, so a whole-string "is this a case variant"
 * test would decline to canonicalize exactly the paths the #1024 regression
 * test (and any macOS temp-dir workflow) runs on. Keeping the prefix is also
 * what bounds this change: on POSIX, `normalizeFilePath` still never resolves
 * a symlink, so a symlinked monorepo package keeps keying under the path the
 * caller held (refs #2490 — a cwd fold for its own sake broke every monorepo).
 *
 * PURE string algebra: this pins what the rewrite DOES, never what the kernel
 * reports — and from two strings alone it cannot tell "the same file, spelled
 * with different case" from "a different file whose name happens to be a case
 * variant". Any symlink whose BASENAME is a case variant of its target's
 * basename (`<root>/MyProject` → `work/myproject`, `node_modules/Foo` →
 * `../pkgs/foo`) has its name replaced while its own parent is kept, so the
 * result names a different place — or no place at all. Measured in #3159
 * review round 2 (F1): two different inodes collapsed onto ONE key (the #1024
 * defect inverted — false suppression), and a symlinked package keyed under a
 * path that does not exist on disk, breaking the #2490 bound above. The caller
 * therefore CONFIRMS every rewrite against the filesystem before adopting it
 * (see `normalizeFilePath`); do not use this function without that step.
 */
function adoptCanonicalCasing(held: string, canonical: string): string {
	const heldParts = held.split("/");
	const realParts = canonical.split("/");
	let i = heldParts.length - 1;
	let j = realParts.length - 1;
	let changed = false;
	while (i >= 0 && j >= 0) {
		const a = heldParts[i] as string;
		const b = realParts[j] as string;
		if (a !== b) {
			if (a.toLowerCase() !== b.toLowerCase()) break;
			heldParts[i] = b;
			changed = true;
		}
		i--;
		j--;
	}
	// Identity-preserving when nothing moved — this runs on every POSIX map-key
	// derivation and the overwhelmingly common answer is "already canonical".
	// NOT a behavioural branch (both arms produce an equal string): it is the
	// same allocation guard `normalizeEphemeralMapKey` documents below.
	return changed ? heldParts.join("/") : held;
}

/**
 * Normalize a file path for consistent Map key usage.
 *
 * On Windows:
 * - If the file exists: uses realpathSync.native() to get the canonical
 *   filesystem path (actual casing, resolved symlinks)
 * - If the file doesn't exist: resolves the path and lowercases
 *   (needed for new files where we haven't written yet)
 *
 * On POSIX:
 * - Folds `.`, `..` and duplicate separators first (#3184, see below).
 * - If the file exists: adopts the on-disk CASING of the trailing segments
 *   (see `adoptCanonicalCasing`) — no lowercasing, no symlink resolution.
 * - If the file doesn't exist: returns the path as-is, case-PRESERVING. On a
 *   case-sensitive filesystem `SUB/a.ts` and `sub/a.ts` are two different
 *   files, and nothing may fold one into the other; only the filesystem's own
 *   answer for a path that EXISTS can tell the two apart, and for a path that
 *   does not exist there is no such answer to ask for.
 *
 * Why the POSIX arm folds dot segments (#3184): the casing arm returns the
 * caller's own spelling whenever `adoptCanonicalCasing` changes nothing, and
 * for `<base>/src/../src/a.ts` it always changes nothing — `realpath` answers
 * a string with FEWER segments, which a casing-only rewrite cannot express, so
 * it declines and the caller's un-folded spelling came back as the map key.
 * Every canonical writer keys through `path.resolve` first (`ctx.filePath` =
 * `normalizeMapKey(resolveAgainstAncestors(...))`, `clients/dispatch/
 * runner-context.ts:49`), so a consumer that passes an ALREADY-absolute
 * agent-typed path straight in (`tools/lens-diagnostic-mark.ts`,
 * `clients/mcp/analyze.ts`) derived an orphan key that no reader could reach.
 * Folding here is pure string algebra — no cwd, no filesystem — so a relative
 * path stays relative (`src/../x` → `x`, `../x` → `../x`, never resolved
 * against `process.cwd()`; refs #2490, where a cwd fold broke every monorepo)
 * and a symlinked package still keys under the path the caller held. These
 * are `path.resolve`'s own TEXTUAL `..` semantics, which is exactly what
 * makes a folded reader key equal to the canonical writer's key: where a
 * `..` sits right after a symlinked directory, textual folding and the
 * kernel disagree, and both sides of every comparison take the textual
 * answer because every canonical writer already resolved that way.
 *
 * Why POSIX canonicalizes casing at all (#3098, the #1024 defect's live half):
 * a case-insensitive POSIX filesystem — macOS's default APFS, `nocase` vfat /
 * ntfs3 / cifs mounts — makes `SUB/a.ts` and `sub/a.ts` ONE file, so a raw
 * mis-cased write (`lens_diagnostic_mark` anchors under `path.resolve(cwd,
 * arg)`) and a `normalizeMapKey` read derived two anchors for one file and the
 * agent's own disposition mark silently never applied. A case-preserving POSIX
 * arm cannot close that: the two keys only become one if the normalizer asks
 * the filesystem which name is really on disk.
 *
 * `realpathSync.native` is `realpath(3)`. On Darwin it rebuilds every
 * component from the filesystem's own `ATTR_CMN_NAME` — Libc-1669.0.4
 * `stdlib/FreeBSD/realpath.c:233` (`getattrlist(resolved, &_rp_alist, …,
 * FSOPT_NOFOLLOW)` with `ATTR_CMN_NAME`) and `:348-354` ("attrs already has
 * the real name") — which is why it returns on-disk casing on APFS/HFS+.
 * MEASURED counter-example (#3098): a Linux ext4/tmpfs `chattr +F` casefold
 * directory aliases the two spellings but `realpath(3)` there returns the
 * spelling the caller asked with, so this arm is a no-op on casefolded Linux
 * directories — filed with the transcript as #3154.
 *
 * Always converts backslashes to forward slashes for consistent Map keys.
 */
export function normalizeFilePath(filePath: string): string {
	if (process.platform === "win32") {
		// Relative values and the empty sentinel are not filesystem identities.
		// In particular, win32.resolve() would silently anchor them to the
		// process cwd, which makes a path-only key depend on the runner's drive
		// (#2490). Keep this guard inside the Windows arm so POSIX relative
		// inputs still receive their realpath/casing treatment.
		if (filePath === "") return "";
		if (!isFullyQualifiedWin32(filePath)) {
			return win32.normalize(filePath).replace(/\\/g, "/");
		}
	}

	// Convert backslashes to forward slashes first
	const normalized = filePath.replace(/\\/g, "/");

	if (process.platform !== "win32" && !isWindowsPath(normalized)) {
		// #3184. `path.posix`, not the host default: this branch is already
		// committed to POSIX parsing of a slash-folded string (shape 2). Only
		// the POSIX arm needs this — the win32 arm below reaches `realpath` or
		// `win32.resolve`/`win32.normalize` on every path, all of which fold
		// dot segments already (measured: `C:\repo\src\..\src\a.ts` →
		// `c:/repo/src/a.ts` on this POSIX host, before this change) — and
		// folding BEFORE the arms would also move which arm a degenerate
		// drive-letter path selects (`path.posix.normalize("C:/repo/../..")`
		// is `"."`, no longer Windows-shaped).
		// Two inputs keep the caller's spelling instead:
		// - "" is a non-path sentinel in this codebase's path-typed fields
		//   (see `normalizeLoggedPath`'s doc); `posix.normalize("")` invents
		//   ".", the process cwd.
		// - a UNC root (`\\server\share`, slash-folded to `//server/share`)
		//   reaches THIS arm on a POSIX host, because `isWindowsPath` tests
		//   the already-folded string and sees no backslash; POSIX
		//   `normalize` collapses its leading `//` to `/`, renaming the path
		//   to an unrelated local one.
		const folded =
			normalized === "" || normalized.startsWith("//")
				? normalized
				: path.posix.normalize(normalized);
		try {
			const canonical = realpathSync.native(folded);
			// Fast path, not a guard: both arms answer `folded` when the
			// strings match, but skipping the two `split`s there is a measured
			// 1.9 vs 2.3 microseconds per call on the per-edit seam (#3098).
			if (canonical === folded) return folded;
			const adopted = adoptCanonicalCasing(folded, canonical);
			if (adopted === folded) return folded;
			// The rewrite is string algebra and can land on a DIFFERENT file
			// (#3159 review round 2, F1 — see `adoptCanonicalCasing`). Adopt it
			// only once the filesystem agrees it still names the file the caller
			// held: `canonical` IS `realpath(normalized)`, so this asks exactly
			// "does the rewritten spelling resolve to the same file?". One extra
			// syscall, and only on the rare branch where casing actually moved —
			// never on an already-canonical path. A throw here (the rewritten
			// path does not exist, the #2490 monorepo case) lands in the catch
			// below and keeps the caller's spelling, which is the same answer.
			return realpathSync.native(adopted) === canonical ? adopted : folded;
		} catch {
			// Does not exist (or is unreadable): case-preserving, as above.
			return folded;
		}
	}

	// Windows: try realpathSync.native() for canonical casing
	// This resolves symlinks and returns the actual filesystem casing
	try {
		const canonical = realpathSync.native(filePath);
		return canonical.replace(/\\/g, "/");
	} catch {
		// File doesn't exist yet (new file) — resolve path and lowercase
		// We need to walk up the directory tree to find the nearest existing
		// parent, resolve its casing, then append the non-existent parts
		try {
			return resolveNonExisting(filePath);
		} catch {
			// Last resort: just lowercase the resolved path
			const resolved = win32.normalize(win32.resolve(filePath));
			return resolved.replace(/\\/g, "/").toLowerCase();
		}
	}
}

/** Resolve a filesystem identity once, retaining a usable absolute fallback. */
export function realpathOrResolve(filePath: string): string {
	const resolved = path.resolve(filePath);
	try {
		return realpathSync(resolved);
	} catch {
		return resolved;
	}
}

/**
 * Normalize a logged `filePath`/`cwd` value, but ONLY when it is already a
 * fully-qualified path (#2219, the #2141 class's sibling loggers). Several
 * NDJSON log-entry types reuse a `filePath`-typed field for non-path
 * sentinels alongside genuine paths — `"<quiet-window>"` in
 * `cascade-logger.ts`, `"<tree-sitter>"` in `tree-sitter-logger.ts`, a shell
 * command or an empty placeholder in `latency-logger.ts`. `normalizeFilePath`
 * resolves a relative-looking string against the CURRENT process cwd (see
 * `resolveNonExisting` above), so running it over one of those sentinels
 * would silently corrupt it into `"<repoRoot>/<quiet-window>"` instead of
 * normalizing it. Only a value that is already fully qualified can be the
 * #2141 mixed-raw/normalized-path defect; anything else is passed through
 * unchanged.
 *
 * #2229 review round 1, F1: this classifier checks BOTH host shapes
 * (`isFullyQualifiedWin32(value) || isFullyQualifiedPosix(value)`), not
 * `isFullyQualified(value)` (host-dispatched on `process.platform`). A
 * Windows-shaped absolute path (`C:\Users\...`) is exactly the log payload
 * this fix exists to normalize, but `isFullyQualified` on Linux CI routes to
 * `isFullyQualifiedPosix`, which rejects it (no leading `/`) — so on Linux
 * the guard silently no-ops for the very inputs the #2141 defect produces,
 * passing the raw backslash form straight through. Checking both shapes
 * makes the classifier's answer for a given STRING independent of which OS
 * is asking; `normalizeFilePath` itself still branches on `process.platform`
 * for how the file is resolved, but whether to normalize at all no longer
 * does (AGENTS.md shape 2, the #1024/#1150 OS-divergence class).
 */
export function normalizeLoggedPath(value: string): string {
	return isFullyQualifiedWin32(value) || isFullyQualifiedPosix(value)
		? normalizeFilePath(value)
		: value;
}

/**
 * Resolve a non-existing path by finding the nearest existing parent,
 * getting its canonical casing, then appending the non-existent parts lowercased.
 *
 * Example: C:\Users\Foo\newdir\file.ts
 * - C:\Users\Foo exists → realpathSync gives C:\Users\Foo
 * - newdir\file.ts doesn't exist → lowercased
 * - Result: C:/Users/Foo/newdir/file.ts
 */
function resolveNonExisting(filePath: string): string {
	const resolved = win32.resolve(filePath);
	let current = resolved;
	const nonExistentParts: string[] = [];

	// Walk up until we find an existing directory
	while (true) {
		if (existsSync(current)) {
			// Found existing ancestor — get its canonical casing
			const canonical = realpathSync.native(current);
			if (nonExistentParts.length === 0) {
				return canonical.replace(/\\/g, "/");
			}
			// Append non-existent parts (lowercased for consistency)
			const tail = nonExistentParts.reverse().join("/").toLowerCase();
			const base = canonical.replace(/\\/g, "/");
			return base.endsWith("/") ? base + tail : `${base}/${tail}`;
		}

		// Use win32.dirname (not the platform-default dirname) so a
		// Windows-shaped path is parsed with win32 semantics regardless of the
		// running OS — consistent with the win32.resolve/win32.normalize this
		// branch already commits to. The platform-default POSIX dirname would
		// find no separator in a win32-resolved "C:\repo\..." path (its only
		// separators are backslashes), collapse to ".", stop the upward walk at
		// cwd, and mangle the key on Linux CI (refs #1150, the #1024
		// OS-divergence class).
		const parent = win32.dirname(current);
		if (parent === current) {
			// Reached filesystem root without finding existing dir
			// Fall back to full lowercase
			throw new Error("No existing parent found");
		}

		nonExistentParts.push(win32.basename(current));
		current = parent;
	}
}

/**
 * Convert a file:// URI to a normalized path.
 * Handles URL decoding and Windows drive letter normalization.
 */
export function uriToPath(uri: string): string {
	try {
		const filePath = fileURLToPath(uri);
		return normalizeFilePath(filePath);
	} catch {
		// Not a valid file:// URI, treat as plain path
		return normalizeFilePath(uri);
	}
}

/**
 * Decode a file:// URI to an on-disk path WITHOUT map-key normalization.
 *
 * `uriToPath` runs its result through `normalizeFilePath`, which on win32
 * lowercases the nonexistent tail of a path (see `resolveNonExisting`) and
 * canonicalizes an existing path to its real casing. That is correct for Map
 * keys, but DESTRUCTIVE for a real create/rename target: creating `NewFile.txt`
 * would write `newfile.txt`, and a legitimate case-only rename would collapse
 * to a no-op ("source and destination must differ"). Disk mutations must honor
 * the caller's intended casing, so they resolve their target through this
 * decode-only path while confinement/validation keep using the normalized
 * `uriToPath`. Non-win32 is unaffected either way (normalizeFilePath is a
 * near-identity there).
 */
export function uriToDiskPath(uri: string): string {
	try {
		return fileURLToPath(uri);
	} catch {
		// Not a valid file:// URI — treat as a plain path (matches uriToPath).
		return uri;
	}
}

/**
 * Convert a path to a file:// URI.
 * Does NOT normalize the path - URIs preserve original casing.
 */
export function pathToUri(filePath: string): string {
	return pathToFileURL(filePath).href;
}

/**
 * Normalize a Map key lookup for file paths.
 * Use this when getting/setting values in Maps that use file paths as keys.
 */
export function normalizeMapKey(filePath: string): string {
	return normalizeFilePath(filePath);
}

/**
 * Human-facing path relative to a project root when the file is inside it.
 *
 * Parses by path SHAPE, not host OS (refs #1150/#1152, shape-2 class #1163):
 * a Windows-shaped `filePath` (drive-letter/UNC — e.g. a persisted call-graph
 * symbol-key path `C:\repo\src\x.ts` rehydrated on a Linux CI run) is split
 * with `win32.*` regardless of `process.platform`. The host-default
 * `isAbsolute`/`relative` find no drive-letter anchor in a win32 path on POSIX:
 * `path.isAbsolute("C:\\repo\\x.ts")` returns FALSE on Linux, short-circuiting
 * to the raw absolute path instead of ever relativizing it — so a file that IS
 * under the project root renders as a full absolute path on Linux but the
 * expected `src/x.ts` on Windows (green-locally / wrong-on-CI, the #1024
 * divergence class). `win32.*` on a native POSIX path (Windows never sees one;
 * Linux native paths aren't Windows-shaped) is never selected, so same-OS
 * native paths are unchanged either way.
 */
export function toProjectRelativePath(
	filePath: string,
	projectRoot: string,
): string {
	const p = isWindowsPath(filePath) ? win32 : path;
	if (!p.isAbsolute(filePath)) return filePath.replace(/\\/g, "/");
	const inside = (root: string, file: string): string | undefined => {
		const relative = p.relative(p.resolve(root), file);
		return relative &&
			relative !== ".." &&
			!relative.startsWith(`..${p.sep}`) &&
			!p.isAbsolute(relative)
			? relative.replace(/\\/g, "/")
			: undefined;
	};
	const direct = inside(projectRoot, filePath);
	if (direct !== undefined) return direct;
	// #4101: a canonical key (`normalizeMapKey`: realpath on win32, so 8.3 names,
	// junctions and subst drives are expanded) set against a root the caller
	// spelled differently. Canonicalize both sides before giving up; a file
	// that really is outside the root stays outside.
	const canonical = inside(
		normalizeFilePath(projectRoot),
		normalizeFilePath(filePath),
	);
	if (canonical !== undefined) return canonical;
	return filePath.replace(/\\/g, "/");
}

/**
 * Cheap, syntactic-only Map key normalization: slash-fold + (on Windows)
 * lowercase. No `realpathSync` / filesystem I/O.
 *
 * `normalizeMapKey` (via `normalizeFilePath`) calls `realpathSync.native()` to
 * get canonical on-disk casing — correct for maps that key long-lived state
 * shared across call sites (e.g. LSP/read-guard caches), but expensive when
 * the *point* of the cache is to avoid filesystem calls in the first place:
 * for a candidate path that does NOT exist (the common case for sibling-probe
 * memos), `normalizeFilePath` walks up the directory tree doing its own
 * `existsSync` calls to resolve the nearest existing ancestor — measured at
 * ~11x slower than the single `existsSync` probe such a cache is trying to
 * save (refs #191).
 *
 * Safe to use ONLY for ephemeral, single-process, single-walk caches whose
 * keys are produced by this process's own `path.join`/`path.resolve` calls
 * within the same run (so separators and casing are already consistent
 * modulo simple slash direction) — never for state shared across processes,
 * persisted, or compared against externally-supplied paths where symlink /
 * real-casing resolution actually matters.
 */
export function normalizeEphemeralMapKey(filePath: string): string {
	// Most hot-path keys on POSIX are already canonical slash-separated strings.
	// Preserve that identity instead of allocating a replacement string for each
	// file in a large diagnostics reconciliation.
	if (process.platform !== "win32" && !filePath.includes("\\")) return filePath;
	const slashed = filePath.replace(/\\/g, "/");
	return process.platform === "win32" ? slashed.toLowerCase() : slashed;
}

/**
 * Compare two file paths for equality, handling Windows case-insensitivity
 * and mixed separators (backslash vs forward slash).
 */
export function pathsEqual(a: string, b: string): boolean {
	return normalizeFilePath(a) === normalizeFilePath(b);
}

/**
 * Check if `child` is under `parent` directory.
 * Separator-agnostic and case-insensitive on Windows.
 */
/**
 * Yield each directory from `startDir` up to (and including) the filesystem
 * root. Terminates when `path.dirname(current) === current` so it works on
 * Windows drive roots and POSIX `/` alike.
 *
 * Single source of truth for the half-dozen "walk up the directory tree
 * looking for X" loops that have accumulated across the codebase. Callers
 * that need an "is there a file named Y anywhere on the way up" check
 * should use `findNearestContaining` instead.
 */
export function* walkUpDirs(startDir: string): Generator<string> {
	let current = path.resolve(startDir);
	while (true) {
		yield current;
		const parent = path.dirname(current);
		if (parent === current) return;
		current = parent;
	}
}

/**
 * Walk up from `startDir` and return the first directory that contains any
 * of `candidates` on disk. Returns `undefined` if none match.
 *
 * @example
 *   findNearestContaining("/repo/pkg/src", ["package.json", "tsconfig.json"]);
 *   // → "/repo/pkg" if pkg/package.json exists, "/repo" if only /repo/package.json
 */
export function findNearestContaining(
	startDir: string,
	candidates: readonly string[],
): string | undefined {
	for (const dir of walkUpDirs(startDir)) {
		for (const name of candidates) {
			if (existsSync(path.join(dir, name))) return dir;
		}
	}
	return undefined;
}

/**
 * Walk up from `startDir` and return the first matching FILE path (not just
 * the containing directory) for any of `names`, first-match-wins within each
 * directory in `names` order. Single source of truth for the "walk up
 * looking for one of these config filenames" loop that `opengrep-config.ts`,
 * `typos-config.ts`, `zizmor-config.ts`, and `sgconfig.ts` each hand-rolled
 * independently (refs #680), and that `php-cs-fixer-config.ts` now delegates
 * to as well (refs #2472 review F2).
 *
 * UNCEILINGED by default (refs #2472 review round 3, F1) — `options.homeDir`
 * is opt-in, not default-on. A prior version applied the SAME `$HOME`
 * ceiling as `findNearestMarkerRoot` unconditionally, which broke every one
 * of these tools' actual discovery contract: each of them treats a config
 * living directly at `$HOME` (`~/typos.toml`, `~/sgconfig.yml`, …) as the
 * user's legitimate GLOBAL config, and reads it itself regardless of pi-lens
 * — the ceiling didn't stop pi-lens from seeing an unrelated ancestor
 * config, it stopped pi-lens from seeing the SAME config the tool was about
 * to read on its own, so pi-lens silently fell back to (or, for typos,
 * injected and let its own shipped `_typos.toml` merge over) the user's
 * config where the tool's own resolver would have honored it. `php-cs-fixer`
 * makes the same mismatch concrete: its detection gates
 * (`hasPhpCsFixerConfig` via `findNearestContaining`, `phpCsFixerFormatter
 * .detect` via its own `findUp`) are both unceilinged, so a ceilinged
 * carriage here disagreed with its own gate — "config exists" from the gate,
 * "config not found" from the resolver — and dropped the very `--config`
 * argv #2472 exists to carry. Pass `options.homeDir` only when a caller
 * affirmatively wants the ceiling (a config found at or above THAT directory
 * is never returned); omitting it walks all the way to the filesystem root,
 * matching `findNearestContaining`'s unceilinged behavior and every
 * underlying tool's own discovery.
 *
 * Distinct from `findNearestContaining`, which returns the containing
 * directory rather than the matched file path — use that one when the caller
 * only needs "is one of these present nearby", not which file it is.
 *
 * @example
 *   findLocalToolConfig(cwd, ["typos.toml", "_typos.toml", ".typos.toml"]);
 *   // → "/repo/typos.toml" if present, else undefined
 */
export function findLocalToolConfig(
	startDir: string,
	names: readonly string[],
	options: { homeDir?: string } = {},
): string | undefined {
	const homeDir =
		options.homeDir !== undefined ? path.resolve(options.homeDir) : undefined;
	for (const dir of walkUpDirs(startDir || process.cwd())) {
		if (homeDir !== undefined && isAtOrAboveHomeDir(dir, homeDir)) {
			return undefined;
		}
		for (const name of names) {
			const candidate = path.join(dir, name);
			if (existsSync(candidate)) return candidate;
		}
	}
	return undefined;
}

export interface FindNearestMarkerRootOptions {
	/**
	 * Directory names/files that, if found BEFORE any of `markers`, stop the
	 * walk and make it return `null` — e.g. `.git`/`.hg`/`.svn` so a search
	 * starting inside a repo without its own project marker doesn't escape
	 * past that repo's VCS boundary to pick up an unrelated parent's marker.
	 * Omit for callers with no such boundary (default: none).
	 */
	boundaries?: readonly string[];
	/** Override for `os.homedir()`, primarily for tests. */
	homeDir?: string;
	/** Further validate a marker path before accepting its containing directory. */
	markerPredicate?: (markerPath: string) => boolean;
}

export type GitMarkerResult =
	| { kind: "valid" | "absent" }
	| { kind: "unavailable"; cause: unknown };

export type MarkerRootResult =
	| { kind: "found"; root: string }
	| { kind: "not-found"; reason: "home-ceiling" | "root" | "depth-limit" }
	| { kind: "unavailable"; markerPath: string; cause: unknown };

/** Detailed ownership walks require a probe that can distinguish I/O failure. */
export interface FindNearestMarkerRootDetailedOptions {
	homeDir?: string;
	markerPredicate: (markerPath: string) => GitMarkerResult;
}

/**
 * Accept only a real Git repository marker: a directory with HEAD, or a
 * worktree/submodule marker file whose first line starts with `gitdir:`.
 * Ownership callers request details: absence may permit climbing, but a read
 * error must not invent an enclosing owner. Legacy callers retain a boolean.
 */
export function isRealGitMarker(
	markerPath: string,
	details: true,
): GitMarkerResult;
export function isRealGitMarker(markerPath: string): boolean;
export function isRealGitMarker(
	markerPath: string,
	details?: true,
): boolean | GitMarkerResult {
	// Array callbacks supply an index here; only the documented true opts in.
	const detailed = details === true;
	try {
		const marker = statSync(markerPath);
		let valid = false;
		if (marker.isDirectory()) {
			// existsSync hides EACCES as false. HEAD is part of ownership evidence,
			// so detailed callers need its failure just as much as the marker's.
			statSync(path.join(markerPath, "HEAD"));
			valid = true;
		} else if (marker.isFile()) {
			valid = readFileSync(markerPath, "utf8")
				.split(/\r?\n/, 1)[0]
				.startsWith("gitdir:");
		}
		if (!detailed) return valid;
		return { kind: valid ? "valid" : "absent" };
	} catch (cause) {
		if (!detailed) return false;
		if (
			typeof cause === "object" &&
			cause !== null &&
			"code" in cause &&
			(cause.code === "ENOENT" || cause.code === "ENOTDIR")
		) {
			return { kind: "absent" };
		}
		return { kind: "unavailable", cause };
	}
}

/**
 * Walk up from `startDir` looking for a directory containing any of
 * `markers`, the same containment-aware climb `knip-client.ts` and
 * `dead-code-client.ts` each used to hand-roll independently (refs #625):
 *
 *   - Never resolves at or above `$HOME` (via `isAtOrAboveHomeDir`) — a
 *     marker found there has escaped the user's workspace.
 *   - If `options.boundaries` is given and one is found before any `marker`,
 *     stops and returns `null` rather than continuing past it.
 *   - Depth-capped at 64 climbs, matching the callers' existing safety bound
 *     (guards a pathological symlink loop; real depths are ~10).
 *   - Returns `null` — never `startDir` — when nothing is found. Callers
 *     must treat `null` as "no project here", not fall back to the start
 *     directory (a `null`-swallowing fallback was the #250/#296 bug class:
 *     scanning $HOME wholesale from a bare cwd).
 *
 * For a plain "find nearest containing directory" with no boundary concept,
 * use `findNearestContaining` instead. Distinct from `startup-scan.ts`'s
 * `findNearestProjectRoot` (fixed marker list, no boundaries, no home-check —
 * that caller applies `isAtOrAboveHomeDir` itself afterward); named
 * differently here to avoid confusion between the two.
 */
export function findNearestMarkerRoot(
	startDir: string,
	markers: readonly string[],
	options: FindNearestMarkerRootOptions = {},
): string | null {
	const boundaries = options.boundaries ?? [];
	const homeDir = path.resolve(options.homeDir ?? os.homedir());
	const markerPredicate = options.markerPredicate ?? (() => true);
	let current = path.resolve(startDir);
	for (let depth = 0; depth < 64; depth++) {
		if (isAtOrAboveHomeDir(current, homeDir)) return null;
		if (
			markers.some(
				(m) =>
					existsSync(path.join(current, m)) &&
					markerPredicate(path.join(current, m)),
			)
		)
			return current;
		if (boundaries.some((m) => existsSync(path.join(current, m)))) return null;
		const parent = path.dirname(current);
		if (parent === current) return null;
		current = parent;
	}
	return null;
}

/**
 * Ownership walk for callers that must tell "no marker here" from "could not
 * tell" (refs #3644, #3691). Same climb as `findNearestMarkerRoot` (home
 * ceiling, 64-step cap) but the predicate returns a `GitMarkerResult`, so an I/O
 * failure stops the walk as `unavailable` instead of becoming "absent" and
 * letting an enclosing root be mistaken for the owner. It takes no
 * `boundaries`, so `"boundary"` is not a reason it can return. Kept separate
 * from the legacy walker so the legacy callers' `existsSync` precheck and
 * boolean predicate contract cannot drift with it.
 */
export function findNearestMarkerRootDetailed(
	startDir: string,
	markers: readonly string[],
	options: FindNearestMarkerRootDetailedOptions,
): MarkerRootResult {
	const homeDir = path.resolve(options.homeDir ?? os.homedir());
	let current = path.resolve(startDir);
	for (let depth = 0; depth < 64; depth++) {
		if (isAtOrAboveHomeDir(current, homeDir))
			return { kind: "not-found", reason: "home-ceiling" };
		for (const marker of markers) {
			const markerPath = path.join(current, marker);
			const checked = options.markerPredicate(markerPath);
			if (checked.kind === "unavailable")
				return { kind: "unavailable", markerPath, cause: checked.cause };
			if (checked.kind === "valid") return { kind: "found", root: current };
		}
		const parent = path.dirname(current);
		if (parent === current) return { kind: "not-found", reason: "root" };
		current = parent;
	}
	return { kind: "not-found", reason: "depth-limit" };
}

/**
 * True when `dir` is the home directory OR an ancestor of it (`/home`,
 * `C:\Users`, the filesystem root, …). A project-root search that climbs to
 * such a directory has escaped the user's workspace — walking down from it
 * scans unrelated trees (the #250 runaway). Use this as the single shared
 * ceiling on any upward project-root resolution, instead of an exact
 * `=== os.homedir()` check (which a marker found *above* `$HOME` slips past).
 * A normal project *under* home (e.g. `~/code/app`) is NOT at-or-above home,
 * so it still resolves fine. Refs #253.
 *
 * ONE expression, deliberately: `path.relative` alone answers "is home inside
 * `dir`, or the same directory as `dir`", and it answers with the PLATFORM's
 * path-equality semantics — case-folding on win32, case-sensitive on POSIX.
 * The `resolvedDir === resolvedHome` shortcut that used to precede it was
 * case-SENSITIVE on every platform, so `c:\Users\jane` (the lowercase-drive
 * form VS Code URIs produce, and the form 46 records in a real `latency.log`
 * carry) missed the equality test AND was then rejected by a `rel !== ""`
 * clause — reporting "not at home" for the home directory itself and letting
 * every ceilinged walker climb straight past HOME (#2544 review F1).
 *
 *   rel === ""                       ⇢ `dir` IS home
 *   rel relative, no leading `..`    ⇢ home is INSIDE `dir` (an ancestor)
 *   rel starts with `..`             ⇢ home is elsewhere — sibling, or the
 *                                      prefix trap `C:\Users\jane2` → home
 *                                      `C:\Users\jane` gives `..\jane`
 *   rel absolute                     ⇢ different Windows drive
 *
 * Same shape as `isUnderDir` above; keep the two in step.
 *
 * `pathImpl` exists so the ubuntu Unit tests lane — the authoritative one —
 * can exercise the WIN32 semantics this helper's whole bug was about. Every
 * assertion that matters here (drive-letter folding, cross-drive `rel`) is
 * win32-only, so with the ambient `path` hardcoded the ceiling was enforced
 * only on a maintainer's dev box and CI's diff was structurally zero (#2544
 * review F2). Production never passes it; `path.win32`/`path.posix` are pure,
 * host-independent implementations, so `tests/clients/path-utils.test.ts` runs
 * the same table under both on every lane. Lane-level fix tracked as #2536.
 */
export function isAtOrAboveHomeDir(
	dir: string,
	homeDir: string = os.homedir(),
	pathImpl: typeof path = path,
): boolean {
	const rel = pathImpl.relative(
		pathImpl.resolve(dir),
		pathImpl.resolve(homeDir),
	);
	return !rel.startsWith("..") && !pathImpl.isAbsolute(rel);
}

/**
 * Rewrite a `$HOME`-anchored path to its `~` form for a DIAGNOSTIC surface.
 *
 * `~/.pi-lens/config.json` says everything an operator needs about which file
 * won, and `C:/Users/jane.doe/.pi-lens/config.json` says that plus the
 * account name. The second is the shape a global config path always has, so any
 * projection that names one leaks an identifier by default rather than by
 * accident (#2440 review finding F5).
 *
 * Deliberately NOT built on `normalizeFilePath`/`isUnderDir`: those resolve
 * through `realpathSync`, and a redaction helper on a diagnostic path must be
 * pure, total, and unable to throw for a file that no longer exists. This is a
 * string rewrite and nothing else.
 *
 * A path that is not under home is returned UNCHANGED — separators included.
 * Normalizing unrelated paths on the way past would make the helper's blast
 * radius every path any projection ever carries, for no redaction benefit.
 */
export function homeRelativePath(
	filePath: string,
	homeDir: string = os.homedir(),
): string {
	if (filePath.length === 0) return filePath;
	const candidate = toPosix(filePath);
	const home = toPosix(homeDir).replace(/\/+$/, "");
	if (home.length === 0) return filePath;
	// Windows paths are case-insensitive, so the COMPARISON folds case there
	// while the returned tail keeps the caller's own casing.
	const fold = (text: string): string =>
		process.platform === "win32" ? text.toLowerCase() : text;
	const foldedHome = fold(home);
	const foldedCandidate = fold(candidate);
	if (foldedCandidate === foldedHome) return "~";
	if (!foldedCandidate.startsWith(`${foldedHome}/`)) return filePath;
	return `~${candidate.slice(home.length)}`;
}

export function isUnderDir(child: string, parent: string): boolean {
	return isUnderCanonicalDir(
		normalizeFilePath(child),
		normalizeFilePath(parent),
	);
}

/**
 * {@link isUnderDir} for two spellings already passed through
 * `normalizeFilePath`, so a caller testing many children against a few
 * parents canonicalizes each path once (#4530).
 */
export function isUnderCanonicalDir(
	normChild: string,
	normParent: string,
): boolean {
	// Ensure parent ends with / for prefix matching
	const parentPrefix = normParent.endsWith("/") ? normParent : `${normParent}/`;
	return normChild === normParent || normChild.startsWith(parentPrefix);
}

/** True when a path is outside the session's project root. */
export function isOutsideProjectRoot(
	filePath: string,
	projectRoot: string,
): boolean {
	return !isUnderDir(filePath, projectRoot);
}

const VENDOR_DIR_NAMES = new Set([
	"node_modules",
	"vendor",
	"vendors",
	"third_party",
	"third-party",
	".venv",
	"site-packages",
	"bower_components",
]);

/** True when any path segment names an installed or vendored dependency tree. */
export function isVendorPath(filePath: string): boolean {
	return normalizeFilePath(filePath)
		.split("/")
		.some((segment) => VENDOR_DIR_NAMES.has(segment.toLowerCase()));
}

/**
 * Returns true when a file should be treated as external/vendor and excluded
 * from pipelines (LSP, diagnostics, complexity, read-guard, etc.).
 *
 * Cases:
 *   1. Outside the project root entirely (e.g. global npm packages, system files)
 *   2. Inside the project but under a vendor directory (node_modules, vendor, third_party, etc.)
 */
export function isExternalOrVendorFile(
	filePath: string,
	projectRoot: string,
): boolean {
	if (isOutsideProjectRoot(filePath, projectRoot)) return true;
	return isVendorPath(filePath);
}

/**
 * Shared marker-glob semantics for every "does this directory contain a file
 * matching this glob" probe (#895 review): match against the entry NAME only,
 * `dot: true` so dotfile markers match, `nocase` on win32 to match the
 * filesystem (and the project ignore matcher). The three marker probes —
 * language-profile.ts `hasProjectMarker`, workspace-topology.ts
 * `hasBasenameMarker`, lsp/server.ts `markerExists` — must all route their
 * glob matching through here rather than call minimatch with hand-copied
 * options.
 */
export function nameMatchesMarkerGlob(name: string, pattern: string): boolean {
	return minimatch(name, pattern, {
		dot: true,
		nocase: process.platform === "win32",
	});
}

/**
 * Files/symlinks-only marker-glob probe over a directory listing — a
 * *directory* named like a marker (e.g. a `Foo.csproj/` dir) is not a project
 * file (#201).
 */
export function direntsHaveMarkerGlobMatch(
	entries: readonly Dirent[],
	pattern: string,
): boolean {
	return entries.some(
		(entry) =>
			(entry.isFile() || entry.isSymbolicLink()) &&
			nameMatchesMarkerGlob(entry.name, pattern),
	);
}

/**
 * The axes on which build tools' workspace-MEMBER glob dialects genuinely
 * diverge (#2591). Every "does this workspace declare this directory as a
 * member" matcher in `clients/` routes through
 * {@link matchesWorkspaceMemberPattern} with one of the dialect constants
 * below rather than hand-rolling its own segment regex or minimatch options
 * block — the same single-source-of-truth rule `nameMatchesMarkerGlob` holds
 * for marker globs.
 *
 * Two axes deliberately do NOT appear here because every dialect agrees on
 * them, and a field with one value across every constant is configuration
 * that can never be wrong:
 *
 * - **Case sensitivity.** Cargo's pre-fold segment regex carried no `i` flag;
 *   uv matches with `MatchOptions { case_sensitive: true, .. }` on every
 *   platform (`MatchOptions::new()`'s default, kept by `is_included_in_workspace`).
 *   Matching is unconditionally case-SENSITIVE here, on Windows too.
 * - **Leading dots.** Cargo's pre-fold `*` compiled to `[^/]*`, which matches a
 *   leading `.` like any other character; uv passes `require_literal_leading_dot:
 *   false` (again the `MatchOptions::new()` default), which pi-lens expressed as
 *   minimatch's `dot: true`. A `*` matches `.hidden` in every dialect.
 *
 * If a fourth dialect ever disagrees on either, it becomes a field then — not
 * before.
 */
export interface WorkspaceMemberGlobDialect {
	/** Dialect name, for the dialect table in `tests/clients/path-utils.test.ts`. */
	readonly name: string;
	/**
	 * `crosses-components`: a path component that is exactly `**` matches zero
	 * or more path components (a TRAILING `/**` requires at least one, matching
	 * minimatch and rust `glob`). `pattern-never-matches`: a pattern containing
	 * `**` anywhere matches nothing at all.
	 */
	readonly globstar: "crosses-components" | "pattern-never-matches";
	/**
	 * Whether `*`/`?` may span a `/` — rust `glob`'s `require_literal_separator:
	 * false`. When false (the common case) a wildcard is confined to one path
	 * component, which is also what makes a pattern's component COUNT have to
	 * equal the path's: `crates/*` cannot reach `crates/a/b` because `[^/]*`
	 * cannot cross the separator. Component-count equality is therefore an
	 * entailment of this axis, not a separate one — see the dialect table's
	 * `segment-count mismatch` vectors, which red if `[^/]*` is widened.
	 */
	readonly wildcardCrossesSeparator: boolean;
	/** Whether `[abc]`/`[!abc]` is a character class or a literal bracket run. */
	readonly characterClasses: boolean;
	/** Tool-specific pattern normalization, applied before compilation. */
	readonly normalizePattern: (pattern: string) => string;
}

/**
 * Cargo `[workspace] members`/`exclude` entries.
 *
 * KNOWN LIMITATION (#1671 F6, documented rather than implemented, preserved
 * byte-for-byte by #2591's fold): a recursive `**` component is NOT supported
 * and a pattern containing one never matches — cargo workspaces that rely on
 * `**` to pull in an arbitrarily-nested crate tree under-hoist (the crate stays
 * independently rooted instead of joining the workspace). Folding cargo onto
 * uv's `crosses-components` globstar would silently change Rust-LSP root
 * selection, so the divergence is kept as a dialect value, not resolved.
 *
 * `characterClasses: false` is likewise a preserved divergence, not a
 * considered choice: cargo's pre-fold segment compiler escaped `[` and `]`
 * into literals, so `crates/[ab]` names a directory literally called `[ab]`.
 * Real cargo (the `glob` crate) would read it as a class; changing that here
 * would be the same unreviewed Rust-hoisting change.
 */
export const CARGO_WORKSPACE_MEMBER_DIALECT: WorkspaceMemberGlobDialect = {
	name: "cargo",
	globstar: "pattern-never-matches",
	wildcardCrossesSeparator: false,
	characterClasses: false,
	normalizePattern: (pattern) => pattern.replace(/\/+$/, ""),
};

/**
 * uv `[tool.uv.workspace] members`, pinned to
 * `astral-sh/uv@3c979abda4530fe9bf3d92e9bcf5c5575e3b3126`,
 * `crates/uv-workspace/src/workspace.rs` `is_included_in_workspace`: the glob is
 * `normalize_path`d first (so a leading `./` and any interior `.` component are
 * not part of the pattern) and matched with
 * `MatchOptions { require_literal_separator: true, ..MatchOptions::new() }`.
 */
export const UV_WORKSPACE_MEMBERS_DIALECT: WorkspaceMemberGlobDialect = {
	name: "uv-members",
	globstar: "crosses-components",
	wildcardCrossesSeparator: false,
	characterClasses: true,
	normalizePattern: (pattern) => path.posix.normalize(toPosix(pattern)),
};

/**
 * uv `[tool.uv.workspace] exclude`, same upstream file and SHA
 * (`WorkspaceExclusions::matches`): an exclusion is matched with
 * `Pattern::matches_path`, i.e. `MatchOptions::new()` defaults, where
 * `require_literal_separator` is FALSE — so a `*` in an exclusion DOES cross
 * `/` (`exclude = ['packages/a*c']` excludes `packages/a/b/c`). Two different
 * option sets inside one tool, which is why the dialect is an object and the
 * two uv constants are not one.
 *
 * Before #2591 this was a documented limitation: minimatch cannot express a
 * separator-crossing `*`, so pi-lens under-excluded. The dialect object can, so
 * it is now implemented rather than documented.
 */
export const UV_WORKSPACE_EXCLUDE_DIALECT: WorkspaceMemberGlobDialect = {
	name: "uv-exclude",
	globstar: "crosses-components",
	wildcardCrossesSeparator: true,
	characterClasses: true,
	normalizePattern: (pattern) => path.posix.normalize(toPosix(pattern)),
};

/**
 * Index of the `]` closing the character class opened at `open`, or `-1` when
 * the run is unterminated (in which case the `[` is a literal). A leading `!`
 * or `^` negates, and a `]` in first position is a literal class member — the
 * shape both minimatch and rust `glob` accept.
 */
function findCharacterClassEnd(segment: string, open: number): number {
	let i = open + 1;
	if (segment[i] === "!" || segment[i] === "^") i += 1;
	if (segment[i] === "]") i += 1;
	for (; i < segment.length; i += 1) if (segment[i] === "]") return i;
	return -1;
}

/**
 * One step of a compiled workspace-member pattern. Every step consumes a
 * BOUNDED amount of the path (one character, or one character at a time under
 * its own repeat), which is what makes the evaluator below non-backtracking:
 * there is no nested quantifier for a backtracking engine to explore.
 *
 * - `literal` — this exact code unit, `/` included.
 * - `one` / `star` — a `?` / `*`, consuming one / any number of characters
 *   that {@link stepAcceptsChar} admits.
 * - `class` — a `[abc]`/`[!abc]` run, compiled to a one-character regex. This
 *   is the only compiled regex left in the matcher, and it is bounded by
 *   construction: one class, no quantifier, tested against a one-character
 *   string.
 * - `split` — an epsilon fork: match from `alternative`, or from the next
 *   step. Only a `**` emits one, to express "zero or more whole components".
 */
type WorkspaceGlobStep =
	| { readonly kind: "literal"; readonly char: string }
	| { readonly kind: "one"; readonly crossesSeparator: boolean }
	| { readonly kind: "star"; readonly crossesSeparator: boolean }
	| { readonly kind: "class"; readonly match: RegExp }
	| WorkspaceGlobSplit;

/** The one mutable step: `alternative` is back-patched once the group it skips is emitted. */
interface WorkspaceGlobSplit {
	readonly kind: "split";
	alternative: number;
}

/**
 * May a wildcard with this separator policy consume `ch`?
 *
 * A separator-confined wildcard (`[^/]` in the regex this replaced) takes
 * anything but `/`. A separator-CROSSING one — uv `exclude`'s `*`/`?`, and
 * every `**` in either uv dialect — spelled `.` in that regex, which is every
 * code unit EXCEPT the four line terminators. That exclusion is preserved
 * deliberately rather than "fixed": minimatch's globstar is `.`-based too, so
 * a `\n` inside a directory name has never matched across a `**` in either
 * implementation, and the differential oracle would flag a change here as a
 * divergence rather than an improvement (#2603).
 */
function stepAcceptsChar(crossesSeparator: boolean, ch: string): boolean {
	return crossesSeparator
		? ch !== "\n" && ch !== "\r" && ch !== "\u2028" && ch !== "\u2029"
		: ch !== "/";
}

/**
 * Compile a normalized workspace-member pattern into a step list, or
 * `undefined` when it cannot be compiled at all.
 *
 * A `**` component consumes zero or more path components — except as the LAST
 * component, where it requires at least one (`a/**` matches `a/b`, not `a`),
 * reproducing both minimatch's and rust `glob`'s answer. It is emitted as
 * `split → one → star → literal "/"`, i.e. "nothing, or one-or-more characters
 * followed by the `/` that ends them", after the separator that precedes it.
 * That is the same language as the `(?:/.+)?/` group the previous compiler
 * emitted — `X(?:/.+)?/Y` and `X/(?:.+/)?Y` both denote `X/Y` ∪ `X/.+/Y` — in a
 * form with no nested quantifier.
 */
function compileWorkspaceMemberPattern(
	pattern: string,
	dialect: WorkspaceMemberGlobDialect,
): WorkspaceGlobStep[] | undefined {
	const isGlobstar = (component: string): boolean =>
		component === "**" && dialect.globstar === "crosses-components";
	const components = pattern.split("/");
	const steps: WorkspaceGlobStep[] = [];
	let needSeparator = false;
	for (let c = 0; c < components.length; c += 1) {
		if (needSeparator) steps.push({ kind: "literal", char: "/" });
		needSeparator = false;
		const component = components[c];
		if (isGlobstar(component)) {
			if (c === components.length - 1) {
				// `.+` — a trailing `**` requires at least one character.
				steps.push({ kind: "one", crossesSeparator: true });
				steps.push({ kind: "star", crossesSeparator: true });
				continue;
			}
			// `(?:.+/)?` — zero or more whole components. The group already ends
			// at a `/`, so the next component must NOT emit one.
			const split: WorkspaceGlobSplit = { kind: "split", alternative: -1 };
			steps.push(split);
			steps.push({ kind: "one", crossesSeparator: true });
			steps.push({ kind: "star", crossesSeparator: true });
			steps.push({ kind: "literal", char: "/" });
			split.alternative = steps.length;
			continue;
		}
		for (let i = 0; i < component.length; i += 1) {
			const ch = component[i];
			if (ch === "*") {
				steps.push({
					kind: "star",
					crossesSeparator: dialect.wildcardCrossesSeparator,
				});
				continue;
			}
			if (ch === "?") {
				steps.push({
					kind: "one",
					crossesSeparator: dialect.wildcardCrossesSeparator,
				});
				continue;
			}
			if (ch === "[" && dialect.characterClasses) {
				const close = findCharacterClassEnd(component, i);
				if (close !== -1) {
					// `\` and a first-position `]` are literal class MEMBERS in glob;
					// left alone they would be a regex escape and an empty-class
					// terminator (`[]ab]` is `[]` + `ab]` in JS), so both are escaped.
					const body = component.slice(i + 1, close).replace(/[\\\]]/g, "\\$&");
					const source = body.startsWith("!")
						? `[^${body.slice(1)}]`
						: `[${body}]`;
					let match: RegExp;
					try {
						match = new RegExp(`^${source}$`);
					} catch {
						// A glob character class is not a JS character class: `[z-a]`
						// is a legal glob (matching nothing, since the range is empty)
						// and an illegal RegExp ("Range out of order"). Fail CLOSED —
						// an uncompilable pattern declares no member and excludes
						// nothing — which is also the answer the deleted minimatch call
						// gave (#2591 review round 2, F2).
						return undefined;
					}
					steps.push({ kind: "class", match });
					i = close;
					continue;
				}
			}
			steps.push({ kind: "literal", char: ch });
		}
		needSeparator = true;
	}
	return steps;
}

const WORKSPACE_GLOB_MEMO_CELL_CAP = 2_000_000;

/**
 * Does the whole of `subject` match the whole of `steps`?
 *
 * A memoized (step index, path index) table, filled once, bottom-up:
 * `table[s][p]` is "steps `s…` match `subject[p…]`". Every cell reads only
 * cells with a larger step index or a larger path index, so one backward
 * double loop fills the table with no recursion and no re-entry — the match is
 * O(steps x characters) in time and space, with no path through it that can
 * take exponential time (#2603).
 *
 * The compiled whole-path regex this replaced was correct but backtracking:
 * every `**` emitted its own nullable `.+`, and N of them explored 2^N splits
 * of a non-matching subject. #2591 collapsed CONSECUTIVE `**`s, which is a
 * normalization that cannot fire across a separating component, so
 * `("**\/*" x12)/zzz` against a 40-component path still took 124900 ms (#2603);
 * the same shapes are microseconds here. There is nothing left to collapse for
 * speed, so no collapse is done: `a/**\/**\/b` compiles to two adjacent
 * `(?:.+/)?` groups, which denote the same language as one and cost the same
 * table.
 */

function matchesWorkspaceMemberSteps(
	steps: readonly WorkspaceGlobStep[],
	subject: string,
	onCap?: () => void,
): boolean {
	const stepCount = steps.length;
	const width = subject.length + 1;
	// 2,000,000 cells is above real ~8e5-cell globs and below the issue's ~1.6e7-cell row.
	if ((stepCount + 1) * width > WORKSPACE_GLOB_MEMO_CELL_CAP) {
		onCap?.();
		return false;
	}
	// One byte per (step, position) cell; `1` means "the rest matches from here".
	const table = new Uint8Array((stepCount + 1) * width);
	for (let p = subject.length; p >= 0; p -= 1) {
		const atEnd = p === subject.length;
		// The empty step list matches only the empty remainder.
		table[stepCount * width + p] = atEnd ? 1 : 0;
		for (let s = stepCount - 1; s >= 0; s -= 1) {
			const step = steps[s];
			const next = (s + 1) * width;
			let matched = 0;
			switch (step.kind) {
				case "literal":
					matched =
						!atEnd && subject[p] === step.char ? table[next + p + 1] : 0;
					break;
				case "one":
					matched =
						!atEnd && stepAcceptsChar(step.crossesSeparator, subject[p])
							? table[next + p + 1]
							: 0;
					break;
				case "class":
					matched =
						!atEnd && step.match.test(subject[p]) ? table[next + p + 1] : 0;
					break;
				case "star":
					// Consume nothing, or one more character and stay on this step.
					matched =
						table[next + p] === 1 ||
						(!atEnd &&
							stepAcceptsChar(step.crossesSeparator, subject[p]) &&
							table[s * width + p + 1] === 1)
							? 1
							: 0;
					break;
				case "split":
					matched =
						table[step.alternative * width + p] === 1 || table[next + p] === 1
							? 1
							: 0;
					break;
			}
			table[s * width + p] = matched;
		}
	}
	return table[0] === 1;
}

/**
 * Does `relativePath` — a `/`-separated path relative to the workspace root —
 * match one declared workspace-member (or workspace-exclude) `pattern` under
 * `dialect`?
 *
 * This is the ONE workspace-member matcher (#2591). `clients/lsp/server.ts`'s
 * `cargoWorkspaceDeclaresMember` and `clients/python-environment.ts`'s
 * `isUvWorkspaceMember` are thin callers of it; neither keeps a private segment
 * compiler or minimatch options block any more.
 *
 * `clients/review-graph/workspace-modules.ts`'s `expandWorkspacePattern` is
 * deliberately NOT a caller: npm/pnpm `workspaces` entries are EXPANDED against
 * the filesystem (one `readdir` of the directory preceding the first `*`,
 * yielding the directories that exist and hold a manifest) rather than tested
 * against a candidate path. It answers "which directories does this pattern
 * name", not "does this pattern name this directory"; folding it in would mean
 * giving this pure function a filesystem.
 *
 * The supported syntax is the intersection of the two upstream dialects: `*`,
 * `?`, `**`, `[abc]`/`[!abc]` (dialect-gated), and literals. minimatch-only
 * extensions the pre-fold uv path inherited by accident — brace expansion,
 * extglobs, leading-`!` negation, leading-`#` comments — are NOT honored, and
 * uv's own `glob` crate does not honor them either (same pinned SHA), so
 * dropping them moves uv toward upstream rather than away from it.
 *
 * Matching is NON-BACKTRACKING (#2603): the pattern compiles to a list of
 * bounded steps and {@link matchesWorkspaceMemberSteps} decides it with one
 * memoized (step, position) table, O(steps x characters), no matter how many
 * `**`s the pattern carries. The anchored whole-path regex this replaced was
 * correct but explored 2^N splits of a non-matching path for N `**`
 * components — 124900 ms for `("**\/*" x12)/zzz` against a 40-component path,
 * on a call `detectPythonEnvironment` awaits with no timeout, i.e. a wedged
 * turn rather than a slow answer. The wall-clock half of that fix lives in
 * `tests/clients/workspace-glob-nonbacktracking-budget.test.ts`; the answers
 * are unchanged, pinned by the dialect table and the minimatch differential in
 * `tests/clients/path-utils.test.ts`.
 *
 * A pattern that cannot be compiled at all answers `false` for every path —
 * it declares no member and excludes nothing (#2591 review round 2, F2). The
 * only such patterns today carry an empty character-class range (`[z-a]`:
 * legal glob, illegal JS RegExp). Reachability note, recorded rather than
 * assumed away: no such pattern can reach here through a manifest right now,
 * because `parseTomlStringArray` (`clients/cargo-manifest.ts`) captures an
 * array body non-greedily up to the FIRST `]`, so any entry containing a `]`
 * loses its closing quote and is dropped before it becomes a pattern. That is
 * a property of the TOML reader, not of this matcher, and it is not this
 * function's to rely on — the character-class axis stays because upstream
 * cargo and uv both support classes, and the reader's gap may be closed later.
 */
export function matchesWorkspaceMemberPattern(
	pattern: string,
	relativePath: string,
	dialect: WorkspaceMemberGlobDialect,
	onCap?: () => void,
): boolean {
	const normalized = dialect.normalizePattern(pattern);
	if (
		dialect.globstar === "pattern-never-matches" &&
		normalized.includes("**")
	) {
		return false;
	}
	const steps = compileWorkspaceMemberPattern(normalized, dialect);
	return (
		steps !== undefined &&
		matchesWorkspaceMemberSteps(steps, relativePath, onCap)
	);
}

/**
 * Narrow no-break space, U+202F. macOS writes it before AM/PM in screenshot
 * file names; users type an ordinary space.
 */
const NARROW_NO_BREAK_SPACE = "\u202F";
/** Right single quotation mark, U+2019. macOS writes it; users type U+0027. */
const RIGHT_SINGLE_QUOTE = "\u2019";

/**
 * The unicode space class pi folds to U+0020, copied character-for-character
 * from `@earendil-works/pi-coding-agent/dist/utils/paths.js:6`
 * (`UNICODE_SPACES`, source `src/utils/paths.ts`). Widening or narrowing this
 * set makes pi-lens resolve a different file than pi does.
 */
const HOST_UNICODE_SPACES = /[\u00A0\u2000-\u200A\u202F\u205F\u3000]/g;

/**
 * Mirror pi's `normalizeWindowsShellPath`
 * (`@earendil-works/pi-coding-agent/dist/utils/paths.js:47-56`): convert Git
 * Bash, MSYS, Cygwin, and WSL drive paths to a form native Windows APIs
 * accept.
 */
function hostNormalizeWindowsShellPath(filePath: string): string {
	if (
		!filePath.startsWith("/") ||
		filePath.startsWith("//") ||
		filePath.includes("\\")
	) {
		return filePath;
	}
	const match = filePath.match(/^\/(?:mnt\/|cygdrive\/)?([a-z])(?:\/(.*))?$/i);
	if (!match) return filePath;
	const suffix = match[2]?.replaceAll("/", "\\");
	return `${match[1].toUpperCase()}:\\${suffix ?? ""}`;
}

interface HostNormalizeOptions {
	/** Fold the unicode space class to U+0020. */
	normalizeUnicodeSpaces?: boolean;
	/** Drop a single leading `@` (pi's file-mention prefix). */
	stripAtPrefix?: boolean;
}

/**
 * Mirror pi's `normalizePath`
 * (`@earendil-works/pi-coding-agent/dist/utils/paths.js:57-79`, source
 * `src/utils/paths.ts`), in pi's order, which is load-bearing: the unicode
 * fold runs BEFORE the `@` strip, and the tilde expansion before the
 * `file://` conversion.
 *
 * The `win32` step is gated on `process.platform`, exactly as pi gates it.
 * This is a deliberate exception to the usual probe-the-filesystem rule
 * (AGENTS.md shape 2): pi-lens runs in pi's own process, so mirroring the
 * host's own platform branch is what keeps the two resolvers in agreement.
 * Shape-based parsing here would DIVERGE from the host, not protect against
 * it.
 */
export function normalizeHostToolPath(
	input: string,
	options: HostNormalizeOptions = {},
): string {
	let normalized = input;
	if (options.normalizeUnicodeSpaces) {
		normalized = normalized.replace(HOST_UNICODE_SPACES, " ");
	}
	if (options.stripAtPrefix && normalized.startsWith("@")) {
		normalized = normalized.slice(1);
	}
	if (process.platform === "win32") {
		normalized = hostNormalizeWindowsShellPath(normalized);
	}
	// `homedir()` is resolved inside the branch, as pi does. This runs on every
	// tool_call and a `~` path is the rare case.
	if (normalized === "~") return os.homedir();
	if (
		normalized.startsWith("~/") ||
		(process.platform === "win32" && normalized.startsWith("~\\"))
	) {
		return path.join(os.homedir(), normalized.slice(2));
	}
	if (normalized.startsWith("file://")) {
		try {
			return fileURLToPath(normalized);
		} catch {
			// pi lets a malformed file: URL throw out of normalizePath, but pi-lens
			// is advisory instrumentation on the same event: a URL pi rejects must
			// degrade to "no path" here, never take down the tool_call handler.
			return normalized;
		}
	}
	return normalized;
}

/**
 * Mirror pi's `resolveToCwd`
 * (`@earendil-works/pi-coding-agent/dist/core/tools/path-utils.js:42-44`,
 * source `src/core/tools/path-utils.ts:~44-46`) \u2014 the BASE resolution every
 * read/edit/write path goes through before the variant ladder below ever
 * runs.
 *
 * Two details are pi's, not ours, and both matter:
 *   - the input is normalized with `normalizeUnicodeSpaces` + `stripAtPrefix`;
 *     the BASE DIR is normalized with neither (`resolvePath`,
 *     `dist/utils/paths.js:80-84`).
 *   - an already-absolute input is re-resolved on its own, ignoring the cwd.
 */
export function resolveHostToolPath(input: string, baseDir: string): string {
	const normalized = normalizeHostToolPath(input, {
		normalizeUnicodeSpaces: true,
		stripAtPrefix: true,
	});
	const normalizedBaseDir = normalizeHostToolPath(baseDir);
	return path.isAbsolute(normalized)
		? path.resolve(normalized)
		: path.resolve(normalizedBaseDir, normalized);
}

export interface HostPathVariantResolution {
	/** The path to use: the first variant that exists, else the naive resolve. */
	path: string;
	/** Set when a VARIANT matched — `path` differs from the naive resolve. */
	variant?: "narrow-nbsp" | "nfd" | "curly-quote" | "nfd-curly-quote";
	/**
	 * The naive resolve did not exist and no variant did either. Distinct from
	 * "the naive resolve existed": callers that expect the file to be there use
	 * this to record a `path-variant-unresolved` degradation instead of
	 * returning silently (defect shape 10 — an empty result must say WHY).
	 */
	unresolved: boolean;
	/**
	 * Variant labels actually probed. Empty when the base resolve existed — and
	 * ALSO empty when every candidate collapsed onto the base path (a plain
	 * ASCII name with no quote and no AM/PM). Callers must therefore gate a
	 * degradation on `unresolved`, never on this being non-empty: the
	 * all-candidates-identical miss is a real miss, and gating it away is how
	 * the base-normalization cases went silent (#1655 review F1).
	 */
	triedVariants: string[];
}

/**
 * Mirror pi's read-path fallback ladder (#1655 item 5).
 *
 * pi does NOT open `resolve(cwd, input.path)`. `resolveReadPath`
 * (`@earendil-works/pi-coding-agent/dist/core/tools/path-utils.js:45-70`,
 * source `src/core/tools/path-utils.ts:52-83`) resolves, and when that path
 * does not exist it silently retries four unicode/spacing variants in this
 * exact order:
 *
 *   1. narrow no-break space before `AM.`/`PM.` (`tryMacOSScreenshotPath`)
 *   2. NFD normalization (`tryNFDVariant`) — macOS stores names decomposed
 *   3. U+0027 → U+2019 (`tryCurlyQuoteVariant`)
 *   4. NFD + curly quote combined
 *
 * Each candidate is used only when it DIFFERS from the resolved path and the
 * file exists; otherwise pi falls back to the resolved path. So the file pi
 * actually read can differ from what a naive `path.resolve` produces, and
 * pi-lens keyed its read guard, LSP touch, and dispatch off the naive form —
 * silently doing nothing for exactly those files.
 *
 * Order matters: it is pi's, so pi-lens picks the same file pi did when more
 * than one variant happens to exist.
 *
 * @param resolvedPath an already-resolved absolute path (the naive form)
 * @param fileExists injectable existence probe; defaults to `existsSync`
 */
export function resolveHostPathVariants(
	resolvedPath: string,
	fileExists: (candidate: string) => boolean = existsSync,
): HostPathVariantResolution {
	if (fileExists(resolvedPath)) {
		return { path: resolvedPath, unresolved: false, triedVariants: [] };
	}

	const nfd = resolvedPath.normalize("NFD");
	const candidates: Array<{
		variant: NonNullable<HostPathVariantResolution["variant"]>;
		candidate: string;
	}> = [
		{
			variant: "narrow-nbsp",
			candidate: resolvedPath.replace(
				/ (AM|PM)\./gi,
				`${NARROW_NO_BREAK_SPACE}$1.`,
			),
		},
		{ variant: "nfd", candidate: nfd },
		{
			variant: "curly-quote",
			candidate: resolvedPath.replaceAll("'", RIGHT_SINGLE_QUOTE),
		},
		{
			variant: "nfd-curly-quote",
			candidate: nfd.replaceAll("'", RIGHT_SINGLE_QUOTE),
		},
	];

	const triedVariants: string[] = [];
	for (const { variant, candidate } of candidates) {
		// pi skips a candidate identical to the resolved path, so pi-lens does
		// too — otherwise a no-op "variant" would be reported as a match.
		if (candidate === resolvedPath) continue;
		triedVariants.push(variant);
		if (fileExists(candidate)) {
			return { path: candidate, variant, unresolved: false, triedVariants };
		}
	}

	return { path: resolvedPath, unresolved: true, triedVariants };
}

clients/python-environment.ts:
import { access, readFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import {
	extractTomlTableSection,
	hasTomlTable,
	parseTomlStringArray,
} from "./cargo-manifest.js";
import {
	isAtOrAboveHomeDir,
	matchesWorkspaceMemberPattern,
	toPosix,
	UV_WORKSPACE_EXCLUDE_DIALECT,
	UV_WORKSPACE_MEMBERS_DIALECT,
	walkUpDirs,
	type WorkspaceMemberGlobDialect,
} from "./path-utils.js";
import { recordDegradationOnce } from "./degradation-ledger.js";
import { logExtension } from "./extension-log.js";
import { normalizeSearchPath } from "./package-manager.js";
import { getProjectTrustState } from "./project-trust.js";

export type PythonEnvironmentSource =
	| "virtual-env"
	| "conda"
	| "project-dot-venv"
	| "project-venv"
	| "uv-project-environment"
	| "uv-workspace";

export interface PythonEnvironment {
	root: string;
	binDir: string;
	pythonPath: string;
	source: PythonEnvironmentSource;
}

interface UvWorkspace {
	/** The workspace root — the project itself unless an ancestor declares one. */
	root: string;
	/** True when {@link root} declares `[tool.uv.workspace]`. */
	explicit: boolean;
	/** The nearest ancestor (inclusive) holding a `pyproject.toml`. */
	projectRoot: string;
	/**
	 * True when {@link projectRoot} IS the directory the walk started from —
	 * i.e. the caller's root is itself a uv project, not merely a directory
	 * somewhere beneath one. This is the whole gate for "does this directory
	 * get uv's project settings": the walk answers "which project OWNS this
	 * directory", which is a different question and only decides membership
	 * (review round 3, S1).
	 */
	isStartDir: boolean;
	members: string[];
	exclude: string[];
}

const UV_WORKSPACE_TABLE = "tool\\.uv\\.workspace";

/**
 * Resolve the uv workspace root using the same discovery shape as uv:
 * start at the nearest pyproject, then continue upward for an explicit
 * `[tool.uv.workspace]` declaration. A nearest pyproject without that table
 * is an implicit single-project workspace.
 *
 * The walk stops AT `homeDir` (`isAtOrAboveHomeDir`, the shared ceiling
 * primitive from #625) so a `pyproject.toml` sitting in `/tmp`, `/home`, or
 * `$HOME` itself cannot supply the environment for every project beneath it.
 * `homeDir` is injected rather than read from `os.homedir()` inside the walk
 * for the same reason every sibling walker takes it (#2536, #2544 F2): the
 * ceiling is otherwise untestable.
 */
async function findUvWorkspace(
	startDir: string,
	homeDir: string,
): Promise<UvWorkspace | undefined> {
	const resolvedStart = path.resolve(startDir);
	let nearestProject: string | undefined;
	for (const dir of walkUpDirs(startDir)) {
		if (isAtOrAboveHomeDir(dir, homeDir)) break;

		let content: string;
		try {
			content = await readFile(path.join(dir, "pyproject.toml"), "utf8");
		} catch {
			continue;
		}

		if (!nearestProject) nearestProject = dir;
		if (hasTomlTable(content, UV_WORKSPACE_TABLE)) {
			const workspaceTable = extractTomlTableSection(
				content,
				UV_WORKSPACE_TABLE,
			);
			return {
				root: dir,
				explicit: true,
				projectRoot: nearestProject,
				isStartDir: nearestProject === resolvedStart,
				members: parseTomlStringArray(workspaceTable, "members"),
				exclude: parseTomlStringArray(workspaceTable, "exclude"),
			};
		}
	}

	return nearestProject
		? {
				root: nearestProject,
				explicit: false,
				projectRoot: nearestProject,
				isStartDir: nearestProject === resolvedStart,
				members: [],
				exclude: [],
			}
		: undefined;
}

/**
 * Apply uv's explicit-workspace membership rules before inheriting its root
 * environment. The workspace root is always a member; descendants must match
 * a declared member glob and must not match an exclusion glob.
 *
 * The glob dialects are pinned to uv 3c979abda4530fe9bf3d92e9bcf5c5575e3b3126,
 * `crates/uv-workspace/src/workspace.rs`, and live beside the ONE shared
 * workspace-member matcher (#2591) instead of as a minimatch options block
 * here: `UV_WORKSPACE_MEMBERS_DIALECT` for `members`
 * (`is_included_in_workspace` — `MatchOptions { require_literal_separator:
 * true, ..MatchOptions::new() }`) and `UV_WORKSPACE_EXCLUDE_DIALECT` for
 * `exclude` (`WorkspaceExclusions::matches` — `Pattern::matches_path`, i.e.
 * `MatchOptions::new()` defaults, where `require_literal_separator` is FALSE
 * and a `*` therefore crosses `/`). Both normalize the pattern first
 * (`normalize_path`, so a leading `./` is not part of the pattern) and are
 * case-SENSITIVE on every platform with no literal-leading-dot requirement.
 *
 * That `exclude` option set used to be a documented limitation rather than
 * behavior: minimatch cannot express a separator-crossing `*`, so
 * `exclude = ['packages/a*c']` did not exclude `packages/a/b/c`. A dialect
 * object can, so #2591 implements it — the one intentional answer change in
 * that fold.
 */
function isUvWorkspaceMember(
	workspace: UvWorkspace,
	projectRoot: string,
): boolean {
	// No `projectRoot === workspace.root` shortcut. uv treats the workspace
	// root as a member of its own workspace, but only in its capacity as a
	// PROJECT — and a project already gets uv's settings through `isStartDir`,
	// with its own `<root>/.venv` reached by the ordinary project candidate at
	// the very same path. Answering "member" on directory equality made every
	// non-project subdirectory of the workspace root inherit the workspace
	// `.venv`, `exclude` included, because equality was tested before the
	// walk result was consulted (review round 3, S2). The relative-path guard
	// below returns false for the root itself, which is the intended answer.
	const relative = toPosix(path.relative(workspace.root, projectRoot));
	if (
		relative.length === 0 ||
		relative === ".." ||
		relative.startsWith("../") ||
		path.isAbsolute(relative)
	) {
		return false;
	}

	const matches =
		(dialect: WorkspaceMemberGlobDialect) =>
		(pattern: string): boolean =>
			matchesWorkspaceMemberPattern(pattern, relative, dialect, () =>
				recordDegradationOnce({
					kind: "workspace-glob-cap",
					subject: String(pattern.length),
					reason: "workspace glob matcher exceeded its memo-table cell cap",
				}),
			);
	return (
		!workspace.exclude.some(matches(UV_WORKSPACE_EXCLUDE_DIALECT)) &&
		workspace.members.some(matches(UV_WORKSPACE_MEMBERS_DIALECT))
	);
}

/**
 * #3871: the process-wide channels a shell can point at any environment on the
 * machine. A linked-worktree run (`allowAmbient: false`) takes one only when
 * its root lies inside the requested project root.
 */
/** Project-config-sourced environments, refused unless the project is trusted. */
const PROJECT_SOURCED_PYTHON_SOURCES = new Set<PythonEnvironmentSource>([
	"project-dot-venv",
	"project-venv",
	"uv-workspace",
]);

const AMBIENT_ENVIRONMENT_VARIABLES = {
	"uv-project-environment": "UV_PROJECT_ENVIRONMENT",
	"virtual-env": "VIRTUAL_ENV",
	conda: "CONDA_PREFIX",
} as const;

/** True when any ambient Python environment channel is set in `env`. */
export function hasAmbientPythonEnvironment(
	env: NodeJS.ProcessEnv = process.env,
): boolean {
	return Object.values(AMBIENT_ENVIRONMENT_VARIABLES).some((name) =>
		Boolean(env[name]),
	);
}

/**
 * Resolve the interpreter and executable directory for the project's Python
 * environment without activating it or invoking a package manager.
 */
export async function detectPythonEnvironment(
	projectRoot: string,
	homeDir: string = os.homedir(),
	options: { allowAmbient?: boolean } = {},
): Promise<PythonEnvironment | undefined> {
	// `path.resolve` once at the seam entry so `isStartDir` below compares like
	// with like: `walkUpDirs` resolves its input, a caller's argument need not
	// be normalized.
	const root = path.resolve(projectRoot);
	const uvWorkspace = await findUvWorkspace(root, homeDir);
	// `UV_PROJECT_ENVIRONMENT` and the workspace `.venv` are uv PROJECT
	// settings. uv applies them to a directory only when that directory IS the
	// project — a `pyproject.toml` merely sitting somewhere ABOVE it makes it a
	// subdirectory of a project, not a project, and nothing below a project
	// root inherits from it (the F3 decision, applied consistently). Exporting
	// `UV_PROJECT_ENVIRONMENT` process-wide is uv's own documented CI/Docker
	// recipe, so a gate on "a pyproject exists at or above root" lets one
	// image-level variable capture every subdirectory on the box that happens
	// to sit under some Python project.
	const isProjectRoot = uvWorkspace?.isStartDir === true;
	// A declared, non-excluded member of an EXPLICIT workspace is itself a
	// project root, so this is a strict refinement of `isProjectRoot`: it adds
	// the workspace `.venv` candidate and re-anchors a relative
	// `UV_PROJECT_ENVIRONMENT` at the workspace root.
	const memberWorkspaceRoot =
		isProjectRoot &&
		uvWorkspace.explicit &&
		isUvWorkspaceMember(uvWorkspace, root)
			? uvWorkspace.root
			: undefined;
	const uvEnvironmentRoot = isProjectRoot
		? (memberWorkspaceRoot ?? uvWorkspace.projectRoot)
		: undefined;
	const uvProjectEnvironment = process.env.UV_PROJECT_ENVIRONMENT;
	// PEP 723 `uv run --script` environments are cache-keyed by script content;
	// without a stable project marker or explicit path, they remain undiscoverable.
	const allowAmbient = options.allowAmbient ?? true;
	const isWithinProjectRoot = (candidateRoot: string): boolean => {
		const relative = path.relative(root, path.resolve(candidateRoot));
		return (
			relative !== ".." &&
			!relative.startsWith(`..${path.sep}`) &&
			// #3871 V1: another Windows drive has no relative path, so
			// `path.relative` returns the absolute target: no `..`, not inside.
			!path.isAbsolute(relative)
		);
	};
	const candidates: Array<{
		root: string | undefined;
		source: PythonEnvironmentSource;
	}> = [
		...(uvEnvironmentRoot !== undefined && uvProjectEnvironment
			? [
					{
						// `path.resolve` leaves an absolute value untouched and
						// anchors a relative one at the project's workspace root.
						root: path.resolve(uvEnvironmentRoot, uvProjectEnvironment),
						source: "uv-project-environment" as const,
					},
				]
			: []),
		...(memberWorkspaceRoot !== undefined
			? [
					{
						root: path.join(memberWorkspaceRoot, ".venv"),
						source: "uv-workspace" as const,
					},
				]
			: []),
		{ root: process.env.VIRTUAL_ENV, source: "virtual-env" },
		{ root: process.env.CONDA_PREFIX, source: "conda" },
		{ root: path.join(root, ".venv"), source: "project-dot-venv" },
		{ root: path.join(root, "venv"), source: "project-venv" },
	];

	for (const candidate of candidates) {
		if (!candidate.root) continue;
		if (
			!allowAmbient &&
			candidate.source in AMBIENT_ENVIRONMENT_VARIABLES &&
			!isWithinProjectRoot(candidate.root)
		)
			continue;
		// A project-sourced interpreter (`.venv`, a uv workspace venv) is a
		// project-local executable and carries the same trust gate as every other
		// one (#4268 acceptance 1, MED-6): unknown/untrusted falls through to a
		// global interpreter, while an explicitly exported `VIRTUAL_ENV`,
		// `CONDA_PREFIX` or `UV_PROJECT_ENVIRONMENT` remains the user's own
		// choice. Explicit untrusted always refuses.
		if (
			PROJECT_SOURCED_PYTHON_SOURCES.has(candidate.source) &&
			getProjectTrustState() !== "trusted"
		) {
			if (
				recordDegradationOnce({
					kind: "trust-refusal",
					subject: `python-environment:${candidate.root}`,
					reason: `project Python environment refused: pi project trust is ${getProjectTrustState()}`,
				})
			) {
				logExtension({
					subsystem: "project-trust",
					level: "warn",
					message:
						"project Python environment refused: mark the project trusted in pi or upgrade pi",
					metadata: { source: candidate.source },
				});
			}
			continue;
		}
		const binDir = path.join(
			candidate.root,
			process.platform === "win32" ? "Scripts" : "bin",
		);
		const pythonPath = path.join(
			binDir,
			process.platform === "win32" ? "python.exe" : "python",
		);
		try {
			await access(pythonPath);
			return {
				root: candidate.root,
				binDir,
				pythonPath,
				source: candidate.source,
			};
		} catch {
			// The marker can outlive its environment. Continue to the next candidate.
		}
	}

	return undefined;
}

/** Preserve the existing interpreter-only API used by LSP initialization. */
export async function detectPythonVenv(
	projectRoot: string,
): Promise<string | undefined> {
	return (await detectPythonEnvironment(projectRoot))?.pythonPath;
}

/**
 * Build a child-only environment for Python tools. The host process remains
 * unchanged, so another project can resolve a different environment.
 */
export function augmentPythonEnvironment(
	baseEnvironment: NodeJS.ProcessEnv,
	environment: PythonEnvironment | undefined,
): NodeJS.ProcessEnv {
	if (!environment) return baseEnvironment;

	const inheritedPath =
		baseEnvironment.PATH ?? baseEnvironment.Path ?? baseEnvironment.path ?? "";
	const augmentedPath = normalizeSearchPath([
		environment.binDir,
		inheritedPath,
	]);
	const childEnvironment: NodeJS.ProcessEnv = {
		...baseEnvironment,
		PATH: augmentedPath,
		VIRTUAL_ENV: environment.root,
	};
	if (process.platform === "win32") childEnvironment.Path = augmentedPath;
	return childEnvironment;
}

/** Return explicit project-environment candidates before a bare PATH fallback. */
export function pythonEnvironmentToolCandidates(
	environment: PythonEnvironment | undefined,
	command: string,
): string[] {
	if (!environment) return [];
	if (process.platform !== "win32") {
		return [path.join(environment.binDir, command)];
	}
	return [
		path.join(environment.binDir, `${command}.exe`),
		path.join(environment.binDir, `${command}.cmd`),
		path.join(environment.binDir, command),
	];
}

clients/safe-spawn.ts:
/**
 * Safe cross-platform spawn utilities
 *
 * Provides both sync (deprecated) and async versions for gradual migration.
 *
 * Async version features:
 * - Non-blocking execution
 * - Proper process cleanup on timeout (no zombies)
 * - Batch execution with concurrency limits
 * - AbortSignal support for cancellation
 *
 * Migration guide:
 * - Change: safeSpawn(cmd, args, opts)
 * - To: await safeSpawnAsync(cmd, args, opts)
 */

import { AsyncLocalStorage } from "node:async_hooks";
import {
	type ChildProcess,
	type SpawnOptions,
	spawn,
	spawnSync,
} from "node:child_process";
import * as fs from "node:fs";
import * as path from "node:path";
import { BoundedFifoMap, BoundedSet } from "./bounded-cache.js";
import { logLatency } from "./latency-logger.js";
import {
	incrementDegradationCount,
	recordDegradation,
	recordDegradationOnce,
} from "./degradation-ledger.js";
import { logExtension } from "./extension-log.js";
import { isFullyQualifiedWin32 } from "./path-utils.js";
import { startSpawnUsageSampler } from "./resource-sampler.js";
import { DEFAULT_MAX_OUTPUT_BYTES } from "./spawn-output-cap.js";
import { compareOrdinal } from "./string-utils.js";

export interface SpawnResourceUsage {
	sampleCount: number;
	avgCpuPercent: number;
	peakCpuPercent: number;
	avgRssBytes: number;
	peakRssBytes: number;
}

export type SpawnFailureKind = "aborted" | "timeout" | "spawn" | "signal";

export type SpawnFailureType =
	| "tool-not-found"
	| "cwd-unresolvable"
	| "permission-denied"
	| "spawn-failed"
	| "trust-refused"
	| "timeout"
	| "killed";

/** Intent-level spawn failure. `cause` retains the original OS Error/errno. */
export class SpawnFailureError extends Error {
	readonly name = "SpawnFailureError";

	constructor(
		readonly kind: SpawnFailureType,
		message: string,
		readonly cause: Error,
	) {
		super(message, { cause });
	}
}

export function hasSpawnFailureKind(
	error: unknown,
	kind: SpawnFailureType,
): boolean {
	return (
		error instanceof Error &&
		"kind" in error &&
		(error as { kind?: unknown }).kind === kind
	);
}

/**
 * #2010: derive teardown evidence from observed timestamps.
 *
 * Pure by design so every branch is deterministically unit-testable,
 * including the natural-exit-at-budget-expiry race where the timeout
 * callback arms a kill against an already-dead child.
 *
 * - No recorded kill start (the guard saw the child already dying), no
 *   observed death at all, or death PREDATING the kill start: the child
 *   left on its own -> "exited", ms 0. Claiming a kill we cannot
 *   distinguish from a natural exit would be invented evidence.
 * - Death observed after the kill started: "escalate-kill" when the
 *   SIGKILL escalation fired, otherwise "killed-by-signal"; ms is the
 *   observed gap (floor 0 - clock jitter must never produce a negative).
 */
export function resolveTeardownOutcome(input: {
	killStartedAtMs?: number;
	deathObservedAtMs?: number;
	escalated: boolean;
}):
	| {
			ms: number;
			outcome: "exited" | "killed-by-signal" | "escalate-kill";
	  }
	| undefined {
	// Another path (abort / output-limit) owns this death: emitting teardown
	// evidence here would describe a kill this timeout didn't perform.
	if (
		input.killStartedAtMs === undefined ||
		input.deathObservedAtMs === undefined
	) {
		return undefined;
	}
	// True natural-exit race: the child beat the budget-expired kill by a
	// hair - death observed before (or exactly at) the kill start.
	if (input.deathObservedAtMs <= input.killStartedAtMs) {
		return { ms: 0, outcome: "exited" };
	}
	return {
		ms: Math.max(0, input.deathObservedAtMs - input.killStartedAtMs),
		outcome: input.escalated ? "escalate-kill" : "killed-by-signal",
	};
}

export interface SpawnResult {
	stdout: string;
	stderr: string;
	status: number | null;
	/**
	 * The signal that killed the child, when one did (#1816). Before this the
	 * signal name lived only inside `error.message`, so no caller could name it
	 * and every ledger reason rendered a SIGKILLed tool indistinguishably from
	 * a clean exit. Absent for a normally-exited process.
	 */
	signal?: NodeJS.Signals;
	error?: Error;
	/** Typed spawn-boundary failure; nonzero tool exits do not populate it. */
	spawnFailure?: SpawnFailureError;
	/** Structured failure reason; nonzero exit statuses are not spawn failures. */
	failure?: SpawnFailureKind;
	/**
	 * #2010: how the process tree died after the spawn's OWN timeout budget
	 * expired - present on that path only. `ms` is wall-clock from budget
	 * expiry to observed tree death, measured separately from the budget so
	 * a slow teardown is visible rather than folded into "how long the tool
	 * ran". `outcome`: the child beat the signal ("exited"), the first
	 * signal ended it ("killed-by-signal"), or the SIGKILL escalation fired
	 * ("escalate-kill"). Platform note: on Windows taskkill /F is always
	 * forceful and arms no escalation timer, so "escalate-kill" is
	 * POSIX-only; forced Windows kills report "killed-by-signal" despite no
	 * signal being delivered - the name describes the semantic tier
	 * (first-tier vs escalated force), not the OS mechanism.
	 */
	timeoutTeardown?: {
		ms: number;
		outcome: "exited" | "killed-by-signal" | "escalate-kill";
	};
	/** True when stdout or stderr was capped before process completion. */
	outputTruncated?: boolean;
	/** True when the output cap started terminating the child. */
	killedForOutputCap?: boolean;
	/**
	 * #3375 round 2 (H3384-1): every signal available for this spawn's teardown
	 * was refused by the OS, so the child may STILL BE RUNNING. Present only on
	 * that path — absent means teardown was never attempted or it succeeded, so
	 * a 4.2.1 result parses unchanged. `killedForOutputCap` keeps its meaning
	 * (we STARTED terminating the child); this field says the attempt failed.
	 */
	killFailed?: boolean;
	/** True when the optional streaming matcher saw a matching chunk. */
	streamingMatch?: boolean;
	/** Peak/average CPU%+RSS sampled across this spawn's lifetime (#620).
	 *  `undefined` when no sample ever landed (process exited faster than the
	 *  first poll tick, or sampling failed for the whole invocation) — never
	 *  read that as "zero resource usage". */
	resourceUsage?: SpawnResourceUsage;
}

function toError(error: unknown): Error {
	return error instanceof Error ? error : new Error(String(error));
}

function errorCode(error: Error): string | undefined {
	return (error as NodeJS.ErrnoException).code;
}

async function cwdIsUnresolvable(cwd: string | undefined): Promise<boolean> {
	if (cwd === undefined) return false;
	try {
		return !(await fs.promises.stat(cwd)).isDirectory();
	} catch {
		return true;
	}
}

function cwdIsUnresolvableSync(cwd: string | undefined): boolean {
	if (cwd === undefined) return false;
	try {
		return !fs.statSync(cwd).isDirectory();
	} catch {
		return true;
	}
}

/**
 * Best-effort presence probe used ONLY to disambiguate ENOENT when the cwd is
 * ALSO unresolvable (#1340 review): a genuinely missing tool must classify as
 * tool-not-found even under a broken cwd, or auto-install can never repair it.
 * Absolute commands are probed directly (with PATHEXT variants on Windows);
 * bare names scan PATH. A relative-with-separator command under a broken cwd
 * is genuinely ambiguous -- we err toward cwd-unresolvable there, because
 * repairing the cwd is actionable while a reinstall loop (#1199) is not.
 */
function commandProbablyPresent(command: string): boolean | "ambiguous" {
	const exts =
		process.platform === "win32"
			? [
					"",
					...(process.env.PATHEXT ?? ".COM;.EXE;.BAT;.CMD")
						.split(";")
						.filter(Boolean),
				]
			: [""];
	const existsWithExt = (base: string): boolean => {
		for (const ext of exts) {
			try {
				if (fs.existsSync(base + ext)) return true;
			} catch {
				// unreadable candidate -- keep probing
			}
		}
		return false;
	};
	if (path.isAbsolute(command)) return existsWithExt(command);
	if (command.includes("/") || command.includes("\\")) return "ambiguous";
	for (const dir of (process.env.PATH ?? "").split(path.delimiter)) {
		if (dir && existsWithExt(path.join(dir, command))) return true;
	}
	return false;
}

/**
 * Shared errno->bucket mapping. `cwdUnresolvable` is the only async-vs-sync
 * difference between the two public classifiers, so it arrives as a resolved
 * flag and everything else lives once (Sonar duplication finding, #1340).
 */
function classifyWithCwdFlag(
	cause: Error,
	options: { command: string; cwd?: string },
	cwdUnresolvable: boolean,
): SpawnFailureError {
	const code = errorCode(cause);
	let failure: SpawnFailureError;
	if (
		code === "ENOENT" &&
		cwdUnresolvable &&
		commandProbablyPresent(options.command) !== false
	) {
		failure = new SpawnFailureError(
			"cwd-unresolvable",
			`Cannot spawn ${options.command}: working directory is unresolvable (${options.cwd})`,
			cause,
		);
	} else if (code === "ENOENT") {
		failure = new SpawnFailureError(
			"tool-not-found",
			`Cannot spawn ${options.command}: tool not found (${cause.message})`,
			cause,
		);
	} else if (code === "EACCES" || code === "EPERM") {
		failure = new SpawnFailureError(
			"permission-denied",
			`Cannot spawn ${options.command}: permission denied`,
			cause,
		);
	} else {
		failure = new SpawnFailureError(
			"spawn-failed",
			`Cannot spawn ${options.command}: ${cause.message}`,
			cause,
		);
	}
	recordSpawnClassification(failure, options);
	return failure;
}

const loggedSpawnClassifications = new Set<string>();
const SPAWN_CLASSIFICATION_LOG_CAP = 200;

function recordSpawnClassification(
	failure: SpawnFailureError,
	options: { command: string; cwd?: string },
): void {
	const pair = `${failure.kind}\0${options.command}`;
	if (!loggedSpawnClassifications.has(pair)) {
		if (loggedSpawnClassifications.size >= SPAWN_CLASSIFICATION_LOG_CAP) {
			loggedSpawnClassifications.clear();
		}
		loggedSpawnClassifications.add(pair);
		logExtension({
			subsystem: "safe-spawn",
			level: "debug",
			message: "spawn failure classified",
			metadata: {
				kind: failure.kind,
				command: options.command,
				cwd: options.cwd,
			},
		});
	}
	if (failure.kind !== "tool-not-found") {
		recordDegradation({
			kind: "spawn-failure",
			subject: options.command,
			reason: `${failure.kind}${options.cwd ? ` in ${options.cwd}` : ""}`,
		});
	}
}

/** Classify a raw Node spawn error without discarding its errno-bearing Error. */
export async function classifySpawnFailure(
	error: unknown,
	options: { command: string; cwd?: string },
): Promise<SpawnFailureError> {
	const cause = toError(error);
	const needsCwdProbe = errorCode(cause) === "ENOENT";
	const cwdUnresolvable =
		needsCwdProbe && (await cwdIsUnresolvable(options.cwd));
	return classifyWithCwdFlag(cause, options, cwdUnresolvable);
}

function classifySpawnFailureSync(
	error: unknown,
	options: { command: string; cwd?: string },
): SpawnFailureError {
	const cause = toError(error);
	const needsCwdProbe = errorCode(cause) === "ENOENT";
	const cwdUnresolvable = needsCwdProbe && cwdIsUnresolvableSync(options.cwd);
	return classifyWithCwdFlag(cause, options, cwdUnresolvable);
}

export interface SafeSpawnOptions {
	timeout?: number;
	/** Absolute wall-clock deadline. The earlier of this and `timeout` wins. */
	deadlineAt?: number;
	cwd?: string;
	env?: NodeJS.ProcessEnv;
	/**
	 * Drop every inherited `npm_config_*` variable (case-insensitive) from the
	 * child environment AFTER the ambient merge (#4268). An `env` override
	 * alone cannot remove a variable, because {@link getSpawnEnvironment}
	 * merges `process.env` underneath it; this flag is the deletion the
	 * override cannot express. Used by the cache-only package-runner seam so a
	 * project's `.npmrc` and the shell's npm config never reach `npx`/`bunx`.
	 * Never mutates `process.env`.
	 */
	stripNpmConfig?: boolean;
	signal?: AbortSignal;
	/**
	 * Opt out of the ambient turn abort signal (which is otherwise the default).
	 * Set this for long, side-effecting operations like tool installs that should
	 * run to completion even if the agent turn is interrupted — matching the old
	 * uncancellable sync `safeSpawn` they replaced (so a half-finished
	 * `gem install` / `go install` can't be left behind by an Esc). An explicit
	 * `signal` still takes precedence over both.
	 */
	ignoreAmbientSignal?: boolean;
	/**
	 * Label recorded on the resource-usage latency.log phase entry (#620) —
	 * typically the runner/tool id (e.g. "jscpd", "knip"). Defaults to the
	 * bare command name when omitted. Purely cosmetic (log correlation); never
	 * affects spawn behavior.
	 */
	resourceLabel?: string;
	/**
	 * Maximum bytes retained across stdout and stderr for this child.
	 * Omitted, zero, negative or non-finite falls back to
	 * `DEFAULT_MAX_OUTPUT_BYTES` (#3375) — there is deliberately no way to opt
	 * out of a cap, because an absent cap is what crashed the host.
	 */
	maxOutputBytes?: number;
	/** Match output chunks before output-cap truncation can discard them. */
	matchWhileStreaming?: RegExp;
	/** Optional stdin payload. Supplying it always writes and closes stdin. */
	input?: string;
	/**
	 * Couple a long-lived, side-effecting child to this Node process. Registered
	 * children are synchronously tree-killed during process exit/signals.
	 * Windows Job Objects would make this kernel-enforced, but require a native
	 * dependency; keep this dependency-free fallback until that follow-up.
	 */
	lifetimeCoupled?: boolean;
}

interface LifetimeCleanupState {
	pids: Set<number>;
	installed: boolean;
}

// Vitest reloads modules inside a reused worker. Keep this registry on the
// process so those module instances share one signal/exit listener set.
const lifetimeStateKey = Symbol.for("pi-lens.safe-spawn.lifetime-state");
const processWithLifetimeState = process as typeof process & {
	[lifetimeStateKey]?: LifetimeCleanupState;
};
const lifetimeState =
	processWithLifetimeState[lifetimeStateKey] ??
	(processWithLifetimeState[lifetimeStateKey] = {
		pids: new Set<number>(),
		installed: false,
	});

/**
 * THE ownership predicate for every kill-by-raw-pid in this repo (#2042).
 *
 * A pid is signalable only when it is a LIVE DIRECT CHILD of this process.
 * `tests/clients/lsp/launch.test.ts` mocked `node:child_process` with a fake
 * child carrying the literal pid `2468`; `safeSpawnAsync` registered it in
 * `lifetimeState.pids`, the fake never emitted `close` so nothing removed it,
 * and at fork teardown `installLifetimeCleanup()` fired
 * `process.kill(-2468, "SIGKILL")`. On ~10 % of GitHub runners pid 2468 was
 * one of the job's own long-lived processes — that is the whole of #2042:
 * exit 137, no failing assertion, no kernel record, five weeks of "infra
 * kill" reruns. A `pid <= 0` guard would not have stopped it; 2468 is a
 * perfectly plausible pid. The defect is OWNERSHIP, not sign.
 *
 * Three guards fold into this one (net-count rule): `lsp/client.ts`'s
 * `pid <= 0`, `lsp/launch.ts`'s `handle.pid <= 0` plus its already-exited
 * recycled-pid check, and `killTree`'s `child.pid > 0` below. It closes
 * fabricated, stale and recycled pids together.
 *
 * NOT folded: `instance-reaper.ts#killPidTree`. Its pids come from OTHER
 * pi-lens instances' registries and from an OS scan of managed binaries with
 * confirmed-dead parents — deliberately NOT our children. Its `!isFinite ||
 * pid <= 0` guard is well-formedness on a different axis, and applying this
 * predicate there would turn the orphan reaper into a no-op.
 *
 * Platform behaviour, stated rather than implied:
 *  - Linux (the authoritative lane, and the one that lost five weeks):
 *    `/proc/<pid>/status` is the kernel's own answer. Missing entry = the pid
 *    does not exist, so there is nothing of ours to kill; `PPid` other than
 *    ours = someone else's process, which is recorded and never signalled.
 *  - Windows and macOS have no `/proc` (and neither does a Linux host with
 *    `/proc` unmounted — probed once, not assumed from `process.platform`),
 *    so ownership is unverifiable from a raw pid and the predicate keeps
 *    today's best-effort behaviour. The `handle` arm applies THERE and only
 *    there: it is the only ownership evidence Windows has, and it is what
 *    `killWindowsTree` already used. It must not gate the POSIX group kill,
 *    which legitimately runs after its leader has died (#3091 F1).
 */
/**
 * Whether `/proc/<pid>/status` can actually be read here, probed ONCE against
 * this process's own entry (#3091 F4). `process.platform === "linux"` is not
 * the same question: a container or a hardened host can run Linux with no
 * `/proc` mounted, and there the per-pid read fails exactly the way a dead pid
 * does. Without this probe that silently refused every registration, so
 * `lifetimeState.pids` stayed empty and the host-exit tree kill stopped working
 * with no record anywhere.
 */
const PROC_PPID_READABLE = ((): boolean => {
	if (process.platform !== "linux") return false;
	try {
		return /^PPid:\s*\d+$/m.test(fs.readFileSync("/proc/self/status", "utf8"));
	} catch {
		return false;
	}
})();

/**
 * Pids this process has PROVEN, from the kernel, to be its own live children.
 * FIFO-bounded (`BoundedFifoMap`, not a wholesale clear): a process that spawns
 * more than the cap drops its OLDEST verdicts, where a wholesale clear would
 * drop the one it is about to need.
 */
export const VERIFIED_OWN_PID_CAP = 512;
const verifiedOwnPids = new BoundedFifoMap<number, true>(VERIFIED_OWN_PID_CAP);

/**
 * Pids whose OWNERSHIP IS HELD for the lifetime of a long-lived resource —
 * today, the LSP children `clients/lsp/launch.ts` spawns with `nodeSpawn`
 * (#3091 F1-r2b).
 *
 * These deliberately do NOT live in `verifiedOwnPids`. Age is the wrong
 * retirement axis for a resource-scoped verdict: an LSP leader is verified once
 * at spawn and then sits untouched for the whole session, so in a FIFO that
 * every `safeSpawnAsync` writes to it is the OLDEST entry and therefore the
 * FIRST evicted — measured, 520 later verdicts were enough — and its group kill
 * at host exit is refused precisely because the server was long-lived enough to
 * matter. Retirement here is by RESOURCE STATE instead: `releaseOwnChildPid`
 * when the shutdown ladder is done with the pid, plus the confirmed-dead sweep
 * below for the paths that never reach a ladder (a server that crashes, or a
 * host killed mid-session).
 *
 * The bound that remains, stated rather than implied: at most
 * `HELD_OWN_PID_SWEEP_AT` entries — the confirmed-dead sweep below runs before
 * every insert, and `BoundedSet`'s own FIFO overflow is the last resort for the
 * case where every held group really is still alive. A crash-looping server cannot grow it without bound
 * because each sweep drops every pid whose process GROUP no longer exists,
 * which is exactly the condition under which the entry can never be needed
 * again.
 */
const HELD_OWN_PID_SWEEP_AT = 256;
const heldOwnPids = new BoundedSet<number>(HELD_OWN_PID_SWEEP_AT);

/** A process group that no longer exists can never need another signal. */
function groupIsGone(pid: number): boolean {
	try {
		process.kill(-pid, 0);
		return false;
	} catch (error) {
		return errorCode(error as Error) === "ESRCH";
	}
}

function sweepHeldOwnPids(): void {
	if (heldOwnPids.size < HELD_OWN_PID_SWEEP_AT) return;
	// Deleting the current entry mid-iteration is well-defined for a Set, so
	// no snapshot copy is needed.
	for (const pid of heldOwnPids) {
		if (groupIsGone(pid)) heldOwnPids.delete(pid);
	}
	// No hand-rolled "drop the oldest" block (#2442 / #3091 round 4): the
	// last-resort eviction, for the case where every held group is still alive
	// at the ceiling, is `BoundedSet.add`'s own FIFO overflow; the caller
	// records it (#3096).
}

/**
 * Verify a pid at ADMISSION and hold the verdict for the resource's lifetime.
 *
 * This is AGENTS.md shape 50's own rule, which #3091 round 1 broke at the site
 * it was fixing: `isOwnLiveChild`'s three call sites were the `safeSpawnAsync`
 * registration, the Windows tree kill, and the SHUTDOWN group kill — so for an
 * LSP child, spawned with `nodeSpawn`, the first offer of verification was also
 * the last, and on the `processExiting` path the leader could already be dead
 * by then (`/proc` gone, nothing on record, signal refused, grandchildren
 * orphaned).
 */
export function holdOwnChildPid(
	pid: number | undefined,
	site: string,
): boolean {
	const owned = isOwnLiveChild(pid, site);
	if (!owned || !PROC_PPID_READABLE || typeof pid !== "number") return owned;
	// Exactly one home: the verification above filed the verdict in the
	// age-bounded FIFO, and leaving a copy there would make BOTH the held set
	// and its release mutation-inert — the FIFO copy would answer for them.
	verifiedOwnPids.delete(pid);
	sweepHeldOwnPids();
	const evicted = heldOwnPids.add(pid);
	if (evicted.length > 0) {
		incrementDegradationCount({
			kind: "held-own-pid-evicted",
			subject: site,
			reason: `held-pid set full of live groups at ${HELD_OWN_PID_SWEEP_AT}; dropped oldest pid ${evicted.join(",")}, a group kill after its leader dies is refused`,
			metadata: { evicted: evicted.length },
		});
	}
	return true;
}

/**
 * Retire a held pid once nothing will signal it again — the end of the
 * shutdown ladder. Idempotent.
 */
export function releaseOwnChildPid(pid: number | undefined): void {
	if (typeof pid === "number") heldOwnPids.delete(pid);
}

/** Once per session: a Linux host whose `/proc` cannot answer the question. */
function recordProcUnavailable(site: string): void {
	if (process.platform !== "linux") return;
	recordDegradationOnce({
		kind: "kill-ownership-unverifiable",
		subject: site,
		reason:
			"/proc/self/status is unreadable on this Linux host; kill-by-pid ownership falls back to best-effort",
	});
}

export function isOwnLiveChild(
	pid: number | undefined,
	site: string,
	handle?: { exitCode?: number | null; signalCode?: NodeJS.Signals | null },
): boolean {
	if (typeof pid !== "number" || !Number.isInteger(pid) || pid <= 0)
		return false;
	if (!PROC_PPID_READABLE) {
		// No `/proc` to consult. A handle that has already reported exit is then
		// the ONLY ownership evidence available, and it is exactly what
		// `killWindowsTree` used before this predicate existed: a dead pid may
		// have been recycled, and `taskkill /F /T` on a recycled pid destroys an
		// unrelated tree. It overrides the memo below deliberately.
		if (handle && (handle.exitCode != null || handle.signalCode != null))
			return false;
		recordProcUnavailable(site);
		return true;
	}
	let status: string;
	try {
		status = fs.readFileSync(`/proc/${pid}/status`, "utf8");
	} catch {
		// The pid does not exist. Not a degradation — a child that exited before
		// the teardown signal is the ordinary case — but not automatically a
		// refusal either: a POSIX process GROUP outlives its leader, and #2026's
		// whole point is that the escalation must still reach a SIGTERM-hardy
		// grandchild after the direct child has died. Ownership verified while
		// the leader was alive is what answers that; a pid this process never
		// owned is still refused.
		return heldOwnPids.has(pid) || verifiedOwnPids.has(pid);
	}
	const parent = /^PPid:\s*(\d+)$/m.exec(status);
	if (!parent) return true;
	if (Number(parent[1]) === process.pid) {
		// Memoized only on a KERNEL-verified verdict, and only here: a pid we
		// never proved was ours can never enter the memo, and a pid that is
		// alive under a different parent is refused above regardless of what the
		// memo holds — so a recycled pid cannot be signalled on the strength of
		// its previous owner.
		//
		// Never for a pid already HELD, though: the shutdown ladder verifies a
		// still-live leader on its way to the group signal, and filing that
		// verdict in the FIFO too would put a held pid back in both stores —
		// which outlives `releaseOwnChildPid` (the FIFO copy would keep
		// answering for a pid this process has explicitly stopped claiming) and
		// makes the held store's own tests unable to fail.
		if (!heldOwnPids.has(pid)) verifiedOwnPids.set(pid, true);
		return true;
	}
	// Alive AND someone else's: the dangerous case, and the only one worth a
	// record. Subject is the SITE (a fixed, tiny set), never the pid, so the
	// ledger stays bounded however often it fires.
	incrementDegradationCount({
		kind: "kill-foreign-pid-refused",
		subject: site,
		reason: `pid ${pid} has parent ${parent[1]}, not this process — signal refused`,
	});
	return false;
}

/**
 * Kill one registered pid's tree at host exit. Deliberately NOT re-checked
 * against `isOwnLiveChild` here: `lifetimeState.pids` has exactly one writer
 * (the registration below), that writer is now gated, and a second gate on
 * the same feeder would make BOTH mutation-inert — remove either one and the
 * other still blocks the kill, so neither would have a test that reds. The
 * gate lives where the pid enters, which is also where ownership is a fact
 * rather than a stale reading (#2042).
 */
function killPidTreeSync(pid: number): void {
	if (process.platform === "win32") {
		try {
			const taskkill = `${process.env.SystemRoot ?? "C:\\Windows"}\\System32\\taskkill.exe`;
			spawnSync(taskkill, ["/F", "/T", "/PID", String(pid)], {
				shell: false,
				windowsHide: true,
				stdio: "ignore",
			});
		} catch {
			// Runs from process `exit`/signal handlers — a SYNCHRONOUS spawn throw
			// (Windows `spawn UNKNOWN`/EINVAL, the pidusage bug class, #533) would
			// become an uncaughtException during shutdown. Best-effort tree-kill:
			// swallow it, mirroring the already-guarded POSIX branch below.
		}
		return;
	}
	try {
		// #2026: negative pid = whole process group (POSIX children spawn
		// detached), reaching grandchildren too. Any failure (ESRCH = already
		// gone, EPERM = raced) falls through to the direct-child attempt.
		try {
			process.kill(-pid, "SIGKILL");
		} catch {
			process.kill(pid, "SIGKILL");
		}
	} catch {
		// Child already exited.
	}
}

function installLifetimeCleanup(): void {
	if (lifetimeState.installed) return;
	lifetimeState.installed = true;
	process.once("exit", () => {
		for (const pid of lifetimeState.pids) killPidTreeSync(pid);
	});
	for (const signal of ["SIGINT", "SIGTERM", "SIGHUP"] as NodeJS.Signals[]) {
		process.once(signal, () => {
			for (const pid of lifetimeState.pids) killPidTreeSync(pid);
			if (process.platform === "win32" && signal === "SIGHUP") {
				// Windows emits SIGHUP when its console closes, but libuv cannot
				// self-send it (process.kill(..., "SIGHUP") throws ENOSYS). The
				// child cleanup above remains the required shutdown action; record
				// the intentional decline synchronously and let the host exit cleanly.
				recordDegradationOnce({
					kind: "safe-spawn-signal-reraise-unsupported",
					subject: `${process.platform}:${signal}`,
					reason: `${process.platform} ${signal}: self signal re-raise is unsupported by the Windows libuv signal capability`,
					metadata: {
						platform: process.platform,
						signal,
						reason: "unsupported",
					},
				});
				return;
			}
			try {
				process.kill(process.pid, signal);
			} catch (error) {
				// #3383: this runs inside a `process.once(signal)` handler, so a
				// throw here is an uncaughtException DURING SHUTDOWN, not a
				// rejection anyone can see. The one failure measured in the field
				// (Windows SIGHUP ENOSYS) is declined in advance just above; this
				// covers every other platform/signal/errno pair the OS can refuse —
				// same ledger kind, `reason: "refused"` instead of "unsupported",
				// because a reader of either row wants the same fact: the host
				// exited without the signal's default disposition. The child
				// cleanup above has already run either way.
				recordDegradationOnce({
					kind: "safe-spawn-signal-reraise-unsupported",
					subject: `${process.platform}:${signal}`,
					reason: `${process.platform} ${signal}: self signal re-raise was refused (${
						(error as { code?: string }).code ?? (error as Error).message
					})`,
					metadata: {
						platform: process.platform,
						signal,
						reason: "refused",
						code: (error as { code?: string }).code ?? null,
					},
				});
			}
		});
	}
}

// ============================================================================
// AMBIENT TURN ABORT SIGNAL
// ============================================================================

/**
 * The current turn's abort signal, published by the lifecycle handlers from
 * pi's `ctx.signal`. Threading the signal explicitly through every
 * dispatch → runner → spawn call site would be invasive, so instead
 * `safeSpawnAsync` defaults to this ambient signal when a call doesn't pass its
 * own. The effect: pressing Esc mid-turn aborts in-flight linter / formatter /
 * type-checker child processes (process-tree kill on Windows) instead of letting
 * them run to their timeout.
 *
 * Each spawn captures the signal at call time (attaching its own abort listener),
 * so clearing this after a handler returns only affects *future* spawns — work
 * already in flight keeps the signal it started with.
 */
let ambientAbortSignal: AbortSignal | undefined;

/** Publish (or clear, with `undefined`) the current turn's abort signal. */
export function setAmbientAbortSignal(signal: AbortSignal | undefined): void {
	ambientAbortSignal = signal;
}

/**
 * The current turn's abort signal, for in-process awaits that aren't child
 * spawns (e.g. an LSP JSON-RPC write that can backpressure on a wedged server).
 * Child spawns read the ambient signal internally; this getter lets the
 * interactive pipeline honor Escape on non-spawn LSP calls too.
 */
export function getAmbientAbortSignal(): AbortSignal | undefined {
	return ambientAbortSignal;
}

// ============================================================================
// INTERNAL HELPERS
// ============================================================================

/**
 * Escape a single argument for the Windows command interpreter.
 * The result is embedded in the `/c` command string below, so metacharacters
 * must remain inside a quoted argument rather than becoming command syntax.
 */
function cmdEscapeArg(arg: string): string {
	if (!/[\s"&|<>^()]/.test(arg)) return arg;
	return `"${arg.replace(/"/g, '""')}"`;
}

/**
 * Build the cmd.exe command string used for Windows wrapper spawning.
 *
 * The COMMAND must be escaped the same way as the args — escaping only the args
 * (the bug behind #214) means a tool whose resolved path contains a space (e.g.
 * `C:\Program Files\Go\bin\go.exe`) makes cmd.exe parse `C:\Program` as the
 * command and fail with "'C:\Program' is not recognized". `cmdEscapeArg` is a
 * no-op for space-free commands, so this is safe for the npm/.pi-lens tool paths
 * that already worked. The `chcp 65001` prefix forces the UTF-8 code page (so
 * tool output isn't mangled by the system code page) and, as a side benefit,
 * keeps the (possibly quoted) command off the front of the line, avoiding
 * cmd.exe's `/s` outer-quote-stripping quirk. #2023: chcp is invoked via its
 * absolute `%SystemRoot%\System32\chcp.com` path and chained with `&`, not
 * `&&` — a child environment whose PATH cannot resolve System32 used to fail
 * the bare `chcp` lookup, and `&&` then short-circuited EVERY .cmd/.bat spawn
 * into exit 1 with empty output. With the pin plus `&`, even a chcp failure
 * can never suppress the real command.
 */
export function buildWindowsShellCommand(
	command: string,
	args: string[],
): string {
	const chcp = `${process.env.SystemRoot ?? "C:\\Windows"}\\System32\\chcp.com`;
	return `${chcp} 65001 >nul 2>&1 & ${[command, ...args].map(cmdEscapeArg).join(" ")}`;
}

// ============================================================================
// WINDOWS COMMAND RESOLUTION (#817)
//
// CodeQL flagged clients/safe-spawn.ts:192 (js/command-line-injection #17/#19,
// js/shell-command-injection-from-environment #18): the old code always routed
// EVERY Windows spawn through `cmd.exe /d /s /c <hand-built string>`, string-
// concatenating caller-tainted `command`/`args` into a shell command line.
// `%` cannot be escaped on a /c line (it expands even inside double quotes)
// and cmd's quote-state toggling can defeat `""` doubling — the escaping was
// unsound, not just a CodeQL false positive.
//
// The fix resolves `command` ourselves (a `where`-equivalent PATH + PATHEXT
// walk) and only falls back to the cmd.exe wrapper for `.cmd`/`.bat` shims,
// which cannot run without it. `.exe`/`.com` — the overwhelming majority of
// spawns (sg, biome, ruff, git, node, where.exe...) — spawn directly with
// `shell: false` and a real args array: no command line is ever built, so
// there is nothing for cmd.exe to reinterpret.
// ============================================================================

export interface ResolvedWindowsCommand {
	/** Absolute path to the resolved executable. */
	resolvedPath: string;
	/** Lowercased extension including the leading dot, e.g. ".exe", ".cmd". */
	ext: string;
}

/**
 * The extensions this resolver treats as executable suffixes on their own,
 * independent of PATHEXT: `.exe`/`.com` and `.cmd`/`.bat`. An explicit suffix
 * outside this set is not treated as a "known executable extension" unless
 * the caller's own PATHEXT says so (#1201).
 *
 * This is a RESOLUTION set, not a dispatch whitelist — do not read it as "the
 * only extensions this module can spawn". Dispatch in
 * `safeSpawnAsync`/`safeSpawn` below routes `.cmd`/`.bat` through the cmd.exe
 * wrapper and EVERYTHING ELSE to direct spawn, so a resolved path with any
 * other suffix (reachable only when the caller's own PATHEXT lists it) is
 * direct-spawned. That is deliberate and not a widening: CreateProcess does no
 * ShellExecute file-association lookup, the default Windows PATHEXT already
 * contains `.VBS`/`.JS`/`.WSF`/`.MSC`, and the set here is strictly narrower
 * than the pre-#1201 behavior. Only the doc claim was ever wrong.
 */
const WINDOWS_DIRECT_RESOLVABLE_EXTS = new Set([
	".exe",
	".com",
	".cmd",
	".bat",
]);

/**
 * Merge a parent and child environment using Windows' case-insensitive variable
 * names. Node's JavaScript environment object can contain both `PATH` and
 * `Path`, even though Windows treats them as one variable. Removing an older
 * spelling before each assignment gives explicit child overrides precedence
 * over every ambient spelling and ensures the environment passed to spawn has
 * one unambiguous value.
 */
export function mergeWindowsEnvironment(
	base: NodeJS.ProcessEnv,
	overrides?: NodeJS.ProcessEnv,
): NodeJS.ProcessEnv {
	const entries = new Map<string, { key: string; value: string }>();
	const assign = (source: NodeJS.ProcessEnv | undefined): void => {
		if (!source) return;
		for (const [key, value] of Object.entries(source)) {
			const folded = key.toLowerCase();
			// Delete before setting so the last explicit spelling wins while the
			// folded map remains O(n) instead of scanning the merged object for
			// every environment entry.
			entries.delete(folded);
			if (value !== undefined) entries.set(folded, { key, value });
		}
	};
	assign(base);
	assign(overrides);

	const merged: NodeJS.ProcessEnv = {};
	for (const { key, value } of entries.values()) merged[key] = value;
	return merged;
}

function getWindowsEnvironmentValue(
	env: NodeJS.ProcessEnv,
	name: string,
): string | undefined {
	let value: string | undefined;
	for (const [key, entry] of Object.entries(env)) {
		if (key.toLowerCase() === name.toLowerCase()) value = entry;
	}
	return value;
}

function driveLetter(value: string): string | undefined {
	const match = /^([A-Za-z]):/.exec(value);
	return match?.[1]?.toUpperCase();
}

function isDriveAbsolute(value: string, drive: string): boolean {
	return (
		value.length >= 3 &&
		value[0]?.toUpperCase() === drive.toUpperCase() &&
		value[1] === ":" &&
		(value[2] === "\\" || value[2] === "/")
	);
}

/** `X:\...` or `X:/...` — a drive-absolute path, for any drive letter. */
function isDriveAbsoluteAnyDrive(value: string): boolean {
	const drive = driveLetter(value);
	return drive !== undefined && isDriveAbsolute(value, drive);
}

/** `\\server\share\...` — a UNC path. Two leading separators, not more. */
function isUncWindowsPath(value: string): boolean {
	return (
		(value[0] === "\\" || value[0] === "/") &&
		(value[1] === "\\" || value[1] === "/") &&
		value[2] !== "\\" &&
		value[2] !== "/"
	);
}

/**
 * A path is "fully qualified" (self-contained, no ambient current-directory
 * lookup required) only when it is drive-absolute (`X:\...`) or UNC
 * (`\\server\share`). `path.win32.isAbsolute("\tools")` also returns `true`
 * for a *rooted* path — one relative to the current drive's root rather than
 * a specific drive — and treating that as fully qualified was the #1201
 * bug: it got statSync'd against the *host* drive while a different
 * `effectiveCwd`/`resolvedDrive` supplied the drive cmd.exe actually used to
 * execute it, so a different file could be validated than executed.
 */
function isFullyQualifiedWindowsPath(value: string): boolean {
	return isFullyQualifiedWin32(value) && !isRootedWindowsPath(value);
}

/**
 * `\tools` or `/tools` — rooted at the current drive's root, but naming no
 * drive of its own (distinct from both `X:\tools` fully-qualified and
 * `X:tools` drive-relative-to-current-directory). Windows resolves this
 * against the root of whichever drive is "current", not the current
 * directory on that drive.
 */
function isRootedWindowsPath(value: string): boolean {
	return (
		(value[0] === "\\" || value[0] === "/") &&
		driveLetter(value) === undefined &&
		!isUncWindowsPath(value)
	);
}

/**
 * Resolve a rooted path (`\tools`) against the ROOT of `driveSource`'s drive
 * — not `driveSource` itself — matching Windows' own rooted-path semantics.
 *
 * When `driveSource` carries NO drive letter, this returns the normalized
 * value rather than `undefined` (#1201, recurring defect shape 2). A
 * drive-less "current drive" provenance means we are not on a drive-lettered
 * filesystem at all — a POSIX host, or a UNC `process.cwd()` such as
 * `\\server\share\...`, which Node permits on real Windows. In that namespace
 * a rooted path is already as qualified as any path can be, so there is
 * nothing to anchor and normalizing is the correct (and pre-#1201) answer.
 * Returning `undefined` instead used to collapse the whole resolution to
 * `null` without a single `statSync`, i.e. a false ENOENT — the exact failure
 * signature #1199 exists to remove. This function must therefore never fail
 * closed on the *shape* of a value that may not be a Windows path at all;
 * the filesystem probe downstream is what decides whether it exists.
 */
function resolveRootedWindowsPath(value: string, driveSource: string): string {
	const drive = driveLetter(driveSource);
	if (drive === undefined) return path.win32.normalize(value);
	return path.win32.normalize(path.win32.resolve(`${drive}:\\`, value));
}

/**
 * Return a validated Windows per-drive current directory. Windows exposes
 * these as environment entries such as `=D:`; unlike ordinary environment
 * variables they are not safe to synthesize from a drive letter. A malformed
 * or wrong-drive value is deliberately ignored so drive-relative resolution
 * fails closed instead of guessing a root.
 *
 * Node never surfaces `=X:` keys from the ambient `process.env` (verified:
 * `Object.keys(process.env).filter(k => k.startsWith("="))` is empty), so
 * this provenance is only ever available when a caller supplies it
 * explicitly in an `env` override — e.g. a test, or a future integration
 * that reads it from a lower-level Windows API. That's a real, if narrow,
 * use: keep this path rather than deleting it, but never synthesize a value
 * Node itself can't hand us.
 */
function getValidatedPerDriveCwd(
	env: NodeJS.ProcessEnv,
	drive: string,
): string | undefined {
	const value = getWindowsEnvironmentValue(env, `=${drive}:`);
	if (value === undefined || !isDriveAbsolute(value, drive)) return undefined;
	return path.win32.normalize(value);
}

function resolveEffectiveWindowsCwd(
	cwd: string | undefined,
	env: NodeJS.ProcessEnv,
): string | undefined {
	if (cwd === undefined) {
		// No caller-supplied cwd: `process.cwd()` IS the effective cwd already —
		// the real, canonical filesystem cwd of THIS process, not a string that
		// needs (re)classifying. On a POSIX CI host it naturally carries no
		// drive letter; that's fine, it never needs one here. Only a
		// CALLER-SUPPLIED cwd string goes through the fully-qualified/rooted/
		// drive-relative classification below — running `process.cwd()`'s own
		// value through `isRootedWindowsPath` was itself a #1201 regression: a
		// drive-less POSIX path (e.g. Linux CI's real cwd) satisfies that
		// predicate too (single leading separator, no drive letter), which then
		// sent it to `resolveRootedWindowsPath` looking for a drive letter on
		// `process.cwd()` that — being the very same drive-less string — could
		// never supply one, resolving to `undefined` (recurring defect shape
		// 2/7: `path.win32.resolve` falls back to `process.cwd()`, which
		// supplies a drive on Windows and none on Linux).
		return path.win32.normalize(process.cwd());
	}
	const requestedDrive = driveLetter(cwd);
	if (requestedDrive !== undefined && !isDriveAbsoluteAnyDrive(cwd)) {
		// `D:foo` — drive-relative to that drive's own current directory.
		const base = getValidatedPerDriveCwd(env, requestedDrive);
		return base === undefined
			? undefined
			: path.win32.normalize(path.win32.resolve(base, cwd));
	}
	if (isFullyQualifiedWindowsPath(cwd)) return path.win32.normalize(cwd);
	if (isRootedWindowsPath(cwd)) {
		// `\tools` — rooted at the CURRENT drive's root.
		//
		// Note the deliberate asymmetry with `resolveWindowsPathEntry`, which
		// anchors rooted PATH entries to `effectiveCwd`'s drive instead. Both
		// use the SAME rule — "anchor to the best available "current drive"
		// provenance at this point in the pipeline" — they just sit at
		// different points. Here we are *computing* `effectiveCwd`, so it does
		// not exist yet and the process's own cwd is the only provenance
		// available (on real Windows it always carries a drive letter). By the
		// time a PATH entry is resolved, `effectiveCwd` is known and is the
		// strictly better answer, because it is the drive the child will
		// actually run from — anchoring PATH entries to the host drive there
		// would validate one file and execute another. Neither call can fail
		// closed on a drive-less provenance; see `resolveRootedWindowsPath`.
		return resolveRootedWindowsPath(cwd, process.cwd());
	}
	return path.win32.normalize(path.win32.resolve(process.cwd(), cwd));
}

function resolveDriveRelativeWindowsPath(
	value: string,
	effectiveCwd: string | undefined,
	env: NodeJS.ProcessEnv,
): string | undefined {
	const drive = driveLetter(value);
	if (drive === undefined) return undefined;
	const cwdDrive =
		effectiveCwd === undefined ? undefined : driveLetter(effectiveCwd);
	const base =
		cwdDrive?.toUpperCase() === drive
			? effectiveCwd
			: getValidatedPerDriveCwd(env, drive);
	if (base === undefined) return undefined;
	return path.win32.normalize(path.win32.resolve(base, value));
}

function resolveWindowsPathEntry(
	entry: string,
	effectiveCwd: string | undefined,
	env: NodeJS.ProcessEnv,
): string | undefined {
	if (driveLetter(entry) !== undefined && !isDriveAbsoluteAnyDrive(entry)) {
		return resolveDriveRelativeWindowsPath(entry, effectiveCwd, env);
	}
	if (isFullyQualifiedWindowsPath(entry)) return path.win32.normalize(entry);
	if (isRootedWindowsPath(entry)) {
		// `\tools` — rooted at the effective child cwd's drive root, not the
		// host process's drive (#1201: a rooted PATH entry must resolve on
		// the SAME drive the child will actually run cmd.exe/the resolved
		// binary from). See `resolveEffectiveWindowsCwd`'s rooted branch for
		// why that function anchors to `process.cwd()` instead — same rule,
		// different point in the pipeline. `undefined` here means the cwd
		// itself was unprovable, which is a genuinely different condition
		// from "the provenance carries no drive letter".
		return effectiveCwd === undefined
			? undefined
			: resolveRootedWindowsPath(entry, effectiveCwd);
	}
	if (effectiveCwd === undefined) return undefined;
	return path.win32.normalize(path.win32.resolve(effectiveCwd, entry));
}

/**
 * Cached PATH + PATHEXT resolution results. The effective child environment is
 * part of the key, not the ambient process environment: one caller's managed
 * bin directory must never poison another caller's resolution. The key also
 * carries the canonical child cwd and Windows `=X:` per-drive cwd entries,
 * because both affect relative PATH and drive-relative lookup. Session-lived
 * (matches this repo's other resolution caches, e.g.
 * `clients/workspace-topology.ts`'s `resetWorkspaceTopology`) — cleared via
 * `resetSafeSpawnWindowsCommandCache()`, wired into `handleSessionStart`. The
 * cache is also count-bounded with oldest-entry eviction because a long-lived
 * process can encounter unbounded cwd/environment combinations.
 */
export const WINDOWS_COMMAND_CACHE_MAX_ENTRIES = 256;
const WINDOWS_COMMAND_NEGATIVE_CACHE_TTL_MS = 1000;
interface WindowsCommandCacheEntry {
	resolved: ResolvedWindowsCommand | null;
	checkedAt: number;
}
const windowsCommandCache = new BoundedFifoMap<
	string,
	WindowsCommandCacheEntry
>(WINDOWS_COMMAND_CACHE_MAX_ENTRIES);

/** Reset after session replacement or a successful managed install. */
export function resetSafeSpawnWindowsCommandCache(): void {
	windowsCommandCache.clear();
	loggedSpawnClassifications.clear();
}

function cacheWindowsCommandResult(
	key: string,
	resolved: ResolvedWindowsCommand | null,
): void {
	// Resolution entries are session-scoped and cheap to recompute. The
	// caller always deletes any stale entry for `key` before reaching here
	// (see resolveWindowsCommandForEnvironment), so this can only grow the
	// map; BoundedFifoMap evicts the oldest insertion first once the map
	// exceeds capacity, so a long-lived process cannot retain every cwd /
	// environment it has ever touched.
	windowsCommandCache.set(key, { resolved, checkedAt: Date.now() });
}

export function getPathExts(env: NodeJS.ProcessEnv): string[] {
	const raw =
		getWindowsEnvironmentValue(env, "PATHEXT") ?? ".COM;.EXE;.BAT;.CMD";
	return raw
		.split(";")
		.map((ext) => ext.trim().toLowerCase())
		.filter(Boolean);
}

/** Filesystem-only command acceptance; stat follows links and rejects dangling ones. */
export function isAcceptedCommandFile(candidate: string): boolean {
	if (!statIsFile(candidate)) return false;
	if (process.platform === "win32") return true;
	try {
		fs.accessSync(candidate, fs.constants.X_OK);
		return true;
	} catch {
		return false;
	}
}

function statIsFile(candidate: string): boolean {
	try {
		return fs.statSync(candidate).isFile();
	} catch {
		return false;
	}
}

function resolveWindowsCommandUncached(
	command: string,
	effectiveCwd: string | undefined,
	env: NodeJS.ProcessEnv,
): ResolvedWindowsCommand | null {
	const pathExts = getPathExts(env);
	const existingExt = path.win32.extname(command).toLowerCase();
	const hasExplicitExt = existingExt.length > 0;
	// A suffix is "known executable" when it's one of the four extensions this
	// resolver actually knows how to run (direct .exe/.com, or the
	// cmd.exe-wrapped .cmd/.bat) OR it's explicitly listed in the caller's own
	// PATHEXT. Anything else with a dot is NOT necessarily "an extension" — a
	// versioned interpreter (`python3.11`, `node-v20.1`) has an `extname()` of
	// `.11`/`.1` that is part of the basename, not a suffix to match exactly
	// (#1201).
	const isKnownExecutableExt = (ext: string): boolean =>
		WINDOWS_DIRECT_RESOLVABLE_EXTS.has(ext) || pathExts.includes(ext);

	const tryBase = (base: string): ResolvedWindowsCommand | null => {
		// Additive, not exclusive: an explicit, known-executable suffix is
		// tried as an exact candidate FIRST (this also lets a caller ask for
		// `foo.cmd` even when the current PATHEXT doesn't happen to list
		// `.CMD`). Whenever the suffix ISN'T a PATHEXT entry — no extension at
		// all, or a versioned/unknown one like `.11` — the PATHEXT-append loop
		// ALSO runs against the full base, so `python3.11` still finds
		// `python3.11.exe`. An unknown suffix (e.g. `foo.txt`) never gets an
		// exact-match short-circuit: that would let an arbitrary
		// non-executable file resolve as "spawnable" and reach the
		// direct-spawn branch downstream.
		if (
			hasExplicitExt &&
			isKnownExecutableExt(existingExt) &&
			statIsFile(base)
		) {
			return { resolvedPath: base, ext: existingExt };
		}
		if (!hasExplicitExt || !pathExts.includes(existingExt)) {
			for (const ext of pathExts) {
				const candidate = base + ext;
				if (statIsFile(candidate)) return { resolvedPath: candidate, ext };
			}
		}
		return null;
	};

	const hasPathSep = /[\\/]/.test(command);
	// `D:tool.exe` is drive-relative on Windows, not a bare PATH command. It
	// uses the effective cwd only when that cwd is on D:. For another drive we
	// require an explicit, validated `=D:` provenance entry; otherwise this
	// resolver fails closed rather than guessing `D:\\` or searching PATH.
	const hasDrivePrefix = driveLetter(command) !== undefined;
	if (hasPathSep || hasDrivePrefix || isFullyQualifiedWindowsPath(command)) {
		let base: string | undefined;
		if (isFullyQualifiedWindowsPath(command)) {
			base = path.win32.normalize(command);
		} else if (hasDrivePrefix) {
			base = resolveDriveRelativeWindowsPath(command, effectiveCwd, env);
		} else if (isRootedWindowsPath(command)) {
			base =
				effectiveCwd === undefined
					? undefined
					: resolveRootedWindowsPath(command, effectiveCwd);
		} else if (effectiveCwd !== undefined) {
			base = path.win32.normalize(path.win32.resolve(effectiveCwd, command));
		}
		return base === undefined ? null : tryBase(base);
	}

	// A bare command (no path separator) is a plain PATH search. Absolute PATH
	// entries don't need `effectiveCwd` at all, so an unresolvable cwd must
	// only skip the relative entries (handled per-entry in
	// resolveWindowsPathEntry below), not abort the whole search (#1201: a bad
	// cwd shouldn't make an otherwise-resolvable command look "not installed").
	const pathValue = getWindowsEnvironmentValue(env, "PATH") ?? "";
	const pathDirs = pathValue.split(path.win32.delimiter);
	for (const dir of pathDirs) {
		if (!dir) continue;
		const resolvedDir = resolveWindowsPathEntry(dir, effectiveCwd, env);
		if (resolvedDir === undefined) continue;
		const found = tryBase(path.win32.join(resolvedDir, command));
		if (found) return found;
	}
	return null;
}

/**
 * Resolve a Windows command using the exact environment that will be passed to
 * the child. Exported as a small platform-independent test/diagnostic seam;
 * callers should pass a Windows-shaped environment and do not need to mutate
 * `process.env` to exercise resolution. Drive-relative commands (`D:tool.exe`)
 * use a same-drive effective cwd, or a validated absolute `=D:` entry for a
 * different drive; without that provenance they fail closed and never search
 * PATH. Relative PATH entries use the canonical effective child cwd.
 */
export function resolveWindowsCommandForEnvironment(
	command: string,
	cwd: string | undefined,
	env: NodeJS.ProcessEnv,
): ResolvedWindowsCommand | null {
	const effectiveCwd = resolveEffectiveWindowsCwd(cwd, env);
	const pathValue = getWindowsEnvironmentValue(env, "PATH");
	const pathExtValue = getWindowsEnvironmentValue(env, "PATHEXT");
	const perDriveCwds = Object.entries(env)
		.flatMap(([key, value]) =>
			/^=[A-Za-z]:$/.test(key)
				? ([[key.toLowerCase(), value] as const] as const)
				: [],
		)
		.sort(([left], [right]) => compareOrdinal(left, right));
	// Keep presence separate from value: absent PATHEXT means the Windows
	// default extension list, while PATHEXT="" means no implicit extensions.
	// The per-drive snapshot is equally important: it is provenance for
	// drive-relative commands and PATH entries, not ambient decoration.
	const cacheKey = JSON.stringify([
		"win32",
		command,
		pathValue === undefined ? ["absent"] : ["present", pathValue],
		pathExtValue === undefined ? ["absent"] : ["present", pathExtValue],
		effectiveCwd === undefined ? ["unresolved"] : ["resolved", effectiveCwd],
		perDriveCwds,
	]);
	const cached = windowsCommandCache.get(cacheKey);
	if (cached) {
		// Positive entries are revalidated on every hit so an executable deleted
		// or replaced mid-session cannot remain spawnable through stale cache
		// state. Negative entries are short-lived to discover external installs;
		// pi-lens-managed installs also reset the cache immediately on success.
		if (cached.resolved && statIsFile(cached.resolved.resolvedPath)) {
			return cached.resolved;
		}
		if (
			!cached.resolved &&
			Date.now() - cached.checkedAt <= WINDOWS_COMMAND_NEGATIVE_CACHE_TTL_MS
		) {
			return null;
		}
		windowsCommandCache.delete(cacheKey);
	}
	const resolved = resolveWindowsCommandUncached(command, effectiveCwd, env);
	cacheWindowsCommandResult(cacheKey, resolved);
	return resolved;
}

/** Cached `where`-equivalent for the effective child environment. */
function resolveWindowsCommand(
	command: string,
	cwd: string | undefined,
	env: NodeJS.ProcessEnv,
): ResolvedWindowsCommand | null {
	return resolveWindowsCommandForEnvironment(command, cwd, env);
}

function getSpawnEnvironment(
	overrides: NodeJS.ProcessEnv | undefined,
	stripNpmConfig: boolean | undefined,
): NodeJS.ProcessEnv {
	const merged =
		process.platform === "win32"
			? mergeWindowsEnvironment(process.env, overrides)
			: { ...process.env, ...overrides };
	if (!stripNpmConfig) return merged;
	// A copy loop rather than `Object.fromEntries(…filter(…))`: `filter` is a
	// retired glossary identifier and a new use would move the census. This runs
	// only on the flagged cache-only package-runner spawns, never the hot
	// default path.
	const stripped: NodeJS.ProcessEnv = {};
	for (const [key, value] of Object.entries(merged)) {
		if (!/^npm_config_/i.test(key)) stripped[key] = value;
	}
	return stripped;
}

/**
 * Characters that make a cmd.exe `/c` command line unsound to build from
 * caller-tainted input: `%`/`!` expand even inside double quotes and cannot
 * be escaped on a `/c` line (only `%%` works, and only in batch files), `"`
 * can toggle cmd's quote-parsing state past the doubling convention, and
 * CR/LF let an argument masquerade as a second command. Reject rather than
 * attempt to escape these (#817) — silent stripping would just move the
 * unsoundness, not remove it.
 */
const CMD_UNSAFE_CHARS = /["%!\r\n]/;

/** First caller-tainted value (command or an arg) that can't be safely
 * passed through the .cmd/.bat cmd.exe wrapper, or `undefined` if all clear. */
function findCmdUnsafeValue(
	command: string,
	args: string[],
): string | undefined {
	if (CMD_UNSAFE_CHARS.test(command)) return command;
	return args.find((arg) => CMD_UNSAFE_CHARS.test(arg));
}

function synthesizeEnoentError(command: string): NodeJS.ErrnoException {
	// Shaped like Node's native `spawn <cmd> ENOENT` error (message/code/
	// syscall/path) so the typed classifier retains the same diagnostic cause
	// now that Windows resolution happens before spawn instead of inside cmd.exe.
	const err = new Error(`spawn ${command} ENOENT`) as NodeJS.ErrnoException;
	err.code = "ENOENT";
	err.syscall = "spawn";
	err.path = command;
	return err;
}

/**
 * One-shot `chcp 65001` before the FIRST direct (.exe/.com) Windows spawn.
 *
 * Mechanism: `chcp` mutates the code page of the console the current process
 * is attached to, and that mutation persists for the console's lifetime —
 * it is not per-child-process state. The old cmd.exe-wrapper path re-ran
 * `chcp 65001 >nul 2>&1 &&` on every single spawn, which was always
 * redundant after the first call; memoizing here (module-level, once per
 * process) is a strict improvement, not a behavior change. Runs through a
 * tiny pinned cmd.exe spawn (same `%SystemRoot%\System32\cmd.exe` pin as
 * `killTree` below) with a static, hardcoded command string — no caller-
 * tainted data anywhere near it.
 */
let utf8ConsoleCodePageApplied = false;

function ensureUtf8ConsoleCodePageOnce(): void {
	if (utf8ConsoleCodePageApplied) return;
	utf8ConsoleCodePageApplied = true;
	try {
		const cmdExe = `${process.env.SystemRoot ?? "C:\\Windows"}\\System32\\cmd.exe`;
		spawnSync(cmdExe, ["/d", "/s", "/c", "chcp 65001 >nul 2>&1"], {
			shell: false,
			windowsHide: true,
			// #1980 population sweep: a synchronous spawn with no timeout parks
			// the event loop for as long as the child takes, and nothing here
			// bounds that. `chcp` is normally instant, but this runs before the
			// FIRST real spawn of the process, which is exactly when a cold or
			// antivirus-throttled cmd.exe is slowest. Matches the 5s bound every
			// other synchronous child-process site in this repo already carries.
			timeout: 5000,
		});
	} catch {
		// Best-effort: worst case is non-ASCII tool output decoded incorrectly, not a
		// spawn failure — never let this block the real spawn.
	}
}

/**
 * Test-only seam: clear the one-shot `chcp` memoization.
 *
 * No test observes it today — the memoized work only runs inside a real
 * Windows direct spawn, so exercising it would mean a Windows-only test, and
 * the state it guards is a console code page, not behavior any assertion
 * depends on. This is kept purely so a future Windows-only test (or a second
 * caller of `ensureUtf8ConsoleCodePageOnce`) can reset process-lifetime state
 * without reaching into the module; it was dropped once as unrelated scope
 * creep in an earlier #1199 revision and restored on review. Do not read the
 * export as evidence of existing coverage (#1201).
 */
export function resetUtf8ConsoleCodePageStateForTests(): void {
	utf8ConsoleCodePageApplied = false;
}

// #1656: post-exit pipe-idle wait constants. Node's "close" event only fires
// once every stdio fd referencing the child has been released — a
// daemonized descendant that inherited our stdout/stderr pipe (the Windows
// no-job-object case) can hold that fd open forever, hanging "close" even
// though the child we spawned is long dead. A fixed post-exit deadline
// avoids that hang but truncates a legitimately still-streaming child. The
// idle-grace construction (adopted from pi's `waitForChildProcess`) does
// neither: after "exit", wait for the pipes to go quiet — no data for
// EXIT_PIPE_IDLE_GRACE_MS, re-armed on every chunk — so a quiet inherited
// handle still releases after one grace window while an actively-writing
// descendant keeps being read. EXIT_PIPE_IDLE_MAX_WAIT_MS caps the total
// extra wait so a pathological, never-quiet descendant can't extend the
// caller's overall budget unboundedly.
const EXIT_PIPE_IDLE_GRACE_MS = 100;
const EXIT_PIPE_IDLE_MAX_WAIT_MS = 2000;

/**
 * #2968: how long past its own deadline this spawn's CPU/RSS sampler may keep
 * polling. Everything this function does to end a child after the deadline
 * fits inside it: `killTree`'s SIGTERM plus its 1000ms SIGKILL escalation (or
 * Windows' `taskkill /F /T`), then at most EXIT_PIPE_IDLE_MAX_WAIT_MS of
 * pipe-idle wait. A child still alive past deadline + this grace has outlived
 * every teardown available here, so polling it further only buys the Windows
 * process pile-up the report measured — and `stop()` still returns whatever
 * the sampler gathered before the cap.
 */
const SPAWN_SAMPLER_TEARDOWN_GRACE_MS = 5_000;

// ============================================================================
// ASYNC VERSION (Recommended - Non-blocking)
// ============================================================================

/** Capture-local cancellation; async context prevents interference with concurrent dispatch. */
export const spawnAbortScope = new AsyncLocalStorage<AbortSignal>();

/**
 * Async spawn with timeout and proper process cleanup.
 *
 * Unlike spawnSync, this:
 * - Doesn't block the event loop
 * - Kills the process on timeout (preventing zombies)
 * - Supports cancellation via AbortSignal
 *
 * ## Why this bound is NOT `bounded()` — the one documented exception (#2523)
 *
 * #2523 slice 2 folded every other "deadline AND abort signal" implementation
 * in the tree onto `clients/deadline-utils.ts#bounded`. This one stays, and it
 * is not a copy of the same idea:
 *
 * `bounded()` ABANDONS a promise — it stops waiting and lets the work run on
 * unobserved, which is safe precisely because everything it wraps is in-process
 * (a dynamic import, an LSP round trip, a `stat`). This function's work is a
 * CHILD PROCESS, and abandoning one leaks it. So its timer does not settle a
 * race at all: `timeoutId` sets `timedOut`, then runs `killTree()` — SIGTERM,
 * an escalation timer, SIGKILL, and on Windows a `taskkill /T` of the whole
 * tree — and the promise settles only when the child's own `close` arrives (or
 * the escalation gives up). The result it produces carries the teardown
 * EVIDENCE (`timeoutTeardown`, #2010): which signal killed it, whether the
 * tree actually died, how long it took. Replacing that with `bounded()` would
 * return `undefined` at the deadline and leave a live `vitest`/`gradle` behind
 * — the orphan class #2504 measured as 59 concurrent spawns starving a turn.
 *
 * The rule the exception preserves: a bound that can CANCEL its work must
 * cancel it. `bounded()` is for work that cannot be cancelled; this is not
 * that. Anything wrapping THIS function still gets `bounded()` around its own
 * await if it needs one.
 *
 * @example
 * const result = await safeSpawnAsync("npm", ["test"], { timeout: 30000 });
 * if (result.error) console.error("Failed:", result.error);
 */
export async function safeSpawnAsync(
	command: string,
	args: string[],
	options?: SafeSpawnOptions,
): Promise<SpawnResult> {
	const configuredTimeout =
		options?.timeout !== undefined &&
		Number.isFinite(options.timeout) &&
		options.timeout >= 0
			? options.timeout
			: 30000;
	const deadlineRemaining =
		options?.deadlineAt !== undefined && Number.isFinite(options.deadlineAt)
			? options.deadlineAt - Date.now()
			: Number.POSITIVE_INFINITY;
	const timeout = Math.max(0, Math.min(configuredTimeout, deadlineRemaining));
	// Fall back to the current turn's ambient signal (set from ctx.signal) so an
	// Esc/abort mid-turn cancels dispatches that didn't thread a signal of their
	// own — unless the caller opts out (installs, which must run to completion).
	const callerSignal =
		options?.signal ??
		(options?.ignoreAmbientSignal ? undefined : ambientAbortSignal);
	const scopedSignal = spawnAbortScope.getStore();
	const abortSignal =
		scopedSignal && callerSignal
			? AbortSignal.any([scopedSignal, callerSignal])
			: (scopedSignal ?? callerSignal);

	return new Promise((resolve) => {
		// Check for early abort
		if (abortSignal?.aborted) {
			const cause = new Error("Spawn aborted before start");
			resolve({
				stdout: "",
				stderr: "",
				status: null,
				error: cause,
				failure: "aborted",
				spawnFailure: new SpawnFailureError("killed", cause.message, cause),
			});
			return;
		}
		if (timeout <= 0) {
			const cause = new Error(`Process timed out after ${timeout}ms`);
			resolve({
				stdout: "",
				stderr: "",
				status: null,
				error: cause,
				failure: "timeout",
				spawnFailure: new SpawnFailureError("timeout", cause.message, cause),
			});
			return;
		}

		let stdout = "";
		let stderr = "";
		let timedOut = false;
		let aborted = false;
		let killed = false;
		let outputTruncated = false;
		let killedForOutputCap = false;
		// #3375: bytes the child actually EMITTED (not what survived the cap) —
		// the one number the field crash report could not supply, so the ledger
		// row below can name how chatty the offending command really was.
		let observedOutputBytes = 0;
		// #3375: bytes RETAINED so far, kept incrementally. The cap check used to
		// re-measure `Buffer.byteLength(stdout) + Buffer.byteLength(stderr)` on
		// every chunk, which flattens both accumulated strings each time — O(n^2)
		// in total output. Harmless while only 12 of 110 call sites passed a cap;
		// with the cap now on by default it would tax every spawn (measured: a
		// 32 MiB child resolved in 7944 ms before this counter, 469 ms after).
		// Equal to the two byte lengths by construction: before
		// truncation `stdout`/`stderr` are exactly the appended texts, and after
		// it the branch that renders from the retained head/tail never reads it.
		let retainedOutputBytes = 0;
		// #3375: latched the first time a chunk handler throws. Later chunks
		// return immediately, so the same fault cannot be re-entered and
		// `refreshRetainedOutputs` can never overwrite the bytes already kept.
		let outputHandlerFailed = false;
		let streamingMatch = false;
		// #1651 review: a single boolean the close/error handlers both check
		// AND set, so whichever one decides the outcome first wins outright —
		// the DECISION itself is shape-based (see the `close` handler below),
		// this flag only stops the loser from resolving a second time.
		let resolved = false;
		// The most recent 'error' Error, captured the instant the event fires
		// regardless of whether that handler goes on to resolve. The `close`
		// handler's shape-based branch (code === null || code < 0) reads this
		// when it decides FIRST, so a genuinely informative ENOENT/EACCES/etc.
		// Error is used when it happens to already be available, instead of
		// always falling back to a generic synthesized one.
		let pendingSpawnError: Error | undefined;
		// #1109: the non-Windows SIGTERM→SIGKILL escalation timer (armed in
		// killTree below). Stored per-call (never shared) so the close/error
		// handlers can clear it if the child exits before it fires — same
		// uncleared-race-timeout class as the LSP client-wait leak (#1097):
		// a ref'd 1s timer that outlives the child it was escalating against
		// would keep a one-shot `pi --print` process alive for up to 1s.
		let escalationTimer: ReturnType<typeof setTimeout> | undefined;
		let teardownStartedAtMs: number | undefined;
		let teardownEscalated = false;
		// #2010: teardown evidence for the spawn's OWN timeout. The wall clock
		// starts when the budget expires and the tree-kill is issued, and stops
		// when the process tree is observed dead (`await killPromise` settles)
		// - measured SEPARATELY from the budget itself, so a slow teardown is
		// visible instead of silently inflating "how long the tool ran".
		// `teardownEscalated` names whether SIGTERM sufficed or the SIGKILL
		// escalation fired (POSIX; Windows taskkill /F is always forceful).
		// #1114: `child.killed` is set by Node the moment `kill()` successfully
		// SENDS a signal, not when the child actually dies — so gating the
		// escalation on `!child.killed` right after a successful `SIGTERM` send
		// is always false and the SIGKILL branch is unreachable. Track observed
		// death via the close/error handlers instead (set synchronously, before
		// any `await`, so a timer firing during the close handler's `await
		// killPromise` still observes the flag correctly).
		let closed = false;
		// #1656: set only while the post-exit idle-pipe wait is active (see
		// waitForPipeIdle below); the stdout/stderr "data" handlers call this to
		// re-arm the grace timer on every chunk. `undefined` before exit / after
		// the wait settles, so the calls below are no-ops outside that window.
		let rearmIdleGrace: (() => void) | undefined;
		// #3375: never `undefined`. An omitted or unusable cap resolves to the
		// module default instead of to unbounded retention, so `appendOutput`
		// below has no arm that concatenates without a ceiling.
		const callerCap = options?.maxOutputBytes;
		const capFromCaller =
			callerCap !== undefined && Number.isFinite(callerCap) && callerCap > 0;
		const maxOutputBytes: number = capFromCaller
			? Math.floor(callerCap)
			: DEFAULT_MAX_OUTPUT_BYTES;
		const outputTruncationMarker = "\n...[output truncated]...\n";
		type OutputStream = "stdout" | "stderr";
		type OutputPart = { stream: OutputStream; text: string };
		let retainedHead: OutputPart[] = [];
		let retainedTail: OutputPart[] = [];
		let retainedTailBytes = 0;
		let retainedTailLimit = 0;
		let truncationStream: OutputStream = "stderr";
		const streamingMatcher = options?.matchWhileStreaming;
		const streamingCarryBytes = streamingMatcher
			? Math.max(0, streamingMatcher.source.length - 1)
			: 0;
		const streamingCarry: Record<OutputStream, string> = {
			stdout: "",
			stderr: "",
		};
		const bytePrefix = (text: string, bytes: number): string =>
			Buffer.from(text).subarray(0, bytes).toString();
		const byteSuffix = (text: string, bytes: number): string => {
			const buffer = Buffer.from(text);
			return buffer.subarray(Math.max(0, buffer.byteLength - bytes)).toString();
		};
		const appendTail = (part: OutputPart, maxBytes: number): void => {
			if (maxBytes <= 0) return;
			retainedTail.push({ stream: part.stream, text: part.text });
			retainedTailBytes += Buffer.byteLength(part.text);
			while (retainedTailBytes > maxBytes && retainedTail.length > 0) {
				const first = retainedTail[0];
				const excess = retainedTailBytes - maxBytes;
				const firstBytes = Buffer.byteLength(first.text);
				if (firstBytes <= excess) {
					retainedTail.shift();
					retainedTailBytes -= firstBytes;
				} else {
					first.text = byteSuffix(first.text, firstBytes - excess);
					retainedTailBytes -= excess;
				}
			}
		};
		const renderOutput = (stream: OutputStream): string => {
			const head = retainedHead
				.filter((part) => part.stream === stream)
				.map((part) => part.text)
				.join("");
			const tail = retainedTail
				.filter((part) => part.stream === stream)
				.map((part) => part.text)
				.join("");
			const marker = stream === truncationStream ? outputTruncationMarker : "";
			return head + marker + tail;
		};
		const refreshRetainedOutputs = (): void => {
			stdout = renderOutput("stdout");
			stderr = renderOutput("stderr");
		};
		const appendOutput = (
			stream: OutputStream,
			current: string,
			chunk: string | Buffer,
		): string => {
			const text = typeof chunk === "string" ? chunk : chunk.toString();
			if (outputTruncated) {
				appendTail({ stream, text }, retainedTailLimit);
				truncationStream = stream;
				return renderOutput(stream);
			}
			const bytes = Buffer.byteLength(text);
			if (retainedOutputBytes + bytes <= maxOutputBytes) {
				retainedOutputBytes += bytes;
				return current + text;
			}
			outputTruncated = true;
			truncationStream = stream;
			const available = Math.max(
				0,
				maxOutputBytes - Buffer.byteLength(outputTruncationMarker),
			);
			const headBytes = Math.floor(available / 2);
			const tailBytes = available - headBytes;
			retainedTailLimit = tailBytes;
			const parts: OutputPart[] = [
				{ stream: "stdout", text: stdout },
				{ stream: "stderr", text: stderr },
				{ stream, text },
			];
			let headRemaining = headBytes;
			for (const part of parts) {
				if (headRemaining <= 0) break;
				const kept = bytePrefix(part.text, headRemaining);
				if (kept) retainedHead.push({ stream: part.stream, text: kept });
				headRemaining -= Buffer.byteLength(kept);
			}
			let tailRemaining = tailBytes;
			for (
				let index = parts.length - 1;
				index >= 0 && tailRemaining > 0;
				index--
			) {
				const part = parts[index];
				const kept = byteSuffix(part.text, tailRemaining);
				if (kept) {
					retainedTail.unshift({ stream: part.stream, text: kept });
					tailRemaining -= Buffer.byteLength(kept);
				}
			}
			retainedTailBytes = tailBytes - tailRemaining;
			return renderOutput(stream);
		};
		const matchStreamingChunk = (
			stream: OutputStream,
			chunk: string | Buffer,
		): void => {
			if (streamingMatch || !streamingMatcher) return;
			const text = typeof chunk === "string" ? chunk : chunk.toString();
			streamingMatcher.lastIndex = 0;
			streamingMatch = streamingMatcher.test(streamingCarry[stream] + text);
			if (streamingCarryBytes > 0) {
				streamingCarry[stream] = Buffer.from(streamingCarry[stream] + text)
					.subarray(-streamingCarryBytes)
					.toString();
			}
		};

		// Spawn the process (non-blocking). Keeping Node's `shell` option false
		// is important on every path here: shell:true concatenates tainted
		// arguments into a command line before spawning (CodeQL #17 / CWE-78).
		//
		// On Windows (#817): resolve `command` ourselves (PATH + PATHEXT walk,
		// cached) instead of always routing through cmd.exe.
		//   - .exe/.com  → spawn the resolved path directly, args stay a real
		//     array, no shell involved at all (injection-proof).
		//   - .cmd/.bat  → these are scripts cmd.exe must interpret (npm shims
		//     are the common case), so keep the wrapper, but pin the
		//     interpreter to %SystemRoot%\System32\cmd.exe (never trust
		//     ComSpec — CodeQL #18) and VALIDATE args instead of trying to
		//     escape them: reject anything containing `"`, `%`, `!`, or CR/LF
		//     rather than spawn with an unsound escape.
		//   - unresolvable → synthesize an ENOENT-shaped error instead of
		//     letting cmd.exe report "not recognized" from inside a shell.
		const isWindows = process.platform === "win32";
		const spawnEnv = getSpawnEnvironment(options?.env, options?.stripNpmConfig);
		// The cwd handed to the CHILD process doesn't need OUR validation —
		// Windows resolves it natively, exactly as it did before #817 ever
		// touched this file. A drive-relative cwd (`D:work`) without a
		// validated `=D:` env entry can't be canonicalized by us (Node never
		// surfaces `=X:` keys from the ambient environment — see
		// `getValidatedPerDriveCwd`'s doc comment), but that is a gap in OUR
		// provenance, not evidence the cwd itself is bad. Fall back to the raw
		// value instead of failing the whole spawn before ever attempting it
		// (#1201) — command resolution just below still fails closed for any
		// relative PATH entry that would need this cwd to be canonical.
		// No `?? process.cwd()` third arm: `resolveEffectiveWindowsCwd(undefined,
		// env)` always returns a string, so the only way to reach `undefined`
		// here is a DEFINED-but-unprovable `options.cwd`, which `?? options?.cwd`
		// already covers. A `process.cwd()` arm would be unreachable, and it
		// would read like a live silent-wrong-directory hazard (#1201).
		const spawnCwd = isWindows
			? (resolveEffectiveWindowsCwd(options?.cwd, spawnEnv) ?? options?.cwd)
			: options?.cwd;
		let spawnCmd = command;
		let spawnArgs = args;
		let windowsVerbatimArguments = false;
		let resolutionError: Error | undefined;

		if (isWindows) {
			// Pass the ORIGINAL (unresolved) cwd here, not `spawnCwd` above — this
			// seam intentionally fails closed on unprovable drive-relative
			// provenance (matches `resolveWindowsCommandForEnvironment`'s
			// documented contract and its dedicated test coverage), independent
			// of the passthrough fallback the actual child cwd gets above.
			const resolved = resolveWindowsCommand(command, options?.cwd, spawnEnv);
			if (!resolved) {
				resolutionError = synthesizeEnoentError(command);
			} else if (resolved.ext === ".cmd" || resolved.ext === ".bat") {
				// Validate the RESOLVED path (what actually gets interpolated
				// into the /c line via buildWindowsShellCommand below), not the
				// caller's original `command` string — a resolved path
				// containing `%`/`!` would otherwise reach the shell unvalidated.
				const unsafeValue = findCmdUnsafeValue(resolved.resolvedPath, args);
				if (unsafeValue !== undefined) {
					resolutionError = new Error(
						`Refusing to spawn "${resolved.resolvedPath}" via cmd.exe: ` +
							`${JSON.stringify(unsafeValue)} contains a character ("` +
							`, %, !, or CR/LF) that cannot be safely escaped on a ` +
							`cmd.exe /c command line (CWE-78, #817). Rename/quote the ` +
							"value or invoke the tool without going through cmd.exe.",
					);
				} else {
					// Pin the interpreter — never trust ComSpec/COMSPEC (#18): an
					// env-controlled ComSpec could point anywhere.
					spawnCmd = `${process.env.SystemRoot ?? "C:\\Windows"}\\System32\\cmd.exe`;
					spawnArgs = [
						"/d",
						"/s",
						"/c",
						buildWindowsShellCommand(resolved.resolvedPath, args),
					];
					// The `/c` payload is already quoted by buildWindowsShellCommand.
					// Prevent Node from escaping those quotes a second time when it
					// builds cmd.exe's Windows command line.
					windowsVerbatimArguments = true;
				}
			} else {
				// .exe / .com: direct spawn, no cmd.exe anywhere in the picture.
				ensureUtf8ConsoleCodePageOnce();
				spawnCmd = resolved.resolvedPath;
				spawnArgs = args;
			}
		}

		if (resolutionError) {
			void classifySpawnFailure(resolutionError, {
				command,
				cwd: options?.cwd,
			}).then((spawnFailure) =>
				resolve({
					stdout: "",
					stderr: "",
					status: null,
					error: resolutionError,
					failure: "spawn",
					spawnFailure,
				}),
			);
			return;
		}

		let child: ChildProcess;
		// #2026: on POSIX, run the child in its OWN process group (detached).
		// killTree/killPidTreeSync then signal the whole GROUP (-pid), which
		// makes grandchildren (npm -> node, sh -> sleep, etc.) die with their
		// tool instead of surviving every timeout as orphans. Detachment stops
		// direct terminal-signal delivery, so EVERY POSIX pid registers for
		// lifetime cleanup - pi's signal/exit handlers forward the kill,
		// preserving die-with-host semantics.
		const posixProcessGroup = process.platform !== "win32";
		try {
			child = spawn(spawnCmd, spawnArgs, {
				cwd: spawnCwd,
				env: spawnEnv,
				windowsHide: true,
				shell: false,
				windowsVerbatimArguments,
				detached: posixProcessGroup,
			});
		} catch (err) {
			// A SYNCHRONOUS spawn throw (Windows `spawn UNKNOWN`/EINVAL — the
			// pidusage bug class, #533) must NOT reject this Promise: every caller
			// relies on safeSpawnAsync never rejecting (they inspect result.error),
			// and many invoke it fire-and-forget in best-effort/background paths, so
			// a rejection here could surface as an unhandledRejection that crashes
			// the host. Resolve the failure gracefully instead — same contract as an
			// asynchronously-emitted `'error'` event (handled below).
			const cause = toError(err);
			void classifySpawnFailure(cause, { command, cwd: options?.cwd }).then(
				(spawnFailure) =>
					resolve({
						stdout: "",
						stderr: "",
						status: null,
						error: cause,
						failure: "spawn",
						spawnFailure,
					}),
			);
			return;
		}
		// Keep historical open stdin by default. An opted-in payload is written
		// completely and followed by EOF; input: "" closes stdin immediately.
		if (options?.input !== undefined) {
			child.stdin?.on("error", () => {});
			child.stdin?.end(options.input);
		}
		// #2042: ownership is a SPAWN-TIME fact — a real child is alive with
		// `PPid == ours` the instant `spawn` returns, while a test double's
		// invented pid never is. Resolve it once, here, and reuse the verdict:
		// the group escalation below must still fire after the direct child
		// dies (#2027: a SIGTERM-hardy grandchild keeps the group alive), so it
		// cannot re-read `/proc` at kill time.
		const ownsChildPid = isOwnLiveChild(child.pid, "safe-spawn-register");
		if (ownsChildPid && (posixProcessGroup || options?.lifetimeCoupled)) {
			// #2026: POSIX registers unconditionally - detached children no
			// longer receive terminal signals directly, so the lifetime
			// cleanup's signal forwarding IS their die-with-host path.
			installLifetimeCleanup();
			lifetimeState.pids.add(child.pid as number);
		}

		// #620: bracket this spawn's lifetime with a short-interval CPU/RSS poll
		// (started right here, stopped in finalize() below) so transient
		// analyzer children (jscpd, knip, madge, gitleaks, etc.) — which live too
		// briefly for heartbeat-cadence sampling to reliably catch — still get a
		// peak/average resource reading. `startSpawnUsageSampler` itself is
		// best-effort/never-throws by design, but this call site wraps it anyway
		// (belt and suspenders: the sampling seam must never be the reason a real
		// spawn fails) with a no-op fallback sampler.
		//
		// #2968: the sampler's polling lifetime is bounded by THIS spawn's own
		// deadline plus the teardown grace, not by the child's willingness to
		// exit. `finalize`/the `error` handler still stop it on every settle
		// path, but none of those paths exist for a child that never settles —
		// a hung `.cmd` shim whose tree survives `taskkill /F /T` kept polling
		// for 5-6 hours in the report.
		let usageSampler: { stop: () => SpawnResourceUsage | null };
		try {
			usageSampler = startSpawnUsageSampler(
				// The poll CADENCE is the sampler's own policy (it owns the backoff
				// too); the DEADLINE is this function's. Passing `undefined` rather
				// than importing the cadence constant keeps this module's view of
				// the sampler at one export, which is also what every existing
				// `vi.mock` of it provides.
				child.pid,
				undefined,
				timeout + SPAWN_SAMPLER_TEARDOWN_GRACE_MS,
			);
		} catch {
			usageSampler = { stop: () => null };
		}
		const resourceLabel = options?.resourceLabel ?? command;

		// #3375 round 2 (H3384-1). `killTree`'s promise is AWAITED by `finalize`
		// from a `void finalize(...)` callback, FIRED AND FORGOTTEN by `onAbort`
		// (`void killTree()`), and its escalation runs in a bare `setTimeout`
		// callback — three structurally different ways a throwing `kill` escaped
		// this spawn: as a rejection that left the public promise pending
		// forever, as an `unhandledRejection`, and (from the timer) as an
		// uncaught exception, which is the very shape #3375 exists to close.
		// So no signal is sent except through `trySend`, which cannot throw.
		type KillPhase = "abort" | "output-cap" | "handler-fault" | "timeout";
		let killFailed = false;
		/** Send one signal. INVARIANT (#3375 r3 / M3384-2): every signal SEND in
		 *  `killTree` goes through this function. Exactly two `try`/`catch`
		 *  blocks remain in there and neither contains a bare send: the Windows
		 *  `await` guard around the taskkill child (its `catch` body sends only
		 *  through `trySend`), and the group LIVENESS PROBE, whose `catch`
		 *  computes a predicate rather than sending anything — the same shape as
		 *  the module-level `groupIsGone`. Returns false instead of throwing, and
		 *  records nothing itself: a refused signal is often ORDINARY (a negative-pid
		 *  ESRCH means the group already exited and the direct-child fallback
		 *  takes over), so only a send with no fallback left behind it pairs
		 *  with `noteKillFailure`. */
		const trySend = (send: () => void): boolean => {
			try {
				send();
				return true;
			} catch {
				return false;
			}
		};
		/** Every signal for this teardown was refused, so the child may still be
		 *  running. One record per spawn — the reviewer's reproduction refused
		 *  two kills (the fault's and then the timeout's) and a row per attempt
		 *  would be a flood. A kind of its own rather than a field on
		 *  `spawn-output-cap-truncated`: this fires on the abort and timeout
		 *  teardowns too, which have nothing to do with an output cap. */
		const noteKillFailure = (phase: KillPhase): void => {
			if (killFailed) return;
			killFailed = true;
			incrementDegradationCount({
				kind: "spawn-kill-failed",
				subject: resourceLabel,
				reason: `every signal available for the ${phase} teardown was refused; the child may still be running`,
				metadata: { phase, pid: child.pid },
			});
		};

		// On Windows, shell:true means child.pid is cmd.exe — child.kill() only
		// kills the wrapper, leaving the actual subprocess (e.g. knip/npx) alive
		// as an orphan. Use taskkill /F /T to kill the full process tree instead.
		const killTree = async (phase: KillPhase): Promise<void> => {
			if (isWindows && child.pid && child.pid > 0) {
				const taskkill = `${process.env.SystemRoot ?? "C:\\Windows"}\\System32\\taskkill.exe`;
				try {
					await new Promise<void>((done) => {
						const killer = spawn(
							taskkill,
							["/F", "/T", "/PID", String(child.pid)],
							{
								shell: false,
								windowsHide: true,
								stdio: "ignore",
							},
						);
						killer.once("close", () => done());
						killer.once("error", () => {
							// E4: a throw HERE would leave the EventEmitter as an
							// uncaught exception, not a rejection.
							if (!trySend(() => child.kill("SIGKILL"))) noteKillFailure(phase);
							done();
						});
					});
				} catch {
					if (!trySend(() => child.kill("SIGKILL"))) noteKillFailure(phase);
				}
			} else if (posixProcessGroup && ownsChildPid) {
				// #2026: signal the whole process group. Grandchildren spawned
				// by the tool share its group, so one signal reaches the whole
				// tree; a negative-pid ESRCH means it already exited.
				const pgid = -(child.pid as number);
				// #3375 round 3 (M3384-2): through the one sink, like every other
				// send. A second ad-hoc `try`/`catch` here would be a rival
				// signal-safety mechanism inside the same teardown — the shape this
				// change deleted four of — and a later edit to this branch would not
				// inherit `trySend`'s total send or its failure accounting.
				// `trySend` returning false here is ORDINARY, not a failure: #2026's
				// negative-pid ESRCH means the group already exited, so the direct
				// child below is the normal fallback and nothing is recorded. Only
				// the last-resort send can fail the teardown.
				if (!trySend(() => process.kill(pgid, "SIGTERM"))) {
					if (!trySend(() => child.kill("SIGTERM"))) noteKillFailure(phase);
				}
				// #2027 round-1: gate the SIGKILL escalation on GROUP liveness,
				// not direct-child death - a tool can exit instantly on SIGTERM
				// while a SIGTERM-hardy grandchild keeps the group alive. The
				// timer stays REF'D for group mode (max 1s tail after resolve):
				// it is the only backstop for this group once finalize deletes
				// the pid from lifetimeState.
				escalationTimer = setTimeout(() => {
					// The WHOLE body, not just the signal: this runs in a bare
					// timer callback, where any throw is an uncaught exception.
					const escalated = trySend(() => {
						let groupAlive = true;
						try {
							process.kill(pgid, 0);
						} catch {
							groupAlive = false;
						}
						if (!groupAlive) return;
						teardownEscalated = true;
						logLatency({
							type: "phase",
							phase: "spawn_group_kill_escalation",
							filePath: "",
							durationMs: 0,
							metadata: { pgid: child.pid },
						});
						// Through the sink too (#3375 r3 / M3384-2): one vocabulary
						// for every send in this function. A false here is ORDINARY
						// — the group raced its own exit — so it is deliberately not
						// escalated to `noteKillFailure`; the enclosing `trySend`
						// already guarantees nothing escapes this timer callback.
						trySend(() => process.kill(pgid, "SIGKILL"));
					});
					if (!escalated) noteKillFailure(phase);
				}, 1000);
			} else {
				// E2/E3. This branch runs whenever `/proc` cannot prove pid
				// ownership — every macOS host, and any Linux host with an
				// unreadable `/proc` — so it is not a hypothetical path.
				if (!trySend(() => child.kill("SIGTERM"))) noteKillFailure(phase);
				escalationTimer = setTimeout(() => {
					if (closed) return;
					teardownEscalated = true;
					if (!trySend(() => child.kill("SIGKILL"))) noteKillFailure(phase);
				}, 1000);
			}
		};

		// Handle abort signal
		const onAbort = () => {
			aborted = true;
			if (!killed && !child.killed) {
				killed = true;
				void killTree("abort");
			}
		};
		abortSignal?.addEventListener("abort", onAbort, { once: true });

		// Output-cap kills are awaited by finalize() below, just like
		// timeout/abort kills. An armed, unmatched streaming matcher is the one
		// exception: retention remains bounded, but the caller's timeout is the
		// bound while the child gets a chance to emit its rescue line.
		let killPromise: Promise<void> | undefined;
		const stopForOutputLimit = (): void => {
			const waitingForStreamingMatch =
				streamingMatcher !== undefined && !streamingMatch;
			if (
				outputTruncated &&
				!waitingForStreamingMatch &&
				!killed &&
				!child.killed
			) {
				killedForOutputCap = true;
				killed = true;
				killPromise = killTree("output-cap");
			}
		};

		// #3375: one bounded, counted ledger row per command label the moment the
		// cap first bites - the crash report named no command, no byte count and
		// no cap value, so nothing in it could identify the chatty producer.
		// `incrementDegradationCount` keeps one latest-reason entry per subject
		// with an exact tally and writes durable rows only at powers of two, so a
		// tool that trips the cap on every dispatch cannot flood the sink.
		const recordOutputCapTrip = (): void => {
			incrementDegradationCount({
				kind: "spawn-output-cap-truncated",
				subject: resourceLabel,
				reason: `retained output reached the ${maxOutputBytes}-byte ${
					capFromCaller ? "caller" : "default"
				} cap after ${observedOutputBytes} bytes; child ${
					killedForOutputCap ? "terminated" : "left running"
				}`,
				metadata: {
					capBytes: maxOutputBytes,
					capSource: capFromCaller ? "caller" : "default",
					observedBytes: observedOutputBytes,
					killed: killedForOutputCap,
				},
			});
		};

		// #3375: the fault path for a chunk handler that threw. Every statement
		// here is total by construction - plain assignments, a ledger call that
		// swallows its own failures, and `killTree()`, which is `async` so a
		// synchronous fault inside it becomes a rejected promise rather than a
		// throw - because a throw raised HERE would escape the same way the
		// original RangeError did.
		const failOutputHandler = (stream: OutputStream, error: Error): void => {
			outputHandlerFailed = true;
			// Retention is over. The bytes already in `stdout`/`stderr` stay as
			// the bounded output: nothing renders from the retained head/tail
			// again, because the re-entry guard returns before that can happen.
			// That is also why `truncationStream` is deliberately NOT set here —
			// only `renderOutput` reads it, and nothing renders after a fault, so
			// the assignment was mutation-inert (removing it reds nothing).
			outputTruncated = true;
			incrementDegradationCount({
				kind: "spawn-output-handler-fault",
				subject: resourceLabel,
				reason: `${stream} chunk handling threw ${error.name} after ${observedOutputBytes} bytes; retention stopped and the child was terminated`,
				metadata: {
					stream,
					error: error.name,
					capBytes: maxOutputBytes,
					observedBytes: observedOutputBytes,
				},
			});
			if (!killed && !child.killed) {
				killedForOutputCap = true;
				killed = true;
				killPromise = killTree("handler-fault");
			}
		};

		// Collect output
		child.stdout?.setEncoding("utf-8");
		child.stderr?.setEncoding("utf-8");
		// #3375: a throw raised inside a stream `data` handler is delivered to
		// the process, not to the caller awaiting this spawn - no `try`/`catch`
		// around `await safeSpawnAsync(...)` can contain it, which is why a
		// `RangeError: Invalid string length` from `appendOutput` terminated the
		// Pi host on 2026-09-22. Every statement the handler runs lives inside
		// this `try`, so ANY fault in the retention path (not just that one
		// RangeError) becomes the bounded output-cap result the caller already
		// knows how to read.
		const onOutputChunk = (
			stream: OutputStream,
			data: string | Buffer,
		): void => {
			if (outputHandlerFailed) return;
			try {
				observedOutputBytes += Buffer.byteLength(data);
				const wasTruncated = outputTruncated;
				matchStreamingChunk(stream, data);
				if (stream === "stdout") stdout = appendOutput(stream, stdout, data);
				else stderr = appendOutput(stream, stderr, data);
				if (outputTruncated) refreshRetainedOutputs();
				stopForOutputLimit();
				if (!wasTruncated && outputTruncated) recordOutputCapTrip();
				rearmIdleGrace?.();
			} catch (error) {
				failOutputHandler(stream, toError(error));
			}
		};
		child.stdout?.on("data", (data) => onOutputChunk("stdout", data));
		child.stderr?.on("data", (data) => onOutputChunk("stderr", data));

		// #1673 review round 3 (F2): registered HERE, at spawn time, alongside
		// the other handlers above — not inside `waitForPipeIdle`. Real Node
		// emits `close` a fraction of a millisecond after `exit` (both fire in
		// the same "process exit" turn, well before any microtask), so a
		// listener attached inside `waitForPipeIdle` — which `finalize` only
		// reaches after `await killPromise`, at least one microtask later — is
		// always attaching to an event that has already happened. That's why
		// the round-2 `child.on("close", finish)` placed inside
		// `waitForPipeIdle` never actually caught a real spawn's `close` early:
		// every real call still paid the full grace window. Capturing the
		// boolean here, before any await, means `waitForPipeIdle` can check
		// "did close already happen" synchronously the moment it runs.
		let closeSeen = false;
		// #2010: WHEN death was observed - the stop-clock for teardown evidence
		// and the discriminator for its outcome. A close that predates the
		// budget-expired kill means the child exited on its own ("exited"), no
		// matter that the timer callback raced and armed a kill anyway.
		let closedAtMs: number | undefined;
		child.on("close", () => {
			closeSeen = true;
			closedAtMs ??= Date.now();
		});

		// Timeout handling - KILL the process, don't just abandon it
		const timeoutId = setTimeout(() => {
			timedOut = true;
			if (!killed && !child.killed) {
				killed = true;
				teardownStartedAtMs = Date.now();
				killPromise = killTree("timeout");
			}
		}, timeout);

		// #620: stop the poll and log peak/average CPU%+RSS for this invocation
		// into the existing per-runner latency.log phase entries — best-effort,
		// wrapped so a logging hiccup can never affect the resolved SpawnResult.
		const finishResourceUsage = (): SpawnResourceUsage | undefined => {
			const summary = usageSampler.stop();
			if (!summary) return undefined;
			try {
				logLatency({
					type: "phase",
					phase: "spawn_resource_usage",
					filePath: "",
					durationMs: 0,
					metadata: {
						command: resourceLabel,
						...summary,
					},
				});
			} catch {
				// best-effort logging only
			}
			return summary;
		};

		// #1656: wait for stdout/stderr to fall idle after exit instead of
		// waiting for Node's "close" event (see the constants' doc comment
		// above). Resolves immediately if the child has no pipes to drain.
		//
		// These timers stay REF'D, matching `timeoutId`/`escalationTimer`
		// elsewhere in this function: the caller's own settlement depends on
		// them firing, so unref'ing would let a short-lived host process (a
		// one-shot CLI whose only other in-flight work was this spawn) exit
		// the event loop before `finish` ever runs — silently abandoning this
		// promise instead of merely leaking a handle. Both paths to `finish`
		// clear both timers, so nothing outlives settlement either way.
		const waitForPipeIdle = (): Promise<void> => {
			if (!child.stdout && !child.stderr) return Promise.resolve();
			// #1673 review round 3 (F2): `close` fires a fraction of a
			// millisecond after `exit` for a real Node child — well before
			// `finalize`'s `await killPromise` ever yields, i.e. before this
			// function is even called. By the time we get here, `closeSeen`
			// (set by the listener registered at spawn time, above) already
			// reflects reality for the overwhelming majority of real spawns:
			// nothing is holding this child's stdio open, so don't pay out the
			// 100ms grace window for a signal that already arrived.
			if (closeSeen) return Promise.resolve();
			return new Promise((finishIdleWait) => {
				let settled = false;
				let graceTimer: ReturnType<typeof setTimeout> | undefined;
				const capTimer: ReturnType<typeof setTimeout> = setTimeout(() => {
					finish();
				}, EXIT_PIPE_IDLE_MAX_WAIT_MS);
				const finish = (): void => {
					if (settled) return;
					settled = true;
					rearmIdleGrace = undefined;
					if (graceTimer) clearTimeout(graceTimer);
					clearTimeout(capTimer);
					// Optional chaining, not a bare call: `child` is a real Node
					// ChildProcess (always an EventEmitter, always has this) in
					// production, but several existing test doubles across the
					// suite fake stdio-bearing children as plain objects with only
					// the handful of methods (`on`, `kill`, ...) their scenario
					// needs — no `removeListener`. Skipping cleanup on those is
					// harmless (the fake is torn down with the test either way);
					// crashing here from inside a timer callback is not: it would
					// throw before `finishIdleWait()` runs, hanging every caller's
					// `safeSpawnAsync` promise (#1673 review round 2 caught this
					// live in tests/clients/installer/version-drift.test.ts).
					child.removeListener?.("close", finish);
					finishIdleWait();
				};
				// The `closeSeen` fast-path above catches the common case (close
				// already happened by the time we get here). This listener is
				// the fallback for the rare case where `close` genuinely lands
				// DURING the wait — e.g. a child whose stdio takes a beat
				// longer than usual to release, but still well under the grace
				// window. `close` is a stronger signal than "no data for
				// EXIT_PIPE_IDLE_GRACE_MS", so finishing on it here still beats
				// waiting out the timer. The anti-hang property is untouched
				// either way: a daemonized descendant holding the pipe open is
				// EXACTLY the case where `close` never fires at all, so the
				// grace/cap timers still bound that case as before.
				child.on("close", finish);
				rearmIdleGrace = (): void => {
					if (graceTimer) clearTimeout(graceTimer);
					graceTimer = setTimeout(finish, EXIT_PIPE_IDLE_GRACE_MS);
				};
				rearmIdleGrace();
			});
		};

		// Process completion
		//
		// #1656 x #1651/#1670: finalize off BOTH `exit` and `close`, not just
		// one — each covers a shape the other misses.
		//   - `exit` is what unblocks the #1656 hang: a daemonized descendant
		//     that inherited our stdout/stderr pipe can hold that fd open
		//     forever, so `close` (which waits for every fd referencing the
		//     child to release) never fires even though the child we spawned
		//     is long dead. `exit` always fires once the child itself exits,
		//     independent of who still holds its pipes.
		//   - `close` is still wired because a child that never actually
		//     launched (bad binary, EACCES, ...) gets NO `exit` event at all —
		//     Node only emits `error` then `close(code<0, null)` for that
		//     shape (#1651/#1670's shape guard below decides from exactly
		//     this). `exit`-only would make that guard unreachable.
		// Whichever fires first drives `finalize`; `settled` (distinct from
		// `resolved`, which `finalize` itself owns) stops the second event
		// from dispatching a redundant, concurrently-racing `finalize` call —
		// double-invoking it would double-run `waitForPipeIdle` and
		// `finishResourceUsage` against the same child.
		let settled = false;
		const onChildSettle = (
			code: number | null,
			signal: NodeJS.Signals | null,
		): void => {
			if (settled || resolved) return;
			settled = true;
			closed = true;
			clearTimeout(timeoutId);
			abortSignal?.removeEventListener("abort", onAbort);
			if (child.pid) lifetimeState.pids.delete(child.pid);
			void finalize(code, signal);
		};

		const finalize = async (
			code: number | null,
			signal: NodeJS.Signals | null,
		): Promise<void> => {
			// Belt, not the decision: whichever path settles `resolved` FIRST
			// wins. A healthy run's outcome must never be discarded by a late,
			// unrelated 'error' (e.g. a post-exit kill() that itself failed
			// with EPERM, #1651 review F4) — so this only bails when something
			// else has ALREADY resolved, never on `error` merely having fired.
			await killPromise;
			if (resolved) return;
			// #1109: the child has exited - clear the non-Windows escalation
			// timer so it doesn't linger as a ref'd handle. #2027 EXCEPTION:
			// in POSIX group mode the timer is the liveness-gated SIGKILL
			// backstop for SIGTERM-hardy grandchildren; it stays armed and
			// self-cleans within 1s of firing (max 1s ref'd tail).
			if (escalationTimer && !posixProcessGroup) {
				clearTimeout(escalationTimer);
			}
			// #1673 review F1: latch the verdict as DECIDED here, before the
			// idle-pipe wait — not after it. `code`/`signal`/`timedOut`/`aborted`
			// are already fixed by this point (they don't change during the
			// wait), so nothing below depends on staying unresolved across it.
			// Leaving `resolved` false across the wait would reopen the exact
			// race #1651 review F4 closed: a late, unrelated 'error' (e.g. a
			// post-exit kill() failing with EPERM) landing inside the
			// idle-grace window (bounded, but up to EXIT_PIPE_IDLE_MAX_WAIT_MS)
			// would steal an already-decided healthy verdict. Pre-#1656 that
			// race window was one microtask — the gap between `close` firing
			// and `resolve()` being called synchronously in the same handler.
			// This closes the window back down to that same shape instead of
			// widening it to the whole wait.
			resolved = true;
			await waitForPipeIdle();
			const resourceUsage = finishResourceUsage();

			const outputInfo = {
				...(outputTruncated ? { outputTruncated: true } : {}),
				...(killedForOutputCap ? { killedForOutputCap: true } : {}),
				...(killFailed ? { killFailed: true } : {}),
			};
			const streamingMatchInfo = streamingMatch ? { streamingMatch: true } : {};
			// #1816: surface the signal name as a field on every path where one
			// exists, so callers can NAME it instead of scraping `error.message`.
			const signalInfo = signal ? { signal } : {};
			if (timedOut) {
				const cause = new Error(
					`Process timed out after ${timeout}ms (killed with ${signal || "SIGTERM"})`,
				);
				// #2010: teardown evidence lives ONLY on the timeout path - it
				// describes how long the tree took to die after the budget
				// expired, and how it died ("exited" = the child beat the signal;
				// "killed-by-signal" / "escalate-kill" = how WE ended it).
				const timeoutTeardown = resolveTeardownOutcome({
					killStartedAtMs: teardownStartedAtMs,
					deathObservedAtMs: closedAtMs,
					escalated: teardownEscalated,
				});
				resolve({
					stdout,
					stderr,
					status: null,
					error: cause,
					failure: "timeout",
					...signalInfo,
					...(timeoutTeardown && { timeoutTeardown }),
					spawnFailure: new SpawnFailureError("timeout", cause.message, cause),
					...outputInfo,
					...streamingMatchInfo,
					resourceUsage,
				});
			} else if (aborted) {
				const cause = new Error("Spawn aborted");
				resolve({
					stdout,
					stderr,
					status: null,
					error: cause,
					failure: "aborted",
					...signalInfo,
					spawnFailure: new SpawnFailureError("killed", cause.message, cause),
					...outputInfo,
					...streamingMatchInfo,
					resourceUsage,
				});
			} else if (signal) {
				const cause = new Error(`Process killed by signal: ${signal}`);
				resolve({
					stdout,
					stderr,
					status: null,
					error: cause,
					failure: "signal",
					...signalInfo,
					spawnFailure: new SpawnFailureError("killed", cause.message, cause),
					...outputInfo,
					...streamingMatchInfo,
					resourceUsage,
				});
			} else if (code === null || code < 0) {
				// #1651 review F3: a real completed process never exits with a
				// null or negative code (Node reports the negated libuv/errno for
				// a child that never launched — e.g. ENOENT: -2 on Linux, -4058
				// on Windows). This decides from that SHAPE alone, independent of
				// whether/when 'error' has fired — Node's docs leave the
				// 'error'/'close' ordering for a failed spawn unspecified, and a
				// same-microtask re-check (the #1651 first-round fix) still loses
				// if 'error' lands a tick later via setImmediate/nextTick.
				// Reuse `pendingSpawnError` when 'error' already landed (a more
				// informative Error — ENOENT vs EACCES vs other); otherwise
				// synthesize an ENOENT-shaped one so a genuinely missing tool is
				// never read as a clean, answered run.
				const cause = pendingSpawnError ?? synthesizeEnoentError(command);
				const spawnFailure = await classifySpawnFailure(cause, {
					command,
					cwd: options?.cwd,
				});
				resolve({
					stdout,
					stderr,
					status: code,
					error: cause,
					failure: "spawn",
					spawnFailure,
					...outputInfo,
					...streamingMatchInfo,
					resourceUsage,
				});
			} else {
				resolve({
					stdout,
					stderr,
					status: code,
					...outputInfo,
					...streamingMatchInfo,
					resourceUsage,
				});
			}
		};

		child.on("exit", onChildSettle);
		child.on("close", onChildSettle);

		child.on("error", (err) => {
			// Capture unconditionally — even when `close` already resolved, this
			// keeps the most recent Error available for anyone reading state
			// mid-flight, and costs nothing (the assignment, not a resolve).
			pendingSpawnError = err;
			// A completed run's own verdict must never be downgraded by an
			// unrelated LATE error (#1651 review F4 — e.g. a post-exit kill()
			// failing with EPERM after `close(0, null)` already answered).
			if (resolved) return;
			resolved = true;
			closed = true;
			clearTimeout(timeoutId);
			abortSignal?.removeEventListener("abort", onAbort);
			// #2027: group-mode timer stays armed as the grandchild backstop.
			if (escalationTimer && !posixProcessGroup) {
				clearTimeout(escalationTimer);
			}
			if (child.pid) lifetimeState.pids.delete(child.pid);
			const resourceUsage = finishResourceUsage();
			let failure: SpawnFailureKind = "spawn";
			if (aborted) failure = "aborted";
			else if (timedOut) failure = "timeout";
			const controlFailure = aborted
				? new SpawnFailureError("killed", err.message, err)
				: timedOut
					? new SpawnFailureError("timeout", err.message, err)
					: undefined;
			const finish = (spawnFailure: SpawnFailureError): void =>
				resolve({
					stdout,
					stderr,
					status: null,
					error: err,
					failure,
					spawnFailure,
					...(outputTruncated ? { outputTruncated: true } : {}),
					...(killedForOutputCap ? { killedForOutputCap: true } : {}),
					...(killFailed ? { killFailed: true } : {}),
					...(streamingMatch ? { streamingMatch: true } : {}),
					resourceUsage,
				});
			if (controlFailure) finish(controlFailure);
			else {
				void classifySpawnFailure(err, { command, cwd: options?.cwd }).then(
					finish,
				);
			}
		});
	});
}

/**
 * Run multiple commands concurrently with limited concurrency.
 *
 * This prevents resource contention when running many linters.
 * Uses async spawn with concurrency limiting built-in.
 *
 * @example
 * const results = await safeSpawnBatch([
 *   { command: "biome", args: ["check", "file.ts"] },
 *   { command: "ruff", args: ["check", "file.py"] },
 * ], 3); // Max 3 concurrent
 */
export async function safeSpawnBatch(
	commands: Array<{
		command: string;
		args: string[];
		options?: SafeSpawnOptions;
	}>,
	concurrency = 3,
): Promise<SpawnResult[]> {
	const results: SpawnResult[] = [];

	// Process in batches to limit concurrent processes
	for (let i = 0; i < commands.length; i += concurrency) {
		const batch = commands.slice(i, i + concurrency);
		const batchResults = await Promise.all(
			batch.map(({ command, args, options }) =>
				safeSpawnAsync(command, args, options),
			),
		);
		results.push(...batchResults);
	}

	return results;
}

/**
 * Check if a command is available in PATH (async version).
 * Callers may supply their own scoped environment for both finder and lookup.
 */
export async function isCommandAvailableAsync(
	command: string,
	env?: NodeJS.ProcessEnv,
): Promise<boolean> {
	const finder = process.platform === "win32" ? "where" : "which";
	const result = await safeSpawnAsync(finder, [command], {
		timeout: 5000,
		env: env ?? process.env,
	});
	return result.status === 0 && !result.error;
}

/**
 * Find the full path to a command (async version).
 * Callers may supply their own scoped environment for both finder and lookup.
 */
export async function findCommandAsync(
	command: string,
	env?: NodeJS.ProcessEnv,
): Promise<string | null> {
	const finder = process.platform === "win32" ? "where" : "which";
	const result = await safeSpawnAsync(finder, [command], {
		timeout: 5000,
		env: env ?? process.env,
	});

	if (result.status !== 0 || result.error) return null;

	// Take the first line (first match). `where` ends lines with CRLF.
	return result.stdout.trim().split(/\r?\n/)[0] || null;
}

// ============================================================================
// SYNC VERSION (Deprecated - Blocking, for backward compatibility)
// ============================================================================

/**
 * ⚠️ DEPRECATED: Use safeSpawnAsync instead.
 *
 * This blocks the entire Node.js event loop until the process exits.
 * If the process hangs, pi will freeze.
 *
 * Kept for backward compatibility during migration (today's only caller:
 * `test-runner-client.ts`'s synchronous pytest-on-PATH probe, called from a
 * sync detection path with many sync callers/tests — not a trivial async
 * migration, see #817 follow-up discussion).
 *
 * #817: the Windows branch used to build a `cmd.exe`/`shell:true` command
 * line from unvalidated caller input (CodeQL #17/#18/#19), same unsoundness
 * as the async version had. It now shares the exact same resolution/
 * validation seams as `safeSpawnAsync` — `resolveWindowsCommand` (cached
 * PATH+PATHEXT walk), direct `spawnSync(resolvedPath, args, { shell: false })`
 * for `.exe`/`.com`, the pinned-cmd.exe wrapper + `findCmdUnsafeValue`
 * rejection for `.cmd`/`.bat`, and a synthesized ENOENT when unresolvable.
 * No `shell: true` anywhere.
 */
export function safeSpawn(
	command: string,
	args: string[],
	options?: SafeSpawnOptions,
): SpawnResult {
	const spawnEnv = getSpawnEnvironment(options?.env, options?.stripNpmConfig);
	if (process.platform === "win32") {
		// See the matching comment in safeSpawnAsync: the child's cwd doesn't
		// need OUR validation (Windows resolves it natively), so an unprovable
		// drive-relative cwd falls back to the raw value instead of failing the
		// whole spawn before ever attempting it (#1201). Command resolution
		// below intentionally still uses the ORIGINAL raw cwd and fails closed
		// for PATH entries that would need it to be canonical.
		// See safeSpawnAsync for why there is no `?? process.cwd()` third arm.
		const spawnCwd =
			resolveEffectiveWindowsCwd(options?.cwd, spawnEnv) ?? options?.cwd;
		const resolved = resolveWindowsCommand(command, options?.cwd, spawnEnv);
		if (!resolved) {
			const error = synthesizeEnoentError(command);
			return {
				stdout: "",
				stderr: "",
				status: null,
				error,
				failure: "spawn",
				spawnFailure: classifySpawnFailureSync(error, {
					command,
					cwd: options?.cwd,
				}),
			};
		}

		let spawnCmd: string;
		let spawnArgs: string[];
		let windowsVerbatimArguments = false;

		if (resolved.ext === ".cmd" || resolved.ext === ".bat") {
			// Validate the value that actually gets interpolated into the /c
			// line — the RESOLVED path, not the caller's original (possibly
			// extensionless) `command` string — plus every arg.
			const unsafeValue = findCmdUnsafeValue(resolved.resolvedPath, args);
			if (unsafeValue !== undefined) {
				const error = new Error(
					`Refusing to spawn "${resolved.resolvedPath}" via cmd.exe: ` +
						`${JSON.stringify(unsafeValue)} contains a character ("` +
						`, %, !, or CR/LF) that cannot be safely escaped on a ` +
						`cmd.exe /c command line (CWE-78, #817). Rename/quote the ` +
						"value or invoke the tool without going through cmd.exe.",
				);
				return {
					stdout: "",
					stderr: "",
					status: null,
					error,
					failure: "spawn",
					spawnFailure: classifySpawnFailureSync(error, {
						command,
						cwd: options?.cwd,
					}),
				};
			}
			spawnCmd = `${process.env.SystemRoot ?? "C:\\Windows"}\\System32\\cmd.exe`;
			spawnArgs = [
				"/d",
				"/s",
				"/c",
				buildWindowsShellCommand(resolved.resolvedPath, args),
			];
			windowsVerbatimArguments = true;
		} else {
			ensureUtf8ConsoleCodePageOnce();
			spawnCmd = resolved.resolvedPath;
			spawnArgs = args;
		}

		const result = spawnSync(spawnCmd, spawnArgs, {
			...(options as SpawnOptions),
			cwd: spawnCwd,
			env: spawnEnv,
			encoding: "utf-8",
			shell: false,
			windowsHide: true,
			windowsVerbatimArguments,
		});

		const spawnFailure = result.error
			? classifySpawnFailureSync(result.error, { command, cwd: options?.cwd })
			: undefined;
		return {
			stdout: result.stdout?.toString() || "",
			stderr: result.stderr?.toString() || "",
			status: result.status,
			error: result.error,
			...(spawnFailure ? { failure: "spawn" as const, spawnFailure } : {}),
		};
	}

	const result = spawnSync(command, args, {
		...(options as SpawnOptions),
		// Explicit override, not just the spread above: `options.env` alone
		// would otherwise reach the child as a full replacement (no
		// process.env merge, no PATH) instead of the merged environment the
		// resolver/Windows branch above both use (#1201) — the module's
		// "resolver and child receive the same merged environment" invariant
		// must hold on every platform, not just Windows.
		env: spawnEnv,
		encoding: "utf-8",
		shell: false,
		windowsHide: true,
	});

	const spawnFailure = result.error
		? classifySpawnFailureSync(result.error, { command, cwd: options?.cwd })
		: undefined;
	return {
		stdout: result.stdout?.toString() || "",
		stderr: result.stderr?.toString() || "",
		status: result.status,
		error: result.error,
		...(spawnFailure ? { failure: "spawn" as const, spawnFailure } : {}),
	};
}

/**
 * Check if a command is available in PATH (sync version - deprecated)
 * @deprecated Use isCommandAvailableAsync
 */
export function isCommandAvailable(command: string): boolean {
	const result = safeSpawn(
		process.platform === "win32" ? "where" : "which",
		[command],
		{ timeout: 5000 },
	);
	return result.status === 0;
}

/**
 * Find the full path to a command (sync version - deprecated)
 * @deprecated Use findCommandAsync
 */
export function findCommand(command: string): string | null {
	const finder = process.platform === "win32" ? "where" : "which";
	const result = safeSpawn(finder, [command], { timeout: 5000 });

	if (result.status !== 0) return null;

	return result.stdout.trim().split(/\r?\n/)[0] || null;
}

clients/test-runner-client.ts:
/**
 * Test Runner Client for pi-lens
 *
 * Detects test files and runs them on write/edit to provide
 * immediate test feedback to the AI agent.
 *
 * Supports: vitest, jest, pytest, go, cargo, dotnet, gradle, maven, rspec,
 * minitest, phpunit, mix (extensible to more)
 *
 * Design: File-level targeted testing — only runs tests for the
 * specific file being edited, not the entire suite.
 */

import { createHash } from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";
import { BoundedFifoMap } from "./bounded-cache.js";
import { emitBounded } from "./bounded-telemetry.js";
import {
	LEDGER_FIELD_MAX,
	recordDegradationOnce,
} from "./degradation-ledger.js";
import { minimatch } from "./deps/minimatch.js";
import { createSubsystemLogger } from "./extension-log.js";
import { detectFileKind, type FileKind } from "./file-kinds.js";
import { detectFileRole } from "./file-role.js";
import { resolveLanguageRootForFile } from "./language-profile.js";
import {
	findGlobalBinary,
	findLocalBinAt,
	localBinPath,
} from "./package-manager.js";
import { getIsolatedNpxSpawnOptions } from "./tool-probe.js";
import { PathKeyedMap } from "./path-keyed-map.js";
import {
	augmentPythonEnvironment,
	detectPythonEnvironment,
} from "./python-environment.js";
import {
	findNearestMarkerRootDetailed,
	type MarkerRootResult,
	isRealGitMarker,
	isUnderDir,
	normalizeEphemeralMapKey,
	normalizeMapKey,
	pathsEqual,
	toPosix,
} from "./path-utils.js";
import { findNearestDirWithAnyBasename } from "./workspace-topology.js";
import { isMeasuredDuration, toMeasuredDurationMs } from "./run-duration.js";
import { safeSpawn, safeSpawnAsync } from "./safe-spawn.js";
import { stripAnsi } from "./sanitize.js";
import { resolveGitCheckout } from "./review-graph/git-identity.js";
import { resolveToolCwd } from "./tool-cwd.js";

// --- Types ---

export interface TestResult {
	file: string; // test file that was run
	sourceFile: string; // the file the agent edited
	runner: string; // "vitest", "jest", "pytest"
	passed: number;
	failed: number;
	skipped: number;
	failures: TestFailure[];
	/**
	 * #1479: elapsed run time in ms, or `undefined` when this run was not
	 * measured at all.
	 *
	 * The two states are different facts and a reader must be able to tell
	 * them apart. A present `0` is a MEASUREMENT — pytest really does print
	 * `in 0.00s`, and a suite whose `startTime` equals its `endTime` really did
	 * run in under a millisecond. `undefined` means no runner-reported figure
	 * was found: no suite timestamps in the payload, an unrecognised summary
	 * line, a runner error, or nothing run at all.
	 *
	 * Producers must not substitute `0` for "did not measure". That is the
	 * defect #1452 removed from the JSON path and #1479 removes from the log.
	 *
	 * #1480: `run-duration.ts` holds this contract in executable form.
	 * `toMeasuredDurationMs` normalises a freshly parsed figure into it,
	 * `isMeasuredDuration` tests it, and `formatRunDurationMs` renders it, so
	 * a reader does not have to find this comment to get the rule right.
	 */
	duration?: number; // ms; absent = not measured
	error?: string; // if runner itself failed
	/**
	 * Set when the run was deliberately not started (#3871 r2): the target's
	 * checkout root has no install of its own for this runner, so running it
	 * would fetch an unpinned tool or use the wrong environment. Not a pass and
	 * not a failure; the turn-end consumer counts it and publishes nothing.
	 */
	notRun?: "no-runner-install";
}

/**
 * #2532: the ONE classification seam for "this `TestResult` carries NO
 * counted failure the agent needs to fix, even though the runner also
 * reported an `error`" — i.e. `failed === 0 && !!error`. This is NOT "the
 * suite never started": a runner can report BOTH counted failures and an
 * error (pytest exit 2 "Interrupted" after `2 failed, 1 passed` already
 * printed — `parsePytestOutput` sets `error` from the exit code
 * independently of the parsed counts, review round 1 S2). The rule is
 * exactly `failed === 0`, nothing about `error`'s presence or cause: a
 * result with counted failures stays blocking even when `error` is also
 * set (`testResultToProjectDiagnostics`/`formatResult` still mention the
 * error in that case, they just don't let it downgrade the verdict).
 *
 * `hasRealFailure`/`runnerErrorOnly` (`runtime-turn.ts`, #2522) key off the
 * exact same fact for the turn-end delivery framing — a batch made
 * entirely of `isRunnerErrorResult` results is advisory, one containing
 * even one counted failure keeps "fix before continuing". Three more
 * surfaces route through this SAME predicate instead of re-deriving it
 * (review round 1 S1's class sweep), so the identical `TestResult` cannot
 * classify differently across them: `testResultToProjectDiagnostics`
 * (`lens_diagnostics mode=full`), the `--lens-guard` merge call in
 * `handleTurnEnd`, and `TestRunnerClient.formatResult`/the turn-end dbg
 * summary (both in this file / `runtime-turn.ts`).
 *
 * Two call sites intentionally test the COMPLEMENT (a truly clean result,
 * no counted failure AND no error) rather than this predicate, and are not
 * a missed fourth spelling: `runtime-turn.ts`'s `cleanFiles` filter
 * (`--lens-guard`'s clear-blocker list) and `testResultToProjectDiagnostics`'s
 * own early "nothing to report" return. Both need "genuinely clean", which
 * `!isRunnerErrorResult(result)` cannot express (it is also true for a
 * counted failure).
 */
export function isRunnerErrorResult(result: TestResult): boolean {
	return result.failed === 0 && !!result.error;
}

export interface TestFailure {
	name: string; // test name
	message: string; // failure message
	location?: string; // "file.ts:42"
	stack?: string; // abbreviated stack trace
}

// Runner detection: config file → runner name
export interface RunnerConfig {
	configFiles: string[];
	/**
	 * #2870: the file kinds this runner can run, in `file-kinds.ts`'s
	 * vocabulary — the ONE gate that decides whether a runner may be handed
	 * an edited file. Before this, `detectRunner` answered from the project
	 * root's config files alone, so in a repo carrying both a `go.mod` and a
	 * Gradle build every `.java` file went to whichever runner is declared
	 * first in this table (`go test ./src/test/java/...` → `FAIL [setup
	 * failed]` on every Java edit).
	 *
	 * The kind check is the gate, NOT the resolved language root (AGENTS.md
	 * defect shape 39): a `.java` file in a go-only repo resolves to the
	 * workspace root — where `go.mod` lives — and must still get no target.
	 * A kind no entry claims (markdown, yaml, an unknown extension) has no
	 * runner, which is what stops a `README.md` under `docs/tests/` from
	 * becoming its own test target.
	 */
	kinds: readonly FileKind[];
	/**
	 * #2871: markers that anchor the CHILD's working directory, when they are
	 * not this runner's own `configFiles` (the default).
	 *
	 * A file-scoped runner names the file or its package in `args`, so running
	 * it from the nearest directory carrying its manifest is exactly right —
	 * `go test ./internal/lightning` only resolves from the module that owns
	 * `go.mod`. A WHOLE-PROJECT runner names nothing: moving its cwd changes
	 * WHICH project is built. `gradle` launches the literal `./gradlew`, so a
	 * module carrying `build.gradle.kts` but no wrapper would fail with `spawn
	 * ./gradlew ENOENT` — it anchors on its LAUNCHER: a module that carries
	 * its own wrapper is a self-contained build and runs there, anything else
	 * walks up to the build that owns the wrapper, which is what it did
	 * before #2871. `maven` must NOT launcher-anchor (#2944): its command is
	 * the PATH binary `mvn`, which never reads `mvnw`, so wrapper-only
	 * markers left a wrapper-less project with no anchor at all and dropped
	 * the child on the dispatch root instead of the module's `pom.xml`.
	 * Maven keeps the default and anchors on the module manifest; a wrapper
	 * is never a reason to anchor elsewhere, since `mvn` does not invoke it
	 * and a wrapper without a `pom.xml` beside it has nothing for `mvn` to
	 * build. `tests/clients/test-runner-spawn-cwd.test.ts` derives this
	 * contract over the whole `RUNNERS` table.
	 */
	spawnCwdMarkers?: readonly string[];
	command: string;
	// Name of the binary in node_modules/.bin (and every package manager's
	// global bin dir) — defaults to the runner key. Must match the ACTUAL
	// binary name resolution looks for (e.g. rspec's real binary is "bundle",
	// not "rspec" — see the rspec entry below), because `stripWrapperArgs`
	// only drops args()'s leading element(s) when they match this name (see
	// its doc comment for the exact wrapper-convention rule it applies).
	binName?: string;
	args: (testFile: string, cwd: string) => string[];
	parseJson: boolean;
}

// Discovery table; exported so the #2928 parity test enumerates its conventions.
export const SOURCE_TO_TEST_PATTERNS: Array<{
	ext: string;
	testExts: string[];
	dirs: string[];
}> = [
	{
		ext: ".ts",
		testExts: [".test.ts", ".spec.ts"],
		dirs: ["__tests__", "tests", ".", "__tests__"],
	},
	{
		ext: ".tsx",
		testExts: [".test.tsx", ".spec.tsx"],
		dirs: ["__tests__", "tests", ".", "__tests__"],
	},
	{
		ext: ".js",
		testExts: [".test.js", ".spec.js"],
		dirs: ["__tests__", "tests", ".", "__tests__"],
	},
	{
		ext: ".jsx",
		testExts: [".test.jsx", ".spec.jsx"],
		dirs: ["__tests__", "tests", ".", "__tests__"],
	},
	{
		ext: ".py",
		testExts: ["test_*.py", "*_test.py"],
		dirs: ["tests", "test", ".", "."],
	},
	{ ext: ".go", testExts: ["_test.go"], dirs: [".", ".", ".", "."] }, // Go tests are co-located
	{ ext: ".rs", testExts: [".rs"], dirs: ["tests", "tests", "src", "."] }, // Rust: tests/ or #[test] in src
	// PHPUnit convention: tests/ mirrors src/ with ClassNameTest.php naming
	// (e.g. src/Foo/Bar.php -> tests/Foo/BarTest.php). Basename is already the
	// class name (PHP files are named after their class), so no case transform
	// is needed — the mirrored-directory search below handles the tests/ root.
	{ ext: ".php", testExts: ["Test.php"], dirs: ["tests"] },
	// ExUnit convention: test/ mirrors lib/ with a _test.exs suffix on the same
	// basename (e.g. lib/accounts/user.ex -> test/accounts/user_test.exs).
	{ ext: ".ex", testExts: ["_test.exs"], dirs: ["test"] },
