import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { getGlobalPiLensDir } from "../../clients/file-utils.js";
import { BiomeClient } from "../../clients/biome-client.js";
import { setProjectTrustState } from "../../clients/project-trust.js";
import { removeTempDirSync } from "./test-utils.js";

const tmpDirs: string[] = [];

afterEach(() => {
	while (tmpDirs.length > 0) {
		const dir = tmpDirs.pop();
		if (dir && fs.existsSync(dir)) {
			removeTempDirSync(dir);
		}
	}
	vi.restoreAllMocks();
});

function setupMonorepo(): {
	workspaceRoot: string;
	subPackageRoot: string;
	subBiomeBin: string;
} {
	const workspaceRoot = fs.mkdtempSync(
		path.join(os.tmpdir(), "pi-lens-biome-monorepo-"),
	);
	tmpDirs.push(workspaceRoot);
	const subPackageRoot = path.join(workspaceRoot, "packages", "app");
	fs.mkdirSync(subPackageRoot, { recursive: true });

	const isWin = process.platform === "win32";
	const subBin = path.join(subPackageRoot, "node_modules", ".bin");
	fs.mkdirSync(subBin, { recursive: true });
	const subBiomeBin = path.join(subBin, isWin ? "biome.cmd" : "biome");
	fs.writeFileSync(subBiomeBin, "#!/bin/sh\necho mock biome\n");
	if (!isWin) fs.chmodSync(subBiomeBin, 0o755);

	return { workspaceRoot, subPackageRoot, subBiomeBin };
}

describe("BiomeClient — per-cwd binary resolution (#121)", () => {
	// This suite plants per-cwd project binaries on purpose; the trust gate is
	// witnessed in `project-local-bin-trust.test.ts`.
	beforeEach(() => setProjectTrustState("trusted"));

	// #4530 r7: managed directories must not become the cached formatter command.
	it("rejects a managed Biome directory", async () => {
		const { workspaceRoot } = setupMonorepo();
		const candidate = path.join(
			getGlobalPiLensDir(),
			"tools",
			"node_modules",
			".bin",
			process.platform === "win32" ? "biome.cmd" : "biome",
		);
		fs.mkdirSync(candidate, { recursive: true });
		try {
			const result = await (
				new BiomeClient() as unknown as {
					getBiomeBinary(cwd: string): Promise<{ cmd: string }>;
				}
			).getBiomeBinary(workspaceRoot);
			expect(result.cmd).not.toBe(candidate);
		} finally {
			fs.rmdirSync(candidate);
		}
	});

	it("resolves the sub-package's biome when cwd points there, not process.cwd()'s", async () => {
		const { workspaceRoot, subPackageRoot, subBiomeBin } = setupMonorepo();
		// Anchor process.cwd() at the workspace root, which has NO biome.
		const previousCwd = process.cwd();
		const cwdSpy = vi.spyOn(process, "cwd").mockReturnValue(workspaceRoot);
		try {
			const client = new BiomeClient();
			// Without cwd → resolves against the workspace root, which has no
			// local biome in node_modules. It may still find an auto-installed
			// binary in ~/.pi-lens/tools or a manager's global bin, so the only
			// invariant we can assert is that it is NOT the sub-package's binary.
			const noCwd = await (
				client as unknown as {
					getBiomeBinary(cwd?: string): Promise<{ cmd: string }>;
				}
			).getBiomeBinary();
			expect(noCwd.cmd).not.toBe(subBiomeBin);

			// With cwd pointing at the sub-package → finds the local binary
			// before any pi-lens-global fallback.
			const withCwd = await (
				client as unknown as {
					getBiomeBinary(cwd?: string): Promise<{ cmd: string }>;
				}
			).getBiomeBinary(subPackageRoot);
			expect(withCwd.cmd).toBe(subBiomeBin);
		} finally {
			cwdSpy.mockRestore();
			// Sanity: spy restored.
			expect(process.cwd()).toBe(previousCwd);
		}
	});

	it("caches the resolved binary per cwd so two sub-packages do not collide", async () => {
		const workspaceRoot = fs.mkdtempSync(
			path.join(os.tmpdir(), "pi-lens-biome-twopkg-"),
		);
		tmpDirs.push(workspaceRoot);
		const isWin = process.platform === "win32";
		const binName = isWin ? "biome.cmd" : "biome";

		const pkgA = path.join(workspaceRoot, "packages", "a");
		const pkgB = path.join(workspaceRoot, "packages", "b");
		const aBin = path.join(pkgA, "node_modules", ".bin", binName);
		const bBin = path.join(pkgB, "node_modules", ".bin", binName);
		fs.mkdirSync(path.dirname(aBin), { recursive: true });
		fs.mkdirSync(path.dirname(bBin), { recursive: true });
		fs.writeFileSync(aBin, "#!/bin/sh\necho a\n");
		fs.writeFileSync(bBin, "#!/bin/sh\necho b\n");
		if (!isWin) {
			fs.chmodSync(aBin, 0o755);
			fs.chmodSync(bBin, 0o755);
		}

		const client = new BiomeClient();
		const resolveA = await (
			client as unknown as {
				getBiomeBinary(cwd?: string): Promise<{ cmd: string }>;
			}
		).getBiomeBinary(pkgA);
		const resolveB = await (
			client as unknown as {
				getBiomeBinary(cwd?: string): Promise<{ cmd: string }>;
			}
		).getBiomeBinary(pkgB);
		expect(resolveA.cmd).toBe(aBin);
		expect(resolveB.cmd).toBe(bBin);
		// Re-resolving against pkgA still returns pkgA's binary, not bBin.
		const resolveAgain = await (
			client as unknown as {
				getBiomeBinary(cwd?: string): Promise<{ cmd: string }>;
			}
		).getBiomeBinary(pkgA);
		expect(resolveAgain.cmd).toBe(aBin);
	});

	// #1731 discipline B: `getBiomeBinary` returned `autoInstalledBinaryPath`
	// (set once, session-wide, the first time ANY cwd auto-installs biome)
	// before it ever looked at THIS cwd's own node_modules/.bin/biome. Once one
	// project in the session triggered an auto-install, every other project's
	// own biome install stopped mattering.
	it("prefers this cwd's own biome over a managed binary auto-installed for a different cwd", async () => {
		const { subPackageRoot, subBiomeBin } = setupMonorepo();

		const client = new BiomeClient();
		// Simulate what `doEnsureAvailable()` sets after auto-installing for some
		// EARLIER cwd this session — a real absolute path, unrelated to
		// `subPackageRoot`.
		(
			client as unknown as { autoInstalledBinaryPath: string | null }
		).autoInstalledBinaryPath = path.join(
			os.tmpdir(),
			"pi-lens-managed-biome",
			"biome",
		);

		const resolved = await (
			client as unknown as {
				getBiomeBinary(cwd?: string): Promise<{ cmd: string }>;
			}
		).getBiomeBinary(subPackageRoot);

		expect(resolved.cmd).toBe(subBiomeBin);
	});
});

tests/clients/biome-client-dedupe.test.t:
import { beforeEach, describe, expect, it, vi } from "vitest";

const safeSpawnAsync = vi.fn();
const safeSpawn = vi.fn();
const ensureTool = vi.fn();

vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../clients/safe-spawn.js")>()),
	safeSpawnAsync,
	safeSpawn,
}));
vi.mock("../../clients/installer/index.js", () => ({
	ensureTool,
	// #1500: the durable-absence arm reads the installer's own attempt record to
	// tell an attempt that failed from one that never ran.
	getInstallAttempt: vi.fn(() => undefined),
}));
// #1546: `getBiomeBinary` falls through to `findGlobalBinary` (#375) when no
// local/pi-lens-managed binary exists, and that helper probes every installed
// package manager's global bin dir — each check is its own `safeSpawnAsync`
// call (`where npm`, `npm config get prefix`, etc). Left unmocked, those calls
// share this file's `safeSpawnAsync` mock and silently consume the "one probe"
// budget these tests assert on, which is a false positive on any machine that
// happens to have a local/managed biome binary and a false failure on any
// machine that doesn't (Windows local, #1546). Short-circuiting it here keeps
// these tests scoped to `ensureAvailable`'s own in-flight dedupe (#120) rather
// than incidentally exercising package-manager's spawn count — the same
// isolation `biome-install-evidence.test.ts` already uses.
vi.mock("../../clients/package-manager.js", async (importOriginal) => ({
	...(await importOriginal<
		typeof import("../../clients/package-manager.js")
	>()),
	findGlobalBinary: vi.fn(async () => undefined),
}));

describe("BiomeClient.ensureAvailable() — in-flight dedupe (#120)", () => {
	beforeEach(() => {
		vi.resetAllMocks();
		ensureTool.mockResolvedValue(null);
	});

	it("dedupes concurrent first-time callers to a single probe", async () => {
		let resolveProbe: ((value: unknown) => void) | undefined;
		safeSpawnAsync.mockImplementationOnce(
			() =>
				new Promise((resolve) => {
					resolveProbe = resolve;
				}),
		);
		const { BiomeClient } = await import("../../clients/biome-client.js");
		const client = new BiomeClient();
		const a = client.ensureAvailable();
		const b = client.ensureAvailable();
		const c = client.ensureAvailable();
		// Binary resolution now awaits a global-bin lookup (#375) before the probe
		// spawns, so flush microtasks; the dedupe still means exactly ONE probe.
		await new Promise((r) => setTimeout(r, 0));
		expect(safeSpawnAsync).toHaveBeenCalledTimes(1);
		resolveProbe?.({
			status: 0,
			error: null,
			stdout: "biome 1.9.4",
			stderr: "",
		});
		const results = await Promise.all([a, b, c]);
		expect(results).toEqual([true, true, true]);
		// Cache is now hot — subsequent calls short-circuit before spawning.
		await client.ensureAvailable();
		expect(safeSpawnAsync).toHaveBeenCalledTimes(1);
	});

	it("does not re-probe once a missing verdict latches durably", async () => {
		// A plain non-zero exit (no timeout/abort) classifies as "missing" and
		// latches immediately (`retryAtMs` stays 0), so `ensureAvailable`'s
		// second call short-circuits on `availabilityLatch.read()` alone and
		// never reaches the `ensureInFlight` check below it — this test cannot
		// observe whether that check, or its `finally`-clear, works at all
		// (#1601). See the two tests below for that guard.
		safeSpawnAsync.mockResolvedValueOnce({
			status: 1,
			error: new Error("not found"),
			stdout: "",
			stderr: "",
		});
		const { BiomeClient } = await import("../../clients/biome-client.js");
		const client = new BiomeClient();
		const first = await client.ensureAvailable();
		expect(first).toBe(false);
		await client.ensureAvailable();
		expect(safeSpawnAsync).toHaveBeenCalledTimes(1);
	});

	it("re-probes once a transient verdict's cooldown expires, rather than returning a leaked settled promise (#1601)", async () => {
		// Unlike the durable "missing" case above, a transient (timeout/abort)
		// verdict's `availabilityLatch.read()` returns null again once its
		// cooldown expires — the ONLY path that reaches `if (this.ensureInFlight)
		// return this.ensureInFlight`. This is the guard the issue describes as
		// vacuous: if `ensureAvailable`'s `finally` stopped clearing the slot,
		// this second call would return the FIRST probe's settled `false`
		// forever instead of re-probing, and `second` would wrongly stay
		// `false` with only one spawn call recorded.
		vi.useFakeTimers();
		try {
			safeSpawnAsync
				.mockResolvedValueOnce({
					status: null,
					error: new Error("probe timed out"),
					failure: "timeout",
					stdout: "",
					stderr: "",
				})
				.mockResolvedValueOnce({
					status: 0,
					error: null,
					stdout: "biome 1.9.4",
					stderr: "",
				});
			const { BiomeClient } = await import("../../clients/biome-client.js");
			const client = new BiomeClient();

			const first = await client.ensureAvailable();
			expect(first).toBe(false);
			expect(safeSpawnAsync).toHaveBeenCalledTimes(1);

			// Base transient cooldown is 30s (TRANSIENT_BASE_COOLDOWN_MS); advance
			// past it so `read()` returns null and the in-flight check is reachable.
			await vi.advanceTimersByTimeAsync(30_000);

			const second = await client.ensureAvailable();
			expect(second).toBe(true);
			expect(safeSpawnAsync).toHaveBeenCalledTimes(2);
		} finally {
			vi.useRealTimers();
		}
	});

	it("dedupes callers racing in as a transient cooldown expires, instead of splitting one onto a leaked settled slot (#1601)", async () => {
		// The settled-slot-through-cooldown window named in the issue: two
		// callers arrive together right as the retry window opens. If the
		// first probe's promise had leaked past its `finally`, one of these
		// two could resolve off the stale settled slot while the other
		// triggered a fresh probe — an inconsistent pair of answers to the
		// same question asked in the same tick.
		vi.useFakeTimers();
		try {
			safeSpawnAsync
				.mockResolvedValueOnce({
					status: null,
					error: new Error("probe timed out"),
					failure: "timeout",
					stdout: "",
					stderr: "",
				})
				.mockResolvedValueOnce({
					status: 0,
					error: null,
					stdout: "biome 1.9.4",
					stderr: "",
				});
			const { BiomeClient } = await import("../../clients/biome-client.js");
			const client = new BiomeClient();

			const first = await client.ensureAvailable();
			expect(first).toBe(false);

			await vi.advanceTimersByTimeAsync(30_000);

			const [a, b] = await Promise.all([
				client.ensureAvailable(),
				client.ensureAvailable(),
			]);
			expect(a).toBe(true);
			expect(b).toBe(true);
			expect(safeSpawnAsync).toHaveBeenCalledTimes(2);
		} finally {
			vi.useRealTimers();
		}
	});
});

