tests/clients/dead-code-vulture-project-:
/**
 * #1731 sweep findings for vulture (PythonDeadCodeClient):
 *
 * - Discipline B: `ensureAvailable()` probed bare `vulture` / `python -m
 *   vulture` / `python3 -m vulture` on PATH only — no `<root>/.venv/bin/
 *   vulture` check, unlike sqlfluff's venv-first binary resolution
 *   (`runner-helpers.ts` `createVenvFinder`). A project's own venv vulture
 *   (the version its dependency set was actually resolved against) never got
 *   a look-in ahead of whatever `vulture` happened to answer on PATH.
 * - Discipline A: `runAnalyze` always passed `--min-confidence` and
 *   `--exclude`, which override `[tool.vulture]` in the project's own
 *   `pyproject.toml`.
 */
import * as fs from "node:fs";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { setProjectTrustState } from "../../clients/project-trust.js";
import { removeTempDirSync, setupTestEnvironment } from "./test-utils.js";

const safeSpawnAsync = vi.fn(
	async (
		..._args: unknown[]
	): Promise<{
		error: Error | null;
		status: number | null;
		stdout: string;
		stderr: string;
	}> => ({ error: null, status: 0, stdout: "", stderr: "" }),
);
vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../clients/safe-spawn.js")>()),
	safeSpawnAsync,
}));

describe("PythonDeadCodeClient (vulture) — project-first resolution (#1731)", () => {
	const tmpDirs: string[] = [];

	beforeEach(() => {
		// This suite witnesses project-first resolution, not the trust gate; the
		// gate is covered by the dedicated trust witnesses.
		setProjectTrustState("trusted");
		safeSpawnAsync.mockReset();
		safeSpawnAsync.mockImplementation(async () => ({
			error: null,
			status: 0,
			stdout: "",
			stderr: "",
		}));
	});

	afterEach(() => {
		while (tmpDirs.length > 0) {
			const dir = tmpDirs.pop();
			if (dir && fs.existsSync(dir)) removeTempDirSync(dir);
		}
	});

	it("probes the project's own .venv vulture before any bare PATH candidate (discipline B)", async () => {
		const env = setupTestEnvironment("pi-lens-vulture-venv-");
		tmpDirs.push(env.tmpDir);
		const isWin = process.platform === "win32";
		const venvBin = isWin
			? path.join(env.tmpDir, ".venv", "Scripts")
			: path.join(env.tmpDir, ".venv", "bin");
		fs.mkdirSync(venvBin, { recursive: true });
		const venvVulture = path.join(venvBin, isWin ? "vulture.exe" : "vulture");
		// #4530 r7: command acceptance requires the executable bit on POSIX.
		fs.writeFileSync(venvVulture, "", { mode: 0o755 });

		const { PythonDeadCodeClient } =
			await import("../../clients/dead-code-client.js");
		const client = new PythonDeadCodeClient() as unknown as {
			ensureAvailable(root?: string): Promise<boolean>;
		};

		const ok = await client.ensureAvailable(env.tmpDir);
		expect(ok).toBe(true);
		expect(safeSpawnAsync).toHaveBeenCalledTimes(1);
		const [cmd] = safeSpawnAsync.mock.calls[0] as [string, ...unknown[]];
		expect(cmd).toBe(venvVulture);
	});

	/**
	 * #2544 round 4 F2 (reverted). `venvCandidates` joined its venv directories
	 * onto `root` and nothing else — a third private spelling of the same four
	 * directories, with a `process.platform` branch that hid the `Scripts`
	 * half from the ubuntu lane entirely (defect shape 30, fixed and kept).
	 * Round 3 ALSO folded the resolution onto the shared ancestor walker,
	 * reasoning a monorepo package should find its repo-root venv — an
	 * unrequested behaviour change with no #2514 defect behind it. Reverted:
	 * a `.venv` at a repo root is invisible from a package subdirectory, and
	 * resolution falls through to the bare `vulture`/`python -m vulture`
	 * PATH candidates instead.
	 */
	it("does not probe a .venv vulture from an ANCESTOR of the analyzed root (#2544 round 4 F2)", async () => {
		const env = setupTestEnvironment("pi-lens-vulture-venv-ancestor-");
		tmpDirs.push(env.tmpDir);
		const isWin = process.platform === "win32";
		const repoRoot = path.join(env.tmpDir, "repo");
		const pkg = path.join(repoRoot, "services", "api");
		fs.mkdirSync(pkg, { recursive: true });
		const venvBin = isWin
			? path.join(repoRoot, ".venv", "Scripts")
			: path.join(repoRoot, ".venv", "bin");
		fs.mkdirSync(venvBin, { recursive: true });
		const venvVulture = path.join(venvBin, isWin ? "vulture.exe" : "vulture");
		fs.writeFileSync(venvVulture, "");

		const { PythonDeadCodeClient } =
			await import("../../clients/dead-code-client.js");
		const client = new PythonDeadCodeClient() as unknown as {
			ensureAvailable(root?: string): Promise<boolean>;
		};

		expect(await client.ensureAvailable(pkg)).toBe(true);
		const [cmd] = safeSpawnAsync.mock.calls[0] as [string, ...unknown[]];
		expect(cmd).not.toBe(venvVulture);
		expect(cmd).toBe("vulture");
	});

	// After #2544 round 4 F2's revert to a fixed `root`-only lookup, this
	// holds for a simpler reason than a ceiling: `project` (root) and
	// `fakeHome` are different directories, and `venvCandidates` never looks
	// anywhere but `root` — the ceiling is moot for a lookup that never climbs.
	it("never probes a .venv vulture planted at HOME (#2514)", async () => {
		const env = setupTestEnvironment("pi-lens-vulture-venv-home-");
		tmpDirs.push(env.tmpDir);
		const originalHome = process.env.HOME;
		const originalUserProfile = process.env.USERPROFILE;
		try {
			const isWin = process.platform === "win32";
			const fakeHome = env.tmpDir;
			const project = path.join(fakeHome, "project");
			fs.mkdirSync(project, { recursive: true });
			const venvBin = isWin
				? path.join(fakeHome, ".venv", "Scripts")
				: path.join(fakeHome, ".venv", "bin");
			fs.mkdirSync(venvBin, { recursive: true });
			const homeVulture = path.join(venvBin, isWin ? "vulture.exe" : "vulture");
			fs.writeFileSync(homeVulture, "");
			process.env.HOME = fakeHome;
			process.env.USERPROFILE = fakeHome;

			const { PythonDeadCodeClient } =
				await import("../../clients/dead-code-client.js");
			const client = new PythonDeadCodeClient() as unknown as {
				ensureAvailable(root?: string): Promise<boolean>;
			};

			await client.ensureAvailable(project);

			const probed = safeSpawnAsync.mock.calls.map((call) => call[0]);
			expect(probed).not.toContain(homeVulture);
			// …and the PATH candidates still ran, so this is a ceiling, not a
			// short-circuit that skips resolution altogether.
			expect(probed).toContain("vulture");
		} finally {
			if (originalHome === undefined) delete process.env.HOME;
			else process.env.HOME = originalHome;
			if (originalUserProfile === undefined) delete process.env.USERPROFILE;
			else process.env.USERPROFILE = originalUserProfile;
		}
	});

	it("omits --min-confidence and --exclude when the project ships [tool.vulture] (discipline A)", async () => {
		const env = setupTestEnvironment("pi-lens-vulture-config-");
		tmpDirs.push(env.tmpDir);
		fs.writeFileSync(
			path.join(env.tmpDir, "pyproject.toml"),
			"[tool.vulture]\nmin_confidence = 80\nexclude = ['migrations/']\n",
		);

		const { PythonDeadCodeClient } =
			await import("../../clients/dead-code-client.js");
		const client = new PythonDeadCodeClient() as unknown as {
			runAnalyze(root: string): Promise<unknown>;
		};

		await client.runAnalyze(env.tmpDir);
		expect(safeSpawnAsync).toHaveBeenCalledTimes(1);
		const [, args] = safeSpawnAsync.mock.calls[0] as [string, string[]];
		expect(args).not.toContain(
			expect.stringMatching(/^--min-confidence=/) as unknown as string,
		);
		expect(args.some((a) => a.startsWith("--min-confidence="))).toBe(false);
		expect(args.some((a) => a.startsWith("--exclude="))).toBe(false);
	});

	it("still passes --min-confidence and --exclude with no project config", async () => {
		const env = setupTestEnvironment("pi-lens-vulture-noconfig-");
		tmpDirs.push(env.tmpDir);

		const { PythonDeadCodeClient } =
			await import("../../clients/dead-code-client.js");
		const client = new PythonDeadCodeClient() as unknown as {
			runAnalyze(root: string): Promise<unknown>;
		};

		await client.runAnalyze(env.tmpDir);
		const [, args] = safeSpawnAsync.mock.calls[0] as [string, string[]];
		expect(args.some((a) => a.startsWith("--min-confidence="))).toBe(true);
		expect(args.some((a) => a.startsWith("--exclude="))).toBe(true);
	});
});

tests/clients/dependency-checker-batch-r:
/**
 * Regression test for #766: `checkFilesBatch` parallelizes the per-turn
 * madge subprocess spawns that used to run one at a time in a sequential
 * `for…await checkFile(file)` loop.
 *
 * The risk: `DependencyChecker` keeps `lastCircular`/`circularFiles` as
 * shared instance state that each single-file madge run OVERWRITES (not
 * merges). Sequentially, the file processed LAST in array order determines
 * the final shared state. A naive `Promise.all` that mutates that shared
 * state as soon as each spawn's own promise resolves makes the final state
 * depend on subprocess COMPLETION order instead — nondeterministic and not
 * equivalent to the sequential baseline.
 *
 * This test sets up two files whose madge results disagree (one reports a
 * circular dependency, the other doesn't) and deliberately makes the
 * array-first file's subprocess resolve LAST. A correct fix folds results in
 * original array order regardless of completion order, so the final shared
 * state (and `isInCircular`/`getCircularForFile`) must match what the
 * sequential loop would have produced — i.e. the array-LAST file's result —
 * even though its spawn completed FIRST.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const safeSpawnAsync = vi.fn();
const safeSpawn = vi.fn();

vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../clients/safe-spawn.js")>()),
	safeSpawnAsync,
	safeSpawn,
}));
vi.mock("../../clients/package-manager.js", async (importOriginal) => ({
	...(await importOriginal<
		typeof import("../../clients/package-manager.js")
	>()),
	findNodeToolBinary: vi.fn(async () => "/fake/bin/madge"),
}));
// Guard: without this, a `findNodeToolBinary → undefined` fallthrough would load
// the REAL installer, whose named imports from the partially-mocked
// package-manager/safe-spawn modules throw — silently degrading every result to
// `{ok: false}` instead of failing loudly.
vi.mock("../../clients/installer/index.js", () => ({
	// #2140: the probe resolver asks the installer for a release-managed
	// binary (`~/.pi-lens/bin`) before falling back to PATH. Undefined is
	// "no managed install", which is what these tests already assumed.
	findManagedToolBinary: vi.fn(async () => undefined),
	ensureTool: vi.fn(async () => undefined),
	getManagedToolsDir: () => path.join("/fake", "pi-lens", "tools"),
	// #1276: stubbed for the same reason as the sibling madge test files — see
	// dependency-checker-madge-resolution.test.ts.
	isSpawnableCommand: vi.fn(async () => true),
}));

describe("DependencyChecker.checkFilesBatch — concurrency race guard (#766)", () => {
	let tmp: string;
	let aPath: string;
	let cPath: string;

	beforeEach(() => {
		vi.resetAllMocks();
		tmp = fs.mkdtempSync(path.join(os.tmpdir(), "pi-lens-pilens-madge-batch-"));
		aPath = path.join(tmp, "a.ts");
		cPath = path.join(tmp, "c.ts");
		fs.writeFileSync(
			aPath,
			"import { b } from './b.js';\nexport const a = 1;\n",
		);
		fs.writeFileSync(cPath, "export const c = 1;\n");
	});

	afterEach(() => {
		fs.rmSync(tmp, { recursive: true, force: true });
	});

	/** Resolve slowly for `a.ts` (reports a circular dep) and fast for `c.ts`
	 * (reports none) — completion order is REVERSED from array order. */
	function mockSpawnDeps() {
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			const target = args[args.length - 1];
			if (target === aPath) {
				// Resolves LAST despite being array-FIRST.
				await new Promise((resolve) => setTimeout(resolve, 40));
				return {
					status: 0,
					error: null,
					stdout: JSON.stringify([[aPath, path.join(tmp, "b.ts")]]),
					stderr: "",
				};
			}
			// c.ts resolves immediately with no cycle.
			return {
				status: 0,
				error: null,
				stdout: JSON.stringify([]),
				stderr: "",
			};
		});
	}

	it("folds results in ARRAY order, not completion order, matching the sequential loop", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		mockSpawnDeps();

		const checker = new DependencyChecker();
		// Array order: a (slow, circular) first, then c (fast, clean) last.
		const { results } = await checker.checkFilesBatch([aPath, cPath], tmp);

		// Per-file local results must still be correct and not clobbered by
		// the sibling call: a's own result reports its cycle...
		expect(results.get(aPath)?.hasCircular).toBe(true);
		// ...and c's own result reports none, regardless of completion order.
		expect(results.get(cPath)?.hasCircular).toBe(false);

		// The shared state, however, reflects last-array-order-wins (c),
		// exactly like the sequential `for…await` loop would have left it —
		// NOT last-to-complete-wins (which would be a, since a's spawn
		// resolves after c's).
		expect(checker.isInCircular(aPath)).toBe(false);
		expect(checker.isInCircular(cPath)).toBe(false);
		expect(checker.getCircularForFile(aPath)).toEqual([]);
	});

	it("matches a true sequential for…await run of the same files/mocks", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");

		// --- Sequential baseline ---
		mockSpawnDeps();
		const sequential = new DependencyChecker();
		const seqResults = new Map<string, boolean>();
		for (const file of [aPath, cPath]) {
			const r = await sequential.checkFile(file, tmp);
			seqResults.set(file, r.hasCircular);
		}
		const seqFinalIsInCircularA = sequential.isInCircular(aPath);
		const seqFinalIsInCircularC = sequential.isInCircular(cPath);

		// --- Batch (parallel) run, same mocks/inputs ---
		vi.resetAllMocks();
		mockSpawnDeps();
		const batch = new DependencyChecker();
		const { results: batchResults } = await batch.checkFilesBatch(
			[aPath, cPath],
			tmp,
		);

		expect(batchResults.get(aPath)?.hasCircular).toBe(seqResults.get(aPath));
		expect(batchResults.get(cPath)?.hasCircular).toBe(seqResults.get(cPath));
		expect(batch.isInCircular(aPath)).toBe(seqFinalIsInCircularA);
		expect(batch.isInCircular(cPath)).toBe(seqFinalIsInCircularC);
	});

	it("would fail under a naive completion-order-wins merge (sanity check on the mock setup)", async () => {
		// This test does not exercise DependencyChecker at all — it just proves
		// the mock setup in this file actually produces reversed completion
		// order, which is the precondition the race-guard test above depends on.
		mockSpawnDeps();
		const order: string[] = [];
		const done = Promise.all([
			(async () => {
				const r = await safeSpawnAsync("/fake/bin/madge", [
					"--circular",
					"--json",
					aPath,
				]);
				order.push("a");
				return r;
			})(),
			(async () => {
				const r = await safeSpawnAsync("/fake/bin/madge", [
					"--circular",
					"--json",
					cPath,
				]);
				order.push("c");
				return r;
			})(),
		]);
		await done;
		// c (array-last) completes FIRST; a (array-first) completes LAST.
		expect(order).toEqual(["c", "a"]);
	});
});

tests/clients/dependency-checker-batch-t:
/**
 * #766: `checkFilesBatch` telemetry and spawn bounds.
 *
 * Turn-end logged one whole-phase `phase: "madge"` duration, which cannot
 * distinguish "many files" from "one slow file" from "command resolution" —
 * exactly the attribution the p99 tail needed. The batch now returns
 * `MadgeBatchStats` alongside its results, and turn-end attaches it as the
 * latency entry's metadata (logLatency no-ops under test, so these assert on the
 * returned stats).
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { removeTempDirSync } from "./test-utils.js";

const safeSpawnAsync = vi.fn();
const safeSpawn = vi.fn();
const findNodeToolBinary = vi.fn();
const ensureTool = vi.fn();

vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../clients/safe-spawn.js")>()),
	safeSpawnAsync,
	safeSpawn,
}));
vi.mock("../../clients/package-manager.js", async (importOriginal) => ({
	...(await importOriginal<
		typeof import("../../clients/package-manager.js")
	>()),
	findNodeToolBinary,
}));
vi.mock("../../clients/installer/index.js", () => ({
	// #2140: the probe resolver asks the installer for a release-managed
	// binary (`~/.pi-lens/bin`) before falling back to PATH. Undefined is
	// "no managed install", which is what these tests already assumed.
	findManagedToolBinary: vi.fn(async () => undefined),
	ensureTool,
	getManagedToolsDir: () => path.join(os.tmpdir(), "pilens-fake-home", "tools"),
	// #1276: the madge staleness check revalidates bare resolved commands via
	// isSpawnableCommand. Not exercised in this file (every resolution here
	// falls through to the unmemoized `npx` fallback), but stubbed so a future
	// bare-command case here doesn't throw on a missing mock export.
	isSpawnableCommand: vi.fn(async () => true),
}));

const VERSION_OK = {
	status: 0,
	error: null,
	stdout: "madge 8.0.0",
	stderr: "",
};

describe("DependencyChecker.checkFilesBatch telemetry (#766)", () => {
	let tmp: string;

	beforeEach(() => {
		vi.resetAllMocks();
		tmp = fs.mkdtempSync(path.join(os.tmpdir(), "pi-lens-pilens-madge-stats-"));
		findNodeToolBinary.mockResolvedValue(undefined);
		ensureTool.mockResolvedValue(undefined);
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args[0] === "--version") return VERSION_OK;
			return { status: 0, error: null, stdout: "[]", stderr: "" };
		});
	});

	afterEach(() => {
		removeTempDirSync(tmp);
	});

	function writeSource(name: string, imports: string[]): string {
		const file = path.join(tmp, name);
		fs.writeFileSync(
			file,
			`${imports.map((i) => `import { x } from "${i}";`).join("\n")}\nexport const v = 1;\n`,
		);
		return file;
	}

	function madgeCalls(): unknown[][] {
		return safeSpawnAsync.mock.calls.filter(
			(c) => (c[1] as string[])[0] !== "--version",
		);
	}

	it("spawns nothing for a body-only edit", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const f = writeSource("a.ts", ["./b.js"]);
		const checker = new DependencyChecker();

		const first = await checker.checkFilesBatch([f], tmp);
		expect(first.stats.spawned).toBe(1);
		expect(madgeCalls()).toHaveLength(1);

		// Same import set, different body — both mtime and size move, so the
		// #1105 freshness fast path does not decide this; the extracted import
		// set does.
		fs.writeFileSync(
			f,
			'import { x } from "./b.js";\nexport const v = 1;\nexport const w = 2;\n',
		);
		const second = await checker.checkFilesBatch([f], tmp);

		expect(second.stats.spawned).toBe(0);
		expect(second.stats.cacheHits).toBe(1);
		expect(second.results.get(f)?.cacheHit).toBe(true);
		// Nothing to spawn means nothing to resolve, either.
		expect(second.stats.commandKind).toBeUndefined();
		expect(madgeCalls()).toHaveLength(1);
	});

	it("bounds concurrent spawns for a pathological turn", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const files = Array.from({ length: 8 }, (_, i) =>
			writeSource(`f${i}.ts`, [`./dep${i}.js`]),
		);
		let inFlight = 0;
		let peak = 0;

		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args[0] === "--version") return VERSION_OK;
			inFlight++;
			peak = Math.max(peak, inFlight);
			await new Promise((resolve) => setTimeout(resolve, 15));
			inFlight--;
			return { status: 0, error: null, stdout: "[]", stderr: "" };
		});

		const { stats } = await new DependencyChecker().checkFilesBatch(files, tmp);

		expect(stats.spawned).toBe(8);
		// Exactly the cap, not merely under it — a peak below 6 would mean the
		// mock never saturated the pool and the bound went untested.
		expect(peak).toBe(6);
	});

	it("counts hits, misses, missing files and failures separately", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const hit = writeSource("hit.ts", ["./h.js"]);
		const ok = writeSource("ok.ts", ["./o.js"]);
		const bad = writeSource("bad.ts", ["./x.js"]);
		const gone = path.join(tmp, "gone.ts");

		const checker = new DependencyChecker();
		// Seed hit.ts's import cache so the batch classifies it as unchanged.
		expect(checker.importsChanged(hit)).toBe(true);

		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args[0] === "--version") return VERSION_OK;
			if (args[args.length - 1] === bad) {
				return {
					status: 1,
					error: new Error("madge exploded"),
					stdout: "",
					stderr: "",
				};
			}
			return { status: 0, error: null, stdout: "[]", stderr: "" };
		});

		const { results, stats } = await checker.checkFilesBatch(
			[hit, ok, bad, gone],
			tmp,
		);

		expect(stats.requested).toBe(4);
		expect(stats.missing).toBe(1);
		expect(stats.cacheHits).toBe(1);
		expect(stats.spawned).toBe(2);
		expect(stats.failed).toBe(1);
		expect(stats.commandKind).toBe("npx");
		// Fast targets do not widen the shared latency record; aggregate counts
		// above remain exact and slow targets are covered below.
		expect(stats.targets).toEqual([]);
		expect(stats.targetsTruncated).toBe(false);
		expect(results.get(hit)?.cacheHit).toBe(true);
		expect(results.get(gone)?.checked).toBe(false);
	});

	it("counts the whole miss set as failed when madge is unavailable", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args[0] === "--version") {
				return {
					status: 1,
					error: new Error("madge: not found"),
					stdout: "",
					stderr: "",
				};
			}
			throw new Error("must not spawn madge while it is unavailable");
		});

		const hit = writeSource("hit.ts", ["./h.js"]);
		const missA = writeSource("a.ts", ["./a-dep.js"]);
		const missB = writeSource("b.ts", ["./b-dep.js"]);
		const gone = path.join(tmp, "gone.ts");

		const checker = new DependencyChecker();
		expect(checker.importsChanged(hit)).toBe(true);

		const { results, stats } = await checker.checkFilesBatch(
			[hit, missA, missB, gone],
			tmp,
		);

		expect(stats.requested).toBe(4);
		expect(stats.missing).toBe(1);
		expect(stats.cacheHits).toBe(1);
		expect(stats.spawned).toBe(0);
		// The miss set is not silently dropped: 0/0 would read as a clean turn
		// with nothing to do.
		expect(stats.failed).toBe(2);
		expect(stats.commandKind).toBeUndefined();
		expect(results.get(missA)?.checked).toBe(false);
		expect(results.get(hit)?.cacheHit).toBe(true);
	});

	it("does not retain fast per-target timings", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const files = Array.from({ length: 12 }, (_, i) =>
			writeSource(`f${i}.ts`, [`./dep${i}.js`]),
		);

		const { stats } = await new DependencyChecker().checkFilesBatch(files, tmp);

		expect(stats.spawned).toBe(12);
		expect(stats.targets).toHaveLength(0);
		expect(stats.targetsTruncated).toBe(false);
	});

	it("retains only slow target timings and caps them", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const files = Array.from({ length: 14 }, (_, i) =>
			writeSource(`f${i}.ts`, [`./dep${i}.js`]),
		);
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args[0] === "--version") return VERSION_OK;
			await new Promise((resolve) => setTimeout(resolve, 120));
			return { status: 0, error: null, stdout: "[]", stderr: "" };
		});

		const { stats } = await new DependencyChecker().checkFilesBatch(files, tmp);

		expect(stats.spawned).toBe(14);
		expect(stats.targets).toHaveLength(12);
		expect(stats.targetsTruncated).toBe(true);
	});

	it("keeps repeated batch metadata bounded", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const files = Array.from({ length: 14 }, (_, i) =>
			writeSource(`repeat${i}.ts`, [`./dep${i}.js`]),
		);
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args[0] === "--version") return VERSION_OK;
			await new Promise((resolve) => setTimeout(resolve, 120));
			return { status: 0, error: null, stdout: "[]", stderr: "" };
		});

		const checker = new DependencyChecker();
		const serializedSizes: number[] = [];
		for (let turn = 0; turn < 3; turn++) {
			for (const [i, file] of files.entries()) {
				fs.writeFileSync(file, `import { x } from "./dep${i}-${turn}.js";\n`);
			}
			const { stats } = await checker.checkFilesBatch(files, tmp);
			expect(stats.targets.length).toBeLessThanOrEqual(12);
			serializedSizes.push(JSON.stringify(stats).length);
		}
		expect(Math.max(...serializedSizes)).toBeLessThanOrEqual(
			Math.max(...serializedSizes.slice(0, 1)),
		);
	});
});

tests/clients/dependency-checker-madge-r:
/**
 * #766: how `DependencyChecker` resolves the madge command.
 *
 * Resolution used to fall straight from `findNodeToolBinary` to `npx madge`,
 * never consulting the tools tree pi-lens itself installs madge into — so an
 * environment whose ONLY madge is the managed one paid npx module resolution on
 * every spawn, and it ran once per file inside the batch mapper (each miss
 * re-walking node_modules and re-spawning the uncached `npm config get prefix` /
 * `pnpm bin -g` global probes).
 *
 * These tests pin the resolution ORDER, that the discovery step can never
 * install, that `kind` is classified from the resolved string rather than the
 * step that produced it, and that the whole chain runs once per project root.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { removeTempDirSync } from "./test-utils.js";

const safeSpawnAsync = vi.fn();
const safeSpawn = vi.fn();
const findNodeToolBinary = vi.fn();
const ensureTool = vi.fn();
// #1276: the madge staleness check now revalidates bare (non-absolute)
// resolved commands via isSpawnableCommand. Defaulted to "still spawnable" in
// beforeEach so existing cache-hit assertions in this file aren't disturbed;
// tests that care about staleness override it explicitly.
const isSpawnableCommand = vi.fn();
const MANAGED_TOOLS_DIR = path.join(os.tmpdir(), "pilens-fake-home", "tools");
// Fake absolute paths standing in for a global-bin install, OUTSIDE the
// managed tree and any project root. Must be fully qualified under the
// HOST's semantics (`isFullyQualified` in clients/path-utils.ts) — on win32
// a bare "/usr/..." literal is ambient-drive-relative, not fully qualified,
// so `classifyMadgeKind`'s `isFullyQualified(resolved)` gate silently
// classifies it as "path" instead of "global" (same defect shape as #1491).
const GLOBAL_BIN_1 =
	process.platform === "win32"
		? String.raw`C:\fake-global\local\bin\madge`
		: "/usr/local/bin/madge";
const GLOBAL_BIN_2 =
	process.platform === "win32"
		? String.raw`C:\fake-global\bin\madge`
		: "/usr/bin/madge";

vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../clients/safe-spawn.js")>()),
	safeSpawnAsync,
	safeSpawn,
}));
vi.mock("../../clients/package-manager.js", async (importOriginal) => ({
	...(await importOriginal<
		typeof import("../../clients/package-manager.js")
	>()),
	findNodeToolBinary,
}));
vi.mock("../../clients/installer/index.js", () => ({
	// #2140: the probe resolver asks the installer for a release-managed
	// binary (`~/.pi-lens/bin`) before falling back to PATH. Undefined is
	// "no managed install", which is what these tests already assumed.
	findManagedToolBinary: vi.fn(async () => undefined),
	ensureTool,
	getManagedToolsDir: () => MANAGED_TOOLS_DIR,
	// #1612: resolveAvailableOrInstallUnshared reads these on the install-
	// success path to derive honest evidence rather than asserting "succeeded".
	getInstallAttempt: vi.fn(() => undefined),
	// #1636: read alongside getInstallAttempt when deriving the compensating
	// row's `resolved` tag. Undefined falls back to "cache", matching this
	// suite's existing not-attempted expectations.
	getLastEnsureResolutionSource: vi.fn(() => undefined),
	getToolInstallStrategy: vi.fn(() => undefined),
	isSpawnableCommand,
}));

describe("DependencyChecker madge resolution (#766)", () => {
	let tmp: string;
	let otherRoot: string;

	beforeEach(() => {
		vi.resetAllMocks();
		tmp = fs.mkdtempSync(
			path.join(os.tmpdir(), "pi-lens-pilens-madge-resolve-"),
		);
		otherRoot = fs.mkdtempSync(
			path.join(os.tmpdir(), "pi-lens-pilens-madge-other-"),
		);
		findNodeToolBinary.mockResolvedValue(undefined);
		ensureTool.mockResolvedValue(undefined);
		isSpawnableCommand.mockResolvedValue(true);
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args[0] === "--version") {
				return {
					status: 0,
					error: undefined,
					stdout: "madge 8.0.0",
					stderr: "",
				};
			}
			return { status: 0, error: undefined, stdout: "[]", stderr: "" };
		});
	});

	afterEach(() => {
		removeTempDirSync(tmp);
		removeTempDirSync(otherRoot);
	});

	function writeSource(name: string, imports: string[], root = tmp): string {
		const file = path.join(root, name);
		fs.writeFileSync(
			file,
			`${imports.map((i) => `import { x } from "${i}";`).join("\n")}\nexport const v = 1;\n`,
		);
		return file;
	}

	/** A real file under `root` standing in for an installed madge binary. */
	function installFakeBinary(root: string): string {
		const bin = path.join(root, "node_modules", ".bin", "madge");
		fs.mkdirSync(path.dirname(bin), { recursive: true });
		fs.writeFileSync(bin, "#!/bin/sh\n");
		return bin;
	}

	/** The madge spawns, excluding `ensureAvailable`'s `--version` probe. */
	function madgeCalls(): unknown[][] {
		return safeSpawnAsync.mock.calls.filter(
			(c) => (c[1] as string[])[0] !== "--version",
		);
	}

	it("real client does not claim coverage from madge cycle output (#2887)", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		writeSource("a.ts", ["./b.js"]);
		findNodeToolBinary.mockResolvedValue("madge");
		safeSpawnAsync.mockImplementation(async (_command, args: string[]) => {
			if (args[0] === "--version") {
				return {
					status: 0,
					error: undefined,
					stdout: "madge 8.0.0",
					stderr: "",
				};
			}
			return {
				status: 0,
				error: undefined,
				// Captured from madge 8 with --circular --json for an acyclic
				// project: the output is an array of cycles, not a graph object.
				stdout: "[]",
				stderr: "",
			};
		});
		const result = await new DependencyChecker().scanProject(tmp);
		expect(result.analyzed).toBe(true);
		expect(result.analyzedFiles).toBeUndefined();
	});

	it("keeps a project-pinned binary winning (#375), without consulting the installer", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const bin = installFakeBinary(tmp);
		findNodeToolBinary.mockResolvedValue(bin);

		const { stats } = await new DependencyChecker().checkFilesBatch(
			[writeSource("a.ts", ["./b.js"])],
			tmp,
		);

		expect(stats.commandKind).toBe("local");
		expect(ensureTool).not.toHaveBeenCalled();
		expect(madgeCalls()[0][0]).toBe(bin);
	});

	it("reports a global-bin hit as `global`, not `local`", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		// findNodeToolBinary probes npm/pnpm/yarn/bun GLOBAL bins too, so the step
		// that answered says nothing about where the binary lives.
		findNodeToolBinary.mockResolvedValue(GLOBAL_BIN_1);

		const { stats } = await new DependencyChecker().checkFilesBatch(
			[writeSource("a.ts", ["./b.js"])],
			tmp,
		);

		expect(stats.commandKind).toBe("global");
	});

	it("uses the managed install instead of npx when nothing local is found", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const managed = path.join(
			MANAGED_TOOLS_DIR,
			"node_modules",
			".bin",
			"madge",
		);
		ensureTool.mockResolvedValue(managed);
		// Exercise the off-PATH auto-install path: ensureAvailable's bare-name
		// probe fails, then resolution must reuse the installed absolute path.
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) =>
			args[0] === "--version"
				? { status: 1, error: new Error("not found"), stdout: "", stderr: "" }
				: { status: 0, error: undefined, stdout: "[]", stderr: "" },
		);

		const { stats } = await new DependencyChecker().checkFilesBatch(
			[writeSource("a.ts", ["./b.js"])],
			tmp,
		);

		expect(stats.commandKind).toBe("managed");
		const [cmd, args] = madgeCalls()[0] as [string, string[]];
		expect(cmd).toBe(managed);
		// No `npx madge` prefix — the binary is invoked directly.
		expect(args[0]).toBe("--circular");
	});

	it("classifies the resolved STRING, not the step that produced it", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");

		// The installer's discovery can hand back a bare PATH name...
		ensureTool.mockResolvedValue("madge");
		const bare = await new DependencyChecker().checkFilesBatch(
			[writeSource("a.ts", ["./b.js"])],
			tmp,
		);
		expect(bare.stats.commandKind).toBe("path");

		// ...or an absolute path outside the managed tree.
		ensureTool.mockResolvedValue(GLOBAL_BIN_2);
		const global = await new DependencyChecker().checkFilesBatch(
			[writeSource("b.ts", ["./c.js"])],
			tmp,
		);
		expect(global.stats.commandKind).toBe("global");
	});

	it("falls back to `npx madge` only when nothing is discoverable", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");

		const { stats } = await new DependencyChecker().checkFilesBatch(
			[writeSource("a.ts", ["./b.js"])],
			tmp,
		);

		expect(stats.commandKind).toBe("npx");
		const [cmd, args] = madgeCalls()[0] as [string, string[]];
		expect(cmd).toBe("npx");
		expect(args[0]).toBe("madge");
	});

	it("never installs from the spawn path", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");

		await new DependencyChecker().checkFilesBatch(
			[writeSource("a.ts", ["./b.js"])],
			tmp,
		);

		// Installation stays owned by ensureAvailable(); discovery here must not
		// be able to trigger a download.
		expect(ensureTool).toHaveBeenCalledWith("madge", { allowInstall: false });
	});

	it("resolves once per project root — not per file, per batch, or for every root", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const bin = installFakeBinary(tmp);
		// The probe chain this memo exists to avoid is genuinely slow (uncached
		// `npm config get prefix` / `pnpm bin -g` spawns), so make it cost time.
		findNodeToolBinary.mockImplementation(async () => {
			await new Promise((resolve) => setTimeout(resolve, 25));
			return bin;
		});
		const files = [
			writeSource("a.ts", ["./x.js"]),
			writeSource("b.ts", ["./y.js"]),
			writeSource("c.ts", ["./z.js"]),
		];

		const checker = new DependencyChecker();
		const first = await checker.checkFilesBatch(files, tmp);
		expect(madgeCalls()).toHaveLength(3);
		// The cold resolution's cost is attributed, not hidden in the phase total.
		expect(first.stats.resolveMs).toBeGreaterThanOrEqual(20);

		// Re-edit the imports so the second batch is three fresh misses.
		files.forEach((f, i) =>
			fs.writeFileSync(
				f,
				`import { x } from "./x${i}.js";\nimport { y } from "./y${i}.js";\nexport const v = 1;\n`,
			),
		);
		const second = await checker.checkFilesBatch(files, tmp);

		expect(madgeCalls()).toHaveLength(6);
		expect(findNodeToolBinary).toHaveBeenCalledTimes(1);
		expect(second.stats.commandKind).toBe("local");

		// A different project root is a different resolution — the memo is keyed
		// per root, not per instance.
		await checker.checkFilesBatch(
			[writeSource("d.ts", ["./q.js"], otherRoot)],
			otherRoot,
		);
		expect(findNodeToolBinary).toHaveBeenCalledTimes(2);
		expect(findNodeToolBinary).toHaveBeenLastCalledWith("madge", otherRoot);
	});

	it("re-resolves after a resolved binary disappears", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const bin = installFakeBinary(tmp);
		findNodeToolBinary.mockResolvedValue(bin);
		const file = writeSource("a.ts", ["./b.js"]);

		const checker = new DependencyChecker();
		const first = await checker.checkFilesBatch([file], tmp);
		expect(first.stats.commandKind).toBe("local");
		expect(findNodeToolBinary).toHaveBeenCalledTimes(1);

		// madge is uninstalled mid-session. Pre-memo, resolution re-probed on
		// every spawn and healed itself; a one-way memo would instead fail every
		// remaining spawn of the session.
		fs.rmSync(bin);
		findNodeToolBinary.mockResolvedValue(undefined);
		fs.writeFileSync(
			file,
			'import { b } from "./b.js";\nimport { c } from "./c.js";\nexport const v = 1;\n',
		);
		const second = await checker.checkFilesBatch([file], tmp);

		expect(findNodeToolBinary).toHaveBeenCalledTimes(2);
		expect(second.stats.commandKind).toBe("npx");
	});

	it("coalesces concurrent stale-entry recovery into one probe", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const bin = installFakeBinary(tmp);
		findNodeToolBinary.mockResolvedValue(bin);
		const firstFile = writeSource("first.ts", ["./b.js"]);
		const secondFile = writeSource("second.ts", ["./c.js"]);

		const checker = new DependencyChecker();
		await checker.checkFilesBatch([firstFile], tmp);
		expect(findNodeToolBinary).toHaveBeenCalledTimes(1);

		// Both operations observe the same stale, already-resolved memo. Keep the
		// replacement probe pending so the old implementation's second continuation
		// can delete its replacement and start a duplicate probe.
		fs.rmSync(bin);
		fs.writeFileSync(
			firstFile,
			'import { b } from "./changed.js";\nexport const v = 1;\n',
		);
		findNodeToolBinary.mockImplementation(async () => {
			await new Promise((resolve) => setTimeout(resolve, 10));
			return undefined;
		});
		ensureTool.mockResolvedValue(undefined);
		const [, second] = await Promise.all([
			checker.checkFilesBatch([firstFile], tmp),
			checker.checkFilesBatch([secondFile], tmp),
		]);

		expect(findNodeToolBinary).toHaveBeenCalledTimes(2);
		expect(second.stats.commandKind).toBe("npx");
	});

	it("survives a throwing installer probe and re-attempts on the next batch", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		ensureTool.mockRejectedValue(new Error("installer exploded"));
		const file = writeSource("a.ts", ["./b.js"]);

		const checker = new DependencyChecker();
		const first = await checker.checkFilesBatch([file], tmp);
		expect(first.stats.commandKind).toBe("npx");
		expect(first.results.get(file)?.checked).toBe(true);

		// npx is never pinned, so one transient installer failure must not disable
		// managed resolution for the rest of the session.
		const managed = path.join(
			MANAGED_TOOLS_DIR,
			"node_modules",
			".bin",
			"madge",
		);
		ensureTool.mockResolvedValue(managed);
		fs.writeFileSync(
			file,
			'import { b } from "./b.js";\nimport { c } from "./c.js";\nexport const v = 1;\n',
		);
		const second = await checker.checkFilesBatch([file], tmp);

		expect(ensureTool).toHaveBeenCalledTimes(2);
		expect(second.stats.commandKind).toBe("managed");
	});

	it("revalidates a cached bare-command resolution's spawnability once, not per checkFile call (#1276 P2)", async () => {
		const { DependencyChecker, resetMadgeManagedPathMemo } =
			await import("../../clients/dependency-checker.js");
		// Nothing local/global; installer discovery hands back a bare `madge` on
		// PATH (kind "path" — not absolute, so classifyMadgeKind's existsSync
		// shortcut never applies and every cache hit goes through
		// resolvedCommandIsStale's isSpawnableCommand branch).
		findNodeToolBinary.mockResolvedValue(undefined);
		ensureTool.mockResolvedValue("madge");
		isSpawnableCommand.mockResolvedValue(true);

		const checker = new DependencyChecker();
		const files = [
			writeSource("a.ts", ["./x.js"]),
			writeSource("b.ts", ["./y.js"]),
			writeSource("c.ts", ["./z.js"]),
		];

		// First call resolves cold — no memo entry exists yet, so there is
		// nothing to revalidate and `isSpawnableCommand` is not consulted.
		await checker.checkFile(files[0], tmp);
		expect(isSpawnableCommand).toHaveBeenCalledTimes(0);

		// Two more cached-resolution hits (different files force
		// `importsChanged`, so each one reaches `resolveMadge` again). Pre-fix,
		// `resolvedCommandIsStale` re-ran `isSpawnableCommand`'s synchronous PATH
		// walk on every one of these; post-fix the answer is memoized alongside
		// the madge-command memo after the first revalidation and is not
		// re-probed again.
		await checker.checkFile(files[1], tmp);
		await checker.checkFile(files[2], tmp);
		expect(isSpawnableCommand).toHaveBeenCalledTimes(1);
		expect(ensureTool).toHaveBeenCalledTimes(1);

		// A completed install still invalidates the cached spawnability answer,
		// exactly like it invalidates the madge-command memo itself. The next
		// resolution is cold again (no isSpawnableCommand call, same as the very
		// first call above); the one after THAT hits the freshly-repopulated
		// cache and revalidates once more.
		resetMadgeManagedPathMemo();
		fs.writeFileSync(
			files[0],
			'import { query } from "./q.js";\nexport const v = 1;\n',
		);
		await checker.checkFile(files[0], tmp);
		expect(isSpawnableCommand).toHaveBeenCalledTimes(1);

		fs.writeFileSync(
			files[1],
			'import { result } from "./r.js";\nexport const v = 1;\n',
		);
		await checker.checkFile(files[1], tmp);
		expect(isSpawnableCommand).toHaveBeenCalledTimes(2);
	});
});

tests/clients/dependency-checker-state-g:
/**
 * #766: cross-operation ordering of the shared circular-dep state.
 *
 * `lastCircular`/`circularFiles` are instance state that every madge run
 * OVERWRITES wholesale, and three writers race for it: turn-end batches,
 * `checkFile`, and the background `scanProject` (runtime-session and
 * project-diagnostics/fresh-fetch both drive one). Folding in array order fixes
 * ordering WITHIN a batch, but nothing stopped an operation that started against
 * OLDER file content from finishing last and resurrecting its stale view over
 * newer state.
 *
 * Each operation now takes a generation when it classifies and publishes only
 * while that generation is still the newest. These tests deliberately reverse
 * completion order against classification order, so a checker without the guard
 * fails them.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { removeTempDirSync } from "./test-utils.js";

const safeSpawnAsync = vi.fn();
const safeSpawn = vi.fn();
const findNodeToolBinary = vi.fn();
const ensureTool = vi.fn();

vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../clients/safe-spawn.js")>()),
	safeSpawnAsync,
	safeSpawn,
}));
vi.mock("../../clients/package-manager.js", async (importOriginal) => ({
	...(await importOriginal<
		typeof import("../../clients/package-manager.js")
	>()),
	findNodeToolBinary,
}));
vi.mock("../../clients/installer/index.js", () => ({
	// #2140: the probe resolver asks the installer for a release-managed
	// binary (`~/.pi-lens/bin`) before falling back to PATH. Undefined is
	// "no managed install", which is what these tests already assumed.
	findManagedToolBinary: vi.fn(async () => undefined),
	ensureTool,
	getManagedToolsDir: () => path.join(os.tmpdir(), "pilens-fake-home", "tools"),
	// #1276: stubbed for the same reason as the sibling madge test files — see
	// dependency-checker-madge-resolution.test.ts.
	isSpawnableCommand: vi.fn(async () => true),
}));

const VERSION_OK = {
	status: 0,
	error: null,
	stdout: "madge 8.0.0",
	stderr: "",
};

describe("DependencyChecker shared-state generation guard (#766)", () => {
	let tmp: string;

	beforeEach(() => {
		vi.resetAllMocks();
		tmp = fs.mkdtempSync(path.join(os.tmpdir(), "pi-lens-pilens-madge-gen-"));
		findNodeToolBinary.mockResolvedValue("/fake/bin/madge");
		ensureTool.mockResolvedValue(undefined);
	});

	afterEach(() => {
		removeTempDirSync(tmp);
	});

	function writeSource(name: string, imports: string[]): string {
		const file = path.join(tmp, name);
		fs.writeFileSync(
			file,
			`${imports.map((i) => `import { x } from "${i}";`).join("\n")}\nexport const v = 1;\n`,
		);
		return file;
	}

	/** A gate the test opens by hand, so ordering never depends on wall-clock. */
	function makeGate(): { wait: Promise<void>; open: () => void } {
		let open!: () => void;
		const wait = new Promise<void>((resolve) => {
			open = resolve;
		});
		return { wait, open };
	}

	it("drops a slow older batch's publish once a newer batch has published", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const x = writeSource("x.ts", ["./b.js"]);
		const gate = makeGate();
		let spawns = 0;

		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args[0] === "--version") return VERSION_OK;
			spawns++;
			if (spawns === 1) {
				// The OLD run: started first, finishes last, reports a cycle.
				await gate.wait;
				return {
					status: 0,
					error: null,
					stdout: JSON.stringify([[x, path.join(tmp, "b.ts")]]),
					stderr: "",
				};
			}
			// The NEW run, against the edited imports: no cycle.
			return { status: 0, error: null, stdout: "[]", stderr: "" };
		});

		const checker = new DependencyChecker();
		const stale = checker.checkFilesBatch([x], tmp);
		await vi.waitFor(() => expect(spawns).toBe(1));

		// x's imports change while the first batch is still spawning.
		fs.writeFileSync(
			x,
			'import { b } from "./b.js";\nimport { c } from "./c.js";\nexport const v = 1;\n',
		);
		const fresh = await checker.checkFilesBatch([x], tmp);

		gate.open();
		const staleResult = await stale;

		// Changed content re-runs madge — the guard adds no result cache (#533).
		expect(spawns).toBe(2);
		expect(fresh.results.get(x)?.hasCircular).toBe(false);
		// Each batch's own returned result still comes from its own spawn...
		expect(staleResult.results.get(x)?.hasCircular).toBe(true);
		// ...but the older classification cannot overwrite the newer publish.
		expect(checker.isInCircular(x)).toBe(false);
		expect(checker.getCircularForFile(x)).toEqual([]);
	});

	it("lets an older publish land when the newer batch learned nothing", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const x = writeSource("x.ts", ["./b.js"]);
		const unchanged = writeSource("h.ts", ["./k.js"]);
		const gate = makeGate();
		let spawns = 0;

		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args[0] === "--version") return VERSION_OK;
			spawns++;
			await gate.wait;
			return {
				status: 0,
				error: null,
				stdout: JSON.stringify([[x, path.join(tmp, "b.ts")]]),
				stderr: "",
			};
		});

		const checker = new DependencyChecker();
		// Seed h.ts's import cache so the later batch is pure cache hits.
		expect(checker.importsChanged(unchanged)).toBe(true);

		const slow = checker.checkFilesBatch([x], tmp);
		await vi.waitFor(() => expect(spawns).toBe(1));

		const idle = await checker.checkFilesBatch([unchanged], tmp);
		expect(idle.stats.spawned).toBe(0);
		expect(idle.stats.cacheHits).toBe(1);

		gate.open();
		await slow;

		// The newer batch folded nothing, so it published nothing and must not
		// have advanced the generation past an older op's legitimate write.
		expect(checker.isInCircular(x)).toBe(true);
	});

	it("makes a slow project scan lose to a newer batch too", async () => {
		const { DependencyChecker } =
			await import("../../clients/dependency-checker.js");
		const y = writeSource("y.ts", ["./z.js"]);
		const x = writeSource("x.ts", ["./b.js"]);
		const gate = makeGate();
		let scanStarted = false;

		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args[0] === "--version") return VERSION_OK;
			if (args[args.length - 1] === tmp) {
				// The whole-project scan: classified first, finishes last.
				scanStarted = true;
				await gate.wait;
				return {
					status: 0,
					error: null,
					// madge's real `--circular --json` shape: an array of cycles,
					// each an array of members. This double used to hand the scan a
					// GRAPH object, which the scan's own parse then read the same
					// wrong way — the double agreed with the defect (#3428), so the
					// generation axis this test owns was being pinned against output
					// madge never emits.
					stdout: JSON.stringify([[y, path.join(tmp, "z.ts")]]),
					stderr: "",
				};
			}
			return { status: 0, error: null, stdout: "[]", stderr: "" };
		});

		const checker = new DependencyChecker();
		const scan = checker.scanProject(tmp);
		await vi.waitFor(() => expect(scanStarted).toBe(true));

		const fresh = await checker.checkFilesBatch([x], tmp);

		gate.open();
		const scanResult = await scan;

		// The scan still reports its own findings to its own caller...
		expect(scanResult.count).toBe(1);
		expect(fresh.results.get(x)?.hasCircular).toBe(false);
		// ...and leaves the newer batch's published state alone.
		expect(checker.isInCircular(y)).toBe(false);
	});
});

tests/clients/dispatch/formatter-exit-co:
/**
 * Formatter exit-code posture guard (#1337, generalizing #1336).
 *
 * #1336: `ruff format` rejected invented `--indent-style` flags and exited 2.
 * Exit-code strictness was OPT-IN (`strictExitCode`) and ruff had not opted in,
 * so `formatFile` ignored the exit, read the untouched file back, and returned
 * `{ success: true, changed: false }` — byte-identical to "already formatted".
 * Every unconfigured Python file silently went unformatted for a release cycle.
 *
 * The flag was the accident; the DEFAULT was the defect. #1337 inverts it: the
 * seam is strict unless a formatter carries `lenientExitCode`, whose value is
 * the documented benign-nonzero evidence (a string, so the justification is
 * structurally required — an opt-out cannot be added without writing why).
 *
 * Two layers here:
 *  1. POSTURE — a static audit of every entry in ALL_FORMATTERS, pinning the
 *     lenient set so a new opt-out cannot ride in unnoticed.
 *  2. SEAM — the behavior itself: a nonzero exit from a formatter that has not
 *     opted out must never read as `{ success: true, changed: false }`.
 */

import * as fs from "node:fs";
import * as path from "node:path";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { setupTestEnvironment } from "../test-utils.js";

const safeSpawnAsync = vi.fn();
vi.mock("../../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../../clients/safe-spawn.js")>()),
