			touchFile.mockResolvedValue(diagsResult([], { inconclusive: true }));

			const result = await runner.run(ctx(filePath, env.tmpDir) as never);
			expect(result.status).toBe("skipped");
			expect(result.diagnostics).toEqual([]);
