const RUNTIME_INSTALLS = [
	["go", () => tryGoInstallGopls()],
	["dotnet", () => tryDotnetToolInstall("pi-lens-4530-fixture-tool")],
	["gem", () => tryGemInstall("pi-lens-4530-fixture-gem")],
