				removeTempDirSync(cwd);
			}
			safeSpawnAsync.mockResolvedValue(
				result({
					status: 0,
					stdout: fixture,
					error: undefined,
				}),
			);
			await expect(
				verifyToolBinary(binary!, undefined, undefined, 10_000, [
					"--no-globs",
					"-",
				]),
			).resolves.toBe(true);
		},
		15_000,
	);
});

function runProbe(
	binary: string,
	args: string[],
	cwd: string,
	input = "",
): Promise<{ stdout: string; stderr: string }> {
	const command =
		process.platform === "win32" ? (process.env.ComSpec ?? "cmd.exe") : binary;
	const commandArgs =
		process.platform === "win32" ? ["/d", "/c", binary, ...args] : args;
	return new Promise((resolve) => {
		const child = execFile(
			command,
			commandArgs,
			{ cwd, timeout: 10_000 },
			(_error, stdout, stderr) =>
				resolve({ stdout: String(stdout), stderr: String(stderr) }),
		);
		child.stdin?.end(input);
	});
}

function resolveMarkdownlintBinary(): string | undefined {
	const binaryName =
		process.platform === "win32"
			? "markdownlint-cli2.cmd"
			: "markdownlint-cli2";
	const candidates = [
		path.join(
			os.homedir(),
			".pi-lens",
			"tools",
			"node_modules",
			".bin",
			binaryName,
		),
		path.join(process.cwd(), "node_modules", ".bin", binaryName),
		process.env.PI_LENS_2045_MARKDOWNLINT_BIN,
	];
	return candidates.find((candidate) => candidate && fs.existsSync(candidate));
}

