		expect(row?.latestReasons?.[0]?.subject).toBe("cmake-language-server");
	});

	it("keeps a PATH candidate whose probe never ran (a stall is not a verdict)", async () => {
		const root = scratchDir();
		const bin = path.join(root, "bin");
