/**
 * #4505 round 2: `shutdown()` waits for a scan that is still in its
 * availability probe.
 *
 * Recurrence: `scan()` fills `inFlight` only after its own `ensureAvailable()`
 * probe (up to the 1.5 s `probeTimeout`), and the session_start task calls
 * `ensureAvailable()` before `scan()`. A drain inside that window saw an empty
 * map and returned; the fork then exited mid-scan and stranded the
 * `pi-lens-jscpd-*` report directory. The review probe measured `shutdown()`
 * returning at 203 ms for a scan that finished near 2600 ms.
 *
 * The probe and the scan are held at the process boundary (`safeSpawnAsync`),
 * so the real client, availability checker and `shutdown()` run.
 */
describe("jscpd-client shutdown covers the availability probe (#4505)", () => {
	const SPAWN_OK = { error: undefined, status: 0, stdout: "", stderr: "" };

	/** Enough event-loop turns for a drain to return if nothing holds it. */
	async function settleTurns(): Promise<void> {
		for (let turn = 0; turn < 200; turn++)
			await new Promise<void>((resolve) => setImmediate(resolve));
	}

	beforeEach(async () => {
		const safeSpawnMod = await import("../../clients/safe-spawn.js");
		vi.mocked(safeSpawnMod.safeSpawnAsync).mockReset();
		vi.mocked(safeSpawnMod.safeSpawnAsync).mockResolvedValue(SPAWN_OK);
		ensureTool.mockReset();
		findNodeToolBinary.mockReset();
		findNodeToolBinary.mockResolvedValue(null);
		const helpers =
			await import("../../clients/dispatch/runners/utils/runner-helpers.js");
		helpers.resetDispatchAvailabilityState();
	});

	it("waits for the probe and the scan that follows it", async () => {
		const { JscpdClient } = await import("../../clients/jscpd-client.js");
		const safeSpawnMod = await import("../../clients/safe-spawn.js");
		const { tmpDir } = setupTestEnvironment("pi-lens-jscpd-probe-");
		const probe = gatedPromise<typeof SPAWN_OK>();
		const scanSpawn = gatedPromise<typeof SPAWN_OK>();
		try {
			fs.writeFileSync(path.join(tmpDir, "src.ts"), "const x = 1;\n");
			vi.mocked(safeSpawnMod.safeSpawnAsync)
				.mockImplementationOnce((() => probe.promise) as never)
				.mockImplementationOnce((() => scanSpawn.promise) as never);
			const client = new JscpdClient(false);
			let scanSettled = false;
			const scan = client.scan(tmpDir).then((result) => {
				scanSettled = true;
				return result;
			});
			let drained = false;
			const drain = client.shutdown().then(() => {
				drained = true;
			});

			await settleTurns();
			expect(drained).toBe(false);

			probe.resolve(SPAWN_OK);
			await settleTurns();
			expect(drained).toBe(false);

			scanSpawn.resolve(SPAWN_OK);
			await drain;
			expect(scanSettled).toBe(true);
			expect((await scan).success).toBe(true);
		} finally {
			probe.resolve(SPAWN_OK);
			scanSpawn.resolve(SPAWN_OK);
			await cleanupTestEnvironmentsDrained("pi-lens-jscpd-");
		}
	});

	it("keeps waiting when a second probe starts after the first settles", async () => {
		// session_start's task shape: ensureAvailable(), then scan(), whose own
		// ensureAvailable() is a second probe that begins after the first one
		// settled. A drain that waits for the probes it sees once returns here.
		const { JscpdClient } = await import("../../clients/jscpd-client.js");
		const safeSpawnMod = await import("../../clients/safe-spawn.js");
		const helpers =
			await import("../../clients/dispatch/runners/utils/runner-helpers.js");
		const { tmpDir } = setupTestEnvironment("pi-lens-jscpd-probe2-");
		const first = gatedPromise<typeof SPAWN_OK>();
		const second = gatedPromise<typeof SPAWN_OK>();
		const scanSpawn = gatedPromise<typeof SPAWN_OK>();
		try {
			fs.writeFileSync(path.join(tmpDir, "src.ts"), "const x = 1;\n");
			vi.mocked(safeSpawnMod.safeSpawnAsync)
				.mockImplementationOnce((() => first.promise) as never)
				.mockImplementationOnce((() => second.promise) as never)
				.mockImplementationOnce((() => scanSpawn.promise) as never);
			const client = new JscpdClient(false);
			let chainSettled = false;
			const chain = (async () => {
				await client.ensureAvailable();
				// A fresh probe for the scan's own check, as after a cooldown.
				helpers.resetDispatchAvailabilityState();
				return client.scan(tmpDir);
			})().then((result) => {
				chainSettled = true;
				return result;
			});
			let drained = false;
			const drain = client.shutdown().then(() => {
				drained = true;
			});

			first.resolve(SPAWN_OK);
			await settleTurns();
			expect(drained).toBe(false);

			second.resolve(SPAWN_OK);
			await settleTurns();
			expect(drained).toBe(false);

			scanSpawn.resolve(SPAWN_OK);
			await drain;
			expect(chainSettled).toBe(true);
			expect((await chain).success).toBe(true);
		} finally {
			first.resolve(SPAWN_OK);
			second.resolve(SPAWN_OK);
			scanSpawn.resolve(SPAWN_OK);
			await cleanupTestEnvironmentsDrained("pi-lens-jscpd-");
		}
	});
});

tests/clients/knip-cache-consumer-stalen:
import { spawnSync } from "node:child_process";
import * as fs from "node:fs";
import * as path from "node:path";
import { describe, expect, it } from "vitest";
import * as os from "node:os";
import { fileURLToPath } from "node:url";
import { getProjectDataDir } from "../../clients/file-utils.js";
import { KnipClient } from "../../clients/knip-client.js";
import { resetProjectTrust } from "../../clients/project-trust.js";
import { setupTestEnvironment } from "./test-utils.js";

// End-to-end proof for #1630 against the real knip binary. knip's glob cache
// only revalidates directories that contributed a matched path, so a consumer
// added to a directory that matched nothing stays invisible and the export it
// imports keeps being reported as unused. Fixed upstream in knip 6.28.0; this
// test still guards the pi-lens side, which must stay correct on the older
// versions the managed install can resolve to.
//
// Skipped where knip is not installed. The version-independent regression is
// the glob-cache prune assertion in knip-client.test.ts, which always runs.
const probeKnip = (env?: NodeJS.ProcessEnv): boolean => {
	try {
		return (
			spawnSync("knip", ["--version"], {
				shell: process.platform === "win32",
				encoding: "utf8",
				env: env ?? process.env,
			}).status === 0
		);
	} catch {
		return false;
	}
};

// The suite redirects PI_LENS_HOME to a per-worker temp dir, so the client's
// managed-tool lookup cannot see a real knip install. Find that install through
// the real home dir and put its bin dir on PATH for the duration of the test.
const managedKnipBinDir = (() => {
	const dir = path.join(
		os.homedir(),
		".pi-lens",
		"tools",
		"node_modules",
		".bin",
	);
	return fs.existsSync(dir) ? dir : null;
})();

// A dev box answers knip through that managed install. CI and the pre-push hook
// have none, and their only knip is this checkout's own devDependency, which a
// bare `knip` reaches only when `node_modules/.bin` is on PATH — `npm test`
// arranges that, a direct vitest run does not. Name it here so both
// environments drive the same binary (#4566 CI red).
const checkoutKnipBinDir = (() => {
	const dir = path.resolve(
		path.dirname(fileURLToPath(import.meta.url)),
		"..",
		"..",
		"node_modules",
		".bin",
	);
	return fs.existsSync(path.join(dir, "knip")) ? dir : null;
})();

const knipBinDir = managedKnipBinDir ?? checkoutKnipBinDir;

const knipAvailable = probeKnip(
	knipBinDir
		? {
				...process.env,
				PATH: `${knipBinDir}${path.delimiter}${process.env.PATH ?? ""}`,
			}
		: undefined,
);

describe("knip cache consumer-import staleness (#1630)", () => {
	it.skipIf(!knipAvailable)(
		"reports no unused export after a new test imports it",
		async () => {
			const { tmpDir, cleanup } = setupTestEnvironment("pi-lens-knip-1630-");
			const originalPath = process.env.PATH;
			// #4566 F6: the analyzed fixture is untrusted; the checkout's
			// devDependency is outside that fixture and remains usable.
			const originalCwd = process.cwd();
			process.chdir(tmpDir);
			try {
				if (knipBinDir) {
					process.env.PATH = `${knipBinDir}${path.delimiter}${originalPath ?? ""}`;
				}

				fs.mkdirSync(path.join(tmpDir, "src"), { recursive: true });
				// `tests/` exists but matches nothing at cache time — the exact
				// shape knip's glob cache fails to revalidate.
				fs.mkdirSync(path.join(tmpDir, "tests"), { recursive: true });
				fs.writeFileSync(
					path.join(tmpDir, "package.json"),
					JSON.stringify({
						name: "knip-1630",
						version: "1.0.0",
						private: true,
						type: "module",
					}),
				);
				fs.writeFileSync(
					path.join(tmpDir, "knip.json"),
					JSON.stringify({
						entry: ["src/index.ts", "tests/**/*.test.ts"],
						project: ["src/**/*.ts", "tests/**/*.ts"],
					}),
				);
				fs.writeFileSync(
					path.join(tmpDir, "src", "util.ts"),
					"export function assertSafeForCmdShell(s: string): string { return s; }\n" +
						'export function used(): string { return "x"; }\n',
				);
				fs.writeFileSync(
					path.join(tmpDir, "src", "index.ts"),
					'import { used } from "./util.js";\nconsole.log(used());\n',
				);

				const cacheLocation = path.join(
					getProjectDataDir(tmpDir),
					"cache",
					"knip",
				);
				fs.rmSync(cacheLocation, { recursive: true, force: true });

				const client = new KnipClient(false);

				const first = await client.analyze(tmpDir);
				expect(first.success).toBe(true);
				// Baseline: with no consumer, knip flags the export.
				expect(first.unusedExports.map((e) => e.name)).toContain(
					"assertSafeForCmdShell",
				);
				expect(fs.existsSync(cacheLocation)).toBe(true);

				fs.writeFileSync(
					path.join(tmpDir, "tests", "consumer.test.ts"),
					'import { assertSafeForCmdShell } from "../src/util.js";\n' +
						'export const t = assertSafeForCmdShell("a");\n',
				);

				const second = await client.analyze(tmpDir);
				expect(second.success).toBe(true);
				expect(second.unusedExports.map((e) => e.name)).not.toContain(
					"assertSafeForCmdShell",
				);
			} finally {
				process.env.PATH = originalPath;
				process.chdir(originalCwd);
				resetProjectTrust();
				cleanup();
			}
		},
		120_000,
	);
});

