	it("re-records when the resolved config changes under the same root", async () => {
		const { tmpDir, cleanup } = setupTestEnvironment("pi-lens-knip-rerecord-");
		try {
			fs.writeFileSync(path.join(tmpDir, "package.json"), '{"name":"demo"}');

