			await client.runAnalyze(tmpDir);
			fs.writeFileSync(path.join(tmpDir, "knip.json"), "{}");
			await client.runAnalyze(tmpDir);

			const rows = await toolchainRows();
			expect(rows).toHaveLength(2);
			expect(rows[1]).toContain("config=knip.json");
		} finally {
			cleanup();
		}
