				const launched = await withLspProjectCodePermission(false, () =>
					launchLSP("yaml-language-server", [], { cwd: root }),
				);
				expect(launched.pid).toBe(9876);
				expect(spawn.mock.calls.map(([command]) => command)).toContain(shim);
			} finally {
				resetProjectTrust();
			}
		},
	);

