				const { TypeScriptServer } =
					await import("../../../clients/lsp/server.js");
				const spawned = await TypeScriptServer.spawn(tree.project, {
					allowInstall: false,
				});
				const launches =
					outsideCompiler || (trust === "trusted" && projectCompiler);
