				"lookup dir inside the project ignored: mark the project trusted in pi or upgrade pi",
			]);
			const ledger = await import("../../../clients/degradation-ledger.js");
			expect(ledger.getDegradationSummary()).toEqual(
				expect.arrayContaining([
					expect.objectContaining({ kind: "trust-refusal" }),
					expect.objectContaining({
						kind: "lsp-registry-decision",
						latestReasons: expect.arrayContaining([
							expect.objectContaining({
								subject: expect.stringMatching(/^typescript-compiler:/),
							}),
						]),
					}),
				]),
			);
		});

		it("emits one trust notice for several refused PATH entries (husky's relative entry)", async () => {
			const tree = buildPathTscTree("multi-refusal");
			// The project compiler sits outside the `node_modules/typescript`
			// ancestor walk, so only a refused PATH route can find it. Husky's
			// `.husky/_/h` prepends the relative `node_modules/.bin`, a second
			// entry that reaches the same untrusted project: both are refused and
			// each records a ledger row, but the notice must stay one.
			const projectPkg = path.join(
				tree.project,
				"tools",
				"node_modules",
				"typescript",
			);
			fs.mkdirSync(path.join(projectPkg, "bin"), { recursive: true });
			fs.mkdirSync(path.join(projectPkg, "lib"), { recursive: true });
			fs.mkdirSync(path.join(tree.project, "tools", "bin"), {
				recursive: true,
			});
			fs.writeFileSync(
				path.join(projectPkg, "package.json"),
				`${JSON.stringify({ name: "typescript", version: "5.9.3" })}\n`,
			);
			fs.writeFileSync(
				path.join(projectPkg, "bin", "tsc"),
				"#!/usr/bin/env node\n",
			);
			fs.chmodSync(path.join(projectPkg, "bin", "tsc"), 0o755);
			fs.writeFileSync(
				path.join(projectPkg, "lib", "tsserver.js"),
				"// project code\n",
			);
			fs.symlinkSync(
				path.join("..", "node_modules", "typescript", "bin", "tsc"),
				path.join(tree.project, "tools", "bin", "tsc"),
			);
			const finderBin = path.join(path.dirname(tree.project), "finder-bin");
			fs.mkdirSync(finderBin);
			fs.symlinkSync("/usr/bin/which", path.join(finderBin, "which"));
			process.chdir(tree.project);
			process.env.PATH = [
				path.join(tree.project, "tools", "bin"),
				"node_modules/.bin",
				finderBin,
			].join(path.delimiter);
			const { setProjectTrustState } =
				await import("../../../clients/project-trust.js");
			setProjectTrustState("unknown");
			const { TypeScriptServer } =
				await import("../../../clients/lsp/server.js");

			const spawned = await TypeScriptServer.spawn(tree.project, {
				allowInstall: false,
			});

			expect(spawned).toBeUndefined();
			expect(launchLSPMock).not.toHaveBeenCalled();
			expect(
				warnMessages().filter((message) => TRUST_WORDING.test(message)),
			).toEqual([
				"lookup dir inside the project ignored: mark the project trusted in pi or upgrade pi",
			]);
			const ledger = await import("../../../clients/degradation-ledger.js");
			const trustRow = ledger
				.getDegradationSummary()
				.find((row) => row.kind === "trust-refusal");
			expect(trustRow?.count).toBe(2);
			expect(trustRow?.latestReasons.map((entry) => entry.subject)).toEqual(
				expect.arrayContaining([
					"project-path-entry:node_modules/.bin",
					`project-path-entry:${path.join(tree.project, "tools", "bin")}`,
				]),
			);
		});
	},
);

tests/clients/package-manager-availabili:
/**
 * #1496 — `isAvailable` in `package-manager.ts` memoized a `where`/`which <pm>`
 * probe for the life of the process. A timeout (a 5 s host-side budget, the
 * same shape as #1467/#1476) was remembered as "this manager is not
 * installed", so a declared pnpm/yarn manager would silently fall back to npm
 * for the rest of the session. The affected call sites are internal (installs
 * into pi-lens's managed tools directory, `pilens_rebuild` on a source
 * checkout) — no user-project lockfile was ever at risk.
 *
 * These tests exercise `resolveNodePackageManager`, the public surface every
 * caller (the installer, `pilens_rebuild`) actually uses, rather than the
 * private `isAvailable` memo directly. `safeSpawnAsync` is mocked; the probe
 * command (`where`/`which <pm>`) is asserted on directly so the test does not
 * depend on which implementation function issues it.
 */

import { readFileSync } from "node:fs";
import fc from "fast-check";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { TRANSIENT_BASE_COOLDOWN_MS } from "../../clients/dispatch/runners/utils/availability-policy.js";
import { setupTestEnvironment, useTrackedTempDirs } from "./test-utils.js";

const { safeSpawnAsync } = vi.hoisted(() => ({ safeSpawnAsync: vi.fn() }));

// `isCommandAvailableAsync` is reimplemented here (not `importOriginal`'d):
// the real function's internal call to `safeSpawnAsync` is bound to its OWN
// module's unmocked binding, not this mock, so importing it would silently
// bypass the mock and hit the real system PATH. Pre-fix `package-manager.ts`
// probes through `isCommandAvailableAsync`; post-fix code calls
// `safeSpawnAsync` directly. Routing both through the same hoisted mock lets
// one test file exercise both at the same boundary.
vi.mock("../../clients/safe-spawn.js", () => ({
	safeSpawnAsync,
	safeSpawn: vi.fn(),
	isCommandAvailableAsync: async (command: string) => {
		const finder = process.platform === "win32" ? "where" : "which";
		const result = await safeSpawnAsync(finder, [command], { timeout: 5000 });
		return result.status === 0 && !result.error;
	},
}));

const timeoutResult = {
	stdout: "",
	stderr: "",
	status: null,
	error: new Error("Process timed out after 5000ms"),
	failure: "timeout",
	spawnFailure: { kind: "timeout" },
};

/** A real `where`/`which` that ran fine and found nothing: genuine absence. */
const notFoundResult = { stdout: "", stderr: "", status: 1 };

const okResult = (pm: string) => ({ stdout: `${pm}\n`, stderr: "", status: 0 });

function finder(): string {
	return process.platform === "win32" ? "where" : "which";
}

function advancePastCooldown(): void {
	vi.setSystemTime(new Date(Date.now() + TRANSIENT_BASE_COOLDOWN_MS + 1));
}

/** Empty project: no lockfile, no `packageManager` field — nothing declared. */
async function emptyProjectDir(): Promise<string> {
	return setupTestEnvironment("pi-lens-pm-latch-").tmpDir;
}

// Every probe is mocked, so nothing but this file owns these roots.
useTrackedTempDirs("pi-lens-pm-latch-");

beforeEach(() => {
	vi.resetAllMocks();
	vi.useFakeTimers({ toFake: ["Date"] });
	return () => vi.useRealTimers();
});

describe("package-manager availability (#1496)", () => {
	it("pins a successful probe: the declared manager resolves", async () => {
		safeSpawnAsync.mockImplementation(async (cmd: string, args: string[]) =>
			cmd === finder() && args[0] === "pnpm"
				? okResult("pnpm")
				: notFoundResult,
		);
		const { resolveNodePackageManager, _resetPackageManagerCache } =
			await import("../../clients/package-manager.js");
		_resetPackageManagerCache();
		const dir = await emptyProjectDir();
		const fs = await import("node:fs");
		const path = await import("node:path");
		fs.writeFileSync(path.join(dir, "pnpm-lock.yaml"), "");

		expect(await resolveNodePackageManager(dir)).toBe("pnpm");
	});

	it("pins a genuine absence: falls back to npm, latched (no re-probe)", async () => {
		safeSpawnAsync.mockImplementation(async (cmd: string, args: string[]) =>
			cmd === finder() && args[0] === "npm" ? okResult("npm") : notFoundResult,
		);
		const { resolveNodePackageManager, _resetPackageManagerCache } =
			await import("../../clients/package-manager.js");
		_resetPackageManagerCache();
		const dir = await emptyProjectDir();
		const fs = await import("node:fs");
		const path = await import("node:path");
		fs.writeFileSync(path.join(dir, "pnpm-lock.yaml"), "");

		// pnpm is declared but genuinely absent — falls back through PREFERENCE.
		expect(await resolveNodePackageManager(dir)).toBe("npm");
		const probesBefore = safeSpawnAsync.mock.calls.filter(
			([cmd, args]) => cmd === finder() && args[0] === "pnpm",
		).length;
		expect(probesBefore).toBeGreaterThan(0);

		// A genuine absence latches: a second resolve does not re-probe pnpm.
		expect(await resolveNodePackageManager(dir)).toBe("npm");
		const probesAfter = safeSpawnAsync.mock.calls.filter(
			([cmd, args]) => cmd === finder() && args[0] === "pnpm",
		).length;
		expect(probesAfter).toBe(probesBefore);
	});

	/**
	 * THE regression proof (#1496): a project declares pnpm. The first probe
	 * for pnpm times out — a transient host stall, not a fact about the
	 * machine. Pre-fix, that timeout latched `false` forever and every later
	 * resolve silently used npm. Post-fix, the verdict expires on its cooldown
	 * and a later probe that finds pnpm resolves it correctly — no restart
	 * needed. This must FAIL on pre-fix code (pre-fix: pnpm never comes back).
	 */
	it("a timed-out probe expires: pnpm is found on retry, no permanent npm downgrade", async () => {
		safeSpawnAsync.mockImplementation(async (cmd: string, args: string[]) =>
			cmd === finder() && args[0] === "pnpm" ? timeoutResult : notFoundResult,
		);
		const { resolveNodePackageManager, _resetPackageManagerCache } =
			await import("../../clients/package-manager.js");
		_resetPackageManagerCache();
		const dir = await emptyProjectDir();
		const fs = await import("node:fs");
		const path = await import("node:path");
		fs.writeFileSync(path.join(dir, "pnpm-lock.yaml"), "");

		// The stalled first probe falls back to npm for THIS call — acceptable,
		// the session still needs an answer right now.
		expect(await resolveNodePackageManager(dir)).toBe("npm");

		// Now pnpm is reachable again (the stall passed) and the cooldown expires.
		advancePastCooldown();
		safeSpawnAsync.mockImplementation(async (cmd: string, args: string[]) =>
			cmd === finder() && args[0] === "pnpm"
				? okResult("pnpm")
				: notFoundResult,
		);

		// Pre-fix: the timeout latched `false` for pnpm for the life of the
		// process, so this still resolves "npm" and the assertion below fails.
		expect(await resolveNodePackageManager(dir)).toBe("pnpm");
	});

	it("concurrent first-time resolves for the same manager share one probe", async () => {
		safeSpawnAsync.mockImplementation(async (cmd: string, args: string[]) =>
			cmd === finder() && args[0] === "npm" ? okResult("npm") : notFoundResult,
		);
		const { resolveNodePackageManager, _resetPackageManagerCache } =
			await import("../../clients/package-manager.js");
		_resetPackageManagerCache();
		const dir = await emptyProjectDir();

		const results = await Promise.all([
			resolveNodePackageManager(dir),
			resolveNodePackageManager(dir),
			resolveNodePackageManager(dir),
		]);
		expect(results).toEqual(["npm", "npm", "npm"]);
		const npmProbes = safeSpawnAsync.mock.calls.filter(
			([cmd, args]) => cmd === finder() && args[0] === "npm",
		).length;
		expect(npmProbes).toBe(1);
	});

	it("dispatch reset does not tear down an airborne package-manager flight", async () => {
		let pnpmCalls = 0;
		let release!: (value: unknown) => void;
		safeSpawnAsync.mockImplementation(async (cmd: string, args: string[]) => {
			if (cmd === finder() && args[0] === "pnpm") {
				pnpmCalls++;
				return new Promise((resolve) => {
					release = resolve;
				});
			}
			return notFoundResult;
		});
		const { resolveNodePackageManager, _resetPackageManagerCache } =
			await import("../../clients/package-manager.js");
		const { resetDispatchAvailabilityState } =
			await import("../../clients/dispatch/runners/utils/runner-helpers.js");
		_resetPackageManagerCache();
		const dir = await emptyProjectDir();
		const fs = await import("node:fs");
		const path = await import("node:path");
		fs.writeFileSync(path.join(dir, "pnpm-lock.yaml"), "");

		const first = resolveNodePackageManager(dir);
		await Promise.resolve();
		await Promise.resolve();
		resetDispatchAvailabilityState();
		const second = resolveNodePackageManager(dir);
		expect(pnpmCalls).toBe(1);
		release(notFoundResult);
		await Promise.all([first, second]);
	});

	/**
	 * #1653 review F1 — `isAvailable`'s in-flight probe cleared its map entry
	 * unconditionally: `.finally(() => inFlightProbes.delete(pm))`. A probe
	 * started BEFORE a session reset that settles AFTER the next session's own
	 * probe for the same manager has already started deletes that NEWER probe's
	 * entry by key, not by identity — so a third caller arriving in the gap
	 * finds no in-flight probe and spawns a duplicate. Reachable in production
	 * via quick-mode's ~2s warmup racing a `/new` inside the 5s probe budget.
	 * The fix is the identity guard `dependency-checker.ts`'s `resolveMadge`
	 * already uses for the same race: only delete the entry if it is still the
	 * promise this call created.
	 */
	it("a pre-reset probe settling late must not evict the new session's in-flight probe", async () => {
		let pnpmCalls = 0;
		const releasers: Array<(value: unknown) => void> = [];
		safeSpawnAsync.mockImplementation(async (cmd: string, args: string[]) => {
			if (cmd !== finder() || args[0] !== "pnpm") return notFoundResult;
			const idx = pnpmCalls++;
			// The first two pnpm probes (session A's, session B's) are held open
			// under test control; anything past that is the regression itself and
			// must resolve on its own so the test cannot hang either way.
			if (idx < 2) {
				return new Promise((resolve) => {
					releasers[idx] = resolve;
				});
			}
			return notFoundResult;
		});

		const { resolveNodePackageManager, _resetPackageManagerCache } =
			await import("../../clients/package-manager.js");
		_resetPackageManagerCache();
		const dir = await emptyProjectDir();
		const fs = await import("node:fs");
		const path = await import("node:path");
		fs.writeFileSync(path.join(dir, "pnpm-lock.yaml"), "");

		// Session A's probe starts and hangs (call #0).
		const callA = resolveNodePackageManager(dir);
		await Promise.resolve();
		await Promise.resolve();
		expect(releasers[0]).toBeDefined();

		// The session boundary: quick-mode's warmup races a fresh session_start.
		_resetPackageManagerCache();

		// Session B's probe starts fresh (its latch and in-flight map were just
		// cleared) and also hangs (call #1).
		const callB = resolveNodePackageManager(dir);
		await Promise.resolve();
		await Promise.resolve();
		expect(releasers[1]).toBeDefined();

		// Session A's spawn settles first. Flush real macrotasks (fake timers
		// here only fake `Date`, so `setTimeout` still runs) so A's PREFERENCE
		// fallback can reach its second pnpm check BEFORE B's spawn resolves —
		// the exact window the race depends on. If B resolved first, B's own
		// latch would answer A's recheck directly and the in-flight map would
		// never be consulted at all, hiding the bug this test exists to catch.
		releasers[0](notFoundResult);
		await new Promise((resolve) => setTimeout(resolve, 0));
		await new Promise((resolve) => setTimeout(resolve, 0));

		// Now release B. Post-fix, A's recheck already joined B's still-pending
		// probe (awaiting `callA` alone would hang without this); pre-fix, A's
		// recheck already spawned its own third probe and does not need B at
		// all — either way, this unblocks whichever of A/B is still waiting.
		releasers[1](notFoundResult);
		await Promise.all([callA, callB]);

		// Pre-fix: A's unconditional `.finally` deleted B's still-in-flight entry
		// out from under it, so A's own PREFERENCE fallback loop (checking pnpm a
		// second time after the declared manager comes back false) found nothing
		// in-flight and spawned a third probe.
		expect(pnpmCalls).toBe(2);
	});
});

it("keeps transient details for a flight joiner after latch eviction (#4566 r13)", async () => {
	// #4566: the joiner must read the shared verdict, not its replacement latch.
	// Schedule join and eviction requests; cover missing as well as transient
	// so repairing disclosure cannot turn a genuine absence into a transient.
	const { allAvailableGlobalBinDirs, _resetPackageManagerCache } =
		await import("../../clients/package-manager.js");
	const roots = await Promise.all(
		Array.from({ length: 4 }, () => emptyProjectDir()),
	);
	const { clearLatencyLog, flushLatencyLog, getLatencyLogPath } =
		await import("../../clients/latency-logger.js");
	const savedMode = process.env.PI_LENS_TEST_MODE;
	process.env.PI_LENS_TEST_MODE = "0";
	try {
		await fc.assert(
			fc.asyncProperty(
				fc.scheduler(),
				fc.boolean(),
				fc.boolean(),
				async (scheduler, transient, evictFirst) => {
					_resetPackageManagerCache();
					clearLatencyLog();
					await flushLatencyLog();
					let release!: (
						value: typeof timeoutResult | typeof notFoundResult,
					) => void;
					let started!: () => void;
					const pending = new Promise<
						typeof timeoutResult | typeof notFoundResult
					>((resolve) => {
						release = resolve;
					});
					const entered = new Promise<void>((resolve) => {
						started = resolve;
					});
					let pnpmCalls = 0;
					safeSpawnAsync.mockImplementation(
						async (cmd: string, args: string[]) => {
							if (cmd === finder() && args[0] === "pnpm" && ++pnpmCalls === 1) {
								started();
								return pending;
							}
							return notFoundResult;
						},
					);
					const firstTransient = vi.fn();
					const joinTransient = vi.fn();
					const first = allAvailableGlobalBinDirs(firstTransient, roots[0]);
					await entered;
					const churn = scheduler
						.schedule(Promise.resolve(), "sibling roots")
						.then(async () => {
							for (const root of roots.slice(1))
								await allAvailableGlobalBinDirs(undefined, root);
						});
					let joiner!: Promise<string[]>;
					const joined = scheduler
						.schedule(Promise.resolve(), "same-key joiner")
						.then(async () => {
							if (evictFirst) await churn;
							joiner = allAvailableGlobalBinDirs(joinTransient, roots[0]);
							await Promise.resolve();
							await Promise.resolve();
						});
					await scheduler.waitFor(Promise.all([churn, joined]));
					release(transient ? timeoutResult : notFoundResult);
					await Promise.all([first, joiner]);
					expect(firstTransient).toHaveBeenCalledTimes(transient ? 1 : 0);
					expect(joinTransient).toHaveBeenCalledTimes(transient ? 1 : 0);
					expect(pnpmCalls).toBe(4);
					await flushLatencyLog();
					const rows = readFileSync(getLatencyLogPath(), "utf8")
						.trim()
						.split("\n")
						.map((line) => JSON.parse(line))
						.filter(
							(row) =>
								row.phase === "availability_decision" &&
								row.metadata?.tool === "pnpm",
						);
					expect(rows.at(-1)?.metadata).toMatchObject({
						outcome: transient ? "transient" : "missing",
						cause: transient ? "probe-timeout" : "not-found",
						classifiedBy: "probe",
					});
				},
			),
			{ seed: 456613, numRuns: 20 },
		);
	} finally {
		if (savedMode === undefined) delete process.env.PI_LENS_TEST_MODE;
		else process.env.PI_LENS_TEST_MODE = savedMode;
	}
});

tests/clients/package-manager.test.ts:
/**
 * package-manager: declaration detection (real lockfiles in temp dirs),
 * availability-aware resolution, command builders, and global-bin discovery.
 * `safeSpawnAsync` is mocked so the system's real package managers never leak
 * into the assertions. The availability probe now spawns `where`/`which <pm>`
 * directly (#1496), so `onlyAvailable` mocks that call rather than the old
 * `isCommandAvailableAsync` wrapper.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { removeTempDirSync } from "./test-utils.js";
import { waitFor } from "./interleaving-kit.js";
import { gatedPromise } from "../support/fault-injection.js";
import {
	resetProjectTrust,
	setProjectTrustState,
} from "../../clients/project-trust.js";

vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../clients/safe-spawn.js")>()),
	isCommandAvailableAsync: vi.fn(),
	safeSpawnAsync: vi.fn(),
}));
import { SpawnFailureError, safeSpawnAsync } from "../../clients/safe-spawn.js";
import {
	_resetPackageManagerCache,
	allAvailableGlobalBinDirs,
	detectNodePackageManager,
	findGlobalBinary,
	findLocalBinAt,
	findNodeToolBinary,
	installArgs,
	pmBinary,
	resolveNodePackageManager,
	runScriptArgs,
	updateArgs,
} from "../../clients/package-manager.js";

const dirs: string[] = [];

function tmpDir(): string {
	const dir = fs.mkdtempSync(path.join(os.tmpdir(), "pi-lens-pm-"));
	dirs.push(dir);
	return dir;
}

function projectWith(files: Record<string, string>): string {
	const dir = tmpDir();
	for (const [name, content] of Object.entries(files)) {
		fs.writeFileSync(path.join(dir, name), content);
	}
	return dir;
}

/**
 * The availability probe spawns `where`/`which <pm>` directly (#1496); a
 * non-probe call (e.g. `npm config get prefix`, `pnpm bin -g`) falls through
 * to `queryResponder`, which individual tests set to answer those queries.
 */
let queryResponder:
	| ((
			cmd: string,
			args: string[],
	  ) => Promise<{
			stdout: string;
			stderr: string;
			status: number | null;
			error?: Error;
	  }>)
	| null = null;
/** Every non-probe (query) call `onlyAvailable`'s mock forwarded — asserts on this, not on `safeSpawnAsync` overall, since the availability probe itself now spawns too. */
let queryCalls: Array<{ cmd: string; args: string[] }> = [];

function setQueryResponder(
	responder: (
		cmd: string,
		args: string[],
	) => Promise<{
		stdout: string;
		stderr: string;
		status: number | null;
		error?: Error;
	}>,
): void {
	queryResponder = responder;
}

/** Make the `where`/`which <pm>` probe resolve available only for the listed managers. */
function onlyAvailable(...available: string[]): void {
	const set = new Set(available);
	vi.mocked(safeSpawnAsync).mockImplementation(async (cmd, args) => {
		const finder = process.platform === "win32" ? "where" : "which";
		if (cmd === finder) {
			const pm = (args ?? [])[0];
			// A real `where`/`which` runs fine and exits 1 when it finds
			// nothing — no spawn error. That is the "genuine absence" shape.
			return set.has(pm)
				? { stdout: `${pm}\n`, stderr: "", status: 0 }
				: { stdout: "", stderr: "", status: 1 };
		}
		queryCalls.push({ cmd, args: args ?? [] });
		if (queryResponder) return queryResponder(cmd, args ?? []);
		return { stdout: "", stderr: "", status: 1 };
	});
}

/** Override process.platform for a test; restored in afterEach. */
let savedPlatform: PropertyDescriptor | undefined;
function setPlatform(platform: NodeJS.Platform): void {
	savedPlatform = Object.getOwnPropertyDescriptor(process, "platform");
	Object.defineProperty(process, "platform", { value: platform });
}

beforeEach(() => {
	setProjectTrustState("trusted");
	_resetPackageManagerCache();
	vi.mocked(safeSpawnAsync).mockReset();
	queryResponder = null;
	queryCalls = [];
});

afterEach(() => {
	resetProjectTrust();
	if (savedPlatform) {
		Object.defineProperty(process, "platform", savedPlatform);
		savedPlatform = undefined;
	}
});

afterEach(() => {
	for (const dir of dirs.splice(0)) {
		removeTempDirSync(dir);
	}
});

describe("detectNodePackageManager", () => {
	it("maps each lockfile to its manager", () => {
		expect(detectNodePackageManager(projectWith({ "bun.lock": "" }))).toBe(
			"bun",
		);
		expect(detectNodePackageManager(projectWith({ "bun.lockb": "" }))).toBe(
			"bun",
		);
		expect(
			detectNodePackageManager(projectWith({ "pnpm-lock.yaml": "" })),
		).toBe("pnpm");
