import * as fs from "node:fs";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { setupTestEnvironment } from "./test-utils.js";

// Mock only the spawn surface — runAutofix's eslint path is pure spawn +
// before/after file diffing on top of the real autofix policy (which reads
// .eslintrc from disk).
const { safeSpawnAsync } = vi.hoisted(() => ({ safeSpawnAsync: vi.fn() }));
vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../clients/safe-spawn.js")>()),
	safeSpawnAsync,
}));

import { runAutofix } from "../../clients/pipeline.js";

// Regression guard for #453: eslint autofix used to spawn twice
// (--fix-dry-run to count fixable issues, then --fix to apply), doubling
// ESLint's 1-3s cold start. tryEslintFix now runs a single `--fix` spawn and
// detects the fix via before/after file content, same idiom as
// tryStylelintFix/tryOxlintFix/etc. Exit code 1 (unfixable problems remain)
// must still be treated as success when the file changed.
describe("runAutofix — eslint single-spawn --fix (#453)", () => {
	let env: ReturnType<typeof setupTestEnvironment>;
	let filePath: string;

	beforeEach(() => {
		safeSpawnAsync.mockReset();
		env = setupTestEnvironment("pi-lens-eslint-autofix-");
		// eslint is config-first: only selected when a config is present.
		fs.writeFileSync(path.join(env.tmpDir, ".eslintrc.json"), "{}\n");
		fs.writeFileSync(
			path.join(env.tmpDir, "package.json"),
			JSON.stringify({ devDependencies: { eslint: "^10.5.0" } }),
		);
		fs.writeFileSync(
			path.join(env.tmpDir, "package-lock.json"),
			JSON.stringify({
				lockfileVersion: 3,
				packages: { "": {}, "node_modules/eslint": { version: "10.5.0" } },
			}),
		);
		filePath = path.join(env.tmpDir, "messy.js");
		fs.writeFileSync(filePath, "const x = 1\nconsole.log(x)\n");
	});

	afterEach(() => env.cleanup());

	function deps() {
		return {
			biomeClient: {
				isSupportedFile: () => false,
				ensureAvailable: async () => false,
			},
			ruffClient: {
				isPythonFile: () => false,
				ensureAvailable: async () => false,
			},
			fixedThisTurn: new Set<string>(),
		};
	}

	it("spawns eslint exactly once and reports a fix when --fix changes the file", async () => {
		let fixCalls = 0;
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args.includes("--version")) {
				return { error: null, status: 0, stdout: "v10.5.0", stderr: "" };
			}
			// no --fix-dry-run branch: the dry-run spawn must be gone entirely.
			expect(args).not.toContain("--fix-dry-run");
			fixCalls++;
			fs.writeFileSync(filePath, "const x = 1;\nconsole.log(x);\n");
			return { error: null, status: 0, stdout: "", stderr: "" };
		});

		const result = await runAutofix(
			filePath,
			env.tmpDir,
			() => undefined,
			() => {},
			deps() as never,
		);

		expect(fixCalls).toBe(1);
		expect(result.attemptedTools).toContain("eslint");
		expect(result.fixedCount).toBeGreaterThan(0);
		expect(result.autofixTools.some((t) => t.startsWith("eslint"))).toBe(true);
	});

	it("does not report a fix when eslint --fix leaves the file unchanged", async () => {
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args.includes("--version")) {
				return { error: null, status: 0, stdout: "v10.5.0", stderr: "" };
			}
			// file left untouched
			return { error: null, status: 0, stdout: "", stderr: "" };
		});

		const result = await runAutofix(
			filePath,
			env.tmpDir,
			() => undefined,
			() => {},
			deps() as never,
		);

		expect(result.fixedCount).toBe(0);
	});

	it("still counts as fixed when eslint exits 1 (unfixable problems remain) but the file changed", async () => {
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args.includes("--version")) {
				return { error: null, status: 0, stdout: "v10.5.0", stderr: "" };
			}
			fs.writeFileSync(filePath, "const x = 1;\nconsole.log(x);\n");
			return { error: null, status: 1, stdout: "", stderr: "" };
		});

		const result = await runAutofix(
			filePath,
			env.tmpDir,
			() => undefined,
			() => {},
			deps() as never,
		);

		expect(result.fixedCount).toBeGreaterThan(0);
	});
});

tests/clients/pipeline-eslint-availabili:
/**
 * #1494 — `tryEslintFix` memoized its `eslint --version` verdict per cwd+PATH
 * in a bounded LRU with no transient split, so one stalled probe stopped eslint
 * autofix for that project until the entry was evicted or the host restarted.
 * The verdict now belongs to the shared availability latch: only a genuine
 * absence sticks.
 */

import * as fs from "node:fs";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { setupTestEnvironment } from "./test-utils.js";
import {
	HOST_STALL_COOLDOWN_MS,
	TRANSIENT_BASE_COOLDOWN_MS,
} from "../../clients/dispatch/runners/utils/availability-policy.js";

const { safeSpawnAsync, logLatencySpy } = vi.hoisted(() => ({
	safeSpawnAsync: vi.fn(),
	logLatencySpy: vi.fn(),
}));
vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../clients/safe-spawn.js")>()),
	safeSpawnAsync,
}));
vi.mock("../../clients/latency-logger.js", async (importOriginal) => ({
	...(await importOriginal()),
	logLatency: logLatencySpy,
	getLastLoggedPhase: () => undefined,
}));

import { runAutofix } from "../../clients/pipeline.js";

const timeoutResult = {
	stdout: "",
	stderr: "",
	status: null,
	error: new Error("Process timed out after 5000ms"),
	failure: "timeout",
	spawnFailure: { kind: "timeout" },
};

describe("eslint autofix availability latch (#1494)", () => {
	let env: ReturnType<typeof setupTestEnvironment>;
	let filePath: string;

	beforeEach(() => {
		safeSpawnAsync.mockReset();
		logLatencySpy.mockReset();
		env = setupTestEnvironment("pi-lens-eslint-latch-");
		fs.writeFileSync(path.join(env.tmpDir, ".eslintrc.json"), "{}\n");
		// #3005 fixture recurrence: availability-latch assertions must reach the
		// real probe, not be declined for absent Node tool agreement first.
		fs.writeFileSync(
			path.join(env.tmpDir, "package.json"),
			JSON.stringify({ devDependencies: { eslint: "^10.5.0" } }),
		);
		fs.writeFileSync(
			path.join(env.tmpDir, "package-lock.json"),
			JSON.stringify({
				lockfileVersion: 3,
				packages: { "": {}, "node_modules/eslint": { version: "10.5.0" } },
			}),
		);
		filePath = path.join(env.tmpDir, "messy.js");
		fs.writeFileSync(filePath, "const x = 1\nconsole.log(x)\n");
		vi.useFakeTimers({ toFake: ["Date"] });
	});

	afterEach(() => {
		vi.useRealTimers();
		env.cleanup();
	});

	function deps() {
		return {
			biomeClient: {
				isSupportedFile: () => false,
				ensureAvailable: async () => false,
			},
			ruffClient: {
				isPythonFile: () => false,
				ensureAvailable: async () => false,
			},
			fixedThisTurn: new Set<string>(),
		};
	}

	const fix = () =>
		runAutofix(
			filePath,
			env.tmpDir,
			() => undefined,
			() => {},
			deps() as never,
		);

	const versionCalls = () =>
		safeSpawnAsync.mock.calls.filter((call) =>
			(call[1] as string[] | undefined)?.includes("--version"),
		).length;

	it("re-probes after a timed-out probe and fixes on the next turn", async () => {
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) =>
			args.includes("--version")
				? timeoutResult
				: { error: null, status: 0, stdout: "", stderr: "" },
		);

		expect((await fix()).fixedCount).toBe(0);
		expect(versionCalls()).toBe(1);
		// Inside the cooldown the verdict is reused rather than re-probed.
		expect((await fix()).fixedCount).toBe(0);
		expect(versionCalls()).toBe(1);

		vi.setSystemTime(new Date(Date.now() + TRANSIENT_BASE_COOLDOWN_MS + 1));
		safeSpawnAsync.mockClear();
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (args.includes("--version")) {
				return { error: null, status: 0, stdout: "v10.5.0", stderr: "" };
			}
			fs.writeFileSync(filePath, "const x = 1;\nconsole.log(x);\n");
			return { error: null, status: 0, stdout: "", stderr: "" };
		});

		expect((await fix()).fixedCount).toBeGreaterThan(0);
		expect(versionCalls()).toBe(1);
		// The record says the first verdict was a timeout, not a missing install.
		expect(
			logLatencySpy.mock.calls
				.map((call) => call[0])
				.find((entry) => entry?.phase === "availability_decision")?.metadata,
		).toMatchObject({ tool: "eslint", outcome: "transient", latched: false });
	});

	it("blames the host when the event loop stalled through the probe window", async () => {
		// The budget is enforced host-side, so a stalled loop expires it while
		// eslint is healthy. Without the stall sampler the timeout is re-caused as
		// `probe-timeout` and gets the escalating 30s cooldown instead of the 5s
		// host-stall one — a six-fold longer outage charged to the wrong party.
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) => {
			if (!args.includes("--version")) {
				return { error: null, status: 0, stdout: "", stderr: "" };
			}
			// The loop was unavailable for 3 s of this probe's window.
			vi.setSystemTime(new Date(Date.now() + 3000));
			return timeoutResult;
		});

		expect((await fix()).fixedCount).toBe(0);
		const decision = logLatencySpy.mock.calls
			.map((call) => call[0])
			.find((entry) => entry?.phase === "availability_decision")?.metadata;
		expect(decision).toMatchObject({
			tool: "eslint",
			outcome: "transient",
			cause: "host-stall",
			retryAfterMs: HOST_STALL_COOLDOWN_MS,
		});
		expect(decision?.hostStallMs).toBeGreaterThanOrEqual(500);
	});

	it("records how the verdict was classified and what the probe returned", async () => {
		// The other half of #1500's leftover: this row landed with no
		// `classifiedBy` and no `evidence` while every other consumer's carried both.
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) =>
			args.includes("--version")
				? {
						stdout: "",
						stderr: "",
						status: null,
						error: Object.assign(new Error("spawn eslint ENOENT"), {
							code: "ENOENT",
						}),
						failure: "spawn",
						spawnFailure: { kind: "tool-not-found" },
					}
				: { error: null, status: 0, stdout: "", stderr: "" },
		);

		expect((await fix()).fixedCount).toBe(0);
		expect(
			logLatencySpy.mock.calls
				.map((call) => call[0])
				.find((entry) => entry?.phase === "availability_decision")?.metadata,
		).toMatchObject({
			tool: "eslint",
			outcome: "missing",
			classifiedBy: "probe",
			evidence: { command: "eslint", errno: "ENOENT" },
		});
	});

	it("latches a genuinely missing eslint and stops probing", async () => {
		safeSpawnAsync.mockImplementation(async (_cmd: string, args: string[]) =>
			args.includes("--version")
				? {
						stdout: "",
						stderr: "",
						status: null,
						error: Object.assign(new Error("spawn ENOENT"), {
							code: "ENOENT",
						}),
						spawnFailure: { kind: "tool-not-found" },
					}
				: { error: null, status: 0, stdout: "", stderr: "" },
		);

		expect((await fix()).fixedCount).toBe(0);
		vi.setSystemTime(new Date(Date.now() + TRANSIENT_BASE_COOLDOWN_MS * 4));
		expect((await fix()).fixedCount).toBe(0);
		expect(versionCalls()).toBe(1);
	});
});

tests/clients/platform-package-resolve.t:
import { existsSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
	resolvePlatformPackageBinary,
	TOOLS,
} from "../../clients/installer/index.js";

const tool = (id: string) => {
	const t = TOOLS.find((x) => x.id === id);
	if (!t) throw new Error(`tool ${id} not found`);
	return t;
};

const supported = new Set([
	"linux-x64",
	"linux-arm64",
	"darwin-x64",
	"darwin-arm64",
	"win32-x64",
	"win32-arm64",
]).has(`${process.platform}-${process.arch}`);

describe("resolvePlatformPackageBinary", () => {
	it("declares platformPackage on the npm platform-CLI tools", () => {
		expect(tool("ast-grep").platformPackage).toBeDefined();
		expect(tool("biome").platformPackage).toBeDefined();
		// pure-JS / non-platform tools must NOT declare it
		expect(tool("knip").platformPackage).toBeUndefined();
		expect(tool("typescript").platformPackage).toBeUndefined();
	});

	it("invariant: platformPackage only on npm-strategy tools (it's an npm-only concept)", () => {
		const offenders = TOOLS.filter(
			(t) => t.platformPackage && t.installStrategy !== "npm",
		).map((t) => `${t.id} (${t.installStrategy})`);
		expect(offenders).toEqual([]);
	});

	it("invariant: every platformPackage tool has a packageName + binaries + suffixes", () => {
		for (const t of TOOLS.filter((x) => x.platformPackage)) {
			expect(t.packageName, t.id).toBeTruthy();
			expect(t.platformPackage?.binaries.length, t.id).toBeGreaterThan(0);
			expect(
				Object.keys(t.platformPackage?.suffixes ?? {}).length,
				t.id,
			).toBeGreaterThan(0);
		}
	});

	it.runIf(supported)(
		"resolves the native ast-grep binary directly (the package that ships it is a runtime dep)",
		() => {
			const bin = resolvePlatformPackageBinary(tool("ast-grep"));
			// @ast-grep/cli-<platform> is installed here (runtime dep), so it resolves.
			expect(bin).toBeTruthy();
			expect(existsSync(bin as string)).toBe(true);
			expect(bin).toMatch(/@ast-grep[/\\]cli-/);
		},
	);

	// #4530 r7: an existing package directory is not a native command.
	it("rejects a directory in a platform package's binary list", () => {
		const native = tool("ast-grep");
		expect(
			resolvePlatformPackageBinary({
				...native,
				platformPackage: { ...native.platformPackage!, binaries: ["."] },
			}),
		).toBeUndefined();
	});

	it("returns undefined for a tool without a platformPackage spec", () => {
		expect(resolvePlatformPackageBinary(tool("knip"))).toBeUndefined();
	});

	it("returns undefined when the platform is unsupported by the spec", () => {
		const fake = {
			...tool("ast-grep"),
			platformPackage: { suffixes: {}, binaries: ["ast-grep"] },
		};
		expect(resolvePlatformPackageBinary(fake)).toBeUndefined();
	});
});

tests/clients/probe-and-root-spawn-cwd.t:
/**
 * #2894 — the two spawn-cwd classes that used to be decided site by site.
 *
 * Recurrence this file prevents (AGENTS.md defect shape 40, "a tool root
 * resolved at a different seam than its child spawn", and the #2872 sweep's
 * admission tables going unauditable):
 *
 * 1. PROBES. 23 availability/version spawns each decided "no cwd" in their own
 *    words, and the sweep carried 23 sentences a reviewer had to re-read one
 *    at a time. `probeToolAsync` owns that decision now, and it STRIPS a cwd
 *    rather than merely omitting one — the failure mode being closed is a
 *    probe that quietly acquires a project directory through an options
 *    object someone widened, which is invisible to the type alone.
 *
 * 2. HAND-DERIVED ROOTS. `ruff-client.ts` computed
 *    `cwd ?? path.dirname(absolutePath)` while `dispatch/runners/ruff.ts`
 *    used `resolveRunnerCwd` for the same file — two derivations for one root,
 *    which `tool-policy.ts`'s own contract says must agree. Measured on
 *    pre-#2894 code, with the caller passing the workspace root and the file
 *    in a nested package that ships its own `pyproject.toml`:
 *
 *      ruff check --output-format json …  cwd=<workspace root>
 *
 *    i.e. the nested package's config never applied. `rust-clippy.ts` had the
 *    same shape with its own `findNearestContaining(dirname(file),
 *    ["Cargo.toml"])` walk, uncapped by the dispatch root.
 *
 * Everything below drives the REAL production paths — the real dispatcher
 * availability probe, the real `RuffClient.fixFileAsync`, the real runner
 * `run()` — and fakes only the process boundary (`safeSpawnAsync`), which is
 * where the child's cwd is observed. A real spawn would show nothing extra
 * and would need `flake-shape-ratchet` admission for a shape the fix does not
 * require.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import type {
	SafeSpawnOptions,
	SpawnResult,
} from "../../clients/safe-spawn.js";

type SafeSpawnAsync = (
	command: string,
	args: string[],
	options?: SafeSpawnOptions,
) => Promise<SpawnResult>;

const spawned: Array<{
	command: string;
	args: string[];
	cwd?: string;
	hasCwdKey: boolean;
}> = [];

const { safeSpawnAsync, findCargoPathAsync } = vi.hoisted(() => ({
	safeSpawnAsync: vi.fn<SafeSpawnAsync>(),
	findCargoPathAsync: vi.fn(async () => "/usr/bin/cargo" as string | null),
}));

// The no-argument `importOriginal()` pass-through is the idiom
// `tests/config/vi-mock-export-sweep.test.ts` recognises as complete (#2784).
vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal()),
	safeSpawnAsync,
}));
vi.mock("../../clients/rust-client.js", async (importOriginal) => {
	const actual = (await importOriginal()) as Record<string, unknown>;
	return {
		...actual,
		rustClient: {
			...(actual.rustClient as object),
			findCargoPathAsync,
		},
	};
});

import { resetDegradationLedger } from "../../clients/degradation-ledger.js";
import { FactStore } from "../../clients/dispatch/fact-store.js";
import { setProjectTrustState } from "../../clients/project-trust.js";
import { probeToolAsync } from "../../clients/tool-probe.js";
import { makeRunnerCtx } from "../support/runner-ctx.js";
import { removeTempDirSync } from "./test-utils.js";

const dirs: string[] = [];
let previousHome: string | undefined;

beforeEach(() => {
	setProjectTrustState("trusted");
	// The seam caps every marker walk at `$HOME` (`isAtOrAboveHomeDir`), so a
	// fixture under the OS temp root is out of reach of its own markers unless
	// the ceiling moves with it. `os.homedir()` reads `$HOME` on POSIX, and
	// pointing it at the temp root is what makes these trees ordinary projects
	// rather than out-of-tree files.
	previousHome = process.env.HOME;
	process.env.HOME = fs.realpathSync(os.tmpdir());
	spawned.length = 0;
	safeSpawnAsync.mockImplementation(async (command, args, options) => {
		spawned.push({
			command,
			args,
			cwd: options?.cwd,
			hasCwdKey: options !== undefined && "cwd" in options,
		});
		return { stdout: "", stderr: "", status: 0 };
	});
	resetDegradationLedger();
});

afterEach(() => {
	for (const dir of dirs.splice(0)) removeTempDirSync(dir);
	if (previousHome === undefined) delete process.env.HOME;
	else process.env.HOME = previousHome;
	vi.clearAllMocks();
});

/** A temp project tree, under the `$HOME` the `beforeEach` pins. */
function makeTree(prefix: string, files: Record<string, string>): string {
	const root = fs.realpathSync(
		fs.mkdtempSync(path.join(os.tmpdir(), `pi-lens-${prefix}-`)),
	);
	dirs.push(root);
	for (const [rel, content] of Object.entries(files)) {
		const full = path.join(root, rel);
		fs.mkdirSync(path.dirname(full), { recursive: true });
		fs.writeFileSync(full, content);
	}
	return root;
}

describe("#2894 probe seam: a tool probe never carries a cwd", () => {
	it("probeToolAsync strips a cwd that reached it inside an options object", async () => {
		// The type forbids `cwd` on a LITERAL; this is the other direction — an
		// already-typed options object widened at the call site, which is what a
		// type alone cannot stop. The strip is what makes the seam's single
		// admission row true for every caller rather than for well-behaved ones.
		const widened = {
			timeout: 1000,
			cwd: "/nested/project",
		} as SafeSpawnOptions;
		await probeToolAsync("sometool", ["--version"], widened);

		expect(spawned).toHaveLength(1);
		expect(spawned[0].cwd).toBeUndefined();
	});

	it("the dispatcher's shared --version probe reaches the child with no cwd", async () => {
		// The real `checkToolAvailability` — the highest-traffic availability
		// consumer in the product, and the seam every `ctx.hasTool(command)`
		// gate goes through.
		const { checkToolAvailability } =
			await import("../../clients/dispatch/dispatcher.js");
		const nested = makeTree("probe-cwd", { "packages/api/main.py": "x = 1\n" });
		const previous = process.cwd();
		process.chdir(path.join(nested, "packages", "api"));
		try {
			// `node` is on PATH in every lane, so the on-disk pre-check that guards
			// the probe passes and the spawn is actually reached.
			expect(await checkToolAvailability("node", new FactStore())).toBe(true);
		} finally {
			process.chdir(previous);
		}

		const probe = spawned.find((call) => call.args[0] === "--version");
		expect(probe, "the availability probe spawned").toBeDefined();
		expect(probe?.cwd).toBeUndefined();
	});
});

describe("#2894 root seam: a hand-derived package root resolves through resolveToolCwd", () => {
	it("ruff autofix runs at the nested package root, not the caller's workspace root", async () => {
		const root = makeTree("ruff-nested", {
			"pyproject.toml": "[tool.ruff]\n",
			"packages/api/pyproject.toml": "[tool.ruff]\n",
			"packages/api/app.py": "import os\n",
		});
		const filePath = path.join(root, "packages", "api", "app.py");
		const { RuffClient } = await import("../../clients/ruff-client.js");

		// The caller (pipeline.ts) passes the dispatch language root. Pre-#2894
		// that value WAS the child's cwd; now it is only the ceiling the seam
		// walks inside.
		await new RuffClient().fixFileAsync(filePath, root);

		const checks = spawned.filter((call) => call.args[0] === "check");
		expect(checks.length, "the pre-scan and the --fix pass").toBe(2);
		for (const call of checks) {
			expect(call.cwd).toBe(path.join(root, "packages", "api"));
		}
	});

	it("cargo clippy runs at the crate root the seam resolves", async () => {
		const root = makeTree("clippy-nested", {
			"Cargo.toml": "[workspace]\n",
			"crates/engine/Cargo.toml": '[package]\nname = "engine"\n',
			"crates/engine/src/lib.rs": "pub fn f() {}\n",
		});
		const filePath = path.join(root, "crates", "engine", "src", "lib.rs");
		const runner = (
			await import("../../clients/dispatch/runners/rust-clippy.js")
		).default;

		await runner.run(makeRunnerCtx(filePath, root, { kind: "rust" }) as never);

		const clippy = spawned.find(
			(call) => call.args[1] === "--message-format=json",
		);
		expect(clippy, "cargo clippy spawned").toBeDefined();
		expect(clippy?.cwd).toBe(path.join(root, "crates", "engine"));
	});

	it("cargo clippy skips rather than running above the dispatch root", async () => {
		// The hand-rolled `findNearestContaining` walk had no ceiling: with the
		// only Cargo.toml ABOVE the dispatch root it ran cargo outside the
		// project pi-lens was asked about. The seam caps at the dispatch root,
		// so the gate — which now asks about the directory cargo would actually
		// start in — declines instead.
		const root = makeTree("clippy-outside", {
			"Cargo.toml": '[package]\nname = "outer"\n',
			"sub/src/lib.rs": "pub fn f() {}\n",
		});
		const filePath = path.join(root, "sub", "src", "lib.rs");
		const runner = (
			await import("../../clients/dispatch/runners/rust-clippy.js")
		).default;

		const result = await runner.run(
			makeRunnerCtx(filePath, path.join(root, "sub"), {
				kind: "rust",
			}) as never,
		);

		expect(result.status).toBe("skipped");
		expect(
			spawned.filter((call) => call.args[1] === "--message-format=json"),
		).toEqual([]);
	});

	it("cargo clippy follows a nearer crate marker created below an already-resolved root", async () => {
		// Recurrence (#2922, probe PA): the seam memoized POSITIVE marker roots
		// per start directory and revalidated only that the marker at the cached
		// root still existed. With a workspace `Cargo.toml` above, the first
		// resolution cached `<ws>`; `cargo init crates/engine` then scaffolded a
		// nearer manifest that stayed invisible for the rest of the session, so
		// `cargo clippy` kept compiling from the workspace root — never linting
		// the new crate, which is not in `[workspace] members` yet — while the
		// runner still reported `succeeded`. The sibling case below starts from an
		// ABSENT marker (#2911's half); this one starts from a positive hit, the
		// direction no test in the tree exercised.
		const root = makeTree("clippy-nearer-later", {
			"Cargo.toml": "[workspace]\n",
			"crates/engine/src/lib.rs": "pub fn f() {}\n",
		});
		const crateRoot = path.join(root, "crates", "engine");
		const filePath = path.join(crateRoot, "src", "lib.rs");
		const runner = (
			await import("../../clients/dispatch/runners/rust-clippy.js")
		).default;

		const first = await runner.run(
			makeRunnerCtx(filePath, root, { kind: "rust" }) as never,
		);
		expect(first.status).toBe("succeeded");

		// `cargo init crates/engine`, mid-session.
		fs.writeFileSync(
			path.join(crateRoot, "Cargo.toml"),
			'[package]\nname = "engine"\n',
		);

		const second = await runner.run(
			makeRunnerCtx(filePath, root, { kind: "rust" }) as never,
		);
		expect(second.status).toBe("succeeded");

		expect(
			spawned
				.filter((call) => call.args[1] === "--message-format=json")
				.map((call) => call.cwd),
		).toEqual([root, crateRoot]);
	});

	it("biome autofix follows a nearer package marker in parity with the runner seam", async () => {
		// #2922 acceptance, the parity half, on a NON-runner consumer.
		// `BiomeClient.fixFileAsync` reaches the same seam through its own
		// `resolveToolCwd("runner", "biome", ...)` call, so the memo hid a
		// `biome.json` scaffolded in a nested package from biome's own config
		// discovery exactly as it hid `Cargo.toml` from clippy — and the two
		// consumers must answer the same question with the same directory.
		const root = makeTree("biome-nearer-later", {
			"biome.json": "{}\n",
			"packages/ui/src/index.ts": "export const a = 1;\n",
		});
		const pkgRoot = path.join(root, "packages", "ui");
		const filePath = path.join(pkgRoot, "src", "index.ts");
		// A trusted project resolves its own biome at the dispatch cwd, so the
		// lint child starts where the resolved binary lives rather than the
		// neutral npx cwd (#4268 acceptance 3).
		for (const dir of [root, pkgRoot]) {
			const bin = path.join(dir, "node_modules", ".bin");
			fs.mkdirSync(bin, { recursive: true });
			// #4530 r7: command acceptance requires the executable bit on POSIX.
			fs.writeFileSync(path.join(bin, "biome"), "", { mode: 0o755 });
			fs.writeFileSync(path.join(bin, "biome.cmd"), "");
		}
		const { BiomeClient } = await import("../../clients/biome-client.js");
		const { resolveToolCwd } = await import("../../clients/tool-cwd.js");
		const client = new BiomeClient();

		await client.fixFileAsync(filePath, root);
		fs.writeFileSync(path.join(pkgRoot, "biome.json"), "{}\n");
		await client.fixFileAsync(filePath, root);

		expect(
			spawned.filter((call) => call.args.includes("lint")).map((c) => c.cwd),
		).toEqual([root, pkgRoot]);
		expect(resolveToolCwd("runner", "biome", filePath, { cwd: root }).cwd).toBe(
			pkgRoot,
		);
	});

	it("cargo clippy sees a crate marker created after its first resolution", async () => {
		const root = makeTree("clippy-created-later", {
			"crates/engine/src/lib.rs": "pub fn f() {}\n",
		});
		const crateRoot = path.join(root, "crates", "engine");
		const filePath = path.join(crateRoot, "src", "lib.rs");
		const runner = (
			await import("../../clients/dispatch/runners/rust-clippy.js")
		).default;

		const first = await runner.run(
			makeRunnerCtx(filePath, root, { kind: "rust" }) as never,
		);
		expect(first.status).toBe("skipped");
		fs.writeFileSync(path.join(crateRoot, "Cargo.toml"), "[package]\n");

		const second = await runner.run(
			makeRunnerCtx(filePath, root, { kind: "rust" }) as never,
		);
		expect(second.status).toBe("succeeded");
		expect(
			spawned.filter((call) => call.args[1] === "--message-format=json"),
		).toHaveLength(1);
	});
});

tests/clients/project-local-bin-trust.te:
/**
 * Witnesses for #4268: project-local executables honour pi's project trust.
 *
 * The shared local-bin lookups (`clients/package-manager.ts`) consult
 * `getProjectTrustState()` and refuse a project-local candidate under
 * unknown/untrusted trust. This file drives the REAL seams:
 *
 *   - `eslintRunner.run` — the witness the issue names — through the real
 *     `resolveToolCommand` and the real availability probe;
 *   - `resolveToolCommand`/`resolveLocalFirstAsync` for oxlint and prisma;
 *   - `prettierFormatter.resolveCommand` for the formatter family;
 *   - `detectPythonEnvironment` for the project `.venv` interpreter.
 *
 * The cache-only npx fallback's CHILD environment (the hostile-`.npmrc`
 * vector) is witnessed at the process boundary in
 * `npx-child-env-isolation.test.ts`; an assertion on
 * `getIsolatedNpxSpawnOptions()`'s own return cannot see the spawn merge.
 *
 * Global and managed binaries stay eligible, so under refusal the runner falls
 * back to a global/PATH command rather than executing the project's shim.
 */
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { makeRunnerCtx } from "../support/runner-ctx.js";
import { setupTestEnvironment } from "./test-utils.js";

const { safeSpawnAsync } = vi.hoisted(() => ({ safeSpawnAsync: vi.fn() }));

vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<Record<string, unknown>>()),
	safeSpawnAsync,
}));

// Config discovery is not what these cases witness; open the eslint gate.
vi.mock("../../clients/tool-policy.js", async (importOriginal) => ({
	...(await importOriginal<Record<string, unknown>>()),
	hasEslintConfig: () => true,
}));

import { resetDegradationLedger } from "../../clients/degradation-ledger.js";
import { resolveToolCommand } from "../../clients/dispatch/runners/utils/runner-helpers.js";
import {
	resetProjectTrust,
	setProjectTrustState,
} from "../../clients/project-trust.js";

/** Plant an executable-looking shim at `<dir>/node_modules/.bin/<name>`. */
function plantNodeBin(dir: string, name: string): string {
	const bin = path.join(dir, "node_modules", ".bin");
	fs.mkdirSync(bin, { recursive: true });
	const target = path.join(bin, name);
	fs.writeFileSync(target, "", { mode: 0o755 });
	fs.writeFileSync(`${target}.cmd`, "");
	return target;
}

const ok = () => ({ error: null, status: 0, stdout: "[]", stderr: "" });

describe("#4268 project-local binary trust gate", () => {
	beforeEach(() => {
		resetDegradationLedger();
		safeSpawnAsync.mockReset();
		safeSpawnAsync.mockResolvedValue(ok());
	});

	afterEach(() => {
		resetProjectTrust();
		vi.unstubAllEnvs();
	});

	it("eslintRunner.run never executes the project's eslint under unknown or untrusted trust", async () => {
		const env = setupTestEnvironment("pi-lens-trust-eslint-");
		try {
			const local = plantNodeBin(env.tmpDir, "eslint");
			const filePath = path.join(env.tmpDir, "sample.ts");
			fs.writeFileSync(filePath, "const a = 1;\n");
			const { default: eslintRunner } =
				await import("../../clients/dispatch/runners/eslint.js");
			const ctx = makeRunnerCtx(filePath, env.tmpDir);
			const commands = (): string[] =>
				safeSpawnAsync.mock.calls.map((c) => c[0] as string);

			for (const trust of ["unknown", "untrusted"] as const) {
				setProjectTrustState(trust);
				safeSpawnAsync.mockClear();
				await eslintRunner.run(ctx as never);
				expect(commands(), `trust=${trust}`).not.toContain(local);
			}

			setProjectTrustState("trusted");
			safeSpawnAsync.mockClear();
			await eslintRunner.run(ctx as never);
			expect(commands()).toContain(local);
		} finally {
			env.cleanup();
		}
	});

	it("resolveToolCommand admits the local oxlint only when trusted", () => {
		const dir = fs.mkdtempSync(path.join(os.tmpdir(), "pi-lens-trust-oxlint-"));
		try {
			const local = plantNodeBin(dir, "oxlint");
			setProjectTrustState("unknown");
			expect(resolveToolCommand(dir, "oxlint")).toBe("oxlint");
			setProjectTrustState("untrusted");
			expect(resolveToolCommand(dir, "oxlint")).toBe("oxlint");
			setProjectTrustState("trusted");
			expect(resolveToolCommand(dir, "oxlint")).toBe(local);
		} finally {
			fs.rmSync(dir, { recursive: true, force: true });
		}
	});

	it("a formatter resolver refuses the project's prettier until trusted", async () => {
		const env = setupTestEnvironment("pi-lens-trust-prettier-");
		try {
			const local = plantNodeBin(env.tmpDir, "prettier");
			const filePath = path.join(env.tmpDir, "app.ts");
			fs.writeFileSync(filePath, "function f() {\n  return 1;\n}\n");
			// No global/managed prettier can answer: every probe fails.
			safeSpawnAsync.mockResolvedValue({
				error: null,
				status: 1,
				stdout: "",
				stderr: "",
			});
			const { prettierFormatter } = await import("../../clients/formatters.js");

			setProjectTrustState("unknown");
			const refused = await prettierFormatter.resolveCommand?.(
				filePath,
				env.tmpDir,
			);
			expect(Array.isArray(refused) ? refused[0] : refused).not.toBe(local);

			setProjectTrustState("trusted");
			const admitted = await prettierFormatter.resolveCommand?.(
				filePath,
				env.tmpDir,
			);
			expect(Array.isArray(admitted) ? admitted[0] : admitted).toBe(local);
		} finally {
			env.cleanup();
		}
	});

	it("detectPythonEnvironment refuses the project's own .venv interpreter until trusted", async () => {
		const env = setupTestEnvironment("pi-lens-trust-venv-");
		try {
			const binDir = path.join(env.tmpDir, ".venv", "bin");
			fs.mkdirSync(binDir, { recursive: true });
			const pythonPath = path.join(binDir, "python");
			fs.writeFileSync(pythonPath, "#!/bin/sh\nexit 0\n", { mode: 0o755 });
			vi.stubEnv("VIRTUAL_ENV", "");
			vi.stubEnv("CONDA_PREFIX", "");
			vi.stubEnv("UV_PROJECT_ENVIRONMENT", "");
			const { detectPythonEnvironment } =
				await import("../../clients/python-environment.js");

			setProjectTrustState("unknown");
			expect(
				await detectPythonEnvironment(env.tmpDir, os.homedir()),
			).toBeUndefined();
			setProjectTrustState("untrusted");
			expect(
				await detectPythonEnvironment(env.tmpDir, os.homedir()),
			).toBeUndefined();
			setProjectTrustState("trusted");
			expect(
				(await detectPythonEnvironment(env.tmpDir, os.homedir()))?.pythonPath,
			).toBe(pythonPath);
		} finally {
			env.cleanup();
		}
	});
});

tests/clients/ruff-client-dedupe.test.ts:
import * as path from "node:path";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { setupTestEnvironment } from "./test-utils.js";

const tmp = setupTestEnvironment("pi-lens-ruff-dedupe-");

const safeSpawnAsync = vi.fn();
const safeSpawn = vi.fn();
const ensureTool = vi.fn();

vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../clients/safe-spawn.js")>()),
	safeSpawnAsync,
	safeSpawn,
}));
vi.mock("../../clients/installer/index.js", () => ({
	// #2140: the probe resolver asks the installer for a release-managed
	// binary (`~/.pi-lens/bin`) before falling back to PATH. Undefined is
	// "no managed install", which is what these tests already assumed.
	findManagedToolBinary: vi.fn(async () => undefined),
	ensureTool,
	// #1612: resolveAvailableOrInstallUnshared reads these on the install-
	// success path to derive honest evidence rather than asserting "succeeded".
	getInstallAttempt: vi.fn(() => undefined),
	// #1636: read alongside getInstallAttempt for the compensating row's
	// `resolved` tag. Undefined falls back to "cache".
	getLastEnsureResolutionSource: vi.fn(() => undefined),
	getToolInstallStrategy: vi.fn(() => undefined),
	resetPathWalkMemo: vi.fn(),
	// Seam probes route through this on cached hits (#1203); default spawnable.
	isSpawnableCommand: vi.fn(async () => true),
}));

describe("RuffClient.ensureAvailable() — in-flight dedupe (#120)", () => {
	beforeEach(async () => {
		vi.resetAllMocks();
		const helpers =
			await import("../../clients/dispatch/runners/utils/runner-helpers.js");
		helpers.resetDispatchAvailabilityState();
		ensureTool.mockResolvedValue(null);
	});

	it("dedupes concurrent first-time callers to a single probe", async () => {
		let resolveProbe: ((value: unknown) => void) | undefined;
		safeSpawnAsync.mockImplementationOnce(
			() =>
				new Promise((resolve) => {
					resolveProbe = resolve;
				}),
		);
		const { RuffClient } = await import("../../clients/ruff-client.js");
		const client = new RuffClient();
		const a = client.ensureAvailable();
		const b = client.ensureAvailable();
		const c = client.ensureAvailable();
		await vi.waitFor(() => expect(safeSpawnAsync).toHaveBeenCalledTimes(1));
		resolveProbe?.({
			status: 0,
			error: undefined,
			stdout: "ruff 0.6.0",
			stderr: "",
		});
		const results = await Promise.all([a, b, c]);
		expect(results).toEqual([true, true, true]);
		// Cache is now hot — subsequent calls short-circuit before spawning.
		await client.ensureAvailable();
		expect(safeSpawnAsync).toHaveBeenCalledTimes(1);
	});

	it("clears ensureInFlight after a failed probe so retries can run", async () => {
		safeSpawnAsync.mockResolvedValueOnce({
			status: 1,
			error: new Error("not found"),
			stdout: "",
			stderr: "",
		});
		const { RuffClient } = await import("../../clients/ruff-client.js");
		const client = new RuffClient();
		const first = await client.ensureAvailable();
		expect(first).toBe(false);
		// A second call is allowed to probe again since the cached value is
		// false, not null — RuffClient does not retry, but we want to confirm
		// the in-flight slot did not leak.
		await client.ensureAvailable();
		expect(safeSpawnAsync).toHaveBeenCalledTimes(1);
	});

	it("uses the managed executable after PATH installation", async () => {
		const managed = "/fake/managed/ruff";
		safeSpawnAsync
			.mockResolvedValueOnce({
				status: 1,
				error: Object.assign(new Error("not found"), { code: "ENOENT" }),
				failure: "spawn",
				spawnFailure: { kind: "tool-not-found" } as never,
				stdout: "",
				stderr: "",
			})
			.mockResolvedValue({
				status: 0,
				error: undefined,
				stdout: "[]",
				stderr: "",
			});
		ensureTool.mockResolvedValue(managed);
		const { RuffClient } = await import("../../clients/ruff-client.js");
		const client = new RuffClient();
		// #4566 round 11: the fixture file lives in this file's own tmp root. A
		// backslash-joined `${process.cwd()}\<name>` is a filename character on
		// POSIX, so it wrote a sibling of the worktree.
		const file = path.join(tmp.tmpDir, "ruff-managed-test.py");
		const fs = await import("node:fs");
		fs.writeFileSync(file, "x = 1\n");
		try {
			await client.fixFileAsync(file);
			expect(safeSpawnAsync.mock.calls.slice(1).map((call) => call[0])).toEqual(
				[managed, managed],
			);
		} finally {
			fs.rmSync(file, { force: true });
		}
	});

	it("suppresses failed installs until the session resets", async () => {
		safeSpawnAsync.mockResolvedValue({
			status: 1,
			error: Object.assign(new Error("not found"), { code: "ENOENT" }),
			failure: "spawn",
			spawnFailure: { kind: "tool-not-found" } as never,
			stdout: "",
			stderr: "",
		});
		const { RuffClient } = await import("../../clients/ruff-client.js");
		const client = new RuffClient();
		expect(await client.ensureAvailable()).toBe(false);
		expect(ensureTool).toHaveBeenCalledTimes(1);
		await client.ensureAvailable();
		expect(ensureTool).toHaveBeenCalledTimes(1);
		const helpers =
			await import("../../clients/dispatch/runners/utils/runner-helpers.js");
		helpers.resetDispatchAvailabilityState();
		ensureTool.mockResolvedValue("ruff");
		expect(await client.ensureAvailable()).toBe(true);
		expect(ensureTool).toHaveBeenCalledTimes(2);
	});
});

