	// #1480 review: the maven aggregate is per MODULE, not per reactor.
	describe("maven multi-module counts (#1480)", () => {
		const parse = (output: string, exitCode: number) =>
			(new TestRunnerClient(false) as any).parseGenericRunnerOutput(
				output,
				"",
				exitCode,
