/**
 * #2522: turn-end selection must never auto-fire an integration/e2e test —
 * those spawn external processes (a plegma dogfooding turn resolved
 * `tests/integration/opencode-delegate.test.ts`, which spawns `opencode` and
 * needs a configured provider — 17s to fail on a box without one, reported
 * as "3/3 failed, fix before proceeding" on an unrelated model-switch turn).
 *
 * One hard-coded built-in list, no per-project config knob. Verified through
 * the REAL `getTestRunTarget` (a real `TestRunnerClient` against real files
 * on disk, same as the rest of this file), not a hand-fed path shaped to hit
 * the exclusion — the self/related strategies must actually resolve to the
 * excluded file first, exactly like the reported turn.
 */
describe("#2522 — turn-end selection excludes integration/e2e test targets", () => {
	const exclusionCleanups: Array<() => void> = [];
	afterEach(() => {
		for (const c of exclusionCleanups.splice(0)) c();
	});

	describe("isExcludedTestTarget", () => {
		// A real absolute cwd, resolved through the host's OWN `path` module —
		// never a hardcoded drive-letter/UNC literal (AGENTS.md: a Windows-shaped
		// literal fed as an INPUT is fine, but this also keeps every case below
		// correctly parseable on Linux CI, where `path` is the posix module).
		const cwd = path.resolve("pi-lens-2522-fixture-root");

		it("excludes tests/integration/**", () => {
			expect(
				isExcludedTestTarget(
					path.join(cwd, "tests", "integration", "foo.test.ts"),
					cwd,
				),
			).toBe(true);
		});

		it("excludes tests/e2e/**", () => {
			expect(
				isExcludedTestTarget(
					path.join(cwd, "tests", "e2e", "foo.test.ts"),
					cwd,
				),
			).toBe(true);
		});

		it("excludes a *.integration.* basename outside an integration/ dir", () => {
			expect(
				isExcludedTestTarget(
					path.join(cwd, "src", "foo.integration.test.ts"),
					cwd,
				),
			).toBe(true);
		});

		it("excludes a *.e2e.* basename outside an e2e/ dir", () => {
			expect(
				isExcludedTestTarget(path.join(cwd, "src", "foo.e2e.test.ts"), cwd),
			).toBe(true);
		});

		it("does not exclude an ordinary unit test", () => {
			expect(
				isExcludedTestTarget(
					path.join(cwd, "tests", "clients", "foo.test.ts"),
					cwd,
				),
			).toBe(false);
		});

		it("matches identically for the host-native path and its forward-slash form (cross-form)", () => {
			// On Windows this exercises the REAL production shape — `path.resolve`
			// returns backslash-separated paths there — against a forward-slash
			// variant of the exact same path (which win32's own `path.resolve`
			// also parses correctly, since it accepts either separator). On
			// POSIX both forms are already identical, so this is a no-op there
			// and stays meaningful specifically on the OS this bug shipped on.
			const native = path.join(cwd, "tests", "integration", "foo.test.ts");
			const forwardSlashForm = native.split(path.sep).join("/");
			expect(isExcludedTestTarget(native, cwd)).toBe(true);
			expect(isExcludedTestTarget(forwardSlashForm, cwd)).toBe(true);
		});
	});

	it("does not auto-fire a self target from a nested Git worktree", () => {
		// A direct edit in a nested checkout still reaches the final turn-end
		// gate, independently of the failed-first cache admission/retirement.
		const { tmpDir, cleanup } = setupTestEnvironment(
			"pi-lens-nested-worktree-",
		);
		exclusionCleanups.push(cleanup);
		fs.mkdirSync(path.join(tmpDir, ".git"));
		fs.writeFileSync(
			path.join(tmpDir, ".git", "HEAD"),
			"ref: refs/heads/main\n",
		);
		fs.writeFileSync(path.join(tmpDir, "go.mod"), "module example.com/main\n");
		const nestedRoot = path.join(tmpDir, ".worktrees", "other");
		fs.mkdirSync(nestedRoot, { recursive: true });
		fs.writeFileSync(
			path.join(nestedRoot, ".git"),
			"gitdir: /git/worktrees/other\n",
		);
		const nestedTest = path.join(nestedRoot, "tests", "other_test.go");
		fs.mkdirSync(path.dirname(nestedTest));
		fs.writeFileSync(nestedTest, "package main\n");
		const ordinaryTest = path.join(tmpDir, "tests", "main_test.go");
		fs.mkdirSync(path.dirname(ordinaryTest));
		fs.writeFileSync(ordinaryTest, "package main\n");

		const client = new TestRunnerClient(false);
		const target = client.getTestRunTarget(nestedTest, tmpDir);
		expect(target).toMatchObject({
			testFile: nestedTest,
			strategy: "self",
		});
		expect(isExcludedTestTarget(target!.testFile, tmpDir)).toBe(true);
		expect(isExcludedTestTarget(ordinaryTest, tmpDir)).toBe(false);
		expect(isExcludedTestTarget(nestedTest, nestedRoot)).toBe(false);
	});

	it("a real self-strategy match under tests/integration/ is reported as excluded by the real getTestRunTarget resolution", () => {
		const { tmpDir, cleanup } = setupTestEnvironment("pi-lens-2522-");
		exclusionCleanups.push(cleanup);

		fs.mkdirSync(path.join(tmpDir, "tests", "integration"), {
			recursive: true,
		});
		const integrationTest = path.join(
			tmpDir,
			"tests",
			"integration",
			"opencode-delegate.test.ts",
		);
		fs.writeFileSync(
			integrationTest,
			"import { it } from 'vitest'; it('spawns opencode', () => {});\n",
		);
		fs.writeFileSync(
			path.join(tmpDir, "vitest.config.ts"),
			"export default {}\n",
		);

		const client = new TestRunnerClient(false);
		// The real "self" strategy: editing the integration test file itself.
		const target = client.getTestRunTarget(integrationTest, tmpDir);
		expect(target?.strategy).toBe("self");
		expect(target?.testFile).toBe(path.resolve(integrationTest));
		// getTestRunTarget itself does not filter — the built-in exclusion is
		// enforced at the turn-end SELECTION site (runtime-turn.ts), which
		// checks every resolved target through this same real function before
		// it is ever added to the fire list.
		expect(isExcludedTestTarget(target!.testFile, tmpDir)).toBe(true);
	});

	/**
	 * #2522 review round 4, P3c — the contract the batch's deferral logic and
	 * its doubles are built on.
	 *
	 * `runTestFileAsync` `await`s `resolveExec` BEFORE it reaches the spawn, and
	 * `safeSpawnAsync` resolves SYNCHRONOUSLY when the signal it is handed is
	 * already aborted. So a target dispatched moments before the batch bound
	 * does not hang and does not reject: it comes back as an ordinary FULFILLED
	 * result with `passed === 0`, `failed === 0` and a runner error describing
	 * work that never happened. Anything downstream that reads "fulfilled" as
	 * "ran" records a suite as complete when nothing was executed.
	 *
	 * This pins the shape against the REAL client, so the doubles in
	 * `runtime-turn-test-runner-bounds.test.ts` that mirror it are not mirroring
	 * an assumption (AGENTS.md: a test double must be production-faithful on the
	 * axis under test).
	 */
	it("resolves an already-aborted run as a fulfilled runner error, not a completed run", async () => {
		const { tmpDir, cleanup } = setupTestEnvironment("pi-lens-2522-p3c-");
		exclusionCleanups.push(cleanup);
		const testFile = path.join(tmpDir, "unit.test.ts");
		fs.writeFileSync(
			testFile,
			"import { it } from 'vitest'; it('x', () => {});\n",
		);
		fs.writeFileSync(
			path.join(tmpDir, "vitest.config.ts"),
			"export default {}\n",
		);

		const controller = new AbortController();
		controller.abort();
		const client = new TestRunnerClient(false);
		const result = await client.runTestFileAsync(testFile, tmpDir, {
			runner: "vitest",
			config: RUNNERS.vitest,
			signal: controller.signal,
		});

		expect(result.passed).toBe(0);
		expect(result.failed).toBe(0);
		expect(result.error).toContain("aborted before start");
	});
});

/**
 * Regression matrix for #1098: `resolveExec` used to drop
 * `config.args(testFile, cwd)[0]` UNCONDITIONALLY whenever local-bin or
 * global-bin resolution succeeded — an npx-wrapper-convention assumption
 * (arg 0 names the binary, like `npx vitest run …`) that only holds for
 * wrapper-style runners (vitest/jest/pytest). For direct runners whose
 * args() leads with a REAL subcommand (`cargo test --no-fail-fast`,
 * `go test -run . ./pkg`, `dotnet test --no-build`, `mvn test -q`,
 * `mix test <file>`), the same unconditional `.slice(1)` silently ate the
 * subcommand — e.g. `cargo test --no-fail-fast` became the argv-invalid
 * `cargo --no-fail-fast` (a clap usage error), which the runner then
 * misreported as "1/1 failed" at turn-end.
 *
 * The fix (`stripWrapperArgs` in clients/test-runner-client.ts) only drops
 * the leading arg(s) when they actually NAME the resolved binary — either
 * `[binName, ...]` (vitest/jest) or `["-m", binName, ...]` (pytest) — and
 * leaves everything else untouched.
 *
 * This asserts the invariant generically by iterating the EXPORTED
 * `RUNNERS` config table (not a hand-copied runner list), across every
 * resolution path `resolveExec` can take:
 *   - local-bin hit  (a real file dropped in node_modules/.bin, or
 *                      vendor/bin for phpunit's Composer convention)
 *   - global-bin hit (findGlobalBinary mocked to resolve)
 *   - fallback       (neither resolves; config.command is used verbatim)
 * so a future runner added to RUNNERS is automatically covered.
 *
 * The expected argv for each case is computed independently of the
 * production `stripWrapperArgs` helper (a local re-statement of the same
 * contract), so a regression that reintroduces unconditional stripping (or
 * any other over/under-stripping) fails this test rather than trivially
 * agreeing with whatever the implementation currently does.
 */
describe("resolveExec argv preservation matrix (#1098)", () => {
	const resolveCleanups: Array<() => void> = [];

	beforeEach(() => {
		findGlobalBinary.mockReset();
		findGlobalBinary.mockResolvedValue(undefined);
	});

	afterEach(() => {
		for (const c of resolveCleanups.splice(0)) c();
	});

	function expectedStrippedArgs(binName: string, args: string[]): string[] {
		if (args[0] === binName) return args.slice(1);
		if (args[0] === "-m" && args[1] === binName) return args.slice(2);
		return args;
	}

	function binSuffix(): string {
		return process.platform === "win32" ? ".cmd" : "";
	}

	for (const [runnerKey, config] of Object.entries(RUNNERS)) {
		const binName = config.binName ?? runnerKey;

		describe(`runner: ${runnerKey}`, () => {
			it("preserves argv on local-bin resolution", () => {
				const { tmpDir, cleanup } = setupTestEnvironment(
					"pi-lens-resolve-exec-",
				);
				resolveCleanups.push(cleanup);
				const client = new TestRunnerClient(false) as any;

				let localBinPath: string;
				if (runnerKey === "phpunit") {
					const phpSuffix = process.platform === "win32" ? ".bat" : "";
					localBinPath = path.join(
						tmpDir,
						"vendor",
						"bin",
						`phpunit${phpSuffix}`,
					);
				} else {
					localBinPath = path.join(
						tmpDir,
						"node_modules",
						".bin",
						`${binName}${binSuffix()}`,
					);
				}
				fs.mkdirSync(path.dirname(localBinPath), { recursive: true });
				// #4530 r7: command acceptance requires the executable bit on POSIX.
				fs.writeFileSync(localBinPath, "", { mode: 0o755 });

				const testFile = path.join(
					tmpDir,
					`sample_test${runnerKey === "go" ? ".go" : ".txt"}`,
				);
				const rawArgs = config.args(testFile, tmpDir);

				return client
					.resolveExec(runnerKey, config, testFile, tmpDir)
					.then((resolved: { command: string; args: string[] }) => {
						expect(resolved.command).toBe(localBinPath);
						// phpunit's local (vendor/bin) resolution never strips —
						// see the dedicated branch in resolveExec.
						const expected =
							runnerKey === "phpunit"
								? rawArgs
								: expectedStrippedArgs(binName, rawArgs);
						expect(resolved.args).toEqual(expected);
					});
			});

			if (runnerKey !== "phpunit") {
				// phpunit has no separate global-bin resolution step — its
				// non-local branch falls straight through to the fallback
				// (`command: "phpunit"`), so it's covered by the fallback case
				// below instead of duplicated here.
				it("preserves argv on global-bin resolution", () => {
					const { tmpDir, cleanup } = setupTestEnvironment(
						"pi-lens-resolve-exec-",
					);
					resolveCleanups.push(cleanup);
					const client = new TestRunnerClient(false) as any;

					const globalBinPath = path.join(tmpDir, "global-bin", binName);
					findGlobalBinary.mockImplementation(async (name: string) =>
						name === binName ? globalBinPath : undefined,
					);

					const testFile = path.join(
						tmpDir,
						`sample_test${runnerKey === "go" ? ".go" : ".txt"}`,
					);
					const rawArgs = config.args(testFile, tmpDir);

					return client
						.resolveExec(runnerKey, config, testFile, tmpDir)
						.then((resolved: { command: string; args: string[] }) => {
							expect(resolved.command).toBe(globalBinPath);
							expect(resolved.args).toEqual(
								expectedStrippedArgs(binName, rawArgs),
							);
						});
				});
			}

			it("preserves argv verbatim on fallback (no local/global bin)", () => {
				const { tmpDir, cleanup } = setupTestEnvironment(
					"pi-lens-resolve-exec-",
				);
				resolveCleanups.push(cleanup);
				const client = new TestRunnerClient(false) as any;

				const testFile = path.join(
					tmpDir,
					`sample_test${runnerKey === "go" ? ".go" : ".txt"}`,
				);
				const rawArgs = config.args(testFile, tmpDir);

				return client
					.resolveExec(runnerKey, config, testFile, tmpDir)
					.then((resolved: { command: string; args: string[] }) => {
						expect(resolved.command).toBe(
							runnerKey === "phpunit" ? "phpunit" : config.command,
						);
						// Fallback never resolves a binary to become the command, so
						// there is nothing to strip — args() is used verbatim.
						expect(resolved.args).toEqual(rawArgs);
					});
			});
		});
	}

	it("cargo's subcommand survives local-bin resolution (the reported #1098 case)", () => {
		const { tmpDir, cleanup } = setupTestEnvironment("pi-lens-resolve-exec-");
		resolveCleanups.push(cleanup);
		const client = new TestRunnerClient(false) as any;

		const localBinPath = path.join(
			tmpDir,
			"node_modules",
			".bin",
			`cargo${binSuffix()}`,
		);
		fs.mkdirSync(path.dirname(localBinPath), { recursive: true });
		// #4530 r7: command acceptance requires the executable bit on POSIX.
		fs.writeFileSync(localBinPath, "", { mode: 0o755 });

		const testFile = path.join(tmpDir, "src", "lib.rs");

		return client
			.resolveExec("cargo", RUNNERS.cargo, testFile, tmpDir)
			.then((resolved: { command: string; args: string[] }) => {
				expect(resolved.command).toBe(localBinPath);
				// Pre-fix, this was ["--no-fail-fast"] (the "test" subcommand was
				// eaten), producing a clap usage error at spawn time.
				expect(resolved.args).toEqual(["test", "--no-fail-fast"]);
			});
	});

	it("rspec resolves the real binary name (bundle), not the runner key", () => {
		const { tmpDir, cleanup } = setupTestEnvironment("pi-lens-resolve-exec-");
		resolveCleanups.push(cleanup);
		const client = new TestRunnerClient(false) as any;

		const bundleBinPath = path.join(tmpDir, "global-bin", "bundle");
		findGlobalBinary.mockImplementation(async (name: string) =>
			name === "bundle" ? bundleBinPath : undefined,
		);

		const testFile = path.join(tmpDir, "spec", "foo_spec.rb");

		return client
			.resolveExec("rspec", RUNNERS.rspec, testFile, tmpDir)
			.then((resolved: { command: string; args: string[] }) => {
				expect(resolved.command).toBe(bundleBinPath);
				// "exec" is a real bundle subcommand, not the binary name — must
				// survive intact so `bundle exec rspec <file>` reaches bundle.
				expect(resolved.args).toEqual(["exec", "rspec", testFile]);
				expect(findGlobalBinary).toHaveBeenCalledWith("bundle", ".cmd", tmpDir);
			});
	});
});

/**
 * #2522 review round 2, F5/F6 — two ways the built-in exclusion opened when
 * it had to stay shut.
 *
 * F5: the globs were matched case-SENSITIVELY, so a repo that names the
 * directory `tests/Integration/` or `tests/E2E/` (or a file
 * `foo.E2E.test.ts`) got the unbounded pre-#2522 behaviour back. The
 * exclusion is a safety bound on what turn_end may auto-fire, and a safety
 * bound that a capital letter defeats is not one. Windows and macOS default
 * to case-insensitive filesystems, so the SAME repo excluded or admitted the
 * same file depending on which box the agent ran on.
 *
 * F6: a target that resolves OUTSIDE the project root produced a `..`-leading
 * relative path, which matches none of the globs — so it fell through as
 * "not excluded" and turn_end would spawn a runner against a file it has no
 * business auto-running. Out-of-tree must fail CLOSED.
 */
describe("#2522 R2 — the built-in exclusion fails closed", () => {
	const r2Cleanups: Array<() => void> = [];
	afterEach(() => {
		while (r2Cleanups.length > 0) r2Cleanups.pop()?.();
	});

	it("excludes integration/e2e directories regardless of case (F5)", () => {
		const cwd = path.resolve("/repo");
		for (const rel of [
			"tests/Integration/opencode-delegate.test.ts",
			"tests/INTEGRATION/opencode-delegate.test.ts",
			"tests/E2E/prune-worktrees.test.ts",
			"tests/E2e/prune-worktrees.test.ts",
		]) {
			expect(isExcludedTestTarget(path.join(cwd, rel), cwd)).toBe(true);
		}
	});

	it("excludes *.integration.*/*.e2e.* basenames regardless of case (F5)", () => {
		const cwd = path.resolve("/repo");
		for (const rel of [
			"tests/clients/delegate.Integration.test.ts",
			"tests/clients/delegate.E2E.test.ts",
		]) {
			expect(isExcludedTestTarget(path.join(cwd, rel), cwd)).toBe(true);
		}
	});

	it("still admits an ordinary unit test whose name merely contains the words", () => {
		const cwd = path.resolve("/repo");
		// `integrationHelpers` / `e2eSupport` are not directory or dotted-suffix
		// matches — case-insensitivity must not widen WHAT the globs match.
		expect(
			isExcludedTestTarget(
				path.join(cwd, "tests/clients/integrationHelpers.test.ts"),
				cwd,
			),
		).toBe(false);
		expect(
			isExcludedTestTarget(
				path.join(cwd, "tests/clients/e2eSupport.test.ts"),
				cwd,
			),
		).toBe(false);
	});

	it("fails CLOSED for a target that resolves outside the project root (F6)", () => {
		const cwd = path.resolve("/repo/project");
		// A `..`-leading relative target and an absolute sibling-tree target
		// both land outside cwd; neither matches any glob, so pre-fix they were
		// reported as "not excluded" and would have been spawned.
		expect(isExcludedTestTarget("../other/tests/thing.test.ts", cwd)).toBe(
			true,
		);
		expect(
			isExcludedTestTarget(
				path.resolve("/repo/other/tests/thing.test.ts"),
				cwd,
			),
		).toBe(true);
		// The project root itself is not a test target either.
		expect(isExcludedTestTarget(cwd, cwd)).toBe(true);
	});

	it("still admits an in-tree unit test after the out-of-tree guard", () => {
		const cwd = path.resolve("/repo/project");
		expect(
			isExcludedTestTarget(path.join(cwd, "tests/clients/widget.test.ts"), cwd),
		).toBe(false);
	});

	it("fails closed through the REAL getTestRunTarget when the resolved target is out of tree", () => {
		const root = setupTestEnvironment("pi-lens-2522-r2-");
		r2Cleanups.push(root.cleanup);
		const project = path.join(root.tmpDir, "project");
		const outside = path.join(root.tmpDir, "outside");
		fs.mkdirSync(project, { recursive: true });
		fs.mkdirSync(outside, { recursive: true });
		fs.writeFileSync(
			path.join(project, "vitest.config.ts"),
			"export default {}\n",
		);
		const strayTest = path.join(outside, "stray.test.ts");
		fs.writeFileSync(strayTest, "export {};\n");

		const client = new TestRunnerClient(false);
		// The real "self" strategy resolves the edited test file itself — here
		// one that lives outside the project root the turn is running in.
		const target = client.getTestRunTarget(strayTest, project);
		expect(target?.strategy).toBe("self");
		expect(isExcludedTestTarget(target!.testFile, project)).toBe(true);
	});
});

tests/clients/tool-tier-degraded-selecti:
/**
 * #1568 — `sawTransient` was consulted ONLY on the all-failed arm.
 *
 * Both ast-grep availability sweeps walk an ordered candidate list and stop at
 * the first candidate that answers. A candidate that timed out was recorded in
 * `sawTransient`, but the flag was read only after every candidate had failed.
 * So when a preferred tier merely stalled and a LOWER tier answered, the sweep
 * took the win at face value and latched it: `sgLatch.noteAvailable()` /
 * `availabilityLatch.noteAvailable()` are durable for the session, and nothing
 * expires them. One busy second at warm-up therefore pinned the whole session
 * to `npx --no -- ast-grep` — a Node process per invocation — with a healthy
 * global ast-grep sitting on PATH the entire time.
 *
 * This is #1539's degraded-selection shape in the tool-tier domain, and the fix
 * mirrors #1559's semantics: a selection made while a candidate ahead of the
 * winner was UNREACHABLE (not absent) is PROVISIONAL. It is used for the
 * current call and held only for the stalled tier's cooldown; after that the
 * next caller re-sweeps, and a recovered preferred tier wins back.
 *
 * Two sites, two scenarios. The control cases — a clean win latches, a
 * genuine absence ahead of the winner latches — are pinned beside each one,
 * because "never cache anything" would be worse than the bug.
 */

import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { TRANSIENT_BASE_COOLDOWN_MS } from "../../clients/dispatch/runners/utils/availability-policy.js";

/**
 * Reset through the SAME module instance the clients load (the compiled `.js`):
 * the shared ast-grep memo is module state, and resetting a second instance of
 * the module silently resets nothing.
 */
async function resetDispatchAvailabilityState(): Promise<void> {
	const helpers =
		await import("../../clients/dispatch/runners/utils/runner-helpers.js");
	helpers.resetDispatchAvailabilityState();
}

const { safeSpawnAsync, safeSpawn, ensureTool, logLatency } = vi.hoisted(
	() => ({
		safeSpawnAsync: vi.fn(),
		safeSpawn: vi.fn(),
		ensureTool: vi.fn(),
		logLatency: vi.fn(),
	}),
);

vi.mock("../../clients/latency-logger.js", async (importOriginal) => {
	const actual =
		await importOriginal<typeof import("../../clients/latency-logger.js")>();
	return { ...actual, logLatency };
});

vi.mock("../../clients/safe-spawn.js", async (importOriginal) => ({
	...(await importOriginal<typeof import("../../clients/safe-spawn.js")>()),
	safeSpawn,
	safeSpawnAsync,
	isCommandAvailableAsync: vi.fn(async () => false),
}));

vi.mock("../../clients/installer/index.js", () => ({
	ensureTool,
	getInstallAttempt: vi.fn(() => undefined),
	isSpawnableCommand: vi.fn(async () => true),
	resetPathWalkMemo: vi.fn(),
	getToolEnvironment: vi.fn(async () => ({})),
}));

vi.mock("../../clients/package-manager.js", async (importOriginal) => ({
	...(await importOriginal<
		typeof import("../../clients/package-manager.js")
	>()),
	findGlobalBinary: vi.fn(async () => undefined),
	findNodeToolBinary: vi.fn(async () => undefined),
}));

/** A probe the host killed at its budget: says nothing about the tool. */
const timeoutResult = {
	stdout: "",
	stderr: "",
	status: null,
	error: new Error("Process timed out after 5000ms"),
	failure: "timeout",
	spawnFailure: { kind: "timeout" },
};

/** A probe that proved the tool is not on this machine. */
const missingResult = {
	stdout: "",
	stderr: "",
	status: null,
	error: Object.assign(new Error("spawn ENOENT"), { code: "ENOENT" }),
	failure: "spawn",
	spawnFailure: { kind: "tool-not-found" },
};

const okResult = (stdout: string) => ({
	stdout,
	stderr: "",
	status: 0,
	error: undefined,
});

const astGrepOk = () => okResult("ast-grep 0.32.3");

/** Availability decision records emitted for `tool`, oldest first. */
function decisionsFor(tool: string): Array<Record<string, unknown>> {
	return logLatency.mock.calls
		.map((call) => call[0] as Record<string, unknown>)
		.filter(
			(entry) =>
				entry?.phase === "availability_decision" &&
				(entry.metadata as Record<string, unknown> | undefined)?.tool === tool,
		);
}

function lastAvailableDecision(tool: string): Record<string, unknown> {
	const available = decisionsFor(tool).filter(
		(entry) =>
			(entry.metadata as Record<string, unknown>).verdict === "available",
	);
	return (available.at(-1)?.metadata ?? {}) as Record<string, unknown>;
}

function advancePastCooldown(): void {
	vi.setSystemTime(new Date(Date.now() + TRANSIENT_BASE_COOLDOWN_MS + 1));
}

/**
 * A provisional verdict escalates on the transient ladder, so the SECOND hop
 * has to clear 60 s, not 30 s.
 */
function advancePastSecondCooldown(): void {
	vi.setSystemTime(new Date(Date.now() + TRANSIENT_BASE_COOLDOWN_MS * 2 + 1));
}

/**
 * Route by command so each tier's verdict is explicit. `npx` is matched
 * exactly; everything else (bare `ast-grep`/`sg` and any absolute
 * `node_modules/.bin` path this host happens to have) is the "preferred" tier.
 */
function routeTiers(options: { preferred: unknown; npx: unknown }): void {
	safeSpawnAsync.mockImplementation(async (cmd: string) =>
		cmd === "npx" ? options.npx : options.preferred,
	);
}

beforeEach(async () => {
	(await import("../../clients/project-trust.js")).setProjectTrustState(
		"trusted",
	);
	vi.resetAllMocks();
	ensureTool.mockResolvedValue(null);
	safeSpawn.mockReturnValue({ stdout: "", stderr: "", status: 1 });
	await resetDispatchAvailabilityState();
	vi.useFakeTimers({ toFake: ["Date"] });
});

afterEach(async () => {
	vi.useRealTimers();
	await resetDispatchAvailabilityState();
	(await import("../../clients/project-trust.js")).resetProjectTrust();
});

describe("shared ast-grep memo: a stalled preferred tier is provisional (#1568)", () => {
	async function loadHelpers() {
		return await import("../../clients/dispatch/runners/utils/runner-helpers.js");
	}

	it("uses npx now, then hands the session back to ast-grep after the cooldown", async () => {
		routeTiers({ preferred: timeoutResult, npx: astGrepOk() });
		const { isSgAvailableAsync, getSgCommand } = await loadHelpers();

		// The current call is served, as before: npx answers, so ast-grep works.
		expect(await isSgAvailableAsync()).toBe(true);
		expect(getSgCommand().cmd).toBe("npx");
		const probesAfterFirst = safeSpawnAsync.mock.calls.length;

		// Inside the cooldown the provisional pick holds — no re-sweep per call.
		expect(await isSgAvailableAsync()).toBe(true);
		expect(safeSpawnAsync.mock.calls.length).toBe(probesAfterFirst);

		// After the stalled tier's cooldown the sweep runs again, and the
		// recovered preferred tier wins. Pre-fix the npx pick was latched
		// `available` for the life of the process, so no second sweep ever ran.
		advancePastCooldown();
		routeTiers({ preferred: astGrepOk(), npx: astGrepOk() });
		expect(await isSgAvailableAsync()).toBe(true);
		expect(safeSpawnAsync.mock.calls.length).toBeGreaterThan(probesAfterFirst);
		expect(getSgCommand().cmd).not.toBe("npx");
	});

	it("says in the decision record that the win was provisional", async () => {
		routeTiers({ preferred: timeoutResult, npx: astGrepOk() });
		const { isSgAvailableAsync } = await loadHelpers();

		expect(await isSgAvailableAsync()).toBe(true);
		const metadata = lastAvailableDecision("ast-grep");
		// Pre-fix an `available` row was always `latched: true` with no retry, so
		// a log reader could not tell a real win from a degraded one.
		expect(metadata.provisional).toBe(true);
		expect(metadata.latched).toBe(false);
		expect(metadata.retryAfterMs).toBe(TRANSIENT_BASE_COOLDOWN_MS);
		expect(metadata.unreachablePreferred).toContain("ast-grep");
	});

	it("control: a clean win still latches for the session", async () => {
		routeTiers({ preferred: astGrepOk(), npx: astGrepOk() });
		const { isSgAvailableAsync } = await loadHelpers();

		expect(await isSgAvailableAsync()).toBe(true);
		const probes = safeSpawnAsync.mock.calls.length;
		expect(lastAvailableDecision("ast-grep").latched).toBe(true);
		expect(lastAvailableDecision("ast-grep").provisional).toBeUndefined();

		// No cooldown to expire: the verdict is a durable fact.
		advancePastCooldown();
		expect(await isSgAvailableAsync()).toBe(true);
		expect(safeSpawnAsync.mock.calls.length).toBe(probes);
	});

	it("control: a genuinely ABSENT preferred tier still latches the npx win", async () => {
		// Nothing stalled, so the npx win is on the merits — re-sweeping every
		// 30 s would be the "never cache anything" regression.
		routeTiers({ preferred: missingResult, npx: astGrepOk() });
		const { isSgAvailableAsync } = await loadHelpers();

		expect(await isSgAvailableAsync()).toBe(true);
		const probes = safeSpawnAsync.mock.calls.length;
		expect(lastAvailableDecision("ast-grep").latched).toBe(true);

		advancePastCooldown();
		expect(await isSgAvailableAsync()).toBe(true);
		expect(safeSpawnAsync.mock.calls.length).toBe(probes);
	});

	it("a still-stalled re-sweep keeps the winner instead of turning ast-grep off", async () => {
		// #1568 review F1. The re-sweep is the point of the provisional state, and
		// on a host that is STILL busy every candidate times out — including the
		// npx that answered 30 s ago. Flipping to `unavailable` there runs #1476's
		// principle backwards: a timeout says nothing about the tool, so it cannot
		// erase a command this very process proved working. `sgCmd` is still in
		// hand; keep serving it and re-arm the cooldown.
		routeTiers({ preferred: timeoutResult, npx: astGrepOk() });
		const { isSgAvailableAsync, getSgCommand } = await loadHelpers();

		expect(await isSgAvailableAsync()).toBe(true);
		expect(getSgCommand().cmd).toBe("npx");

		advancePastCooldown();
		safeSpawnAsync.mockResolvedValue(timeoutResult);
		expect(await isSgAvailableAsync()).toBe(true);
		expect(getSgCommand().cmd).toBe("npx");

		const metadata = lastAvailableDecision("ast-grep");
		expect(metadata.provisional).toBe(true);
		expect(metadata.retained).toBe(true);
		expect(metadata.latched).toBe(false);
		// Re-armed, and escalated: attempt 2 on the transient ladder.
		expect(metadata.retryAfterMs).toBe(TRANSIENT_BASE_COOLDOWN_MS * 2);

		// Still provisional, so recovery still lands once the host settles.
		advancePastSecondCooldown();
		routeTiers({ preferred: astGrepOk(), npx: astGrepOk() });
		expect(await isSgAvailableAsync()).toBe(true);
		expect(getSgCommand().cmd).not.toBe("npx");
		expect(lastAvailableDecision("ast-grep").latched).toBe(true);
	});

	it("logs candidate NAMES, never absolute local paths (#1568 review F3)", async () => {
		// Tier 1 is `node_modules/.bin/<name>`, an absolute path under the user's
		// home. Every sibling row in latency.log carries a tool name, so writing a
		// filesystem path here both leaks it and breaks the grep.
		routeTiers({ preferred: timeoutResult, npx: astGrepOk() });
		const { isSgAvailableAsync } = await loadHelpers();

		expect(await isSgAvailableAsync()).toBe(true);
		const unreachable = lastAvailableDecision("ast-grep")
			.unreachablePreferred as string[];
		expect(unreachable.length).toBeGreaterThan(0);
		for (const name of unreachable) {
			expect(name).not.toMatch(/[\\/]/);
		}
		expect(unreachable).toContain("ast-grep");
	});
});

describe("SgRunner.doEnsureAvailable: a stalled DIRECT tier is provisional (#1568)", () => {
	async function loadRunner() {
		const { SgRunner } = await import("../../clients/sg-runner.js");
		return new SgRunner();
	}

	it("re-sweeps after the cooldown instead of staying on npx all session", async () => {
		routeTiers({ preferred: timeoutResult, npx: astGrepOk() });
		const runner = await loadRunner();

		expect(await runner.ensureAvailable()).toBe(true);
		// A stalled DIRECT candidate must still not trigger the install (#1476).
		expect(ensureTool).not.toHaveBeenCalled();
		const probesAfterFirst = safeSpawnAsync.mock.calls.length;

		// Held for the cooldown: one provisional sweep, not one per caller.
		expect(await runner.ensureAvailable()).toBe(true);
		expect(safeSpawnAsync.mock.calls.length).toBe(probesAfterFirst);

		// Pre-fix `noteAvailable()` latched the npx pick permanently, so this
		// second sweep never happened and the recovered binary was never seen.
		advancePastCooldown();
		routeTiers({ preferred: astGrepOk(), npx: astGrepOk() });
		expect(await runner.ensureAvailable()).toBe(true);
		expect(safeSpawnAsync.mock.calls.length).toBeGreaterThan(probesAfterFirst);
		// The re-sweep asked the preferred tier first and it answered, so this
		// win is durable — no further sweep is owed.
		const settled = safeSpawnAsync.mock.calls.length;
		advancePastCooldown();
		expect(await runner.ensureAvailable()).toBe(true);
		expect(safeSpawnAsync.mock.calls.length).toBe(settled);
	});

	it("says in the decision record that the win was provisional", async () => {
		routeTiers({ preferred: timeoutResult, npx: astGrepOk() });
		const runner = await loadRunner();

		expect(await runner.ensureAvailable()).toBe(true);
		const metadata = lastAvailableDecision("ast-grep");
		expect(metadata.provisional).toBe(true);
		expect(metadata.latched).toBe(false);
		expect(metadata.retryAfterMs).toBe(TRANSIENT_BASE_COOLDOWN_MS);
		expect(metadata.unreachablePreferred).toContain("ast-grep");
	});

	it("control: a stalled npx FALLBACK does not make a later real win provisional", async () => {
		// npx is asked before the global-bin / platform-package tiers but is
		// explicitly the fallback, so its stall says nothing about a winner that
		// is a genuine binary. Marking that win provisional would re-sweep the
		// slow npx forever — the regression #1489 already fixed once.
		const { findGlobalBinary } =
			await import("../../clients/package-manager.js");
		vi.mocked(findGlobalBinary).mockResolvedValue(
			"/global/bin/ast-grep" as never,
		);
		safeSpawnAsync.mockImplementation(async (cmd: string) => {
			if (cmd === "npx") return timeoutResult;
			if (cmd === "/global/bin/ast-grep") return astGrepOk();
			return missingResult;
		});
		const runner = await loadRunner();

		expect(await runner.ensureAvailable()).toBe(true);
		expect(lastAvailableDecision("ast-grep").latched).toBe(true);
		expect(lastAvailableDecision("ast-grep").provisional).toBeUndefined();
		const probes = safeSpawnAsync.mock.calls.length;

		advancePastCooldown();
		expect(await runner.ensureAvailable()).toBe(true);
		expect(safeSpawnAsync.mock.calls.length).toBe(probes);
	});

	it("control: a genuinely ABSENT direct tier still latches the npx win", async () => {
		routeTiers({ preferred: missingResult, npx: astGrepOk() });
		const runner = await loadRunner();

		expect(await runner.ensureAvailable()).toBe(true);
		const probes = safeSpawnAsync.mock.calls.length;
		expect(lastAvailableDecision("ast-grep").latched).toBe(true);

		advancePastCooldown();
		expect(await runner.ensureAvailable()).toBe(true);
		expect(safeSpawnAsync.mock.calls.length).toBe(probes);
	});

	it("a still-stalled re-sweep keeps the winner and does NOT install", async () => {
		// #1568 review F1, plus the second-order case: the re-sweep must not fall
		// through to Step 4. Auto-installing ast-grep because the host was busy is
		// exactly what #1476 removed, and here there is an even stronger reason —
		// the runner is still holding a command it proved working one cooldown ago.
		routeTiers({ preferred: timeoutResult, npx: astGrepOk() });
		const runner = await loadRunner();

		expect(await runner.ensureAvailable()).toBe(true);

		advancePastCooldown();
		safeSpawnAsync.mockResolvedValue(timeoutResult);
		expect(await runner.ensureAvailable()).toBe(true);
		expect(ensureTool).not.toHaveBeenCalled();

		const metadata = lastAvailableDecision("ast-grep");
		expect(metadata.provisional).toBe(true);
		expect(metadata.retained).toBe(true);
		expect(metadata.latched).toBe(false);
		expect(metadata.retryAfterMs).toBe(TRANSIENT_BASE_COOLDOWN_MS * 2);

		// And it still recovers: the retained state is provisional, not a new latch.
		advancePastSecondCooldown();
		routeTiers({ preferred: astGrepOk(), npx: astGrepOk() });
		expect(await runner.ensureAvailable()).toBe(true);
		expect(lastAvailableDecision("ast-grep").latched).toBe(true);
	});

	it("boundary: only a GENUINE absence on the re-sweep reaches the install", async () => {
		// The other side of the arm above. If the re-sweep finds every candidate
		// genuinely gone — the npx that answered included — then ast-grep really is
		// missing now, and the install is the right move. Retaining the old winner
		// here would serve a command that ENOENTs on the next run.
		routeTiers({ preferred: timeoutResult, npx: astGrepOk() });
		const runner = await loadRunner();

		expect(await runner.ensureAvailable()).toBe(true);
		expect(ensureTool).not.toHaveBeenCalled();

		advancePastCooldown();
		safeSpawnAsync.mockResolvedValue(missingResult);
		expect(await runner.ensureAvailable()).toBe(false);
		expect(ensureTool).toHaveBeenCalledWith("ast-grep");
	});
});

tests/clients/turn-scenarios.test.ts:
/**
 * The turn-simulation harness's seed scenarios — #1635 item 1.
 *
 * Four dogfood incidents from 2026-08-18, each replayed as a scripted turn
 * sequence against `handleTurnEnd`, asserting what the AGENT SEES.
 *
 * ## Why some of these are skipped
 *
 * A scenario asserts the CORRECT behavior, always. When the fix for that
 * incident is not on master yet, the scenario carries `pendingOn` and is
 * skipped. It is never rewritten to assert the buggy behavior — a suite that
 * encodes today's bug as today's expectation defends the bug, and the fix then
 * arrives looking like a regression.
 *
 * That also makes the redness proof trivial and honest for the pending ones:
 * delete the `pendingOn` line, run the file, and the scenario fails on current
 * master because the defect is still there. See the PR body for the captured
 * output of each.
 *
 * `skipWhen` is a different thing and says so: the fix exists and the scenario
 * runs, but this host does not have the tool it drives (scenario 2 shells out
 * to a real knip).
 *
 * Live as of this revision: scenario 1 (#1627 merged), scenario 2 (#1637
 * merged 2026-08-18) and scenario 3 (#1633 merged 2026-08-19). Pending:
 * scenario 4 on nothing — that blind spot has no fix in flight.
 */

import { spawnSync } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { KnipClient } from "../../clients/knip-client.js";
import { resetProjectTrust } from "../../clients/project-trust.js";
import {
	defineTurnScenario,
	runTurnScenario,
	type TurnScenario,
} from "../support/turn-harness.js";

// ── Scenario 1 — gitleaks stale replay (#1622, fixed by PR #1627) ────────────

const gitleaksStaleReplay = defineTurnScenario({
	id: "gitleaks-stale-replay",
	incident:
		"gitleaks flagged src:397, the agent edited that file, and the STOP blocker kept citing 397 for the rest of the 30-minute TTL",
	issue: "#1622",
	async run(h) {
		h.write("src/config.ts", "const key = 'AKIA0000000000000000';\n");
		h.advance(1_000);
		h.edit("src/app.ts", "export const app = 1;\n");
		h.scan("gitleaks", {
			findings: [
				{
					ruleId: "aws-access-token",
					file: h.pathOf("src/config.ts"),
					startLine: 397,
					description: "AWS key",
				},
			],
		});

		// Turn 1: nothing has moved since the scan, so the credential is a
		// full-severity blocker with its coordinate intact.
		const first = await h.turnEnd();
		expect(first.blockers.join("\n")).toContain("hardcoded secrets detected");
		expect(first.text).toContain("src/config.ts:397");

		// Turn 2: the agent edits the cited file. The line number is now a claim
		// about a file revision that no longer exists.
		h.advance(5_000);
		h.edit("src/config.ts", "const key = process.env.AWS_KEY;\n");
		const second = await h.turnEnd();

		// Demoted, not dropped: an edit must never mute a real credential.
		expect(second.blockers.join("\n")).not.toContain(
			"hardcoded secrets detected",
		);
		expect(second.actionNeeded.join("\n")).toContain("src/config.ts");
		expect(second.text).not.toContain(":397");
	},
});

// ── Scenario 2 — knip stale cache (#1630, fixed by PR #1637) ─────────────────

/**
 * knip is a real binary this scenario shells out to, through the REAL
 * `KnipClient`. Review round R1 (S4) was right that the first cut could never
 * fail the way #1630 fails: it replaced the whole client with a stub, and
 * #1637's fix — pruning knip's glob cache before each run — lives inside
 * `KnipClient.analyze`, the layer the stub removed.
 *
 * The availability probe mirrors `tests/clients/knip-cache-consumer-staleness.ts`'s:
 * the suite redirects `PI_LENS_HOME` to a per-worker temp dir, so the managed
 * install has to be found through the real home directory and put on PATH.
 */
const managedKnipBinDir = (() => {
	const dir = path.join(
		os.homedir(),
		".pi-lens",
		"tools",
		"node_modules",
		".bin",
	);
	return fs.existsSync(dir) ? dir : null;
})();

// CI and the pre-push hook have no managed install, and their only knip is this
// checkout's own devDependency: a bare `knip` reaches it only when
// `node_modules/.bin` is on PATH, which `npm test` arranges and a direct vitest
// run does not. Name it so both environments drive the same binary (#4566 CI red).
const checkoutKnipBinDir = (() => {
	const dir = path.resolve(
		path.dirname(fileURLToPath(import.meta.url)),
		"..",
		"..",
		"node_modules",
		".bin",
	);
	return fs.existsSync(path.join(dir, "knip")) ? dir : null;
})();

const knipBinDir = managedKnipBinDir ?? checkoutKnipBinDir;

/**
 * Probe the BINARY, not the directory that usually holds it.
 *
 * The managed-tools directory can exist while knip itself is absent — a host
 * that installed some other managed tool, or a first run that has not lazily
 * installed knip yet. A directory-existence check calls that "available", the
 * scenario then runs against a client whose `analyze` returns an availability
 * failure with no findings, and the baseline assertion fails for a reason that
 * has nothing to do with the defect. Spawning `knip --version` with the same
 * PATH the scenario will use answers the question that actually matters.
 */
function knipUnavailableReason(): string | undefined {
	const env = { ...process.env };
	if (knipBinDir) {
		env.PATH = `${knipBinDir}${path.delimiter}${env.PATH ?? ""}`;
	}
	try {
		if (
			spawnSync("knip", ["--version"], {
				shell: process.platform === "win32",
				encoding: "utf8",
				env,
			}).status === 0
		) {
			return undefined;
		}
	} catch {
		// fall through to the skip reason
	}
	return "knip is not runnable on this host";
}

const knipStaleCache = defineTurnScenario({
	id: "knip-stale-unused-export",
	incident:
		"pi-lens warned that assertSafeForCmdShell was unused while a test in the same tree imported it; a direct knip run returned 0 hits",
	issue: "#1630",
	skipWhen: knipUnavailableReason,
	harnessOptions: () => ({ knipClient: new KnipClient(false) }),
	async run(h) {
		const originalPath = process.env.PATH;
		if (knipBinDir) {
			process.env.PATH = `${knipBinDir}${path.delimiter}${originalPath ?? ""}`;
		}
		// #4566 F6: keep unknown trust on the fixture; the test toolchain
		// belongs to the checkout outside it.
		const originalCwd = process.cwd();
		process.chdir(h.cwd);
		try {
			h.write(
				"package.json",
				JSON.stringify({
					name: "knip-1630-scenario",
					version: "1.0.0",
					private: true,
					type: "module",
				}),
			);
			h.write(
				"knip.json",
				JSON.stringify({
					entry: ["src/index.ts", "tests/**/*.test.ts"],
					project: ["src/**/*.ts", "tests/**/*.ts"],
				}),
			);
			h.write(
				"src/util.ts",
				"export function assertSafeForCmdShell(s: string): string { return s; }\n" +
					'export function used(): string { return "x"; }\n',
			);
			h.write(
				"src/index.ts",
				'import { used } from "./util.js";\nconsole.log(used());\n',
			);
			// `tests/` exists but matches nothing when the cache is written — the
			// exact shape knip's glob cache failed to revalidate.
			fs.mkdirSync(h.pathOf("tests"), { recursive: true });

			// Prime knip's own incremental cache while nothing imports the symbol.
			// This is the session's earlier scan, out of band from any turn.
			const client = h.knipClient as KnipClient;
			const primed = await client.analyze(h.cwd);
			expect(
				primed.unusedExports.map((e) => e.name),
				`baseline: knip should flag the export while nothing imports it (success=${primed.success}, summary=${primed.summary})`,
			).toContain("assertSafeForCmdShell");

			// The consumer appears AFTER that scan. The declaring file's mtime does
			// not move, which is why #1622's per-cited-path freshness gate cannot
			// see this: "unused export" is a whole-graph property.
			h.advance(10_000);
			h.write(
				"tests/consumer.test.ts",
				'import { assertSafeForCmdShell } from "../src/util.js";\n' +
					'export const t = assertSafeForCmdShell("a");\n',
			);

			// The agent edits the declaring file, and the turn re-runs knip.
			h.advance(1_000);
			h.edit(
				"src/util.ts",
				"export function assertSafeForCmdShell(s: string): string { return s.trim(); }\n" +
					'export function used(): string { return "x"; }\n',
			);
			const view = await h.turnEnd();

			// The agent must not be told a symbol is unused when the current source
			// tree contains an importer of it.
			expect(view.text).not.toContain("assertSafeForCmdShell");
		} finally {
			process.env.PATH = originalPath;
			process.chdir(originalCwd);
			resetProjectTrust();
		}
	},
});

// ── Scenario 3 — dependency-drift replay (#1631, fixed by PR #1633) ──────────

const dependencyDriftReplay = defineTurnScenario({
	id: "dependency-drift-replay",
	incident:
		"a blocker on the consumer file replayed for 50 minutes after the missing export was added to its dependency by a bash script",
	issue: "#1631",
	async run(h) {
		h.write("src/worktree.ts", "export const other = 1;\n");
		h.edit(
			"tests/git-env.test.ts",
			"import { gitEnv } from '../src/worktree.js';\ngitEnv();\n",
		);
		h.blocker(
			"tests/git-env.test.ts",
			"TS2305: Module '\"../src/worktree\"' has no exported member 'gitEnv'.",
		);

		// Turn 1: the blocker is true at this instant.
		const first = await h.turnEnd();
		expect(first.blockers.join("\n")).toContain("gitEnv");

		// The export lands via a bash script — the dependency file is never
		// dispatched, so no existing invalidation event can fire.
		h.advance(17_000);
		h.write(
			"src/worktree.ts",
			"export const other = 1;\nexport function gitEnv() {}\n",
		);

		// Turn 2: an unrelated edit ends the turn.
		h.advance(1_000);
		h.edit("src/unrelated.ts", "export const x = 1;\n");
		const second = await h.turnEnd();

		// The consumer's cached verdict is a claim about its import closure. That
		// closure changed, so the verdict must be revalidated or demoted — never
		// re-served verbatim as a STOP-tier blocker.
		expect(second.blockers.join("\n")).not.toContain(
			"has no exported member 'gitEnv'",
		);
	},
});

// ── Scenario 4 — advisory-provenance file-set blind spot ─────────────────────

const provenanceFileSetBlindSpot = defineTurnScenario({
	id: "advisory-provenance-file-set",
	incident:
		'a whole-graph advisory kept validating as "current" because provenance only captured the declaring file, never the consumer set whose change made the claim false',
	issue: "#1630 (analysis section); no fix issue of its own yet",
	pendingOn:
		"unfixed — provenance validates only the captured file set, so a change outside it cannot be seen",
	async run(h) {
		h.edit("src/cmd.ts", "export function assertSafeForCmdShell() {}\n");

		// The advisory is "assertSafeForCmdShell is unused" — a claim about every
		// file in the project. Provenance captures the declaring file alone.
		const verdict = h.provenanceStatus([{ relative: "src/cmd.ts" }], () => {
			h.advance(10_000);
			h.write(
				"tests/cmd.test.ts",
				"import { assertSafeForCmdShell } from '../src/cmd.js';\n",
			);
		});

		// A file the claim depends on changed. "current" is a false statement of
		// freshness, not a true one about the captured set.
		expect(verdict.status).not.toBe("current");
	},
});

/** Every seed scenario, in incident order. */
export const SEED_SCENARIOS: TurnScenario[] = [
	gitleaksStaleReplay,
	knipStaleCache,
	dependencyDriftReplay,
	provenanceFileSetBlindSpot,
];

describe("turn-simulation harness seed scenarios (#1635 item 1)", () => {
	for (const scenario of SEED_SCENARIOS) {
		const title = `${scenario.id} (${scenario.issue}) — ${scenario.incident}`;
		if (scenario.pendingOn) {
			it.skip(`${title} [pending: ${scenario.pendingOn}]`, async () => {
				await runTurnScenario(scenario);
			});
			continue;
		}
		// `skipWhen` is evaluated at collection time so the reason reaches the
		// report. It answers a different question from `pendingOn`: the fix
		// exists, this host just lacks the tool the scenario drives.
		const absent = scenario.skipWhen?.();
		it.skipIf(absent !== undefined)(
			absent ? `${title} [skipped: ${absent}]` : title,
			async () => {
				await runTurnScenario(scenario);
			},
			120_000,
		);
	}

	// The skip list is the honest part of this file, so it is itself asserted:
	// a scenario is either live or carries a reason naming what blocks it.
	it("every pending scenario names what blocks it", () => {
		for (const scenario of SEED_SCENARIOS) {
			if (!scenario.pendingOn) continue;
			expect(scenario.pendingOn.length).toBeGreaterThan(20);
			expect(scenario.pendingOn).toMatch(/#\d+|unfixed/);
		}
	});

	it("seeds all four 2026-08-18 incidents", () => {
		expect(SEED_SCENARIOS.map((s) => s.id)).toEqual([
			"gitleaks-stale-replay",
			"knip-stale-unused-export",
			"dependency-drift-replay",
			"advisory-provenance-file-set",
		]);
	});
});

tests/config/bounded-container-guard.tes:
/** Registered-or-fail guard for long-lived container growth (#2981). */
import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import { Lang, parse } from "@ast-grep/napi";
import { describe, expect, it } from "vitest";
import {
	auditRegistry,
	listSourceFiles,
	stableOccurrenceKey,
} from "../support/sweep-kit.js";
import {
	scanSessionStateCandidates,
	shippedContainerSourceRoots,
} from "../support/session-state-scan.js";

const ROOT = path.resolve(
	path.dirname(fileURLToPath(import.meta.url)),
	"../..",
);
const BUILTINS = new Set(["Map", "Set", "WeakMap", "WeakSet"]);
const BOUNDED_HELPERS = new Set([
	"BoundedFifoMap",
	"BoundedLruCache",
	"BoundedSet",
	"PathKeyedMap",
]);
// Content-keyed, so an exemption must be re-confirmed after an edit.
const FINITE_REASONS: Readonly<Record<string, string>> = {
	// #4483: files whose pre-edit linter capture is still running. Each capture
	// adds its own file before its linters run and deletes it in `finally`.
	"clients/dispatch/integration.ts#preEditCaptureFacts:3fc075f7":
		"one key per pre-edit capture still running; the capture deletes its own key in finally once its linters settle (each runner has its own spawn timeout)",
	// #4403 round 5 (V1): the primaries whose cascade "no language server
	// answered" line was delivered. Keyed by LSP server id, written only for a
	// primary a delivered line named, and cleared at session_start.
	"clients/cascade-format.ts#cascadeCarrySuffix:369e7dcc":
		"keys are LSP server ids from the server catalog (finite, ~60), one per primary whose line was delivered this session; cleared by resetDispatchBaselines",
	// #2372: one adapter per live LSPService identity; WeakMap keys are the
	// bounded process-local service population and entries die with the service.
	"clients/lsp/capabilities.ts#1e3511a9":
		"adapter cache is keyed by live LSPService objects and reclaimed with them; it cannot retain path or user-key growth",
	// #4496: one literal requirement per loaded ast-grep rule object.
	"clients/dispatch/runners/ast-grep-literal-anchors.ts#satisfied:c607e2fd":
		"WeakMap keyed by the YamlRule objects the rule loaders cache; entries are reclaimed with those objects, so it cannot grow with files, paths or sessions",
	// #3968: the runner-id identity leaf — written once per runner definition
	// that enters a `RunnerRegistry` through `register` (the dispatch
	// registry's own population, finite and ~50 today), never per file, per
	// session or per user value. A named cap here would drop a legitimate
	// runner id from the `lsp.servers.<id>.covers` validation — worse wrong
	// than unbounded over a closed population.
	"clients/dispatch/known-runner-ids.ts#177da0f7":
		"runner-id identity written once per RunnerRegistry.register'd runner definition; finite vocabulary, bounded by the dispatch registry's own population",
	"clients/session-scope.ts#toStartReason:e2e4ae2a":
		"#3612 `sessionStores`: keyed by store name, one entry per `defineSessionStore` call at module load (a second declaration of a name throws); four stores today, and the session-scope sweep pins every name",
};

type Verdict = 1 | 2 | 3 | 5;
type KeyAxis =
	| "file path"
	| "cwd"
	| "pid"
	| "session id"
	| "language id"
	| "tool id"
	| "undetermined";
type Site = {
	key: string;
	detail: string;
	name: string;
	verdict: Verdict;
	keyExpression: string | undefined;
	keyAxis: KeyAxis;
};

function walk(node: any, visit: (node: any) => void): void {
	visit(node);
	for (const child of node.children()) walk(child, visit);
}

/**
 * One parse and ONE pre-order walk per source text. Every predicate below
 * reads this document-ordered node array instead of parsing and walking the
 * tree itself.
 *
 * #3058: the predicates used to take the source STRING, so `scan()` re-parsed
 * and re-walked each whole file up to six times per container occurrence --
 * 302 occurrences over 121 files, ~1,800 whole-file passes. An
 * `@ast-grep/napi` root holds a native tree-sitter arena and every
 * `children()` call materialises a NAPI handle per node, none of which V8
 * accounts for and so none of which it ever feels pressure to collect.
 * Measured 9,207 MB peak RSS against 62 MB of V8 heap. Passing the node array
 * makes the per-call pass structurally impossible to re-introduce: a
 * predicate has no source string to parse and no root to walk.
 */
export function parseNodes(source: string): any[] {
	const nodes: any[] = [];
	walk(parse(Lang.TypeScript, source).root(), (node) => nodes.push(node));
	return nodes;
}

function identifier(node: any): string | undefined {
	return node?.kind() === "identifier" ? node.text() : undefined;
}

function isLiteralVocabularyValue(node: any): boolean {
	if (
		[
			"string",
			"number",
			"true",
			"false",
			"null",
			"regex",
			"undefined",
		].includes(node.kind())
	)
		return true;
	return (
		node.kind() === "template_string" &&
		!node
			.namedChildren()
			.some((child: any) => child.kind() === "template_substitution")
	);
}

/**
 * AST population rule. A custom class instance is a lifecycle-owned singleton,
 * not a container occurrence. A Map/Set made from a literal and never written
 * again is an import-time vocabulary. Built-in cells with writes, or with a
 * non-literal source, remain in the growth-shaped population.
 */
export function isGrowthShapedContainer(nodes: any[], name: string): boolean {
	let declared = false;
	let builtin = false;
	let written = false;
	for (const node of nodes) {
		if (
			node.kind() === "variable_declarator" &&
			identifier(node.field("name")) === name
		) {
			const value = node.field("value");
			if (value?.kind() !== "new_expression") continue;
			const ctor = identifier(value.field("constructor"));
			if (!BUILTINS.has(ctor ?? "") && !BOUNDED_HELPERS.has(ctor ?? ""))
				continue;
			declared = true;
			builtin = BUILTINS.has(ctor ?? "");
		}
		if (node.kind() !== "call_expression") continue;
		const fn = node.field("function");
		if (
			fn?.kind() !== "member_expression" ||
			identifier(fn.field("object")) !== name
		)
			continue;
		if (!["set", "add"].includes(fn.field("property")?.text() ?? "")) continue;
		const key = node.field("arguments")?.namedChildren()[0];
		// Literal keys/entries can be vocabulary initialization. Every other
		// expression is dynamic, including an opaque identifier such as `key`;
		// do not turn the AST population into a path-name heuristic (#2981).
		if (!key) continue;
		if (isLiteralVocabularyValue(key)) continue;
		// A non-literal write is growth-shaped regardless of where the AST puts
		// it. Module-scope writes are unusual, but filtering them by function
		// ancestry loses the same arbitrary-key evidence as filtering by a
		// filename-shaped identifier (#2981 / BCG-1-R1).
		written = true;
	}
	return declared && (!builtin || written);
}

function keyExpressionFor(nodes: any[], name: string): string | undefined {
	let expression: string | undefined;
	for (const node of nodes) {
		if (expression || node.kind() === "subscript_expression") {
			if (
				node.kind() === "subscript_expression" &&
				identifier(node.field("argument")) === name
			)
				expression = node.field("index")?.text();
			continue;
		}
		if (node.kind() !== "call_expression") continue;
		const fn = node.field("function");
		if (
			fn?.kind() !== "member_expression" ||
			identifier(fn.field("object")) !== name ||
			!["set", "add", "get", "has", "delete"].includes(
				fn.field("property")?.text() ?? "",
			)
		)
			continue;
		expression = node.field("arguments")?.namedChildren()[0]?.text();
	}
	return expression;
}

const KEY_AXIS_NAMES: Readonly<
	Record<Exclude<KeyAxis, "undetermined">, ReadonlySet<string>>
> = {
	"file path": new Set([
		"file",
		"filename",
		"filepath",
		"path",
		"artifact",
		"snapshot",
		"touch",
	]),
	cwd: new Set(["cwd", "dir", "directory", "project", "root", "workspace"]),
	pid: new Set(["pid", "process"]),
	"session id": new Set(["session", "sessionid", "turn"]),
	"language id": new Set(["language", "languageid", "lang"]),
	"tool id": new Set(["package", "runner", "tool", "toolid"]),
};

function axisName(node: any): KeyAxis {
	const text = node.text().toLowerCase();
	for (const [axis, names] of Object.entries(KEY_AXIS_NAMES) as Array<
		[Exclude<KeyAxis, "undetermined">, ReadonlySet<string>]
	>) {
		if (names.has(text)) return axis;
	}
	return "undetermined";
}

export function determineKeyAxis(expression: string | undefined): KeyAxis {
	if (!expression) return "undetermined";
	const root = parse(Lang.TypeScript, expression).root();
	const expressionNode = root.namedChildren()[0]?.namedChildren()[0];
	if (
		!["identifier", "member_expression", "subscript_expression"].includes(
			(expressionNode?.kind() as string | undefined) ?? "",
		)
	)
		return "undetermined";
	let axis: KeyAxis = "undetermined";
	walk(root, (node) => {
		if (
			axis !== "undetermined" ||
			!["identifier", "property_identifier"].includes(node.kind())
		)
			return;
		axis = axisName(node);
	});
	return axis;
}

export function hasBoundedConstructor(nodes: any[], name: string): boolean {
	let result = false;
	for (const node of nodes) {
		if (
			result ||
			node.kind() !== "variable_declarator" ||
			identifier(node.field("name")) !== name
		)
			continue;
		const value = node.field("value");
		if (value?.kind() !== "new_expression") continue;
		const ctor = identifier(value.field("constructor"));
		if (
			["BoundedFifoMap", "BoundedLruCache", "BoundedSet"].includes(ctor ?? "")
		)
			result = true;
		if (
			ctor === "PathKeyedMap" &&
			(value.field("arguments")?.namedChildren().length ?? 0) >= 2
		)
			result = true;
	}
	return result;
}

export function hasNamedSizeComparison(nodes: any[], name: string): boolean {
	let result = false;
	for (const node of nodes) {
		if (result || node.kind() !== "binary_expression") continue;
		const left = node.field("left");
		if (![">", ">=", "<", "<="].includes(node.field("operator")?.text() ?? ""))
			continue;
		if (
			identifier(left?.field("object")) === name &&
			left?.field("property")?.text() === "size" &&
			node.field("right")?.kind() === "identifier"
		) {
			let parent = node.parent();
			while (parent) {
				if (
					[
						"if_statement",
						"while_statement",
						"for_statement",
						"do_statement",
					].includes(parent.kind())
				) {
					walk(parent, (child) => {
						if (
							child.kind() !== "call_expression" ||
							child.field("function")?.kind() !== "member_expression" ||
							identifier(child.field("function")?.field("object")) !== name ||
							!["delete", "clear"].includes(
								child.field("function")?.field("property")?.text() ?? "",
							)
						)
							return;
						result = true;
					});
					break;
				}
				parent = parent.parent();
			}
		}
	}
	return result;
}

export function hasDeletingTimer(nodes: any[], name: string): boolean {
	let result = false;
	for (const node of nodes) {
		if (result || node.kind() !== "call_expression") continue;
		const fn = node.field("function");
		if (
			fn?.kind() !== "member_expression" ||
			fn.field("property")?.text() !== "delete" ||
			identifier(fn.field("object")) !== name
		)
			continue;
		let parent = node.parent();
		while (parent) {
			if (
				parent.kind() === "call_expression" &&
				parent.field("function")?.text() === "setTimeout"
			)
				result = true;
			parent = parent.parent();
		}
	}
	return result;
}

export function scan(
	roots: readonly string[] = shippedContainerSourceRoots(),
): { sites: Site[]; scanned: number } {
	const sites: Site[] = [];
	let scanned = 0;
	for (const root of roots) {
		const files = fs.statSync(root).isDirectory()
			? listSourceFiles(root, { extensions: [".ts"], skipTests: true })
			: [root];
		const scanRoot = root.endsWith("index.ts") ? path.dirname(root) : root;
		const candidates = new Map(
			scanSessionStateCandidates(scanRoot, {
				includeUnresetContainers: true,
			}).map((item) => [item.file, item]),
		);
		for (const absolute of files) {
			const relative = path.relative(ROOT, absolute).split(path.sep).join("/");
			const source = fs.readFileSync(absolute, "utf8");
			const key = path.relative(scanRoot, absolute).split(path.sep).join("/");
			const candidate = candidates.get(key);
			const containers = candidate?.containerDetails ?? [];
			if (containers.length === 0) continue;
			// Parsed and walked once for the whole file and shared by every
			// container in it, and the source lines split once (#3058).
			const nodes = parseNodes(source);
			const lines = source.split("\n");
			for (const container of containers) {
				scanned++;
				if (!isGrowthShapedContainer(nodes, container.name)) continue;
				const verdict: Verdict = hasBoundedConstructor(nodes, container.name)
					? 1
					: hasNamedSizeComparison(nodes, container.name)
						? 2
						: hasDeletingTimer(nodes, container.name)
							? 3
							: 5;
				const keyExpression = keyExpressionFor(nodes, container.name);
				sites.push({
					key: stableOccurrenceKey(relative, lines, container.line - 1),
					detail: `${relative}:${container.line}`,
					name: container.name,
					verdict,
					keyExpression,
					keyAxis: determineKeyAxis(keyExpression),
				});
			}
		}
	}
	return { sites, scanned };
}

function exemptionsForAudit(
	_sites: readonly Site[],
	reasons: Readonly<Record<string, string>> = FINITE_REASONS,
): Readonly<Record<string, string>> {
	return reasons;
}

function finiteReason(
	site: Site,
	reasons: Readonly<Record<string, string>> = FINITE_REASONS,
): string | undefined {
	return reasons[site.key];
}

function validateAdmissionRegistry(
	flagged: readonly Site[],
	registered: readonly string[],
): string[] {
	const current = new Set(flagged.map((site) => site.key));
	const stale = registered.filter((key) => !current.has(key));
	return stale.length === 0
		? []
		: [
				`registry contains ${stale.length} stale content identity(ies): ${stale.join(", ")}`,
			];
}

