		for (const site of result.sites)
			counts.set(site.verdict, (counts.get(site.verdict) ?? 0) + 1);
		expect(result.scanned).toBeGreaterThanOrEqual(100);
		expect(counts.get(1) ?? 0).toBeGreaterThan(0);
