					home,
				);
				expect(code).toBe(2);
				const reason = readFailureRecord(home)?.metadata.reason ?? "";
				expect(reason.length).toBe(truncated ? 1013 : 1000);
				expect(reason.includes("… (truncated)")).toBe(truncated);
				expect(stderr.trim()).toBe(`pi-lens-analyze failed: ${reason}`);
			} finally {
